CREATE OR REPLACE FUNCTION "public"."_field_visible"("_scope" "text", "_is_friend_tier" boolean, "_is_owner_tier" boolean) RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT CASE COALESCE(NULLIF(_scope,''), 'public')
    WHEN 'public'  THEN true
    WHEN 'friends' THEN _is_friend_tier
    WHEN 'only_me' THEN _is_owner_tier
    ELSE true
  END;
$$;


