CREATE OR REPLACE FUNCTION "public"."_flag_review_keyword_hit"("_content" "text") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _kw text;
  _norm text;
  _gap text;
BEGIN
  IF _content IS NULL OR length(btrim(_content)) = 0 THEN
    RETURN NULL;
  END IF;
  FOR _kw IN
    SELECT keyword FROM public.blocked_keywords
    WHERE is_active = true AND severity = 'flag_review'
      AND keyword IS NOT NULL AND length(btrim(keyword)) > 0
  LOOP
    _norm := lower(regexp_replace(_kw, '[^a-zA-Z0-9]', '', 'g'));
    CONTINUE WHEN _norm = '';
    _gap := '\y' || regexp_replace(_norm, '(.)', '\1[^a-zA-Z0-9]*', 'g') || '\y';
    IF _content ~* _gap THEN
      RETURN _kw;
    END IF;
  END LOOP;
  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."_flag_review_keyword_hit"("_content" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_gen_competition_order_no"() RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
