CREATE OR REPLACE FUNCTION "public"."_notification_template_for_entry"("_status" "text", "_placement" "text") RETURNS TABLE("kind" "text", "email_template" "text", "in_app_type" "text", "in_app_title" "text", "in_app_message" "text")
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
  SELECT
    CASE
      WHEN _placement IN ('winner','1st_runner_up','2nd_runner_up','special_jury','runner_up','honorable_mention') THEN 'entry_award'
      WHEN _status IN ('winner','runner_up','honorable_mention') THEN 'entry_award'
      WHEN _status = 'finalist' THEN 'entry_finalist'
      WHEN _status ILIKE 'round%qualified' OR _status = 'qualified' THEN 'entry_qualified_round'
      WHEN _status ILIKE '%shortlist%' THEN 'entry_shortlisted'
      WHEN _status = 'rejected' THEN 'entry_rejected'
      WHEN _status = 'approved' THEN 'entry_approved'
      ELSE NULL
    END,
    CASE
      WHEN _placement IN ('winner','1st_runner_up','2nd_runner_up','special_jury','runner_up','honorable_mention') THEN 'competition_winner'
      WHEN _status IN ('winner','runner_up','honorable_mention') THEN 'competition_winner'
      WHEN _status = 'finalist' THEN 'entry_finalist'
      WHEN _status ILIKE 'round%qualified' OR _status = 'qualified' THEN 'entry_qualified'
      WHEN _status ILIKE '%shortlist%' THEN 'entry_shortlisted'
      WHEN _status = 'rejected' THEN 'entry_rejected'
      WHEN _status = 'approved' THEN 'entry_approved'
      ELSE NULL
    END,
    CASE
      WHEN _placement IN ('winner','1st_runner_up','2nd_runner_up','special_jury','runner_up','honorable_mention') THEN 'award'
      WHEN _status IN ('winner','runner_up','honorable_mention') THEN 'award'
      WHEN _status = 'finalist' THEN 'finalist'
      WHEN _status ILIKE 'round%qualified' OR _status = 'qualified' THEN 'qualified'
      WHEN _status ILIKE '%shortlist%' THEN 'shortlisted'
      WHEN _status = 'rejected' THEN 'rejected'
      WHEN _status = 'approved' THEN 'approved'
      ELSE NULL
    END,
    CASE
      WHEN _placement IN ('winner','1st_runner_up','2nd_runner_up','special_jury','runner_up','honorable_mention') THEN 'Congratulations on your award!'
      WHEN _status IN ('winner','runner_up','honorable_mention') THEN 'Congratulations on your award!'
      WHEN _status = 'finalist' THEN 'You are a finalist!'
      WHEN _status ILIKE 'round%qualified' OR _status = 'qualified' THEN 'You advanced to the next round'
      WHEN _status ILIKE '%shortlist%' THEN 'Your entry was shortlisted'
      WHEN _status = 'rejected' THEN 'Update on your entry'
      WHEN _status = 'approved' THEN 'Entry Approved'
      ELSE NULL
    END,
    'See your entry status in the dashboard.';
$$;


ALTER FUNCTION "public"."_notification_template_for_entry"("_status" "text", "_placement" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_resolve_stage_key_from_entry"("_status" "text", "_current_round" "text", "_progression_decision" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _round_num integer;
  _key text;
BEGIN
  -- Highest priority: explicit progression_decision (already canonical v3).
  _key := NULLIF(_progression_decision, '');
  IF _key IS NOT NULL THEN
    RETURN _key;
  END IF;

  _round_num := NULLIF(regexp_replace(COALESCE(_current_round, ''), '\D', '', 'g'), '')::integer;

  RETURN CASE
    WHEN _round_num = 1 AND _status ILIKE '%shortlist%'        THEN 'r1_shortlisted_r2'
    WHEN _round_num = 1 AND _status = 'approved'                THEN 'r1_accepted'
    WHEN _round_num = 1 AND _status = 'rejected'                THEN 'r1_rejected'
    WHEN _round_num = 1 AND _status ILIKE '%needs%verif%'       THEN 'r1_needs_verification'
    WHEN _round_num = 1 AND _status ILIKE '%needs%review%'      THEN 'r1_needs_verification'
    WHEN _round_num = 2 AND (_status ILIKE '%qualified%' OR _status = 'qualified') THEN 'r2_qualified_r3'
    WHEN _round_num = 2 AND _status = 'approved'                THEN 'r2_accepted'
    WHEN _round_num = 2 AND _status = 'rejected'                THEN 'r2_not_selected'
    WHEN _round_num = 3 AND (_status ILIKE '%qualified%' OR _status = 'qualified') THEN 'r3_qualified_final'
    WHEN _round_num = 3 AND _status = 'approved'                THEN 'r3_accepted'
    WHEN _round_num = 3 AND _status = 'rejected'                THEN 'r3_not_selected'
    WHEN _status = 'winner'                                     THEN 'r4_winner'
    WHEN _status IN ('runner_up','runner_up_1','1st_runner_up') THEN 'r4_runner_up_1'
    WHEN _status IN ('runner_up_2','2nd_runner_up')             THEN 'r4_runner_up_2'
    WHEN _status IN ('honorable_mention','honourable_mention','honorary_mention') THEN 'r4_honorary_mention'
    WHEN _status = 'special_jury'                               THEN 'r4_special_jury'
    WHEN _status = 'top_50'                                     THEN 'r4_top_50'
    WHEN _status = 'top_100'                                    THEN 'r4_top_100'
    WHEN _status = 'finalist'                                   THEN 'r4_finalist'
    ELSE NULL
  END;
END;
$$;


ALTER FUNCTION "public"."_resolve_stage_key_from_entry"("_status" "text", "_current_round" "text", "_progression_decision" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_resolve_stage_key_from_entry"("_status" "text", "_current_round" "text", "_progression_decision" "text") IS 'Phase 7: single source of truth mapping legacy entry.status + current_round → canonical v3 stage_key. Used by every judging-lifecycle email emitter so payloads always carry stageKey. progression_decision wins when present.';



