CREATE OR REPLACE FUNCTION "public"."_tg_round_publish_recompute"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  cid uuid;
  e   record;
BEGIN
  cid := COALESCE(NEW.competition_id, OLD.competition_id);
  FOR e IN SELECT id FROM public.competition_entries WHERE competition_id = cid LOOP
    PERFORM public.recompute_entry_public_status(e.id);
  END LOOP;
  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."_tg_round_publish_recompute"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_tg_v3_catalog_recompute"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  r record;
  affected_key text;
BEGIN
  -- On UPDATE/DELETE consider OLD; on UPDATE also consider NEW (key rename)
  IF TG_OP = 'DELETE' THEN
    affected_key := OLD.stage_key;
  ELSE
    affected_key := NEW.stage_key;
  END IF;

  FOR r IN
    SELECT id FROM public.competition_entries
    WHERE progression_decision = affected_key
       OR (TG_OP = 'UPDATE' AND progression_decision = OLD.stage_key)
  LOOP
    PERFORM public.recompute_entry_public_status(r.id);
  END LOOP;

  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."_tg_v3_catalog_recompute"() OWNER TO "postgres";


