COMMENT ON FUNCTION "public"."account_is_live"() IS 'True when the caller''s account still exists in auth.users. Used by RESTRICTIVE write policies so a deleted account loses write access immediately instead of when its token expires (up to 3600s later). Added 2026-08-06 after a deleted member was found still able to act.';



CREATE OR REPLACE FUNCTION "public"."acquire_judge_lock"("_entry_id" "uuid", "_photo_index" integer, "_judge_id" "uuid", "_ttl_minutes" integer DEFAULT 5) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _existing record;
  _result jsonb;
BEGIN
  -- Clear expired locks for this entry+photo
  DELETE FROM judge_entry_locks
  WHERE entry_id = _entry_id AND photo_index = _photo_index AND expires_at < now();

  -- Check if lock exists
  SELECT * INTO _existing FROM judge_entry_locks
  WHERE entry_id = _entry_id AND photo_index = _photo_index;

  IF _existing IS NOT NULL THEN
    IF _existing.judge_id = _judge_id THEN
      -- Extend own lock
      UPDATE judge_entry_locks
      SET expires_at = now() + (_ttl_minutes || ' minutes')::interval,
          locked_at = now()
      WHERE id = _existing.id;
      RETURN jsonb_build_object('acquired', true, 'lock_id', _existing.id);
    ELSE
      -- Locked by another judge
      RETURN jsonb_build_object(
        'acquired', false,
        'locked_by', _existing.judge_id,
        'expires_at', _existing.expires_at
      );
    END IF;
  END IF;

  -- No lock exists, create one
  INSERT INTO judge_entry_locks (entry_id, photo_index, judge_id, expires_at)
  VALUES (_entry_id, _photo_index, _judge_id, now() + (_ttl_minutes || ' minutes')::interval)
  RETURNING id INTO _existing;

  RETURN jsonb_build_object('acquired', true, 'lock_id', _existing.id);
END;
$$;


ALTER FUNCTION "public"."acquire_judge_lock"("_entry_id" "uuid", "_photo_index" integer, "_judge_id" "uuid", "_ttl_minutes" integer) OWNER TO "postgres";


