CREATE OR REPLACE FUNCTION "public"."admin_purge_orphan_user_data"("_uid" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _c jsonb := '{}'::jsonb;
  _n integer;
BEGIN
  IF _uid IS NULL THEN
    RAISE EXCEPTION 'admin_purge_orphan_user_data: _uid is required';
  END IF;

  -- Same trusted-deletion bypass as admin_delete_auth_user: the judge_* deletes
  -- below would otherwise be blocked by enforce_round_lock for completed rounds.
  PERFORM set_config('app.bypass_round_lock', 'on', true);

  DELETE FROM public.ad_conversions           WHERE user_id = _uid;            GET DIAGNOSTICS _n = ROW_COUNT; _c := _c || jsonb_build_object('ad_conversions', _n);
  DELETE FROM public.ai_chat_usage            WHERE user_id = _uid;            GET DIAGNOSTICS _n = ROW_COUNT; _c := _c || jsonb_build_object('ai_chat_usage', _n);
  DELETE FROM public.auth_login_attempts      WHERE user_id = _uid;            GET DIAGNOSTICS _n = ROW_COUNT; _c := _c || jsonb_build_object('auth_login_attempts', _n);
  DELETE FROM public.feed_events              WHERE user_id = _uid OR author_id = _uid; GET DIAGNOSTICS _n = ROW_COUNT; _c := _c || jsonb_build_object('feed_events', _n);
  DELETE FROM public.raw_commitments          WHERE user_id = _uid;            GET DIAGNOSTICS _n = ROW_COUNT; _c := _c || jsonb_build_object('raw_commitments', _n);
  DELETE FROM public.custom_url_history       WHERE user_id = _uid;            GET DIAGNOSTICS _n = ROW_COUNT; _c := _c || jsonb_build_object('custom_url_history', _n);
  DELETE FROM public.held_result_notifications WHERE recipient_user_id = _uid; GET DIAGNOSTICS _n = ROW_COUNT; _c := _c || jsonb_build_object('held_result_notifications', _n);
  DELETE FROM public.notification_emit_log    WHERE recipient_user_id = _uid;  GET DIAGNOSTICS _n = ROW_COUNT; _c := _c || jsonb_build_object('notification_emit_log', _n);
  DELETE FROM public.post_tags                WHERE tagged_user_id = _uid;     GET DIAGNOSTICS _n = ROW_COUNT; _c := _c || jsonb_build_object('post_tags', _n);

  -- Judge working-state + audit rows (consistent with existing judge_scores/
  -- judge_comments/judge_tag_assignments deletion in delete-user).
  DELETE FROM public.judge_decisions          WHERE judge_id = _uid;           GET DIAGNOSTICS _n = ROW_COUNT; _c := _c || jsonb_build_object('judge_decisions', _n);
  DELETE FROM public.judge_award_tags         WHERE judge_id = _uid;           GET DIAGNOSTICS _n = ROW_COUNT; _c := _c || jsonb_build_object('judge_award_tags', _n);
  DELETE FROM public.judge_activity_logs      WHERE judge_id = _uid;           GET DIAGNOSTICS _n = ROW_COUNT; _c := _c || jsonb_build_object('judge_activity_logs', _n);
  DELETE FROM public.judge_entry_assignments  WHERE judge_id = _uid;           GET DIAGNOSTICS _n = ROW_COUNT; _c := _c || jsonb_build_object('judge_entry_assignments', _n);
  DELETE FROM public.judge_entry_locks        WHERE judge_id = _uid;           GET DIAGNOSTICS _n = ROW_COUNT; _c := _c || jsonb_build_object('judge_entry_locks', _n);
  DELETE FROM public.judge_sessions           WHERE judge_id = _uid;           GET DIAGNOSTICS _n = ROW_COUNT; _c := _c || jsonb_build_object('judge_sessions', _n);
  -- judge_id has no FK to the user (no cascade), and is round-lock protected:
  -- purge here with the bypass active so completed-round judges can be deleted.
  DELETE FROM public.judge_comments           WHERE judge_id = _uid;           GET DIAGNOSTICS _n = ROW_COUNT; _c := _c || jsonb_build_object('judge_comments', _n);
  DELETE FROM public.judge_tag_assignments    WHERE judge_id = _uid;           GET DIAGNOSTICS _n = ROW_COUNT; _c := _c || jsonb_build_object('judge_tag_assignments', _n);

  -- Strip the deleted user from OTHER users' scheduled-post tag arrays (keep the post).
  UPDATE public.scheduled_posts
     SET tagged_user_ids = array_remove(tagged_user_ids, _uid)
   WHERE _uid = ANY(tagged_user_ids);
  GET DIAGNOSTICS _n = ROW_COUNT; _c := _c || jsonb_build_object('scheduled_posts_tag_stripped', _n);

  RETURN _c;
END;
$$;


ALTER FUNCTION "public"."admin_purge_orphan_user_data"("_uid" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_reject_wallet_transaction"("_admin_id" "uuid", "_txn_id" "uuid", "_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_current_status text;
  v_user_id uuid;
  v_amount numeric;
  v_type text;
  v_actor uuid;
BEGIN
  -- BUG-001: derive admin identity from the real session (ignore caller-supplied _admin_id)
  v_actor := auth.uid();
  IF NOT public.has_role(v_actor, 'admin') THEN
    RAISE EXCEPTION 'unauthorized: caller is not admin' USING ERRCODE = '42501';
  END IF;

  IF _txn_id IS NULL THEN
    RAISE EXCEPTION 'txn_id is required' USING ERRCODE = '22023';
  END IF;

  SELECT status, user_id, amount, type
    INTO v_current_status, v_user_id, v_amount, v_type
  FROM public.wallet_transactions
  WHERE id = _txn_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'wallet_transaction % not found', _txn_id USING ERRCODE = 'P0002';
  END IF;

  IF v_current_status = 'rejected' THEN
    RETURN jsonb_build_object('success', true, 'already', true, 'txn_id', _txn_id, 'status', 'rejected');
  END IF;

  IF v_current_status <> 'pending' THEN
    RAISE EXCEPTION 'illegal state transition: status=% cannot be rejected (only pending allowed)', v_current_status
      USING ERRCODE = '22023';
  END IF;

  UPDATE public.wallet_transactions
  SET
    status = 'rejected',
    metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object(
      'rejected_by', v_actor,
      'rejected_at', now(),
      'rejected_reason', _reason
    )
  WHERE id = _txn_id;

  INSERT INTO public.db_audit_logs (table_name, operation, row_id, old_data, new_data, changed_by)
  VALUES (
    'wallet_transactions',
    'admin_reject_wallet_transaction',
    _txn_id::text,
    jsonb_build_object('status', v_current_status),
    jsonb_build_object('status', 'rejected', 'prev_status', v_current_status, 'reason', _reason, 'user_id', v_user_id, 'amount', v_amount, 'type', v_type),
    v_actor
  );

  RETURN jsonb_build_object('success', true, 'already', false, 'txn_id', _txn_id, 'status', 'rejected', 'prev_status', v_current_status);
END;
$$;


ALTER FUNCTION "public"."admin_reject_wallet_transaction"("_admin_id" "uuid", "_txn_id" "uuid", "_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_reject_wallet_transaction"("_admin_id" "uuid", "_txn_id" "uuid", "_reason" "text") IS 'Phase 1 Mutation #2 Step A. Admin-only state-only reject of a pending wallet_transactions row. No money movement. Idempotent on already-rejected. Body-level has_role admin check + row lock. Audit row written to db_audit_logs. Rollback: DROP FUNCTION IF EXISTS public.admin_reject_wallet_transaction(uuid, uuid, text);';



CREATE OR REPLACE FUNCTION "public"."admin_rewind_stage"("_entry_id" "uuid", "_to_stage_key" "text", "_reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _is_admin bool;
BEGIN
  SELECT public.has_role(auth.uid(), 'admin') INTO _is_admin;
  IF NOT COALESCE(_is_admin, false) THEN
    RAISE EXCEPTION 'admin_rewind_stage requires admin role'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF _reason IS NULL OR length(trim(_reason)) < 5 THEN
    RAISE EXCEPTION 'admin_rewind_stage requires a reason (>=5 chars)';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.v3_stage_catalog
     WHERE stage_key = _to_stage_key AND is_active = true
  ) THEN
    RAISE EXCEPTION 'unknown or inactive stage_key %', _to_stage_key;
  END IF;

  PERFORM set_config('app.allow_stage_rewind', 'on', true);
  UPDATE public.competition_entries
     SET stage_key = _to_stage_key
   WHERE id = _entry_id;
  PERFORM set_config('app.allow_stage_rewind', 'off', true);

  INSERT INTO public.db_audit_logs(table_name, operation, row_id, new_data, changed_by)
  VALUES (
    'competition_entries',
    'admin_rewind_stage',
    _entry_id::text,
    jsonb_build_object('to_stage_key', _to_stage_key, 'reason', _reason),
    auth.uid()
  );
END;
$$;


ALTER FUNCTION "public"."admin_rewind_stage"("_entry_id" "uuid", "_to_stage_key" "text", "_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_search_users"("search_query" "text" DEFAULT ''::"text", "search_by" "text" DEFAULT 'name'::"text") RETURNS TABLE("id" "uuid", "email" "text", "full_name" "text", "avatar_url" "text", "bio" "text", "is_suspended" boolean, "suspended_until" timestamp with time zone, "suspension_reason" "text", "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT public.has_role(auth.uid(), 'admin') THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;
  
  IF search_query = '' THEN
    RETURN QUERY
    SELECT p.id, au.email::text, p.full_name, p.avatar_url, p.bio, p.is_suspended, p.suspended_until, p.suspension_reason, p.created_at
    FROM public.profiles p
    LEFT JOIN auth.users au ON au.id = p.id
    ORDER BY p.created_at DESC LIMIT 100;
  ELSIF search_by = 'email' THEN
    RETURN QUERY
    SELECT p.id, au.email::text, p.full_name, p.avatar_url, p.bio, p.is_suspended, p.suspended_until, p.suspension_reason, p.created_at
    FROM public.profiles p
    LEFT JOIN auth.users au ON au.id = p.id
    WHERE au.email ILIKE '%' || search_query || '%'
    ORDER BY p.created_at DESC LIMIT 50;
  ELSE
    RETURN QUERY
    SELECT p.id, au.email::text, p.full_name, p.avatar_url, p.bio, p.is_suspended, p.suspended_until, p.suspension_reason, p.created_at
    FROM public.profiles p
    LEFT JOIN auth.users au ON au.id = p.id
    WHERE p.full_name ILIKE '%' || search_query || '%'
    ORDER BY p.created_at DESC LIMIT 50;
  END IF;
END;
$$;


ALTER FUNCTION "public"."admin_search_users"("search_query" "text", "search_by" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_set_photo_rejected"("_entry_id" "uuid", "_photo_index" integer, "_rejected" boolean, "_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _is_admin    boolean;
  _meta        jsonb;
  _photos_len  integer;
  _meta_len    integer;
  _new_meta    jsonb;
  _item        jsonb;
  _i           integer;
  _all_rejected boolean := true;
  _any_active  boolean := false;
  _old_status  text;
  _new_status  text;
  _old_meta    jsonb;
BEGIN
  -- Admin gate (uses existing has_role helper)
  SELECT public.has_role(auth.uid(), 'admin'::app_role) INTO _is_admin;
  IF NOT COALESCE(_is_admin, false) THEN
    RAISE EXCEPTION 'forbidden: admin role required'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  -- Load entry
  SELECT photo_meta, status, COALESCE(array_length(photos,1),0)
    INTO _old_meta, _old_status, _photos_len
  FROM public.competition_entries
  WHERE id = _entry_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'entry not found' USING ERRCODE = 'no_data_found';
  END IF;

  _meta_len := COALESCE(jsonb_array_length(_old_meta), 0);
  IF _photo_index < 0 OR _photo_index >= _meta_len THEN
    RAISE EXCEPTION 'photo_index % out of range (0..%)', _photo_index, _meta_len - 1
      USING ERRCODE = 'check_violation';
  END IF;

  -- Set rejected flag on the target index
  _item := _old_meta -> _photo_index;
  _item := _item || jsonb_build_object(
    'rejected', _rejected,
    'rejected_at', CASE WHEN _rejected THEN to_jsonb(now()) ELSE 'null'::jsonb END,
    'rejected_by', CASE WHEN _rejected THEN to_jsonb(auth.uid()) ELSE 'null'::jsonb END,
    'rejected_reason', CASE WHEN _rejected THEN to_jsonb(_reason) ELSE 'null'::jsonb END
  );
  _new_meta := jsonb_set(_old_meta, ARRAY[_photo_index::text], _item, false);

  -- Derive entry-level status
  FOR _i IN 0.._meta_len - 1 LOOP
    IF COALESCE(((_new_meta -> _i) ->> 'rejected')::boolean, false) THEN
      -- still rejected — track
      NULL;
    ELSE
      _all_rejected := false;
      _any_active := true;
    END IF;
  END LOOP;

  IF _all_rejected THEN
    _new_status := 'rejected';
  ELSIF _old_status = 'rejected' AND _any_active THEN
    -- Restore from full-rejection state back to pending
    _new_status := 'pending';
  ELSE
    _new_status := _old_status;
  END IF;

  UPDATE public.competition_entries
     SET photo_meta = _new_meta,
         status     = _new_status,
         updated_at = now()
   WHERE id = _entry_id;

  -- Audit
  INSERT INTO public.db_audit_logs (table_name, operation, row_id, changed_by, old_data, new_data)
  VALUES (
    'competition_entries',
    'photo_reject_toggle',
    _entry_id::text,
    auth.uid(),
    jsonb_build_object('photo_index', _photo_index, 'old_status', _old_status, 'old_meta_item', _old_meta -> _photo_index),
    jsonb_build_object('photo_index', _photo_index, 'new_status', _new_status, 'new_meta_item', _new_meta -> _photo_index, 'reason', _reason)
  );

  RETURN jsonb_build_object(
    'entry_id', _entry_id,
    'photo_index', _photo_index,
    'rejected', _rejected,
    'old_status', _old_status,
    'new_status', _new_status,
    'all_rejected', _all_rejected
  );
END;
$$;


ALTER FUNCTION "public"."admin_set_photo_rejected"("_entry_id" "uuid", "_photo_index" integer, "_rejected" boolean, "_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_wallet_credit"("_admin_id" "uuid", "_target_user_id" "uuid", "_amount" numeric, "_type" "text", "_description" "text" DEFAULT NULL::"text", "_reference_id" "uuid" DEFAULT NULL::"uuid", "_reference_type" "text" DEFAULT NULL::"text", "_metadata" "jsonb" DEFAULT NULL::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- BUG-001: authority from session. Authenticated callers must actually be admins;
  -- trusted service_role calls (auth.uid() IS NULL) are allowed. _admin_id is ignored.
  IF auth.uid() IS NOT NULL AND NOT has_role(auth.uid(), 'admin'::app_role) THEN
    RAISE EXCEPTION 'Only admins can credit wallets';
  END IF;

  RETURN wallet_transaction(_target_user_id, _type, _amount, _description, _reference_id, _reference_type, _metadata);
END;
$$;


