CREATE OR REPLACE FUNCTION "public"."audit_nr_drift_at_r2_plus"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.decision = 'needs_review' AND NEW.round_number <> 1 THEN
    INSERT INTO public.db_audit_logs (table_name, operation, row_id, new_data, changed_by)
    VALUES (
      'judge_decisions',
      'NR_DRIFT_R2_PLUS',
      NEW.id::text,
      jsonb_build_object(
        'phase', '1.1',
        'gap', 'G1',
        'entry_id', NEW.entry_id,
        'judge_id', NEW.judge_id,
        'round_number', NEW.round_number,
        'photo_index', NEW.photo_index,
        'decision', NEW.decision,
        'message', 'NR decision written for R2+; trigger trg_guard_needs_review_round1_only may be dropped/bypassed/reordered'
      ),
      auth.uid()
    );
    RAISE WARNING 'Phase 1.1 NR drift detected: NR row at round_number=% (entry_id=%, judge_id=%)',
      NEW.round_number, NEW.entry_id, NEW.judge_id;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."audit_nr_drift_at_r2_plus"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."audit_nr_drift_at_r2_plus"() IS 'Phase 1.1 (G1): Defense-in-depth audit logger. Fires AFTER the hard-guard
trigger trg_guard_needs_review_round1_only. If the hard guard is ever dropped
or bypassed, this logger records the violation to db_audit_logs with
operation=NR_DRIFT_R2_PLUS for forensic traceability. No-op for healthy data.';



CREATE OR REPLACE FUNCTION "public"."audit_phase_parity"("sample_limit" integer DEFAULT 100) RETURNS TABLE("id" "uuid", "status" "text", "starts_at" timestamp with time zone, "ends_at" timestamp with time zone, "voting_ends_at" timestamp with time zone, "judging_completed" boolean, "legacy_phase" "text", "db_phase" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    c.id,
    c.status,
    c.starts_at,
    c.ends_at,
    c.voting_ends_at,
    c.judging_completed,
    c.phase AS legacy_phase,
    public.current_phase(c.id) AS db_phase
  FROM public.competitions c
  ORDER BY c.created_at DESC NULLS LAST
  LIMIT GREATEST(1, LEAST(sample_limit, 1000));
$$;


ALTER FUNCTION "public"."audit_phase_parity"("sample_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."audit_phase_parity"("sample_limit" integer) IS 'Phase R5 — Returns inputs + DB-computed phase so client can verify identical output for parity testing.';



CREATE OR REPLACE FUNCTION "public"."audit_sensitive_table"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    INSERT INTO public.db_audit_logs (table_name, operation, row_id, old_data, changed_by)
    VALUES (TG_TABLE_NAME, 'DELETE', OLD.id::text, to_jsonb(OLD), auth.uid());
    RETURN OLD;
  ELSIF TG_OP = 'UPDATE' THEN
    INSERT INTO public.db_audit_logs (table_name, operation, row_id, old_data, new_data, changed_by)
    VALUES (TG_TABLE_NAME, 'UPDATE', NEW.id::text, to_jsonb(OLD), to_jsonb(NEW), auth.uid());
    RETURN NEW;
  ELSIF TG_OP = 'INSERT' THEN
    INSERT INTO public.db_audit_logs (table_name, operation, row_id, new_data, changed_by)
    VALUES (TG_TABLE_NAME, 'INSERT', NEW.id::text, to_jsonb(NEW), auth.uid());
    RETURN NEW;
  END IF;
  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."audit_sensitive_table"() OWNER TO "postgres";


