BEGIN
  IF TG_OP = 'DELETE' THEN
    INSERT INTO public.db_audit_logs (table_name, operation, row_id, old_data, changed_by)
    VALUES (TG_TABLE_NAME, 'DELETE', OLD.key, to_jsonb(OLD), auth.uid());
    RETURN OLD;
  ELSIF TG_OP = 'UPDATE' THEN
    INSERT INTO public.db_audit_logs (table_name, operation, row_id, old_data, new_data, changed_by)
    VALUES (TG_TABLE_NAME, 'UPDATE', NEW.key, to_jsonb(OLD), to_jsonb(NEW), auth.uid());
    RETURN NEW;
  ELSIF TG_OP = 'INSERT' THEN
    INSERT INTO public.db_audit_logs (table_name, operation, row_id, new_data, changed_by)
    VALUES (TG_TABLE_NAME, 'INSERT', NEW.key, to_jsonb(NEW), auth.uid());
    RETURN NEW;
  END IF;
  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."audit_site_settings_table"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."auto_certificate_on_r4_award"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _comp_title text;
  _cert_type text;
  _cert_title text;
  _cert_desc text;
  _placement text;
  _round_text text;
  _r4_published boolean;
BEGIN
  IF current_setting('app.write_path', true) = 'judging_write_decision_atomic' THEN
    RETURN NEW;
  END IF;

  IF (NEW.status IS DISTINCT FROM OLD.status)
     OR (NEW.placement IS DISTINCT FROM OLD.placement) THEN

    _round_text := COALESCE(NEW.current_round, '');
    IF _round_text NOT IN ('4','round4','r4') THEN
      RETURN NEW;
    END IF;

    _placement := COALESCE(NEW.placement, '');
    IF NEW.status = 'winner' THEN
      _cert_type := 'competition_winner';
      _cert_title := 'Winner Certificate';
    ELSIF _placement = 'runner_up_1' THEN
      _cert_type := 'competition_runner_up_1';
      _cert_title := '1st Runner-Up Certificate';
    ELSIF _placement = 'runner_up_2' THEN
      _cert_type := 'competition_runner_up_2';
      _cert_title := '2nd Runner-Up Certificate';
    ELSIF _placement = 'honorary_mention' THEN
      _cert_type := 'competition_honorary_mention';
      _cert_title := 'Honorary Mention Certificate';
    ELSIF _placement = 'special_jury' THEN
      _cert_type := 'competition_special_jury';
      _cert_title := 'Special Jury Award Certificate';
    ELSIF _placement = 'top_50' THEN
      _cert_type := 'competition_top_50';
      _cert_title := 'Top 50 Certificate';
    ELSIF _placement = 'top_100' THEN
      _cert_type := 'competition_top_100';
      _cert_title := 'Top 100 Certificate';
    ELSE
      RETURN NEW;
    END IF;

    IF EXISTS (
      SELECT 1 FROM public.certificates
      WHERE user_id = NEW.user_id
        AND reference_id = NEW.competition_id
        AND type = _cert_type
        AND is_revoked = false
    ) THEN
      RETURN NEW;
    END IF;

    SELECT title INTO _comp_title FROM public.competitions WHERE id = NEW.competition_id;
    _cert_desc := 'Awarded in ' || COALESCE(_comp_title, 'competition') || ' (Round 4)';

    _r4_published := EXISTS (
      SELECT 1 FROM public.competition_round_publish crp
      WHERE crp.competition_id = NEW.competition_id
        AND crp.round_number = 4
        AND crp.published_at IS NOT NULL
    );

    INSERT INTO public.certificates (user_id, title, description, type, reference_id, published_at)
    VALUES (
      NEW.user_id,
      COALESCE(_comp_title, 'Competition') || ' — ' || _cert_title,
      _cert_desc,
      _cert_type,
      NEW.competition_id,
      CASE WHEN _r4_published THEN now() ELSE NULL END   -- hold until declare
    );
  END IF;

  RETURN NEW;
END;
$$;


