CREATE OR REPLACE FUNCTION "public"."backfill_judging_notifications"("_window_days" integer DEFAULT 90, "_dry_run" boolean DEFAULT true) RETURNS TABLE("scanned" bigint, "would_emit" bigint, "emitted" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _scanned bigint := 0;
  _candidates bigint := 0;
  _emitted bigint := 0;
  _row record;
  _tmpl record;
  _site_url text := 'https://fiftymmretinaworld.lovable.app';
  _stage_key text;
BEGIN
  IF NOT has_role(auth.uid(), 'admin') THEN
    RAISE EXCEPTION 'admin_only';
  END IF;

  FOR _row IN
    SELECT ce.id, ce.user_id, ce.competition_id, ce.status, ce.placement,
           ce.current_round, ce.progression_decision, ce.title
    FROM competition_entries ce
    WHERE ce.updated_at > now() - make_interval(days => _window_days)
  LOOP
    _scanned := _scanned + 1;
    SELECT * INTO _tmpl FROM public._notification_template_for_entry(_row.status, _row.placement);
    CONTINUE WHEN _tmpl.email_template IS NULL;

    IF EXISTS (
      SELECT 1 FROM notification_emit_log
      WHERE entity_id = _row.id
        AND email_template = _tmpl.email_template
        AND recipient_user_id = _row.user_id
    ) THEN
      CONTINUE;
    END IF;

    _candidates := _candidates + 1;
    _stage_key := public._resolve_stage_key_from_entry(_row.status, _row.current_round, _row.progression_decision);

    IF NOT _dry_run THEN
      PERFORM public.emit_notification(
        _tmpl.kind,
        _row.id,
        NULLIF(regexp_replace(COALESCE(_row.current_round,''), '\D','','g'),'')::int,
        _row.user_id,
        _tmpl.in_app_type,
        _tmpl.in_app_title,
        _tmpl.in_app_message,
        _row.competition_id,
        _tmpl.email_template,
        jsonb_build_object('entryTitle', _row.title, 'backfilled', true, 'stageKey', _stage_key),
        _site_url || '/dashboard?entry=' || _row.id::text
      );
      _emitted := _emitted + 1;
    END IF;
  END LOOP;

  RETURN QUERY SELECT _scanned, _candidates, _emitted;
END;
$$;


ALTER FUNCTION "public"."backfill_judging_notifications"("_window_days" integer, "_dry_run" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."backfill_tag_decision_drift_admin"() RETURNS TABLE("inserted_count" integer, "scanned_count" integer, "sample" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_fixed integer := 0;
  v_inserted integer := 0;
  v_updated integer := 0;
  v_scanned integer := 0;
  v_sample jsonb := '[]'::jsonb;
BEGIN
  IF v_caller IS NULL OR NOT public.has_role(v_caller, 'admin'::app_role) THEN
    RAISE EXCEPTION 'admin only';
  END IF;

  PERFORM set_config('app.bypass_round_lock', 'on', true);
  PERFORM set_config('app.bypass_mirror_trigger', 'on', true);

  CREATE TEMP TABLE IF NOT EXISTS pg_temp._tag_decision_backfill_plan (
    entry_id uuid,
    judge_id uuid,
    round_number integer,
    photo_index integer,
    decision text,
    tag_id uuid,
    existing_id uuid,
    existing_decision text
  ) ON COMMIT DROP;

  TRUNCATE pg_temp._tag_decision_backfill_plan;

  INSERT INTO pg_temp._tag_decision_backfill_plan
    (entry_id, judge_id, round_number, photo_index, decision, tag_id, existing_id, existing_decision)
  SELECT DISTINCT ON (jta.entry_id, jta.judge_id, m.round_number, COALESCE(jta.photo_index, 0))
         jta.entry_id,
         jta.judge_id,
         m.round_number,
         COALESCE(jta.photo_index, 0),
         m.decision,
         jta.tag_id,
         jd.id,
         jd.decision
  FROM public.judge_tag_assignments jta
  JOIN public.system_tag_decision_map m ON m.tag_id = jta.tag_id
  LEFT JOIN public.judge_decisions jd
    ON jd.entry_id = jta.entry_id
   AND jd.judge_id = jta.judge_id
   AND jd.round_number = m.round_number
   AND COALESCE(jd.photo_index, 0) = COALESCE(jta.photo_index, 0)
  WHERE jd.id IS NULL OR jd.decision IS DISTINCT FROM m.decision
  ORDER BY jta.entry_id, jta.judge_id, m.round_number, COALESCE(jta.photo_index, 0), jta.created_at DESC;

  SELECT count(*)::int INTO v_scanned FROM pg_temp._tag_decision_backfill_plan;

  WITH upd AS (
    UPDATE public.judge_decisions jd
       SET decision = p.decision,
           updated_at = now()
      FROM pg_temp._tag_decision_backfill_plan p
     WHERE jd.id = p.existing_id
       AND jd.decision IS DISTINCT FROM p.decision
    RETURNING jd.id
  )
  SELECT count(*)::int INTO v_updated FROM upd;

  WITH ins AS (
    INSERT INTO public.judge_decisions
      (entry_id, judge_id, round_number, photo_index, decision, updated_at)
    SELECT p.entry_id, p.judge_id, p.round_number, p.photo_index, p.decision, now()
    FROM pg_temp._tag_decision_backfill_plan p
    WHERE p.existing_id IS NULL
    ON CONFLICT (entry_id, judge_id, round_number, photo_index)
    DO UPDATE SET decision = EXCLUDED.decision,
                  updated_at = now()
    RETURNING id
  )
  SELECT count(*)::int INTO v_inserted FROM ins;

  v_fixed := v_inserted + v_updated;

  SELECT COALESCE(jsonb_agg(to_jsonb(s)), '[]'::jsonb)
  INTO v_sample
  FROM (
    SELECT entry_id, judge_id, round_number, photo_index, decision, existing_decision, tag_id
    FROM pg_temp._tag_decision_backfill_plan
    LIMIT 5
  ) s;

  INSERT INTO public.db_audit_logs
    (table_name, operation, row_id, new_data, changed_by)
  VALUES (
    'judging_invariants',
    'backfill_tag_decision_drift',
    'tag_decision_drift',
    jsonb_build_object(
      'fixed', v_fixed,
      'inserted', v_inserted,
      'updated', v_updated,
      'scanned', v_scanned,
      'sample', v_sample,
      'ran_at', now()
    ),
    v_caller
  );

  -- inserted_count now means "fixed rows" for backward-compatible UI text.
  RETURN QUERY SELECT v_fixed, v_scanned, v_sample;
END;
$$;


ALTER FUNCTION "public"."backfill_tag_decision_drift_admin"() OWNER TO "postgres";


