CREATE OR REPLACE FUNCTION "public"."claim_username"("candidate" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  uid uuid := auth.uid();
  updated int;
BEGIN
  IF uid IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_authenticated');
  END IF;
  candidate := lower(trim(candidate));
  IF NOT (candidate ~ '^[a-z0-9_][a-z0-9._]{1,28}[a-z0-9_]$')
     OR candidate ~ '\.\.' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'invalid_format');
  END IF;
  -- Legacy guard bypass (block_custom_url_update trigger)
  PERFORM set_config('app.allow_custom_url_update', 'true', true);
  BEGIN
    UPDATE public.profiles
       SET custom_url = candidate,
           custom_url_changed_at = now()
     WHERE id = uid AND custom_url IS NULL;
    GET DIAGNOSTICS updated = ROW_COUNT;
  EXCEPTION WHEN unique_violation THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'taken');
  END;
  IF updated = 0 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'already_set_or_no_profile');
  END IF;
  INSERT INTO public.custom_url_history (user_id, custom_url, is_current)
  VALUES (uid, candidate, true)
  ON CONFLICT DO NOTHING;
  RETURN jsonb_build_object('ok', true, 'username', candidate);
END;
$_$;


ALTER FUNCTION "public"."claim_username"("candidate" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."classify_judging_tag"("p_label" "text", "p_visible_in_round" integer[]) RETURNS TABLE("family" "text", "advances_to" integer, "blocks_from" integer, "verification_round" integer)
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
  n text := lower(regexp_replace(coalesce(p_label,''), '\s+', ' ', 'g'));
  rnd int := CASE WHEN p_visible_in_round IS NOT NULL AND array_length(p_visible_in_round,1) > 0
                  THEN p_visible_in_round[1] ELSE NULL END;
BEGIN
  -- Verification (check first; phrase is unambiguous)
  IF position('verification required' in n) > 0 THEN
    RETURN QUERY SELECT 'verification'::text, NULL::int, NULL::int, rnd; RETURN;
  END IF;

  -- Progression fail
  IF position('not selected for' in n) > 0 THEN
    RETURN QUERY SELECT 'progression_fail'::text, NULL::int,
      CASE
        WHEN position('2nd round' in n) > 0 THEN 2
        WHEN position('3rd round' in n) > 0 THEN 3
        WHEN position('4th round' in n) > 0 OR position('final round' in n) > 0 THEN 4
        ELSE NULL
      END, NULL::int;
    RETURN;
  END IF;

  -- Rejection
  IF n = 'rejected' THEN
    RETURN QUERY SELECT 'rejection'::text, NULL::int, NULL::int, NULL::int; RETURN;
  END IF;

  -- Progression pass
  IF n = 'accepted' THEN
    RETURN QUERY SELECT 'progression_pass'::text, 2, NULL::int, NULL::int; RETURN;
  END IF;
  IF position('qualified for' in n) > 0 THEN
    RETURN QUERY SELECT 'progression_pass'::text,
      CASE
        WHEN position('2nd round' in n) > 0 OR position('round 2' in n) > 0 THEN 2
        WHEN position('3rd round' in n) > 0 OR position('round 3' in n) > 0 THEN 3
        WHEN position('final round' in n) > 0 OR position('4th round' in n) > 0 OR position('round 4' in n) > 0 THEN 4
        ELSE NULL
      END, NULL::int, NULL::int;
    RETURN;
  END IF;

  -- Awards
  IF n = ANY(ARRAY['winner','1st runner up','2nd runner up','honorable mention',
                   'special jury award','best moment award',
                   'top 10 global photographer','top 50 finalist','top 100 global photographer']) THEN
    RETURN QUERY SELECT 'award'::text, NULL::int, NULL::int, NULL::int; RETURN;
  END IF;

  -- Unknown (no-op)
  RETURN QUERY SELECT 'unknown'::text, NULL::int, NULL::int, NULL::int;
END $$;


ALTER FUNCTION "public"."classify_judging_tag"("p_label" "text", "p_visible_in_round" integer[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."clear_custom_url"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  UPDATE public.custom_url_history
  SET is_current = false, released_at = now()
  WHERE user_id = auth.uid() AND is_current = true;

  -- Set bypass flag for the guard trigger
  PERFORM set_config('app.allow_custom_url_update', 'true', true);

  UPDATE public.profiles
  SET custom_url = NULL, custom_url_changed_at = now()
  WHERE id = auth.uid();
END;
$$;


