CREATE OR REPLACE FUNCTION "public"."compute_entry_rank_score"("_entry_id" "uuid") RETURNS numeric
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH agg AS (
    SELECT 
      AVG(COALESCE(js.score, 0)) AS avg_score,
      AVG(COALESCE(js.composition_score, 0)) AS avg_comp,
      AVG(COALESCE(js.light_score, 0)) AS avg_light
    FROM judge_scores js
    WHERE js.entry_id = _entry_id
  ),
  e AS (
    SELECT EXTRACT(EPOCH FROM created_at) AS subs
    FROM competition_entries WHERE id = _entry_id
  )
  SELECT 
    COALESCE(agg.avg_score, 0) * 1000000000
    + COALESCE(agg.avg_comp, 0) * 1000000
    + COALESCE(agg.avg_light, 0) * 1000
    + (1.0 - COALESCE(e.subs, 0) / 100000000000.0)
  FROM agg, e;
$$;


ALTER FUNCTION "public"."compute_entry_rank_score"("_entry_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."contributor_points_since"("_since" "date") RETURNS TABLE("uid" "uuid", "score" numeric)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH eligible AS (
    -- ACCOUNT ELIGIBILITY. Owner, 2026-08-11: "Only the admin role is excluded
    -- by account role. Do NOT automatically exclude judge, content_editor,
    -- registered_photographer, student, normal user."
    --
    -- The profiles row is what makes a deleted account disappear instantly:
    -- no profile, no score, no ranking, on the very next call. Note that
    -- deleting an account does NOT delete its posts (posts.user_id has no
    -- foreign key to auth.users, which is why admin_purge_orphan_user_data
    -- exists), so this join is doing real work, not decoration.
    SELECT pr.id
    FROM public.profiles pr
    WHERE COALESCE(pr.is_suspended, false) = false
      AND COALESCE(pr.is_banned, false) = false
      AND EXISTS (SELECT 1 FROM auth.users u WHERE u.id = pr.id)
      AND NOT EXISTS (
        SELECT 1 FROM public.user_roles ur
        WHERE ur.user_id = pr.id
          AND ur.role::text = 'admin'
      )
  ),
  post_days AS (
    -- Public photographs only. Private and friends-only earn nothing.
    SELECT p.user_id AS u,
           (p.created_at AT TIME ZONE 'UTC')::date AS d,
           COUNT(*) AS n
    FROM public.posts p
    JOIN eligible e ON e.id = p.user_id
    WHERE p.privacy = 'public'
      AND (_since IS NULL OR (p.created_at AT TIME ZONE 'UTC')::date >= _since)
    GROUP BY 1, 2
  ),
  comment_days AS (
    -- Comments the member WROTE. Comments received on their photographs are
    -- not here at all — that is the whole difference from v1.
    -- Ad comments are excluded by construction: they live in
    -- ad_creative_comments, which is not read by this function.
    SELECT c.u, c.d, COUNT(*) AS n
    FROM (
      SELECT pc.user_id AS u, (pc.created_at AT TIME ZONE 'UTC')::date AS d
      FROM public.post_comments pc
      JOIN eligible e ON e.id = pc.user_id
      WHERE (_since IS NULL OR (pc.created_at AT TIME ZONE 'UTC')::date >= _since)
      UNION ALL
      SELECT ic.user_id AS u, (ic.created_at AT TIME ZONE 'UTC')::date AS d
      FROM public.image_comments ic
      JOIN eligible e ON e.id = ic.user_id
      WHERE ic.is_flagged = false
        AND (_since IS NULL OR (ic.created_at AT TIME ZONE 'UTC')::date >= _since)
    ) c
    GROUP BY 1, 2
  ),
  post_pts AS (
    SELECT pd.u, pd.d,
           LEAST(pd.n, 3) * 10
         + GREATEST(LEAST(pd.n, 6)  - 3, 0) * 5
         + GREATEST(LEAST(pd.n, 10) - 6, 0) * 2 AS pts
    FROM post_days pd
  ),
  comment_pts AS (
    SELECT cd.u, cd.d,
           LEAST(cd.n, 5) * 4
         + GREATEST(LEAST(cd.n, 15) - 5,  0) * 2
         + GREATEST(LEAST(cd.n, 30) - 15, 0) * 1 AS pts
    FROM comment_days cd
  ),
  day_scores AS (
    -- FULL OUTER JOIN of two aggregates, never of raw rows. This is the
    -- deliberate difference from v1, which joins posts against reactions AND
    -- comments in one query: a post with 10 reactions and 8 comments produces
    -- 80 intermediate rows there. Here each side is already one row per
    -- (member, day) before they meet, so nothing multiplies.
    SELECT COALESCE(pp.u, cp.u) AS u,
           COALESCE(pp.pts, 0)  AS ppts,
           COALESCE(cp.pts, 0)  AS cpts
    FROM post_pts pp
    FULL OUTER JOIN comment_pts cp
      ON cp.u = pp.u AND cp.d = pp.d
  )
  SELECT ds.u,
         SUM(3 * (450 * ds.ppts / 53.0 + 350 * ds.cpts / 55.0))
  FROM day_scores ds
  GROUP BY ds.u;
$$;


ALTER FUNCTION "public"."contributor_points_since"("_since" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."contributor_points_since"("_since" "date") IS 'Contributor points per member from live data. _since NULL = lifetime, otherwise from that UTC date. Excludes the admin role, suspended, banned and deleted accounts. Not callable directly - EXECUTE is revoked from everyone so the scores of all members cannot be enumerated; the two public wrappers reach it as SECURITY DEFINER.';



CREATE OR REPLACE FUNCTION "public"."create_pending_deposit"("_user_id" "uuid", "_amount" numeric, "_gateway" "text", "_reference" "text", "_metadata" "jsonb" DEFAULT '{}'::"jsonb", "_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  _txn_id        uuid;
  _existing      uuid;
  _key           text;
  _gateway_label text;
  _safe_ref      text;
BEGIN
  -- 1. Authority: caller must be the user themselves OR service-role (auth.uid() IS NULL).
  IF auth.uid() IS NOT NULL AND auth.uid() IS DISTINCT FROM _user_id THEN
    RAISE EXCEPTION 'Permission denied' USING ERRCODE = '42501';
  END IF;

  -- 2. Validate gateway
  IF _gateway NOT IN ('upi','bank_transfer') THEN
    RAISE EXCEPTION 'Invalid gateway: %', _gateway USING ERRCODE = '22023';
  END IF;

  -- 3. Validate amount (matches submit-deposit edge fn: $1..$50,000)
  IF _amount IS NULL OR _amount < 1 OR _amount > 50000 THEN
    RAISE EXCEPTION 'Amount out of range' USING ERRCODE = '22003';
  END IF;

  -- 4. Validate reference
  IF _reference IS NULL OR length(btrim(_reference)) = 0 THEN
    RAISE EXCEPTION 'Reference required' USING ERRCODE = '22023';
  END IF;
  _safe_ref := left(btrim(_reference), 200);

  _gateway_label := CASE _gateway WHEN 'upi' THEN 'UPI' ELSE 'Bank Transfer' END;
  _key := COALESCE(_idempotency_key, _gateway || ':' || _safe_ref);

  -- 5. Idempotency: same user + same key in last 24h returns the existing txn id.
  SELECT id INTO _existing
  FROM public.wallet_transactions
  WHERE user_id = _user_id
    AND type   = 'deposit'
    AND status = 'pending'
    AND metadata->>'idempotency_key' = _key
    AND created_at > now() - interval '24 hours'
  LIMIT 1;
  IF _existing IS NOT NULL THEN
    RETURN _existing;
  END IF;

  -- 6. Rate limit: 2000 txns/user/hour (mirrors wallet_transaction).
  IF (SELECT COUNT(*) FROM public.wallet_transactions
        WHERE user_id = _user_id
          AND created_at > now() - interval '1 hour') >= 2000 THEN
    RAISE EXCEPTION 'Rate limit exceeded' USING ERRCODE = '54000';
  END IF;

  -- 7. Insert pending row. Frozen shape — does NOT touch wallets.balance.
  INSERT INTO public.wallet_transactions
    (user_id, type, amount, balance_after, description, status, metadata,
     reference_id, reference_type)
  VALUES
    (_user_id,
     'deposit',
     _amount,
     0,
     _gateway_label || ' deposit — Ref: ' || _safe_ref,
     'pending',
     COALESCE(_metadata, '{}'::jsonb)
       || jsonb_build_object(
            'gateway',         _gateway,
            'idempotency_key', _key,
            'submitted_at',    now()
          ),
     NULL,
     NULL)
  RETURNING id INTO _txn_id;

  RETURN _txn_id;
END;
$_$;


ALTER FUNCTION "public"."create_pending_deposit"("_user_id" "uuid", "_amount" numeric, "_gateway" "text", "_reference" "text", "_metadata" "jsonb", "_idempotency_key" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_pending_deposit"("_user_id" "uuid", "_amount" numeric, "_gateway" "text", "_reference" "text", "_metadata" "jsonb", "_idempotency_key" "text") IS 'RLS-HOTFIX-5 Step 1: Server-side pending deposit creator. SECURITY DEFINER. Inserts wallet_transactions row with status=pending, balance_after=0; never mutates wallets.balance. Self-only auth or service-role. Idempotent on (user_id, idempotency_key) within 24h.';



CREATE OR REPLACE FUNCTION "public"."create_system_post"("_content" "text", "_image_url" "text", "_image_urls" "text"[], "_thumbnail_urls" "text"[], "_media_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  _uid uuid := auth.uid();
  _id  uuid;
BEGIN
  IF _uid IS NULL THEN
    RAISE EXCEPTION 'AUTH-0001: sign-in required' USING ERRCODE = 'insufficient_privilege';
  END IF;

  INSERT INTO public.posts (user_id, content, image_url, image_urls, thumbnail_urls, privacy, post_kind, categories)
  VALUES (_uid, _content, _image_url, COALESCE(_image_urls,'{}'), _thumbnail_urls, 'public', 'system', '{}')
  RETURNING id INTO _id;

  IF _media_ids IS NOT NULL AND array_length(_media_ids, 1) > 0 THEN
    BEGIN
      PERFORM public.post_attach_media(_id, _media_ids);
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'MEDIA-4008: system post % published without media references: %', _id, SQLERRM;
    END;
  END IF;

  RETURN _id;
END;
$$;


ALTER FUNCTION "public"."create_system_post"("_content" "text", "_image_url" "text", "_image_urls" "text"[], "_thumbnail_urls" "text"[], "_media_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_system_post"("_content" "text", "_image_url" "text", "_image_urls" "text"[], "_thumbnail_urls" "text"[], "_media_ids" "uuid"[]) IS 'The only way to create a post_kind=system post. Optionally attaches verified media (guarded, all-or-none). Profile-update posts pass NULL because their avatar URL is mutable and cannot carry content identity - see MEDIA-2102.';



CREATE OR REPLACE FUNCTION "public"."current_phase"("p_competition_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_status text;
  v_starts_at timestamptz;
  v_ends_at timestamptz;
  v_voting_ends_at timestamptz;
  v_judging_completed boolean;
  v_legacy_phase text;
BEGIN
  SELECT status, starts_at, ends_at, voting_ends_at, judging_completed, phase
    INTO v_status, v_starts_at, v_ends_at, v_voting_ends_at, v_judging_completed, v_legacy_phase
  FROM public.competitions
  WHERE id = p_competition_id;

  IF NOT FOUND THEN RETURN NULL; END IF;

  RETURN public.current_phase_for(
    v_status, v_starts_at, v_ends_at, v_voting_ends_at, v_judging_completed, v_legacy_phase
  );
END;
$$;


ALTER FUNCTION "public"."current_phase"("p_competition_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."current_phase"("p_competition_id" "uuid") IS 'Phase R5 — Canonical phase resolver. Single source of truth used by edge functions and parity audits. Mirrors src/lib/competitionPhase.ts.';



CREATE OR REPLACE FUNCTION "public"."current_phase_for"("p_status" "text", "p_starts_at" timestamp with time zone, "p_ends_at" timestamp with time zone, "p_voting_ends_at" timestamp with time zone, "p_judging_completed" boolean, "p_legacy_phase" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_now timestamptz := now();
  v_voting_end timestamptz;
BEGIN
  IF p_status = 'archived' THEN RETURN 'archived'; END IF;

  IF p_starts_at IS NOT NULL AND p_ends_at IS NOT NULL THEN
    v_voting_end := COALESCE(p_voting_ends_at, p_ends_at);
    IF v_now < p_starts_at THEN RETURN 'upcoming';
    ELSIF v_now >= p_starts_at AND v_now <= p_ends_at THEN RETURN 'submission_open';
    ELSIF v_now > p_ends_at AND v_now <= v_voting_end THEN RETURN 'voting';
    ELSIF COALESCE(p_judging_completed, false) THEN RETURN 'result';
    ELSE RETURN 'judging';
    END IF;
  END IF;

  IF p_legacy_phase IS NOT NULL AND p_legacy_phase <> '' THEN RETURN p_legacy_phase; END IF;

  IF p_status IS NOT NULL THEN
    RETURN CASE p_status
      WHEN 'draft' THEN 'submission_open'
      WHEN 'open' THEN 'submission_open'
      WHEN 'upcoming' THEN 'submission_open'
      WHEN 'active' THEN 'judging'
      WHEN 'judging' THEN 'judging'
      WHEN 'closed' THEN 'result'
      WHEN 'completed' THEN 'result'
      ELSE 'submission_open'
    END;
  END IF;

  RETURN 'submission_open';
END;
$$;


ALTER FUNCTION "public"."current_phase_for"("p_status" "text", "p_starts_at" timestamp with time zone, "p_ends_at" timestamp with time zone, "p_voting_ends_at" timestamp with time zone, "p_judging_completed" boolean, "p_legacy_phase" "text") OWNER TO "postgres";


