CREATE OR REPLACE FUNCTION "public"."derive_decision_from_score"("_avg" numeric, "_round_number" integer) RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- Null/zero average → Needs Review (judge has not committed any score)
  IF _avg IS NULL OR _avg = 0 THEN
    RETURN 'needs_review';
  END IF;

  -- Round-specific tiering per SOW
  IF _round_number = 2 THEN
    -- 1-6 → Qualified for R2; 7-10 → Shortlisted for R3
    IF _avg >= 7 THEN RETURN 'shortlist'; ELSE RETURN 'qualified'; END IF;

  ELSIF _round_number = 3 THEN
    -- 1-6 → Qualified for R3; 7-10 → Shortlisted for Final
    IF _avg >= 7 THEN RETURN 'shortlist'; ELSE RETURN 'qualified'; END IF;

  ELSIF _round_number = 4 THEN
    -- 1-6 → Qualified for Final; 7-10 → Award-eligible (Finalist; admin assigns Winner/RU placement)
    IF _avg >= 7 THEN RETURN 'finalist'; ELSE RETURN 'qualified'; END IF;
  END IF;

  -- R1 or unknown → no auto-decision (R1 is purely manual decision mode)
  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."derive_decision_from_score"("_avg" numeric, "_round_number" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."derive_status_from_stage_key"("_stage_key" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE PARALLEL SAFE
    SET "search_path" TO ''
    AS $$
  SELECT CASE _stage_key
    -- Round 1
    WHEN 'r1_accepted'            THEN 'round1_qualified'
    WHEN 'r1_shortlisted_r2'      THEN 'shortlisted'
    WHEN 'r1_needs_verification'  THEN 'needs_review'
    WHEN 'r1_rejected'            THEN 'rejected'
    WHEN 'r1_needs_review'        THEN 'needs_review'
    -- Round 2  (Q-V4a: r2_accept → round1_qualified per approved mapping)
    WHEN 'r2_accepted'            THEN 'round1_qualified'
    WHEN 'r2_qualified_r3'        THEN 'round2_qualified'
    WHEN 'r2_not_selected_r3'     THEN 'rejected'
    -- Round 3  (Q-V4a: r3_accept → round2_qualified per approved mapping)
    WHEN 'r3_accepted'            THEN 'round2_qualified'
    WHEN 'r3_qualified_final'     THEN 'finalist'
    WHEN 'r3_not_selected_final'  THEN 'rejected'
    -- Round 4  (Q-V4b: all non-winner R4 awards collapse to finalist)
    WHEN 'r4_winner'              THEN 'winner'
    WHEN 'r4_runner_up_1'         THEN 'finalist'
    WHEN 'r4_runner_up_2'         THEN 'finalist'
    WHEN 'r4_honorary_mention'    THEN 'finalist'
    WHEN 'r4_special_jury'        THEN 'finalist'
    WHEN 'r4_top_50'              THEN 'finalist'
    WHEN 'r4_top_100'             THEN 'finalist'
    WHEN 'r4_finalist'            THEN 'finalist'
    WHEN 'r4_qualified_final'     THEN 'finalist'
    ELSE NULL
  END;
$$;


ALTER FUNCTION "public"."derive_status_from_stage_key"("_stage_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."detect_duplicate_post"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  hash_val text;
  dupe_exists boolean;
BEGIN
  -- Generate hash from content + image URLs
  hash_val := md5(
    COALESCE(NEW.content, '') || '|' ||
    COALESCE(array_to_string(NEW.image_urls, ','), '') || '|' ||
    COALESCE(NEW.image_url, '')
  );

  NEW.content_hash := hash_val;

  -- Serialise check-then-insert for THIS member and THIS content only.
  -- Without it, the read below is of a snapshot a concurrent submit cannot
  -- appear in, and both submits pass the guard (measured: 2 rows).
  PERFORM pg_advisory_xact_lock(hashtextextended(NEW.user_id::text || ':' || hash_val, 0));

  -- Check for duplicate by same user within 10 minutes
  SELECT EXISTS (
    SELECT 1 FROM public.posts
    WHERE user_id = NEW.user_id
      AND content_hash = hash_val
      AND created_at > now() - interval '10 minutes'
  ) INTO dupe_exists;

  IF dupe_exists THEN
    RAISE EXCEPTION 'Duplicate post detected. Please wait before posting similar content.';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."detect_duplicate_post"() OWNER TO "postgres";


