CREATE OR REPLACE FUNCTION "public"."enforce_comment_blocklist"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _kw text;
  _norm_kw text;
  _gap text;
BEGIN
  IF NEW.content IS NULL OR length(btrim(NEW.content)) = 0 THEN
    RETURN NEW;
  END IF;
  FOR _kw IN
    SELECT keyword FROM public.blocked_keywords
    WHERE is_active = true AND severity = 'auto_hide' AND keyword IS NOT NULL AND length(btrim(keyword)) > 0
  LOOP
    -- normalize the keyword to alphanumerics only (chars are then all regex-safe)
    _norm_kw := lower(regexp_replace(_kw, '[^a-zA-Z0-9]', '', 'g'));
    CONTINUE WHEN _norm_kw = '';
    -- build boundary-anchored gap pattern: k[^alnum]*w[^alnum]*...
    _gap := '\y' || regexp_replace(_norm_kw, '(.)', '\1[^a-zA-Z0-9]*', 'g') || '\y';
    IF NEW.content ~* _gap THEN
      RAISE EXCEPTION 'Comment blocked by content filter' USING ERRCODE = 'check_violation';
    END IF;
  END LOOP;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_comment_blocklist"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_entry_fee"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  _entry_fee numeric;
BEGIN
  SELECT entry_fee INTO _entry_fee
  FROM public.competitions
  WHERE id = NEW.competition_id;

  IF _entry_fee IS NOT NULL AND _entry_fee > 0 THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.wallet_transactions
      WHERE user_id = NEW.user_id
        AND reference_id = NEW.competition_id
        AND reference_type = 'competition_entry_fee'
        AND status = 'completed'
        AND amount < 0
    ) THEN
      RAISE EXCEPTION 'Entry fee of $% has not been paid for this competition.', _entry_fee;
    END IF;
  END IF;

  RETURN NEW;
END;
$_$;


