CREATE OR REPLACE FUNCTION "public"."enforce_post_caption_only_update"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF public.has_role(auth.uid(), 'admin'::public.app_role) THEN
    RETURN NEW;
  END IF;

  IF auth.uid() = OLD.user_id THEN
    -- Author may only change `content`. Counter columns
    -- (likes_count, comments_count, shares_count) are intentionally
    -- excluded because they are maintained by server-side triggers,
    -- not by the author's UPDATE statement.
    IF NEW.user_id        IS DISTINCT FROM OLD.user_id        OR
       NEW.image_url      IS DISTINCT FROM OLD.image_url      OR
       NEW.image_urls     IS DISTINCT FROM OLD.image_urls     OR
       NEW.thumbnail_url  IS DISTINCT FROM OLD.thumbnail_url  OR
       NEW.thumbnail_urls IS DISTINCT FROM OLD.thumbnail_urls OR
       NEW.privacy        IS DISTINCT FROM OLD.privacy        OR
       NEW.created_at     IS DISTINCT FROM OLD.created_at     OR
       NEW.content_hash   IS DISTINCT FROM OLD.content_hash   THEN
      RAISE EXCEPTION 'Only the caption can be edited'
        USING ERRCODE = 'check_violation';
    END IF;
    NEW.updated_at := now();
    RETURN NEW;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_post_caption_only_update"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_post_categories"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _bad text;
  _n   integer;
  _client boolean := current_user IN ('authenticated', 'anon');
BEGIN
  -- ── post_kind is not the client's to decide ────────────────────────────────
  IF TG_OP = 'INSERT' THEN
    IF _client THEN NEW.post_kind := 'member'; END IF;
  ELSE
    IF _client THEN NEW.post_kind := OLD.post_kind; END IF;
  END IF;

  -- ── normalise before validating, so 'Portrait' and ' portrait ' both work ──
  -- and a duplicate never counts twice toward the maximum.
  --
  -- ORDER IS PRESERVED. A plain SELECT DISTINCT returns rows in whatever order
  -- the planner likes, so ARRAY['street','night'] came back as {night,street} —
  -- silently reordering something the member chose. Today nothing depends on
  -- the order, but "the first one is the primary category" is an obvious future
  -- ask, and a stored array that quietly shuffles itself would make that
  -- impossible to build on. WITH ORDINALITY keeps the member's own order and
  -- drops later duplicates rather than earlier ones.
  NEW.categories := ARRAY(
    SELECT t.slug FROM (
      SELECT DISTINCT ON (lower(btrim(u.c)))
             lower(btrim(u.c)) AS slug, u.ord
      FROM unnest(COALESCE(NEW.categories, '{}')) WITH ORDINALITY AS u(c, ord)
      WHERE btrim(u.c) <> ''
      ORDER BY lower(btrim(u.c)), u.ord
    ) t
    ORDER BY t.ord
  );
  _n := cardinality(NEW.categories);

  -- ── every slug must exist in the taxonomy AND be active ───────────────────
  SELECT string_agg(c, ', ') INTO _bad
  FROM unnest(NEW.categories) AS c
  WHERE NOT EXISTS (
    SELECT 1 FROM public.categories cat WHERE cat.slug = c AND cat.is_active
  );
  IF _bad IS NOT NULL THEN
    RAISE EXCEPTION 'POST-CAT-001: unknown or inactive category slug(s): %', _bad
      USING ERRCODE = 'check_violation';
  END IF;

  -- ── the minimum, INSERT only ──────────────────────────────────────────────
  --
  -- ⚠ DELIBERATELY ABSENT IN B1. This is the ONE behavioural difference
  -- between this file and the version audited on 2026-08-12.
  --
  -- The rule it will enforce, verbatim, when B2 activates it:
  --
  --     IF NEW.post_kind = 'member' AND _n < 1 THEN
  --       RAISE EXCEPTION 'POST-CAT-002: a member post requires between 1 and
  --                        5 categories' USING ERRCODE = 'check_violation';
  --     END IF;
  --
  -- It is not deleted, it is scheduled: see
  --   supabase/migrations/20260812090000_post_categories_enforce_minimum.sql
  -- which re-creates this whole function with the block restored. B2 changes
  -- nothing else — same normaliser, same slug check, same post_kind pin, same
  -- POST-CAT-003 — so the diff between the two functions is exactly this rule
  -- and nothing may ride along with it.
  --
  -- `_n` is still computed above and is still used by POST-CAT-003 below, so
  -- there is no dead code here and no branch that only exists for B2.
  IF TG_OP = 'INSERT' THEN
    NULL;  -- B1: a member post with zero categories is accepted. B2 refuses it.
  ELSE
    -- On UPDATE the rule is narrower on purpose: a post that HAS categories may
    -- not be stripped of them, but a legacy post that never had any stays
    -- editable. Applying the minimum to every update would make the existing
    -- 204 posts (production count, 2026-08-12) impossible to edit.
    IF NEW.post_kind = 'member'
       AND cardinality(COALESCE(OLD.categories, '{}')) > 0
       AND _n < 1 THEN
      RAISE EXCEPTION 'POST-CAT-003: a categorised post cannot have all its categories removed'
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_post_categories"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_post_draft_rules"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _bad text;
  _n   integer;
  _client boolean := current_user IN ('authenticated', 'anon');
BEGIN
  -- Normalise exactly as posts do, so a draft and the post it becomes agree.
  -- Order is preserved: a plain DISTINCT reorders, and "the first one is the
  -- primary category" is an obvious future ask.
  NEW.categories := ARRAY(
    SELECT t.slug FROM (
      SELECT DISTINCT ON (lower(btrim(u.c)))
             lower(btrim(u.c)) AS slug, u.ord
      FROM unnest(COALESCE(NEW.categories, '{}')) WITH ORDINALITY AS u(c, ord)
      WHERE btrim(u.c) <> ''
      ORDER BY lower(btrim(u.c)), u.ord
    ) t
    ORDER BY t.ord
  );

  -- Slugs must be real and active. A draft may hold ZERO categories - that is
  -- the point of a draft - but it may never hold one that cannot exist.
  SELECT string_agg(c, ', ') INTO _bad
  FROM unnest(NEW.categories) AS c
  WHERE NOT EXISTS (
    SELECT 1 FROM public.categories cat WHERE cat.slug = c AND cat.is_active
  );
  IF _bad IS NOT NULL THEN
    RAISE EXCEPTION 'DRAFT-001: unknown or inactive category slug(s): %', _bad
      USING ERRCODE = 'check_violation';
  END IF;

  -- The cap. Without it, drafts are an unbounded upload channel: 500 drafts of
  -- 10 photos each is 5,000 images one member can park in storage for a week.
  IF TG_OP = 'INSERT' THEN
    SELECT count(*) INTO _n FROM public.post_drafts d WHERE d.user_id = NEW.user_id;
    IF _n >= 20 THEN
      RAISE EXCEPTION 'DRAFT-002: a member may keep at most 20 drafts'
        USING ERRCODE = 'check_violation';
    END IF;
  ELSIF _client THEN
    -- ⚠ BOTH LINES BELOW ARE CLIENT-ONLY, AND THE FIRST VERSION GOT THIS WRONG.
    --
    -- The bug: `updated_at := now()` fired on EVERY update, including the
    -- `UPDATE ... SET expiring_at = now()` inside mark_expiring_post_drafts().
    -- So marking a draft reset the very timestamp the 7-day clock measures,
    -- the mark could never stick, and the whole cleanup chain silently did
    -- nothing. A stale draft would have lived forever. Caught by the harness
    -- returning 0 marked instead of 1.
    --
    -- `updated_at` must mean "when the MEMBER last edited this", not "when any
    -- statement last touched the row". So only a client edit moves it, and the
    -- cleanup functions - which run as the definer, not as authenticated - can
    -- set expiring_at without disturbing the clock.
    NEW.updated_at := now();

    -- And a client may not mark or unmark its own draft. Without this a member
    -- could set expiring_at themselves, hiding the draft from their own list
    -- and queueing its images for deletion. Same pinning pattern as post_kind.
    NEW.expiring_at := OLD.expiring_at;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_post_draft_rules"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_progression_decision_pending_gate"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_gate_round int;
BEGIN
  IF NEW.progression_decision IS NULL THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE'
     AND NEW.progression_decision IS NOT DISTINCT FROM OLD.progression_decision THEN
    RETURN NEW;
  END IF;

  v_gate_round := NULLIF(substring(NEW.progression_decision from '^r([1-4])_'), '')::int;
  IF v_gate_round IS NULL THEN
    v_gate_round := NULLIF(regexp_replace(COALESCE(NEW.current_round, OLD.current_round, ''), '[^0-9]', '', 'g'), '')::int;
  END IF;

  IF v_gate_round IS NOT NULL AND public.any_photo_pending(NEW.id, v_gate_round) THEN
    RAISE EXCEPTION
      'progression_decision cannot be set to % while entry % has pending photos in judged round % (any_photo_pending = TRUE). Phase 3 Step 4 gate.',
      NEW.progression_decision, NEW.id, v_gate_round
      USING ERRCODE = 'P0001';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_progression_decision_pending_gate"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."enforce_progression_decision_pending_gate"() IS 'Blocks progression_decision writes only when the round encoded in that progression decision still has pending eligible photos; avoids checking the next round during promotion.';



CREATE OR REPLACE FUNCTION "public"."enforce_progression_decision_vocabulary"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_active_round int;
  v_valid_keys text;
BEGIN
  IF NEW.progression_decision IS NULL THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE'
     AND OLD.progression_decision IS NOT DISTINCT FROM NEW.progression_decision THEN
    RETURN NEW;
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.v3_stage_catalog
    WHERE stage_key = NEW.progression_decision
      AND (
        is_active = true
        OR stage_key IN ('r2_not_selected_r3', 'r3_not_selected_final')
      )
  ) THEN
    BEGIN
      SELECT public.current_round_int(c.current_round)
      INTO v_active_round
      FROM public.competitions c
      WHERE c.id = NEW.competition_id;
    EXCEPTION WHEN OTHERS THEN
      v_active_round := NULL;
    END;

    SELECT string_agg(stage_key, ', ' ORDER BY stage_key)
    INTO v_valid_keys
    FROM public.v3_stage_catalog
    WHERE (is_active = true OR stage_key IN ('r2_not_selected_r3', 'r3_not_selected_final'))
      AND (v_active_round IS NULL OR round_number = v_active_round);

    RAISE EXCEPTION
      'progression_decision = % is not a valid v3_stage_catalog stage_key (entry=%, competition=%, active_round=%). Valid keys for round %: [%]. See docs/judging/vocabulary.md.',
      NEW.progression_decision,
      NEW.id,
      NEW.competition_id,
      COALESCE(v_active_round::text, 'unknown'),
      COALESCE(v_active_round::text, 'any'),
      COALESCE(v_valid_keys, '(none)')
      USING ERRCODE = 'P0001',
            HINT    = 'Use an active canonical stage_key, or the explicit R2/R3 not-selected stage keys for declared non-progression outcomes.';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_progression_decision_vocabulary"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."enforce_progression_decision_vocabulary"() IS 'Phase 4: enforces progression_decision ∈ v3_stage_catalog (is_active=true). Dynamic — no hardcoded vocabulary. Replaces legacy CHECK constraint progression_decision_valid.';



CREATE OR REPLACE FUNCTION "public"."enforce_round_lock"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _comp_id uuid;
  _round_status text;
  _round_number int;
  _entry_id uuid;
  _row jsonb;
  _current_round_text text;
BEGIN
  -- Trusted internal sync bypass (e.g. tag→decision mirror, backfills).
  IF current_setting('app.bypass_round_lock', true) = 'on' THEN
    IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
  END IF;

  IF TG_OP = 'DELETE' THEN _row := to_jsonb(OLD); ELSE _row := to_jsonb(NEW); END IF;

  _entry_id := NULLIF(_row->>'entry_id','')::uuid;
  IF _entry_id IS NULL THEN
    IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
  END IF;

  IF _row ? 'round_number' AND NULLIF(_row->>'round_number','') IS NOT NULL THEN
    _round_number := (_row->>'round_number')::int;
  END IF;

  IF _round_number IS NULL AND _row ? 'round_id' AND NULLIF(_row->>'round_id','') IS NOT NULL THEN
    SELECT round_number INTO _round_number
    FROM public.judging_rounds WHERE id = (_row->>'round_id')::uuid;
  END IF;

  IF _round_number IS NULL THEN
    SELECT competition_id, current_round
      INTO _comp_id, _current_round_text
    FROM public.competition_entries WHERE id = _entry_id;
    _round_number := NULLIF(regexp_replace(COALESCE(_current_round_text, ''), '\D', '', 'g'), '')::int;
  ELSE
    SELECT competition_id INTO _comp_id
    FROM public.competition_entries WHERE id = _entry_id;
  END IF;

  IF _round_number IS NOT NULL AND _comp_id IS NOT NULL THEN
    SELECT status INTO _round_status
    FROM public.judging_rounds
    WHERE competition_id = _comp_id AND round_number = _round_number;

    IF _round_status = 'completed' THEN
      RAISE EXCEPTION 'This round has been completed. Scoring is locked.';
    END IF;
  END IF;

  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_round_lock"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_status_round_consistency"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _round_int integer;
BEGIN
  -- current_round is TEXT and historically stores values like 'round2', '3', 'r4', etc.
  -- Extract digits before casting; NULL if no digits found.
  _round_int := NULLIF(regexp_replace(COALESCE(NEW.current_round, ''), '\D', '', 'g'), '')::integer;

  IF NEW.status = 'finalist' AND _round_int IS NOT NULL AND _round_int < 3 THEN
    RAISE EXCEPTION 'Finalist status requires round 3 or higher, got round %', NEW.current_round;
  END IF;

  IF NEW.status = 'winner' AND _round_int IS NOT NULL AND _round_int < 4 THEN
    RAISE EXCEPTION 'Winner status requires round 4, got round %', NEW.current_round;
  END IF;

  IF NEW.status = 'submitted' AND _round_int IS NOT NULL AND _round_int > 1 THEN
    RAISE EXCEPTION 'Submitted entries cannot be in round %', NEW.current_round;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_status_round_consistency"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."engagement_collector_health"() RETURNS TABLE("metric" "text", "value" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT 'raw_minutes', COUNT(*)::text FROM public.member_activity_minutes
  UNION ALL
  SELECT 'distinct_members', COUNT(DISTINCT user_id)::text FROM public.member_activity_minutes
  UNION ALL
  SELECT 'first_row', COALESCE(MIN(minute_bucket)::text, 'none') FROM public.member_activity_minutes
  UNION ALL
  SELECT 'last_row', COALESCE(MAX(minute_bucket)::text, 'none') FROM public.member_activity_minutes
  UNION ALL
  SELECT 'public_minutes', COUNT(*)::text FROM public.member_activity_minutes WHERE surface = 'public'
  UNION ALL
  SELECT 'internal_minutes', COUNT(*)::text FROM public.member_activity_minutes WHERE surface = 'internal'
  UNION ALL
  SELECT 'interacted_minutes', COUNT(*)::text FROM public.member_activity_minutes WHERE had_interaction
  UNION ALL
  SELECT 'carried_minutes', COUNT(*)::text FROM public.member_activity_minutes WHERE NOT had_interaction
  UNION ALL
  -- Bounded near 2.0 by the 120s window. A member pinned at the ceiling every
  -- day is a parked tab, not a reader.
  SELECT 'carried_per_interacted',
         COALESCE(ROUND(
           (COUNT(*) FILTER (WHERE NOT had_interaction))::numeric
           / NULLIF(COUNT(*) FILTER (WHERE had_interaction), 0)
         , 2)::text, 'n/a')
  FROM public.member_activity_minutes
  UNION ALL
  -- INVARIANT: nobody can be credited more than the 30-minute cap.
  SELECT 'days_breaching_30min_cap',
         COUNT(*)::text FROM public.contributor_engagement_daily WHERE minutes_credited > 30
  UNION ALL
  -- INVARIANT: the surfaces must add up to the total.
  SELECT 'days_with_surface_mismatch',
         COUNT(*)::text FROM public.contributor_engagement_daily
         WHERE minutes_public + minutes_internal <> minutes_actual
  UNION ALL
  -- INVARIANT: a member cannot have more minutes in a day than the day has had.
  SELECT 'days_exceeding_elapsed_minutes',
         COUNT(*)::text FROM public.contributor_engagement_daily
         WHERE minutes_actual > CASE
           WHEN utc_date < (now() AT TIME ZONE 'UTC')::date THEN 1440
           ELSE EXTRACT(EPOCH FROM (now() AT TIME ZONE 'UTC') - utc_date::timestamp) / 60
         END
  UNION ALL
  SELECT 'rollup_rows', COUNT(*)::text FROM public.contributor_engagement_daily;
$$;


ALTER FUNCTION "public"."engagement_collector_health"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."engagement_collector_health"() IS 'Phase 2a diagnostics: volume, surface split, the carried-to-interacted ratio that exposes over-counting, and three invariants that must all read zero. Aggregate only - no member timeline is exposed.';



CREATE OR REPLACE FUNCTION "public"."engagement_probe_report"("_days" integer DEFAULT 14) RETURNS TABLE("probe_source" "text", "probes" bigint, "covered" bigint, "coverage_pct" numeric)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH launch AS (
    SELECT COALESCE(MIN(minute_bucket), now()) AS t0
    FROM public.member_activity_minutes
  ),
  probe AS (
    SELECT 'posts' AS src, p.user_id AS uid, date_trunc('minute', p.created_at) AS m
    FROM public.posts p, launch l
    WHERE p.created_at >= l.t0
      AND p.created_at >= now() - (_days || ' days')::interval
    UNION ALL
    SELECT 'post_comments', c.user_id, date_trunc('minute', c.created_at)
    FROM public.post_comments c, launch l
    WHERE c.created_at >= l.t0
      AND c.created_at >= now() - (_days || ' days')::interval
  )
  SELECT
    pr.src,
    COUNT(*),
    COUNT(*) FILTER (
      WHERE EXISTS (
        SELECT 1 FROM public.member_activity_minutes a
        WHERE a.user_id = pr.uid AND a.minute_bucket = pr.m
      )
    ),
    ROUND(
      100.0 * COUNT(*) FILTER (
        WHERE EXISTS (
          SELECT 1 FROM public.member_activity_minutes a
          WHERE a.user_id = pr.uid AND a.minute_bucket = pr.m
        )
      ) / NULLIF(COUNT(*), 0)
    , 1)
  FROM probe pr
  GROUP BY pr.src;
$$;


ALTER FUNCTION "public"."engagement_probe_report"("_days" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."engagement_probe_report"("_days" integer) IS 'Independent correctness check: every post and comment timestamp proves the member was present in that minute, so a matching activity bucket must exist. Low coverage means the collector is losing time.';



CREATE OR REPLACE FUNCTION "public"."enqueue_email"("queue_name" "text", "payload" "jsonb") RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- Named queues only. Everything else is rejected before pgmq is touched,
  -- so an unrecognised name can no longer create a table as a side effect.
  IF queue_name IS NULL OR queue_name NOT IN ('transactional_emails', 'auth_emails') THEN
    RAISE EXCEPTION 'enqueue_email: queue % is not permitted', coalesce(queue_name, '<null>')
      USING ERRCODE = '42501';
  END IF;

  RETURN pgmq.send(queue_name, payload);
EXCEPTION
  -- Reachable only for an allow-listed name, because the check above already
  -- passed. Preserves the original create-if-missing resilience without the
  -- arbitrary-table-creation half of it.
  WHEN undefined_table THEN
    PERFORM pgmq.create(queue_name);
    RETURN pgmq.send(queue_name, payload);
END;
$$;


ALTER FUNCTION "public"."enqueue_email"("queue_name" "text", "payload" "jsonb") OWNER TO "postgres";


