CREATE OR REPLACE FUNCTION "public"."expire_gift_credit"("_gift_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _gift    record;
  _balance numeric;
  _deduct  numeric;
BEGIN
  -- Lock the gift row: a concurrent run blocks, then sees is_expired and skips.
  SELECT id, user_id, amount, reason, is_expired
  INTO _gift
  FROM public.gift_announcements
  WHERE id = _gift_id
  FOR UPDATE;

  IF _gift IS NULL THEN
    RETURN jsonb_build_object('skipped', true, 'reason', 'not_found');
  END IF;
  IF _gift.is_expired THEN
    RETURN jsonb_build_object('skipped', true, 'reason', 'already_expired');
  END IF;

  SELECT balance INTO _balance FROM public.wallets WHERE user_id = _gift.user_id;
  _deduct := LEAST(COALESCE(_gift.amount, 0), COALESCE(_balance, 0));

  IF _deduct > 0 THEN
    -- reference_id/type tag makes the debit idempotent via uq_wallet_txn_gift_expiry.
    PERFORM public.wallet_transaction(
      _gift.user_id,
      'gift_expiry',
      -_deduct,
      'Gift credit expired: "' || COALESCE(_gift.reason, '') || '"',
      _gift.id,
      'gift_expiry',
      jsonb_build_object('expired_gift_id', _gift.id, 'original_amount', _gift.amount)
    );
  END IF;

  UPDATE public.gift_announcements SET is_expired = true WHERE id = _gift_id;

  RETURN jsonb_build_object('expired', true, 'deducted', _deduct);
END;
$$;


ALTER FUNCTION "public"."expire_gift_credit"("_gift_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."expiring_post_drafts"() RETURNS TABLE("id" "uuid", "urls" "text"[])
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT d.id,
         -- ORDER BY is not decoration: without it DISTINCT returns whatever
         -- order the planner likes, so two runs over the same draft log
         -- different object lists and become impossible to compare when
         -- diagnosing a purge that half-failed.
         ARRAY(SELECT DISTINCT u FROM unnest(
           COALESCE(d.image_urls,'{}') ||
           COALESCE(d.thumbnail_urls,'{}') ||
           CASE WHEN d.image_url IS NULL THEN '{}'::text[] ELSE ARRAY[d.image_url] END
         ) AS u WHERE u IS NOT NULL AND u <> '' ORDER BY u)
  FROM public.post_drafts d
  WHERE d.expiring_at IS NOT NULL
  ORDER BY d.expiring_at
  LIMIT 500;
$$;


ALTER FUNCTION "public"."expiring_post_drafts"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."extract_hashtags"("body" "text") RETURNS "text"[]
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
  select coalesce(array_agg(distinct t), '{}')
  from (
    select public.normalize_hashtag(m[1]) as t
    from regexp_matches(coalesce(body, ''), '#([A-Za-z0-9_]{1,60})', 'g') as m
  ) s
  where t is not null;
$$;


ALTER FUNCTION "public"."extract_hashtags"("body" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."extract_hashtags"("body" "text") IS 'Every hashtag in a caption, canonical and de-duplicated. Mirrors RichContentRenderer''s #(\w+) so a tag that renders as a link is a tag that gets counted, with a 60-char ceiling against pathological input.';



CREATE OR REPLACE FUNCTION "public"."extract_photo_hashes"("_meta" "jsonb") RETURNS TABLE("photo_index" integer, "sha256" "text", "phash" "text")
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
  SELECT
    (idx - 1)::integer AS photo_index,
    NULLIF(elem->'image_hash'->>'sha256', '') AS sha256,
    NULLIF(elem->'image_hash'->>'phash',  '') AS phash
  FROM jsonb_array_elements(COALESCE(_meta, '[]'::jsonb)) WITH ORDINALITY AS arr(elem, idx)
  WHERE elem ? 'image_hash'
    AND elem->'image_hash' IS NOT NULL
    AND elem->'image_hash' <> 'null'::jsonb;
$$;


ALTER FUNCTION "public"."extract_photo_hashes"("_meta" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fan_out_new_post"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _followers int;
  _cap       constant int := 1000;
BEGIN
  -- Public posts only. A private or friends-only photo notifies nobody.
  IF NEW.privacy IS DISTINCT FROM 'public' THEN
    RETURN NEW;
  END IF;

  SELECT count(*) INTO _followers
    FROM public.follows f
   WHERE f.following_id = NEW.user_id
     AND f.follower_id <> NEW.user_id;

  IF _followers = 0 THEN
    RETURN NEW;
  END IF;

  IF _followers > _cap THEN
    RAISE LOG 'fan_out_new_post: author % has % followers, capping notification fan-out at %',
              NEW.user_id, _followers, _cap;
  END IF;

  INSERT INTO public.user_notifications (user_id, type, title, message, reference_id, actor_id)
  SELECT f.follower_id,
         'new_post_from_following',
         'New post',
         'just shared a post',
         NEW.id,
         NEW.user_id
    FROM public.follows f
   WHERE f.following_id = NEW.user_id
     AND f.follower_id <> NEW.user_id
   ORDER BY f.created_at DESC
   LIMIT _cap;

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  -- Posting must never fail because notifications failed. But it must not be
  -- silent either -- that is how push stayed broken from launch to 2026-08-01.
  RAISE LOG 'fan_out_new_post failed for post % by % : % / %',
            NEW.id, NEW.user_id, SQLSTATE, SQLERRM;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fan_out_new_post"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."feed_candidates"("_seed" "text", "_categories" "text"[] DEFAULT NULL::"text"[], "_recent" integer DEFAULT 500, "_sample" integer DEFAULT 1000, "_own" integer DEFAULT 100, "_friends" integer DEFAULT 200) RETURNS TABLE("id" "uuid", "user_id" "uuid", "created_at" timestamp with time zone, "bucket" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH me AS (SELECT auth.uid() AS uid)
  (SELECT p.id, p.user_id, p.created_at, p.viewer_bucket_stable
     FROM public.posts p
    WHERE p.is_public AND (_categories IS NULL OR p.categories && _categories)
    ORDER BY p.created_at DESC LIMIT _recent)
  UNION
  (SELECT p.id, p.user_id, p.created_at, p.viewer_bucket_stable
     FROM public.posts p
    WHERE p.is_public AND (_categories IS NULL OR p.categories && _categories)
      AND p.rand_key >= (hashtextextended(_seed, 0) & 2147483647)::float8 / 2147483647.0
    ORDER BY p.rand_key LIMIT _sample)
  UNION
  (SELECT p.id, p.user_id, p.created_at, p.viewer_bucket_stable
     FROM public.posts p, me
    WHERE p.user_id = me.uid AND (_categories IS NULL OR p.categories && _categories)
    ORDER BY p.created_at DESC LIMIT _own)
  UNION
  (SELECT p.id, p.user_id, p.created_at, p.viewer_bucket_stable
     FROM public.posts p
    WHERE p.privacy = 'friends'
      AND (_categories IS NULL OR p.categories && _categories)
      AND p.user_id IN (
        SELECT CASE WHEN f.requester_id = m2.uid THEN f.addressee_id ELSE f.requester_id END
          FROM public.friendships f, me m2
         WHERE f.status = 'accepted'
           AND (f.requester_id = m2.uid OR f.addressee_id = m2.uid))
    ORDER BY p.created_at DESC LIMIT _friends);
$$;


ALTER FUNCTION "public"."feed_candidates"("_seed" "text", "_categories" "text"[], "_recent" integer, "_sample" integer, "_own" integer, "_friends" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."feed_rank_score"("_id" "uuid", "_bucket" integer, "_seed" "text") RETURNS double precision
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT _bucket + (hashtextextended(_id::text || _seed, 0) & 2147483647)::float8
                   / 2147483647.0 * 6.0;
$$;


