CREATE OR REPLACE FUNCTION "public"."flag_post_for_review"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE _hit text;
BEGIN
  _hit := public._flag_review_keyword_hit(NEW.content);
  IF _hit IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.post_reports
    WHERE post_id = NEW.id AND reason = 'auto_flagged_keyword' AND reporter_id IS NULL
  ) THEN
    INSERT INTO public.post_reports (post_id, reporter_id, reason, details, status)
    VALUES (NEW.id, NULL, 'auto_flagged_keyword', 'Auto-flagged by blocklist review keyword', 'pending');
  END IF;
  RETURN NULL;
END;
$$;


