CREATE OR REPLACE FUNCTION "public"."generate_certificate_identifiers"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.certificate_id IS NULL THEN
    NEW.certificate_id := 'CERT-' || UPPER(SUBSTRING(REPLACE(gen_random_uuid()::text, '-', '') FROM 1 FOR 10));
  END IF;
  IF NEW.verification_token IS NULL THEN
    NEW.verification_token := REPLACE(gen_random_uuid()::text, '-', '') || REPLACE(gen_random_uuid()::text, '-', '');
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."generate_certificate_identifiers"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_competition_slug"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  base_slug text;
  final_slug text;
  counter integer := 0;
BEGIN
  IF NEW.slug IS NULL OR NEW.slug = '' THEN
    base_slug := lower(regexp_replace(regexp_replace(NEW.title, '[^a-zA-Z0-9\s-]', '', 'g'), '\s+', '-', 'g'));
    final_slug := base_slug;
    
    LOOP
      EXIT WHEN NOT EXISTS (SELECT 1 FROM public.competitions WHERE slug = final_slug AND id != NEW.id);
      counter := counter + 1;
      final_slug := base_slug || '-' || counter;
    END LOOP;
    
    NEW.slug := final_slug;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."generate_competition_slug"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_ad_analytics"("_since" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH imp_agg AS (
    SELECT
      slot_id,
      placement,
      device,
      ad_source,
      event_type,
      COUNT(*) AS cnt,
      COALESCE(SUM(revenue_estimate), 0) AS revenue
    FROM public.ad_impressions
    WHERE created_at >= _since
    GROUP BY slot_id, placement, device, ad_source, event_type
  ),
  conv_agg AS (
    SELECT
      ad_id,
      placement,
      device,
      conversion_type,
      COUNT(*) AS cnt,
      COALESCE(SUM(conversion_value), 0) AS conv_value
    FROM public.ad_conversions
    WHERE created_at >= _since
    GROUP BY ad_id, placement, device, conversion_type
  )
  SELECT jsonb_build_object(
    'impressions', COALESCE((SELECT jsonb_agg(jsonb_build_object(
      'slot_id', slot_id,
      'placement', placement,
      'device', device,
      'ad_source', ad_source,
      'event_type', event_type,
      'count', cnt,
      'revenue', revenue
    )) FROM imp_agg), '[]'::jsonb),
    'conversions', COALESCE((SELECT jsonb_agg(jsonb_build_object(
      'ad_id', ad_id,
      'placement', placement,
      'device', device,
      'conversion_type', conversion_type,
      'count', cnt,
      'conv_value', conv_value
    )) FROM conv_agg), '[]'::jsonb)
  );
$$;


ALTER FUNCTION "public"."get_ad_analytics"("_since" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_ad_autoscale_stats"("_since" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH imp_agg AS (
    SELECT slot_id, ad_source, event_type, COUNT(*) AS cnt
    FROM public.ad_impressions
    WHERE created_at >= _since AND event_type IN ('impression', 'click')
    GROUP BY slot_id, ad_source, event_type
  ),
  conv_agg AS (
    -- BUG-073: group conversions by their OWN recorded ad_source (ad_id == slot_id).
    -- Legacy rows have ad_source NULL and are left for the edge's last-click fallback.
    SELECT ad_id, ad_source, COUNT(*) AS cnt
    FROM public.ad_conversions
    WHERE created_at >= _since
    GROUP BY ad_id, ad_source
  ),
  click_sources AS (
    SELECT DISTINCT ON (slot_id) slot_id, ad_source
    FROM public.ad_impressions
    WHERE created_at >= _since AND event_type = 'click'
    ORDER BY slot_id, created_at DESC
  )
  SELECT jsonb_build_object(
    'impressions', COALESCE((SELECT jsonb_agg(jsonb_build_object(
      'slot_id', slot_id, 'ad_source', ad_source, 'event_type', event_type, 'count', cnt
    )) FROM imp_agg), '[]'::jsonb),
    'conversions', COALESCE((SELECT jsonb_agg(jsonb_build_object(
      'ad_id', ad_id, 'ad_source', ad_source, 'count', cnt
    )) FROM conv_agg), '[]'::jsonb),
    'click_sources', COALESCE((SELECT jsonb_agg(jsonb_build_object(
      'slot_id', slot_id, 'ad_source', ad_source
    )) FROM click_sources), '[]'::jsonb)
  );
$$;


ALTER FUNCTION "public"."get_ad_autoscale_stats"("_since" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_ad_engagement"("_creative_ids" "uuid"[]) RETURNS TABLE("creative_id" "uuid", "like_count" integer, "comment_count" integer, "share_count" integer, "my_reaction" "text", "my_shared" boolean, "reaction_counts" "jsonb")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    c.id AS creative_id,
    COALESCE((SELECT count(*) FROM public.ad_creative_reactions r WHERE r.creative_id = c.id), 0)::integer,
    COALESCE((SELECT count(*) FROM public.ad_creative_comments m WHERE m.creative_id = c.id), 0)::integer,
    COALESCE((SELECT count(*) FROM public.ad_creative_shares s WHERE s.creative_id = c.id), 0)::integer,
    (SELECT r.reaction_type FROM public.ad_creative_reactions r
      WHERE r.creative_id = c.id AND r.user_id = auth.uid()),
    EXISTS (SELECT 1 FROM public.ad_creative_shares s
      WHERE s.creative_id = c.id AND s.user_id = auth.uid()),
    COALESCE((
      SELECT jsonb_object_agg(t.reaction_type, t.n)
      FROM (
        SELECT r.reaction_type, count(*) AS n
        FROM public.ad_creative_reactions r
        WHERE r.creative_id = c.id
        GROUP BY r.reaction_type
      ) t
    ), '{}'::jsonb)
  FROM public.ad_creatives c
  WHERE c.id = ANY(_creative_ids);
$$;


ALTER FUNCTION "public"."get_ad_engagement"("_creative_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_ad_engagement"("_creative_ids" "uuid"[]) IS 'Counts and the calling member''s own reaction/share state for a batch of ad creatives. One round trip for a whole screen of feed ads.';



CREATE OR REPLACE FUNCTION "public"."get_app_event_counts_admin"("_hours" integer DEFAULT 24) RETURNS TABLE("code" "text", "event" "text", "severity" "text", "occurrences" bigint, "members" bigint, "last_seen" timestamp with time zone, "sample" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT public.has_role(auth.uid(), 'admin'::app_role) THEN
    RAISE EXCEPTION 'admin only';
  END IF;
  RETURN QUERY
  SELECT e.code,
         (array_agg(e.event ORDER BY e.created_at DESC))[1],
         (array_agg(e.severity ORDER BY e.created_at DESC))[1],
         count(*), count(DISTINCT e.user_id), max(e.created_at),
         (array_agg(e.reason ORDER BY e.created_at DESC))[1]
    FROM public.client_errors e
   WHERE e.code IS NOT NULL
     AND e.created_at > now() - make_interval(hours => GREATEST(1, LEAST(_hours, 720)))
   GROUP BY e.code
   ORDER BY count(*) DESC;
END;
$$;


ALTER FUNCTION "public"."get_app_event_counts_admin"("_hours" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_app_events_admin"("_hours" integer DEFAULT 24, "_code" "text" DEFAULT NULL::"text", "_severity" "text" DEFAULT NULL::"text", "_limit" integer DEFAULT 200) RETURNS TABLE("id" "uuid", "created_at" timestamp with time zone, "code" "text", "event" "text", "severity" "text", "message" "text", "fn" "text", "src_file" "text", "reason" "text", "expected" "text", "actual" "text", "next_step" "text", "duration_ms" integer, "correlation_id" "text", "user_id" "uuid", "platform" "text", "app_build" "text", "url" "text", "detail" "jsonb")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT public.has_role(auth.uid(), 'admin'::app_role) THEN
    RAISE EXCEPTION 'admin only';
  END IF;
  RETURN QUERY
  SELECT e.id, e.created_at, e.code, e.event, e.severity, e.message, e.fn,
         e.src_file, e.reason, e.expected, e.actual, e.next_step,
         e.duration_ms, e.correlation_id, e.user_id, e.platform, e.app_build,
         e.url, e.detail
    FROM public.client_errors e
   WHERE e.code IS NOT NULL
     AND e.created_at > now() - make_interval(hours => GREATEST(1, LEAST(_hours, 720)))
     AND (_code IS NULL OR e.code = _code)
     AND (_severity IS NULL OR e.severity = lower(_severity))
   ORDER BY e.created_at DESC
   LIMIT GREATEST(1, LEAST(COALESCE(_limit, 200), 1000));
END;
$$;


ALTER FUNCTION "public"."get_app_events_admin"("_hours" integer, "_code" "text", "_severity" "text", "_limit" integer) OWNER TO "postgres";


