CREATE OR REPLACE FUNCTION "public"."get_broadcast_feed"("_exclude_ids" "uuid"[], "_limit" integer, "_newest_first" integer) RETURNS TABLE("id" "uuid", "user_id" "uuid", "content" "text", "image_url" "text", "image_urls" "text"[], "privacy" "text", "created_at" timestamp with time zone, "likes_count" integer, "comments_count" integer, "shares_count" integer, "feed_tier" "text", "author_name" "text", "author_avatar" "text", "thumbnail_urls" "text"[], "categories" "text"[])
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT * FROM public.get_broadcast_feed(_exclude_ids, _limit, _newest_first, NULL::text[]);
$$;


ALTER FUNCTION "public"."get_broadcast_feed"("_exclude_ids" "uuid"[], "_limit" integer, "_newest_first" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_broadcast_feed"("_exclude_ids" "uuid"[], "_limit" integer, "_newest_first" integer, "_categories" "text"[]) RETURNS TABLE("id" "uuid", "user_id" "uuid", "content" "text", "image_url" "text", "image_urls" "text"[], "privacy" "text", "created_at" timestamp with time zone, "likes_count" integer, "comments_count" integer, "shares_count" integer, "feed_tier" "text", "author_name" "text", "author_avatar" "text", "thumbnail_urls" "text"[], "categories" "text"[])
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH seed AS (
    -- Per viewer, per hour. Old callers send no seed, so one is derived: each
    -- member gets their own shuffle, stable for an hour, reshuffled after —
    -- closer to the old per-call random() re-deal than a fixed seed would be,
    -- and it keeps _exclude_ids paging coherent within the hour.
    SELECT to_char(now(), 'YYYYMMDDHH24') || coalesce(auth.uid()::text, 'anon') AS s
  ),
  pool AS (
    SELECT c.id, c.user_id, c.created_at, c.bucket
    FROM seed, public.feed_candidates(seed.s, _categories) c
    WHERE NOT (c.id = ANY(COALESCE(_exclude_ids, '{}'::uuid[])))
  ),
  visible AS (
    SELECT pl.id, p.user_id, p.content, p.image_url, p.image_urls, p.privacy,
           p.created_at, p.likes_count, p.comments_count, p.shares_count, pl.bucket
    FROM pool pl
    JOIN public.posts p ON p.id = pl.id
  ),
  newest AS (
    SELECT v.*, row_number() OVER (ORDER BY v.created_at DESC, v.id) AS rn
    FROM visible v
    ORDER BY v.created_at DESC, v.id
    LIMIT GREATEST(_newest_first, 0)
  ),
  my_events AS (
    SELECT fe.post_id,
           count(*) FILTER (WHERE fe.event_type = 'view') AS views,
           count(*) FILTER (WHERE fe.event_type = 'skip') AS skips,
           max(fe.created_at)                             AS last_seen_at
    FROM public.feed_events fe
    WHERE fe.user_id = auth.uid()
      AND fe.event_type IN ('view', 'skip')
    GROUP BY fe.post_id
  ),
  seen AS (
    SELECT e.post_id, e.last_seen_at
    FROM my_events e
    WHERE e.views > 0
       OR e.skips >= 2
       OR (e.skips = 1 AND e.last_seen_at > now() - interval '12 hours')
  ),
  -- The count(DISTINCT) LATERAL that used to run once per visible post is gone.
  -- viewer_bucket_stable carries the same signal, precomputed. That LATERAL was
  -- 1,032 of 1,072 buffers at 210 posts and 97% of the cost at 100k.
  unseen_ranked AS (
    SELECT v.*,
           row_number() OVER (
             ORDER BY public.feed_rank_score(v.id, v.bucket, (SELECT s FROM seed)) ASC, v.id
           ) AS rn
    FROM visible v
    WHERE NOT EXISTS (SELECT 1 FROM seen s WHERE s.post_id = v.id)
      AND NOT EXISTS (SELECT 1 FROM newest n WHERE n.id = v.id)
  ),
  seen_ranked AS (
    SELECT v.*,
           row_number() OVER (
             ORDER BY floor(extract(epoch FROM (now() - s.last_seen_at)) / 86400.0) DESC,
                      public.feed_rank_score(v.id, v.bucket, (SELECT s FROM seed)) ASC
           ) AS rn
    FROM visible v
    JOIN seen s ON s.post_id = v.id
    WHERE NOT EXISTS (SELECT 1 FROM newest n WHERE n.id = v.id)
  ),
  ranked AS (
    SELECT x.id, x.user_id, x.content, x.image_url, x.image_urls, x.privacy,
           x.created_at, x.likes_count, x.comments_count, x.shares_count,
           x.feed_tier, x.tier_order, x.rn
    FROM (
      SELECT n.id, n.user_id, n.content, n.image_url, n.image_urls, n.privacy,
             n.created_at, n.likes_count, n.comments_count, n.shares_count,
             'newest'::text AS feed_tier, 0 AS tier_order, n.rn
      FROM newest n
      UNION ALL
      SELECT u.id, u.user_id, u.content, u.image_url, u.image_urls, u.privacy,
             u.created_at, u.likes_count, u.comments_count, u.shares_count,
             'unseen'::text AS feed_tier, 1 AS tier_order, u.rn
      FROM unseen_ranked u
      WHERE u.rn <= _limit
      UNION ALL
      SELECT s.id, s.user_id, s.content, s.image_url, s.image_urls, s.privacy,
             s.created_at, s.likes_count, s.comments_count, s.shares_count,
             'recycled'::text AS feed_tier, 2 AS tier_order, s.rn
      FROM seen_ranked s
      WHERE s.rn <= _limit
    ) x
    ORDER BY x.tier_order ASC, x.rn ASC
    LIMIT _limit
  )
  SELECT r.id, r.user_id, r.content, r.image_url, r.image_urls, r.privacy,
         r.created_at, r.likes_count, r.comments_count, r.shares_count,
         r.feed_tier,
         ppd.full_name  AS author_name,
         ppd.avatar_url AS author_avatar,
         p.thumbnail_urls,
         p.categories
  FROM ranked r
  LEFT JOIN public.profiles_public_data ppd ON ppd.id = r.user_id
  LEFT JOIN public.posts p                  ON p.id  = r.id
  ORDER BY r.tier_order ASC, r.rn ASC;
$$;


ALTER FUNCTION "public"."get_broadcast_feed"("_exclude_ids" "uuid"[], "_limit" integer, "_newest_first" integer, "_categories" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_certificate_drift_admin"("p_competition_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("certificate_id" "uuid", "cert_title" "text", "cert_type" "text", "cert_user_id" "uuid", "reference_id" "uuid", "entry_id" "uuid", "entry_user_id" "uuid", "entry_status" "text", "entry_placement" "text", "entry_certificate_ready" boolean, "competition_id" "uuid", "issued_at" timestamp with time zone, "drift_type" "text", "severity" "text", "reason" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT public.has_role(auth.uid(), 'admin') THEN
    RAISE EXCEPTION 'forbidden: admin only';
  END IF;

  RETURN QUERY
  WITH cert_entry AS (
    SELECT
      c.id AS cert_id,
      c.title AS c_title,
      c.type AS c_type,
      c.user_id AS c_user,
      c.reference_id AS c_ref,
      c.issued_at AS c_issued,
      e.id AS e_id,
      e.user_id AS e_user,
      e.status AS e_status,
      e.placement AS e_placement,
      e.certificate_ready AS e_ready,
      e.competition_id AS comp_id,
      comp.status AS comp_status
    FROM public.certificates c
    JOIN public.competition_entries e ON e.id = c.reference_id
    JOIN public.competitions comp ON comp.id = e.competition_id
    WHERE c.reference_id IS NOT NULL
      AND c.type IN ('competition_winner','winner','finalist','participation')
      AND comp.status <> 'archived'
      AND (p_competition_id IS NULL OR e.competition_id = p_competition_id)
  )
  SELECT
    cert_id, c_title, c_type, c_user, c_ref,
    e_id, e_user, e_status, e_placement, e_ready, comp_id,
    c_issued,
    'wrong_recipient'::text,
    'critical'::text,
    format('Certificate user_id (%s) does not match entry owner (%s)', c_user, e_user)
  FROM cert_entry
  WHERE c_user IS DISTINCT FROM e_user

  UNION ALL
  SELECT
    cert_id, c_title, c_type, c_user, c_ref,
    e_id, e_user, e_status, e_placement, e_ready, comp_id,
    c_issued,
    'stale_eligibility'::text,
    'high'::text,
    'Certificate issued but entry is no longer certificate_ready (entry may have been reverted)'::text
  FROM cert_entry
  WHERE e_ready = false

  UNION ALL
  SELECT
    cert_id, c_title, c_type, c_user, c_ref,
    e_id, e_user, e_status, e_placement, e_ready, comp_id,
    c_issued,
    'type_mismatch'::text,
    'elevated'::text,
    format('Cert type "%s" does not match entry placement "%s" / status "%s"', c_type, COALESCE(e_placement,'—'), COALESCE(e_status,'—'))
  FROM cert_entry
  WHERE (c_type IN ('winner','competition_winner') AND e_placement IS DISTINCT FROM 'winner')
     OR (c_type = 'finalist' AND e_status NOT IN ('finalist','round2_qualified','round1_qualified'))

  ORDER BY 14, 13;
END;
$$;


ALTER FUNCTION "public"."get_certificate_drift_admin"("p_competition_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_certificate_readiness_drift_admin"("_competition_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("entry_id" "uuid", "competition_id" "uuid", "competition_title" "text", "competition_phase" "text", "status" "text", "certificate_ready" boolean, "reason" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT has_role(auth.uid(), 'admin') THEN
    RAISE EXCEPTION 'Forbidden: admin role required';
  END IF;

  RETURN QUERY
  SELECT 
    ce.id, ce.competition_id, c.title, c.phase, ce.status, ce.certificate_ready,
    CASE
      WHEN ce.status IN ('winner','runner_up_1','runner_up_2','special_jury','honorary_mention')
        THEN 'awarded_missing_certificate'
      WHEN ce.status IN ('finalist','round1_qualified','round2_qualified','shortlisted')
           AND c.phase = 'result'
        THEN 'qualified_in_completed_comp_missing_certificate'
      ELSE 'unexpected'
    END AS reason
  FROM competition_entries ce
  JOIN competitions c ON c.id = ce.competition_id
  WHERE ce.certificate_ready = false
    AND (_competition_id IS NULL OR ce.competition_id = _competition_id)
    AND (
      ce.status IN ('winner','runner_up_1','runner_up_2','special_jury','honorary_mention')
      OR (ce.status IN ('finalist','round1_qualified','round2_qualified','shortlisted')
          AND c.phase = 'result')
    );
END;
$$;


ALTER FUNCTION "public"."get_certificate_readiness_drift_admin"("_competition_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_client_error_stats_admin"("_hours" integer DEFAULT 24) RETURNS TABLE("hour_bucket" timestamp with time zone, "kind" "text", "platform" "text", "app_build" "text", "occurrences" bigint, "members" bigint, "sample" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT public.has_role(auth.uid(), 'admin'::app_role) THEN
    RAISE EXCEPTION 'admin only';
  END IF;
  RETURN QUERY
  SELECT date_trunc('hour', e.created_at), e.kind, e.platform, e.app_build,
         count(*), count(DISTINCT e.user_id),
         (array_agg(e.message ORDER BY e.created_at DESC))[1]
  FROM public.client_errors e
  WHERE e.created_at > now() - make_interval(hours => GREATEST(1, LEAST(_hours, 720)))
  GROUP BY 1,2,3,4
  ORDER BY 1 DESC, 5 DESC;
END;
$$;


ALTER FUNCTION "public"."get_client_error_stats_admin"("_hours" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_competition_duplicate_clusters"("_competition_id" "uuid") RETURNS TABLE("cluster_key" "text", "match_type" "text", "entry_id" "uuid", "photo_index" integer, "user_id" "uuid", "entry_title" "text", "photo_url" "text", "thumbnail_url" "text", "created_at" timestamp with time zone, "matched_against_entry" "uuid", "matched_against_photo" integer, "hamming_distance" integer)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _caller uuid := auth.uid();
  _allowed boolean;
BEGIN
  IF _caller IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  SELECT public.has_role(_caller, 'admin'::app_role) OR EXISTS (
    SELECT 1 FROM public.competition_judges
    WHERE competition_id = _competition_id AND judge_id = _caller
  ) INTO _allowed;

  IF NOT _allowed THEN
    RAISE EXCEPTION 'Permission denied: not a judge for this competition';
  END IF;

  RETURN QUERY
  WITH photo_hashes AS (
    SELECT
      ce.id   AS entry_id,
      ce.user_id,
      ce.title,
      ce.created_at,
      ce.photos,
      ce.photo_thumbnails,
      ph.photo_index,
      ph.sha256,
      ph.phash
    FROM public.competition_entries ce
    CROSS JOIN LATERAL public.extract_photo_hashes(ce.photo_meta) ph
    WHERE ce.competition_id = _competition_id
      AND ce.status NOT IN ('rejected')
  ),
  -- exact sha256 collisions
  exact_pairs AS (
    SELECT
      a.sha256 AS cluster_key,
      'exact'::text AS match_type,
      a.entry_id,
      a.photo_index,
      a.user_id,
      a.title AS entry_title,
      a.photos[a.photo_index + 1] AS photo_url,
      COALESCE(a.photo_thumbnails[a.photo_index + 1], a.photos[a.photo_index + 1]) AS thumbnail_url,
      a.created_at,
      b.entry_id AS matched_against_entry,
      b.photo_index AS matched_against_photo,
      0 AS hamming_distance
    FROM photo_hashes a
    JOIN photo_hashes b
      ON a.sha256 = b.sha256
     AND a.sha256 IS NOT NULL
     AND (a.entry_id <> b.entry_id OR a.photo_index <> b.photo_index)
  ),
  -- perceptual collisions (only when not already exact-matched)
  similar_pairs AS (
    SELECT
      LEAST(a.phash, b.phash) || '~' || GREATEST(a.phash, b.phash) AS cluster_key,
      'similar'::text AS match_type,
      a.entry_id,
      a.photo_index,
      a.user_id,
      a.title AS entry_title,
      a.photos[a.photo_index + 1] AS photo_url,
      COALESCE(a.photo_thumbnails[a.photo_index + 1], a.photos[a.photo_index + 1]) AS thumbnail_url,
      a.created_at,
      b.entry_id AS matched_against_entry,
      b.photo_index AS matched_against_photo,
      public.hex_hamming_distance(a.phash, b.phash) AS hamming_distance
    FROM photo_hashes a
    JOIN photo_hashes b
      ON a.phash IS NOT NULL
     AND b.phash IS NOT NULL
     AND length(a.phash) = length(b.phash)
     AND (a.entry_id <> b.entry_id OR a.photo_index <> b.photo_index)
     AND (a.sha256 IS NULL OR b.sha256 IS NULL OR a.sha256 <> b.sha256)
    WHERE public.hex_hamming_distance(a.phash, b.phash) <= 6
  )
  SELECT * FROM exact_pairs
  UNION ALL
  SELECT * FROM similar_pairs
  ORDER BY match_type, cluster_key, created_at;
END;
$$;


ALTER FUNCTION "public"."get_competition_duplicate_clusters"("_competition_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_competition_raw_commitments"("_competition_id" "uuid") RETURNS TABLE("entry_id" "uuid", "photo_index" integer, "user_id" "uuid", "entry_title" "text", "photo_url" "text", "thumbnail_url" "text", "photo_title" "text", "raw_required" boolean, "exif_available" boolean, "committed_at" timestamp with time zone, "source" "text", "raw_delivered_at" timestamp with time zone, "raw_file_url" "text", "admin_verified_at" timestamp with time zone, "admin_verified_by" "uuid")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _caller uuid := auth.uid();
  _allowed boolean;
BEGIN
  IF _caller IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  SELECT public.has_role(_caller, 'admin'::app_role) OR EXISTS (
    SELECT 1 FROM public.competition_judges
    WHERE competition_id = _competition_id AND judge_id = _caller
  ) INTO _allowed;

  IF NOT _allowed THEN
    RAISE EXCEPTION 'Permission denied: not a judge for this competition';
  END IF;

  RETURN QUERY
  WITH photo_meta_unnested AS (
    SELECT
      ce.id AS entry_id,
      ce.user_id,
      ce.title AS entry_title,
      ce.photos,
      ce.photo_thumbnails,
      (idx - 1)::integer AS photo_index,
      elem AS meta
    FROM public.competition_entries ce
    CROSS JOIN LATERAL jsonb_array_elements(COALESCE(ce.photo_meta, '[]'::jsonb))
      WITH ORDINALITY AS arr(elem, idx)
    WHERE ce.competition_id = _competition_id
      AND ce.status NOT IN ('rejected')
  ),
  flagged AS (
    SELECT
      pmu.entry_id,
      pmu.photo_index,
      pmu.user_id,
      pmu.entry_title,
      pmu.photos[pmu.photo_index + 1] AS photo_url,
      COALESCE(pmu.photo_thumbnails[pmu.photo_index + 1], pmu.photos[pmu.photo_index + 1]) AS thumbnail_url,
      NULLIF(pmu.meta->>'title', '') AS photo_title,
      COALESCE((pmu.meta->>'raw_required')::boolean, false) AS raw_required,
      COALESCE((pmu.meta->>'exif_available')::boolean, false) AS exif_available
    FROM photo_meta_unnested pmu
    WHERE COALESCE((pmu.meta->>'raw_required')::boolean, false) = true
  )
  SELECT
    f.entry_id,
    f.photo_index,
    f.user_id,
    f.entry_title,
    f.photo_url,
    f.thumbnail_url,
    f.photo_title,
    f.raw_required,
    f.exif_available,
    rc.committed_at,
    rc.source,
    rc.raw_delivered_at,
    rc.raw_file_url,
    rc.admin_verified_at,
    rc.admin_verified_by
  FROM flagged f
  LEFT JOIN LATERAL (
    SELECT *
    FROM public.raw_commitments r
    WHERE r.entry_id = f.entry_id
      AND r.photo_index = f.photo_index
    ORDER BY r.committed_at DESC
    LIMIT 1
  ) rc ON true
  ORDER BY f.entry_title, f.photo_index;
END;
$$;


ALTER FUNCTION "public"."get_competition_raw_commitments"("_competition_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_contributor_scores"("_user_ids" "uuid"[]) RETURNS TABLE("user_id" "uuid", "contributor_score" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT c.uid, ROUND(c.score)::integer
  FROM public.contributor_points_since(NULL::date) c
  WHERE c.uid = ANY(_user_ids)
    AND c.score > 0;
$$;


