CREATE OR REPLACE FUNCTION "public"."get_derived_status_drift_admin"() RETURNS TABLE("entry_id" "uuid", "competition_id" "uuid", "cached_value" "text", "canonical_value" "text", "status" "text", "current_round" "text", "stage_key" "text", "placement" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT (public.has_role(auth.uid(), 'admin') OR public.has_role(auth.uid(), 'super_admin')) THEN
    RAISE EXCEPTION 'forbidden: admin role required';
  END IF;

  RETURN QUERY
  SELECT  e.id,
          e.competition_id,
          e.public_status_derived,
          v.public_status,
          e.status,
          e.current_round,
          e.stage_key,
          e.placement
    FROM  public.competition_entries e
    JOIN  public.entry_public_status v ON v.entry_id = e.id
   WHERE  e.public_status_derived IS DISTINCT FROM v.public_status;
END;
$$;


