CREATE OR REPLACE FUNCTION "public"."get_feed_candidates"("_network_ids" "uuid"[], "_recent_limit" integer DEFAULT 120, "_network_limit" integer DEFAULT 150, "_popular_limit" integer DEFAULT 100) RETURNS TABLE("id" "uuid", "user_id" "uuid", "content" "text", "image_url" "text", "image_urls" "text"[], "privacy" "text", "created_at" timestamp with time zone, "likes_count" integer, "comments_count" integer, "shares_count" integer, "source_type" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH recent AS (
    SELECT p.id, p.user_id, p.content, p.image_url, p.image_urls, p.privacy,
           p.created_at, p.likes_count, p.comments_count, p.shares_count,
           'recent'::text AS source_type
    FROM public.posts p
    WHERE p.privacy = 'public'
      AND p.created_at >= now() - interval '48 hours'
    ORDER BY p.created_at DESC
    LIMIT _recent_limit
  ),
  network AS (
    SELECT p.id, p.user_id, p.content, p.image_url, p.image_urls, p.privacy,
           p.created_at, p.likes_count, p.comments_count, p.shares_count,
           'network'::text AS source_type
    FROM public.posts p
    WHERE p.user_id = ANY(_network_ids)
      AND (p.privacy = 'public' OR p.user_id = (SELECT auth.uid()))
    ORDER BY p.created_at DESC
    LIMIT _network_limit
  ),
  popular AS (
    SELECT p.id, p.user_id, p.content, p.image_url, p.image_urls, p.privacy,
           p.created_at, p.likes_count, p.comments_count, p.shares_count,
           'popular'::text AS source_type
    FROM public.posts p
    WHERE p.privacy = 'public'
      AND p.created_at >= now() - interval '7 days'
    ORDER BY p.created_at DESC
    LIMIT _popular_limit
  ),
  combined AS (
    SELECT * FROM recent
    UNION ALL
    SELECT * FROM network
    UNION ALL
    SELECT * FROM popular
  )
  SELECT DISTINCT ON (c.id) c.*
  FROM combined c
  WHERE NOT EXISTS (
    SELECT 1 FROM public.profiles pr
    WHERE pr.id = c.user_id
      AND (pr.is_banned IS TRUE OR pr.is_suspended IS TRUE)
  )
  ORDER BY c.id, c.created_at DESC;
$$;


ALTER FUNCTION "public"."get_feed_candidates"("_network_ids" "uuid"[], "_recent_limit" integer, "_network_limit" integer, "_popular_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_feed_stories_bar"() RETURNS TABLE("user_id" "uuid", "full_name" "text", "avatar_url" "text", "is_official" boolean, "latest_story_at" timestamp with time zone, "story_count" integer, "has_unseen" boolean)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH me AS (SELECT auth.uid() AS uid),
  official AS (SELECT public.get_primary_admin_user_id() AS oid),
  active AS (
    -- Every user with at least one live story. No follow/friend filter:
    -- stories are public to the whole community.
    SELECT s.user_id,
           max(s.created_at) AS latest_story_at,
           count(*)::int      AS story_count,
           bool_or(sv.story_id IS NULL) AS has_unseen
    FROM public.stories s
    LEFT JOIN public.story_views sv
      ON sv.story_id = s.id AND sv.viewer_id = (SELECT uid FROM me)
    WHERE s.expires_at > now()
      AND s.user_id <> (SELECT uid FROM me)   -- own stories live in the "Your Story" bubble
    GROUP BY s.user_id
  )
  SELECT a.user_id,
         p.full_name,
         p.avatar_url,
         (a.user_id = (SELECT oid FROM official)) AS is_official,
         a.latest_story_at,
         a.story_count,
         a.has_unseen
  FROM active a
  JOIN public.profiles_public_data p ON p.id = a.user_id
  ORDER BY a.latest_story_at DESC
  LIMIT 100;
$$;


ALTER FUNCTION "public"."get_feed_stories_bar"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_flag"("flag_key" "text") RETURNS boolean
