CREATE OR REPLACE FUNCTION "public"."get_gated_entry_status"("p_entry_ids" "uuid"[]) RETURNS TABLE("entry_id" "uuid", "competition_id" "uuid", "public_status" "text", "public_round" "text", "public_placement" "text", "public_progression_note" "text", "public_r4_tags" "text"[], "has_pending_verification" boolean, "verification_overrides_status" boolean, "is_published_any_round" boolean)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    ce.id,
    ce.competition_id,
    COALESCE(ce.public_status_derived, v.public_status),
    COALESCE(ce.public_round_derived,  v.public_round),
    COALESCE(ce.public_placement_derived, v.public_placement),
    COALESCE(ce.public_progression_note_derived, v.public_progression_note),
    COALESCE(ce.public_r4_tags_derived, v.public_r4_tags),
    false,
    false,
    EXISTS (
      SELECT 1 FROM public.competition_round_publish crp
       WHERE crp.competition_id = ce.competition_id
         AND crp.published_at IS NOT NULL
    )
  FROM public.competition_entries ce
  LEFT JOIN public.entry_public_status v ON v.entry_id = ce.id
  WHERE ce.id = ANY(p_entry_ids);
$$;


ALTER FUNCTION "public"."get_gated_entry_status"("p_entry_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_gated_entry_status"("p_entry_ids" "uuid"[]) IS 'Phase 3 · Step 2. Adds entry-level pending gate via any_photo_pending(): if ANY photo in entry.current_round has no valid judge_decisions row, public_status collapses to judging_in_progress and placement / r4_tags / progression_note are nulled. No fallback to legacy progression_decision read.';



CREATE OR REPLACE FUNCTION "public"."get_gated_status_runtime_drift_admin"("p_entry_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS TABLE("entry_id" "uuid", "field" "text", "cache_value" "text", "view_value" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'super_admin')) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  RETURN QUERY
  SELECT ce.id, 'public_status'::text, ce.public_status_derived, v.public_status
    FROM public.competition_entries ce
    JOIN public.entry_public_status v ON v.entry_id = ce.id
   WHERE (p_entry_ids IS NULL OR ce.id = ANY(p_entry_ids))
     AND ce.public_status_derived IS DISTINCT FROM v.public_status
  UNION ALL
  SELECT ce.id, 'public_round', ce.public_round_derived, v.public_round
    FROM public.competition_entries ce
    JOIN public.entry_public_status v ON v.entry_id = ce.id
   WHERE (p_entry_ids IS NULL OR ce.id = ANY(p_entry_ids))
     AND ce.public_round_derived IS DISTINCT FROM v.public_round
  UNION ALL
  SELECT ce.id, 'public_placement', ce.public_placement_derived, v.public_placement
    FROM public.competition_entries ce
    JOIN public.entry_public_status v ON v.entry_id = ce.id
   WHERE (p_entry_ids IS NULL OR ce.id = ANY(p_entry_ids))
     AND ce.public_placement_derived IS DISTINCT FROM v.public_placement
  UNION ALL
  SELECT ce.id, 'public_progression_note',
         ce.public_progression_note_derived, v.public_progression_note
    FROM public.competition_entries ce
    JOIN public.entry_public_status v ON v.entry_id = ce.id
   WHERE (p_entry_ids IS NULL OR ce.id = ANY(p_entry_ids))
     AND ce.public_progression_note_derived IS DISTINCT FROM v.public_progression_note
  UNION ALL
  SELECT ce.id, 'public_r4_tags',
         array_to_string(ce.public_r4_tags_derived,','),
         array_to_string(v.public_r4_tags,',')
    FROM public.competition_entries ce
    JOIN public.entry_public_status v ON v.entry_id = ce.id
   WHERE (p_entry_ids IS NULL OR ce.id = ANY(p_entry_ids))
     AND ce.public_r4_tags_derived IS DISTINCT FROM v.public_r4_tags;
END;
$$;


ALTER FUNCTION "public"."get_gated_status_runtime_drift_admin"("p_entry_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_gift_drift_admin"() RETURNS TABLE("drift_type" "text", "announcement_id" "uuid", "user_id" "uuid", "gift_credit_id" "uuid", "expected_amount" numeric, "actual_amount" numeric, "is_expired" boolean, "created_at" timestamp with time zone, "notes" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT has_role(auth.uid(), 'admin') THEN
    RAISE EXCEPTION 'Forbidden: admin role required';
  END IF;

  RETURN QUERY
  -- A) Announcements with no matching wallet tx
  SELECT 'announcement_no_wallet_credit'::text,
    ga.id, ga.user_id, ga.gift_credit_id, ga.amount, NULL::numeric,
    ga.is_expired, ga.created_at,
    CASE WHEN ga.is_expired THEN 'Expired without crediting' ELSE 'Active gift not yet credited' END
  FROM gift_announcements ga
  WHERE NOT EXISTS (
    SELECT 1 FROM wallet_transactions wt
    WHERE wt.user_id = ga.user_id
      AND wt.reference_id = ga.gift_credit_id
      AND wt.type = 'gift'
      AND wt.status = 'completed'
  )
  UNION ALL
  -- B) Amount mismatch between announcement and wallet tx
  SELECT 'amount_mismatch'::text,
    ga.id, ga.user_id, ga.gift_credit_id, ga.amount, wt.amount,
    ga.is_expired, ga.created_at,
    'Wallet credit amount differs from announcement'
  FROM gift_announcements ga
  JOIN wallet_transactions wt
    ON wt.user_id = ga.user_id
   AND wt.reference_id = ga.gift_credit_id
   AND wt.type = 'gift'
   AND wt.status = 'completed'
  WHERE wt.amount <> ga.amount
  UNION ALL
  -- C) Wallet gift credit with no source announcement (orphan)
  SELECT 'orphan_wallet_credit'::text,
    NULL, wt.user_id, wt.reference_id, NULL::numeric, wt.amount,
    NULL::boolean, wt.created_at,
    'Wallet credited but no gift_announcement row exists'
  FROM wallet_transactions wt
  WHERE wt.type = 'gift'
    AND wt.status = 'completed'
    AND wt.reference_id IS NOT NULL
    AND NOT EXISTS (
      SELECT 1 FROM gift_announcements ga
      WHERE ga.user_id = wt.user_id AND ga.gift_credit_id = wt.reference_id
    );
END;
$$;


ALTER FUNCTION "public"."get_gift_drift_admin"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_judge_collusion_admin"("p_competition_id" "uuid" DEFAULT NULL::"uuid", "p_min_overlap" integer DEFAULT 10, "p_min_correlation" numeric DEFAULT 0.9) RETURNS TABLE("competition_id" "uuid", "judge_a" "uuid", "judge_b" "uuid", "shared_entries" integer, "pearson_r" numeric, "mean_diff" numeric, "severity" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT public.has_role(auth.uid(), 'admin') THEN
    RAISE EXCEPTION 'forbidden: admin only';
  END IF;

  RETURN QUERY
  WITH paired AS (
    SELECT
      ce.competition_id AS comp_id,
      js.judge_id,
      js.entry_id,
      js.photo_index,
      js.score::NUMERIC AS score
    FROM public.judge_scores js
    JOIN public.competition_entries ce ON ce.id = js.entry_id
    JOIN public.competitions c ON c.id = ce.competition_id
    WHERE js.score IS NOT NULL
      AND c.status <> 'archived'
      AND (p_competition_id IS NULL OR ce.competition_id = p_competition_id)
  ),
  pairs AS (
    SELECT
      a.comp_id,
      a.judge_id AS judge_a,
      b.judge_id AS judge_b,
      a.score AS score_a,
      b.score AS score_b
    FROM paired a
    JOIN paired b
      ON a.comp_id = b.comp_id
     AND a.entry_id = b.entry_id
     AND a.photo_index = b.photo_index
     AND a.judge_id < b.judge_id
  ),
  agg AS (
    SELECT
      p.comp_id,
      p.judge_a,
      p.judge_b,
      COUNT(*)::INT AS n,
      CORR(p.score_a, p.score_b)::NUMERIC AS r,
      AVG(p.score_a - p.score_b)::NUMERIC AS avg_diff
    FROM pairs p
    GROUP BY p.comp_id, p.judge_a, p.judge_b
    HAVING COUNT(*) >= p_min_overlap
  )
  SELECT
    a.comp_id AS competition_id,
    a.judge_a,
    a.judge_b,
    a.n AS shared_entries,
    ROUND(a.r, 4) AS pearson_r,
    ROUND(a.avg_diff, 3) AS mean_diff,
    CASE
      WHEN ABS(a.r) >= 0.98 THEN 'critical'
      WHEN ABS(a.r) >= 0.95 THEN 'high'
      ELSE 'elevated'
    END AS severity
  FROM agg a
  WHERE a.r IS NOT NULL
    AND ABS(a.r) >= p_min_correlation
  ORDER BY ABS(a.r) DESC, a.n DESC;
END;
$$;


ALTER FUNCTION "public"."get_judge_collusion_admin"("p_competition_id" "uuid", "p_min_overlap" integer, "p_min_correlation" numeric) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_judge_collusion_admin"("p_competition_id" "uuid", "p_min_overlap" integer, "p_min_correlation" numeric) IS 'Phase K: Forensic collusion detector. Returns judge pairs with Pearson r >= threshold over >= min_overlap shared scored photos. Admin-only.';



CREATE OR REPLACE FUNCTION "public"."get_judge_entries_page"("_competition_id" "uuid", "_round_number" integer, "_cursor_created_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "_cursor_id" "uuid" DEFAULT NULL::"uuid", "_limit" integer DEFAULT 10) RETURNS TABLE("id" "uuid", "title" "text", "description" "text", "photos" "text"[], "photo_thumbnails" "text"[], "user_id" "uuid", "status" "text", "created_at" timestamp with time zone, "competition_id" "uuid", "placement" "text", "is_ai_generated" boolean, "ai_detection_result" "jsonb", "exif_data" "jsonb", "view_count" integer, "current_round" "text", "next_cursor_created_at" timestamp with time zone, "next_cursor_id" "uuid", "has_more" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
#variable_conflict use_column
DECLARE
  _caller            uuid := auth.uid();
  _is_admin          boolean;
  _is_assigned_judge boolean;
  _assignment_mode   text;
  _effective_limit   integer;
  _fetch_limit       integer;
  _assigned_ids      uuid[];
  _eligible_ids      uuid[];
  _rows              record;
  _row_count         integer := 0;
  _has_more          boolean := false;
BEGIN
  IF _caller IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  _is_admin := public.has_role(_caller, 'admin'::app_role);

  SELECT EXISTS (
    SELECT 1 FROM public.competition_judges cj
    WHERE cj.competition_id = _competition_id AND cj.judge_id = _caller
  ) INTO _is_assigned_judge;

  IF NOT (_is_admin OR _is_assigned_judge) THEN
    RAISE EXCEPTION 'Permission denied: not a judge for this competition';
  END IF;

  IF _round_number IS NULL OR _round_number < 1 OR _round_number > 4 THEN
    RAISE EXCEPTION 'Invalid round number: %', _round_number;
  END IF;

  _effective_limit := LEAST(GREATEST(COALESCE(_limit, 10), 1), 100);
  _fetch_limit     := _effective_limit + 1;

  SELECT judge_assignment_mode INTO _assignment_mode
  FROM public.competitions WHERE id = _competition_id;

  IF _assignment_mode = 'distributed' AND NOT _is_admin THEN
    SELECT COALESCE(array_agg(entry_id), ARRAY[]::uuid[])
    INTO _assigned_ids
    FROM public.judge_entry_assignments
    WHERE competition_id = _competition_id AND judge_id = _caller;

    IF array_length(_assigned_ids, 1) IS NULL THEN
      RETURN;
    END IF;
  END IF;

  IF _round_number >= 2 THEN
    -- Only count shortlists from currently-assigned judges.
    SELECT COALESCE(array_agg(DISTINCT jd.entry_id), ARRAY[]::uuid[])
    INTO _eligible_ids
    FROM public.judge_decisions jd
    JOIN public.competition_entries ce ON ce.id = jd.entry_id
    JOIN public.competition_judges cj
      ON cj.judge_id = jd.judge_id
     AND cj.competition_id = _competition_id
    WHERE ce.competition_id = _competition_id
      AND jd.round_number   = _round_number - 1
      AND jd.decision IN ('shortlist','shortlisted');

    IF array_length(_eligible_ids, 1) IS NULL THEN
      RETURN;
    END IF;
  END IF;

  FOR _rows IN
    SELECT
      ce.id, ce.title, ce.description, ce.photos, ce.photo_thumbnails,
      ce.user_id, ce.status, ce.created_at, ce.competition_id, ce.placement,
      ce.is_ai_generated, ce.ai_detection_result, ce.exif_data,
      ce.view_count, ce.current_round
    FROM public.competition_entries ce
    WHERE ce.competition_id = _competition_id
      AND (_cursor_created_at IS NULL OR (ce.created_at, ce.id) < (_cursor_created_at, _cursor_id))
      AND (_assigned_ids IS NULL OR ce.id = ANY(_assigned_ids))
      AND (
        _round_number = 1
        OR (_eligible_ids IS NOT NULL AND ce.id = ANY(_eligible_ids))
      )
    ORDER BY ce.created_at DESC, ce.id DESC
    LIMIT _fetch_limit
  LOOP
    _row_count := _row_count + 1;
    IF _row_count > _effective_limit THEN
      _has_more := true;
      EXIT;
    END IF;

    id                  := _rows.id;
    title               := _rows.title;
    description         := _rows.description;
    photos              := _rows.photos;
    photo_thumbnails    := _rows.photo_thumbnails;
    user_id             := _rows.user_id;
    status              := _rows.status;
    created_at          := _rows.created_at;
    competition_id      := _rows.competition_id;
    placement           := _rows.placement;
    is_ai_generated     := _rows.is_ai_generated;
    ai_detection_result := _rows.ai_detection_result;
    exif_data           := _rows.exif_data;
    view_count          := _rows.view_count;
    current_round       := _rows.current_round;
    next_cursor_created_at := NULL;
    next_cursor_id      := NULL;
    has_more            := false;
    RETURN NEXT;
  END LOOP;

  RETURN;
END;
$$;


ALTER FUNCTION "public"."get_judge_entries_page"("_competition_id" "uuid", "_round_number" integer, "_cursor_created_at" timestamp with time zone, "_cursor_id" "uuid", "_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_judge_entries_page_filtered"("_competition_id" "uuid", "_round_number" integer, "_bucket" "text" DEFAULT NULL::"text", "_cursor_created_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "_cursor_id" "uuid" DEFAULT NULL::"uuid", "_limit" integer DEFAULT 10) RETURNS TABLE("id" "uuid", "title" "text", "description" "text", "photos" "text"[], "photo_thumbnails" "text"[], "user_id" "uuid", "status" "text", "created_at" timestamp with time zone, "competition_id" "uuid", "placement" "text", "is_ai_generated" boolean, "ai_detection_result" "jsonb", "exif_data" "jsonb", "view_count" integer, "current_round" "text", "bucket" "text", "matching_photo_indexes" integer[], "next_cursor_created_at" timestamp with time zone, "next_cursor_id" "uuid", "has_more" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
#variable_conflict use_column
DECLARE
  _caller            uuid := auth.uid();
  _is_admin          boolean;
  _is_assigned_judge boolean;
  _assignment_mode   text;
  _effective_limit   integer;
  _fetch_limit       integer;
  _assigned_ids      uuid[];
  _eligible_ids      uuid[];
  _candidate_ids     uuid[];
  _bucket_norm       text;
  _allowed_buckets   text[];
  _rows              record;
  _row_count         integer := 0;
  _has_more          boolean := false;
BEGIN
  -- ── 1. Auth ─────────────────────────────────────────────────────────────
  IF _caller IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  _is_admin := public.has_role(_caller, 'admin'::app_role);

  SELECT EXISTS (
    SELECT 1 FROM public.competition_judges cj
    WHERE cj.competition_id = _competition_id AND cj.judge_id = _caller
  ) INTO _is_assigned_judge;

  IF NOT (_is_admin OR _is_assigned_judge) THEN
    RAISE EXCEPTION 'Permission denied: not a judge for this competition';
  END IF;

  -- ── 2. Round validation ────────────────────────────────────────────────
  IF _round_number IS NULL OR _round_number < 1 OR _round_number > 4 THEN
    RAISE EXCEPTION 'Invalid round number: %', _round_number;
  END IF;

  _effective_limit := LEAST(GREATEST(COALESCE(_limit, 10), 1), 100);
  _fetch_limit     := _effective_limit + 1;

  -- ── 3. Bucket validation (Master Key v2 §5: retired keys are forbidden)
  _bucket_norm := NULLIF(TRIM(LOWER(_bucket)), '');

  IF _bucket_norm IN ('not_selected_r3', 'not_selected_final',
                      'r2_not_selected', 'r3_not_selected') THEN
    RAISE EXCEPTION
      'Bucket % is a retired derived label, not a queryable stored bucket. '
      'See Master Key v2 §5.', _bucket_norm;
  END IF;

  IF _bucket_norm IS NOT NULL THEN
    _allowed_buckets := CASE _round_number
      WHEN 1 THEN ARRAY['accept','accepted','shortlist','shortlisted','needs_review','reject','rejected']
      WHEN 2 THEN ARRAY['accept','accepted','shortlist','shortlisted','qualified_r3']
      WHEN 3 THEN ARRAY['accept','accepted','shortlist','shortlisted','qualified_final','shortlisted_final']
      WHEN 4 THEN ARRAY[]::text[]   -- R4 uses tags, no bucket filter
    END;

    IF NOT (_bucket_norm = ANY(_allowed_buckets)) THEN
      RAISE EXCEPTION
        'Bucket % is not valid for round %. Allowed: %',
        _bucket_norm, _round_number, _allowed_buckets;
    END IF;
  END IF;

  -- ── 4. Distributed-mode assignment scope ──────────────────────────────
  SELECT judge_assignment_mode INTO _assignment_mode
  FROM public.competitions WHERE id = _competition_id;

  IF _assignment_mode = 'distributed' AND NOT _is_admin THEN
    SELECT COALESCE(array_agg(entry_id), ARRAY[]::uuid[])
    INTO _assigned_ids
    FROM public.judge_entry_assignments
    WHERE competition_id = _competition_id AND judge_id = _caller;

    IF array_length(_assigned_ids, 1) IS NULL THEN
      RETURN;
    END IF;
  END IF;

  -- ── 5. Round eligibility (mirror existing get_judge_entries_page) ─────
  IF _round_number >= 2 THEN
    SELECT COALESCE(array_agg(DISTINCT jd.entry_id), ARRAY[]::uuid[])
    INTO _eligible_ids
    FROM public.judge_decisions jd
    JOIN public.competition_entries ce ON ce.id = jd.entry_id
    JOIN public.competition_judges cj
      ON cj.judge_id = jd.judge_id
     AND cj.competition_id = _competition_id
    WHERE ce.competition_id = _competition_id
      AND jd.round_number   = _round_number - 1
      AND jd.decision IN ('shortlist','shortlisted');

    IF array_length(_eligible_ids, 1) IS NULL THEN
      RETURN;
    END IF;
  END IF;

  -- ── 6. Bucket filter via per-photo CONSENSUS (aggregate, not per-judge) ─
  IF _bucket_norm IS NOT NULL THEN
    -- Candidate set = entries in this competition+round that pass scope/eligibility
    WITH scope_entries AS (
      SELECT ce.id
      FROM public.competition_entries ce
      WHERE ce.competition_id = _competition_id
        AND (_assigned_ids IS NULL OR ce.id = ANY(_assigned_ids))
        AND (_round_number = 1 OR ce.id = ANY(_eligible_ids))
    ),
    consensus AS (
      SELECT *
      FROM public.get_per_photo_consensus(
        ARRAY(SELECT id FROM scope_entries)
      )
      WHERE round_number = _round_number
    )
    SELECT COALESCE(array_agg(DISTINCT entry_id), ARRAY[]::uuid[])
    INTO _candidate_ids
    FROM consensus
    WHERE has_consensus = true
      AND (
        decision = _bucket_norm
        OR (_bucket_norm IN ('accept','accepted')              AND decision IN ('accept','accepted'))
        OR (_bucket_norm IN ('shortlist','shortlisted','qualified_r3','qualified_final','shortlisted_final')
            AND decision IN ('shortlist','shortlisted','qualified_r3','qualified_final','shortlisted_final'))
        OR (_bucket_norm IN ('reject','rejected')              AND decision IN ('reject','rejected'))
        OR (_bucket_norm = 'needs_review'                       AND decision = 'needs_review')
      );

    IF _candidate_ids IS NULL OR array_length(_candidate_ids, 1) IS NULL THEN
      RETURN;
    END IF;
  END IF;

  -- ── 7. Page rows + per-row matching photo_indexes ─────────────────────
  FOR _rows IN
    SELECT
      ce.id, ce.title, ce.description, ce.photos, ce.photo_thumbnails,
      ce.user_id, ce.status, ce.created_at, ce.competition_id, ce.placement,
      ce.is_ai_generated, ce.ai_detection_result, ce.exif_data,
      ce.view_count, ce.current_round
    FROM public.competition_entries ce
    WHERE ce.competition_id = _competition_id
      AND (_cursor_created_at IS NULL OR (ce.created_at, ce.id) < (_cursor_created_at, _cursor_id))
      AND (_assigned_ids IS NULL OR ce.id = ANY(_assigned_ids))
      AND (_round_number = 1 OR ce.id = ANY(_eligible_ids))
      AND (_bucket_norm IS NULL OR ce.id = ANY(_candidate_ids))
    ORDER BY ce.created_at DESC, ce.id DESC
    LIMIT _fetch_limit
  LOOP
    _row_count := _row_count + 1;
    IF _row_count > _effective_limit THEN
      _has_more := true;
      EXIT;
    END IF;

    id                  := _rows.id;
    title               := _rows.title;
    description         := _rows.description;
    photos              := _rows.photos;
    photo_thumbnails    := _rows.photo_thumbnails;
    user_id             := _rows.user_id;
    status              := _rows.status;
    created_at          := _rows.created_at;
    competition_id      := _rows.competition_id;
    placement           := _rows.placement;
    is_ai_generated     := _rows.is_ai_generated;
    ai_detection_result := _rows.ai_detection_result;
    exif_data           := _rows.exif_data;
    view_count          := _rows.view_count;
    current_round       := _rows.current_round;
    bucket              := _bucket_norm;

    -- Which photos in this entry actually match the bucket (consensus grain)
    IF _bucket_norm IS NULL THEN
      matching_photo_indexes := NULL;
    ELSE
      SELECT COALESCE(array_agg(c.photo_index ORDER BY c.photo_index), ARRAY[]::integer[])
      INTO matching_photo_indexes
      FROM public.get_per_photo_consensus(ARRAY[_rows.id]) c
      WHERE c.round_number = _round_number
        AND c.has_consensus = true
        AND (
          c.decision = _bucket_norm
          OR (_bucket_norm IN ('accept','accepted')         AND c.decision IN ('accept','accepted'))
          OR (_bucket_norm IN ('shortlist','shortlisted','qualified_r3','qualified_final','shortlisted_final')
              AND c.decision IN ('shortlist','shortlisted','qualified_r3','qualified_final','shortlisted_final'))
          OR (_bucket_norm IN ('reject','rejected')         AND c.decision IN ('reject','rejected'))
          OR (_bucket_norm = 'needs_review'                  AND c.decision = 'needs_review')
        );
    END IF;

    next_cursor_created_at := NULL;
    next_cursor_id      := NULL;
    has_more            := false;
    RETURN NEXT;
  END LOOP;

  RETURN;
END;
$$;


ALTER FUNCTION "public"."get_judge_entries_page_filtered"("_competition_id" "uuid", "_round_number" integer, "_bucket" "text", "_cursor_created_at" timestamp with time zone, "_cursor_id" "uuid", "_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_judge_entries_page_v1"("_competition_id" "uuid", "_round_number" integer, "_cursor_created_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "_cursor_id" "uuid" DEFAULT NULL::"uuid", "_limit" integer DEFAULT 10) RETURNS TABLE("id" "uuid", "title" "text", "description" "text", "photos" "text"[], "photo_thumbnails" "text"[], "user_id" "uuid", "status" "text", "created_at" timestamp with time zone, "competition_id" "uuid", "placement" "text", "is_ai_generated" boolean, "ai_detection_result" "jsonb", "exif_data" "jsonb", "view_count" integer, "current_round" "text", "next_cursor_created_at" timestamp with time zone, "next_cursor_id" "uuid", "has_more" boolean)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH page AS (
    SELECT
      r.*,
      ROW_NUMBER() OVER (ORDER BY r.created_at DESC, r.id DESC) AS rn,
      COUNT(*) OVER () AS total_in_page
    FROM public.get_judge_entries_page(
      _competition_id, _round_number, _cursor_created_at, _cursor_id, _limit
    ) r
  )
  SELECT
    p.id, p.title, p.description, p.photos, p.photo_thumbnails,
    p.user_id, p.status, p.created_at, p.competition_id, p.placement,
    p.is_ai_generated, p.ai_detection_result, p.exif_data,
    p.view_count, p.current_round,
    CASE WHEN p.rn = p.total_in_page THEN p.created_at ELSE NULL END AS next_cursor_created_at,
    CASE WHEN p.rn = p.total_in_page THEN p.id         ELSE NULL END AS next_cursor_id,
    CASE WHEN p.rn = p.total_in_page THEN p.has_more   ELSE false END AS has_more
  FROM page p
  ORDER BY p.created_at DESC, p.id DESC;
$$;


ALTER FUNCTION "public"."get_judge_entries_page_v1"("_competition_id" "uuid", "_round_number" integer, "_cursor_created_at" timestamp with time zone, "_cursor_id" "uuid", "_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_judging_drift_admin"() RETURNS TABLE("finding_code" "text", "source_table" "text", "source_row_id" "uuid", "entry_id" "uuid", "judge_id" "uuid", "round_number" integer, "photo_index" integer, "detail_label" "text", "expected_value" "text", "actual_value" "text", "occurred_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT public.has_role(auth.uid(), 'admin') THEN
    RAISE EXCEPTION 'Forbidden: admin role required';
  END IF;

  RETURN QUERY
  SELECT v.finding_code, v.source_table, v.source_row_id, v.entry_id,
         v.judge_id, v.round_number, v.photo_index, v.detail_label,
         v.expected_value, v.actual_value, v.occurred_at
  FROM public.v_judging_drift v
  ORDER BY v.finding_code, v.occurred_at DESC NULLS LAST;
END;
$$;


ALTER FUNCTION "public"."get_judging_drift_admin"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_judging_live_tag_progression_invariant_admin"() RETURNS TABLE("check_name" "text", "status" "text", "proof" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH facts AS (
    SELECT
      EXISTS (
        SELECT 1
        FROM pg_trigger
        WHERE tgrelid = 'public.judge_tag_assignments'::regclass
          AND tgname = 'trg_aggregate_tag_assignments'
          AND NOT tgisinternal
      ) AS obsolete_trigger_exists,
      (
        SELECT count(*)::int
        FROM pg_trigger
        WHERE tgrelid = 'public.judge_tag_assignments'::regclass
          AND NOT tgisinternal
          AND pg_get_triggerdef(oid) ILIKE '%mirror_system_tag_to_decision%'
      ) AS mirror_trigger_count,
      (
        SELECT pg_get_functiondef(p.oid)
        FROM pg_proc p
        JOIN pg_namespace n ON n.oid = p.pronamespace
        WHERE n.nspname = 'public'
          AND p.proname = 'recompute_entry_from_tag_assignments'
        LIMIT 1
      ) AS recompute_def,
      (
        SELECT count(*)::int
        FROM pg_proc p
        JOIN pg_namespace n ON n.oid = p.pronamespace
        WHERE n.nspname = 'public'
          AND pg_get_functiondef(p.oid) ILIKE '%UPDATE competition_entries%'
          AND pg_get_functiondef(p.oid) ILIKE '%progression_decision%'
          AND p.proname NOT IN (
            'enforce_progression_decision_pending_gate',
            'enforce_progression_decision_vocabulary',
            'get_judging_live_tag_progression_invariant_admin'
          )
      ) AS db_functions_with_live_progression_update
  )
  SELECT
    'obsolete_live_tag_aggregator_absent'::text,
    CASE WHEN obsolete_trigger_exists THEN 'FAIL' ELSE 'PASS' END,
    CASE WHEN obsolete_trigger_exists
      THEN 'trg_aggregate_tag_assignments still exists on judge_tag_assignments'
      ELSE 'trg_aggregate_tag_assignments is absent from judge_tag_assignments'
    END
  FROM facts
  UNION ALL
  SELECT
    'tag_to_decision_mirror_present'::text,
    CASE WHEN mirror_trigger_count >= 1 THEN 'PASS' ELSE 'FAIL' END,
    'mirror_system_tag_to_decision trigger count on judge_tag_assignments = ' || mirror_trigger_count::text
  FROM facts
  UNION ALL
  SELECT
    'deprecated_recompute_function_inert'::text,
    CASE
      WHEN recompute_def ILIKE '%BEGIN%RETURN;%END%' OR recompute_def ILIKE '%BEGIN% RETURN; %END%'
      THEN 'PASS'
      ELSE 'FAIL'
    END,
    CASE
      WHEN recompute_def IS NULL THEN 'recompute_entry_from_tag_assignments function not found'
      WHEN recompute_def ILIKE '%UPDATE competition_entries%' THEN 'function still contains UPDATE competition_entries'
      ELSE 'recompute_entry_from_tag_assignments exists but returns without updating competition_entries'
    END
  FROM facts
  UNION ALL
  SELECT
    'no_other_live_progression_writer_function'::text,
    CASE WHEN db_functions_with_live_progression_update = 0 THEN 'PASS' ELSE 'FAIL' END,
    'non-gate DB functions containing UPDATE competition_entries + progression_decision = ' || db_functions_with_live_progression_update::text
  FROM facts;
$$;


ALTER FUNCTION "public"."get_judging_live_tag_progression_invariant_admin"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_judging_live_tag_progression_invariant_admin"() IS 'Admin forensic invariant: proves live judge tag clicks cannot update competition_entries.progression_decision directly, while tag-to-decision mirroring remains installed.';



CREATE OR REPLACE FUNCTION "public"."get_judging_tag_assignment_counts"() RETURNS TABLE("tag_id" "uuid", "assignment_count" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- Admin gate (uses existing has_role helper + app_role enum)
  IF NOT public.has_role(auth.uid(), 'admin'::public.app_role) THEN
    RAISE EXCEPTION 'permission denied: admin role required'
      USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT
    t.id AS tag_id,
    COALESCE(COUNT(jta.id), 0)::bigint AS assignment_count
  FROM public.judging_tags t
  LEFT JOIN public.judge_tag_assignments jta ON jta.tag_id = t.id
  GROUP BY t.id;
END;
$$;


ALTER FUNCTION "public"."get_judging_tag_assignment_counts"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_lesson_content"("_lesson_id" "uuid") RETURNS TABLE("id" "uuid", "title" "text", "content" "text", "video_url" "text", "image_url" "text", "sort_order" integer, "course_id" "uuid")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid    uuid := auth.uid();
  v_lesson public.lessons%ROWTYPE;
  v_course public.courses%ROWTYPE;
  v_is_privileged boolean := false;
BEGIN
  SELECT * INTO v_lesson FROM public.lessons l WHERE l.id = _lesson_id;
  IF NOT FOUND THEN
    RETURN;                       -- unknown lesson -> zero rows ("not found")
  END IF;

  SELECT * INTO v_course FROM public.courses c WHERE c.id = v_lesson.course_id;
  IF NOT FOUND THEN
    RETURN;
  END IF;

  IF v_uid IS NOT NULL THEN
    v_is_privileged :=
         v_course.author_id = v_uid
      OR public.has_role(v_uid, 'admin'::app_role);
      -- NOTE: live app_role enum has no 'super_admin' value; 'admin' is the
      -- only elevated role (matches the certificates admin RLS policy).
  END IF;

  -- Unpublished courses: only author/admin may read (same as courses RLS)
  IF v_course.status <> 'published' AND NOT v_is_privileged THEN
    RETURN;                       -- behave as "not found", don't leak existence
  END IF;

  IF v_course.is_free
     OR v_is_privileged
     OR (v_uid IS NOT NULL AND EXISTS (
           SELECT 1 FROM public.course_enrollments e
           WHERE e.user_id = v_uid AND e.course_id = v_course.id))
  THEN
    RETURN QUERY SELECT
      v_lesson.id, v_lesson.title, v_lesson.content, v_lesson.video_url,
      v_lesson.image_url, v_lesson.sort_order, v_lesson.course_id;
  ELSE
    RAISE EXCEPTION 'Enrollment required to view this lesson'
      USING ERRCODE = '42501';    -- insufficient_privilege
  END IF;
END;
$$;


ALTER FUNCTION "public"."get_lesson_content"("_lesson_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_my_certificate_entries"() RETURNS TABLE("id" "uuid", "title" "text", "competition_id" "uuid", "status" "text", "placement" "text", "current_round" "text", "current_round_int" integer, "progression_decision" "text", "competition_title" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT ce.id, ce.title, ce.competition_id, ce.status, ce.placement,
         ce.current_round, ce.current_round_int, ce.progression_decision,
         c.title AS competition_title
  FROM public.competition_entries ce
  JOIN public.competitions c ON c.id = ce.competition_id
  WHERE ce.user_id = (SELECT auth.uid())
    AND ce.certificate_ready = true
    AND EXISTS (
      SELECT 1 FROM public.competition_round_publish crp
      WHERE crp.competition_id = ce.competition_id AND crp.published_at IS NOT NULL
    );
$$;


