CREATE OR REPLACE FUNCTION "public"."get_my_notifications_grouped"("_limit" integer DEFAULT 30, "_before" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE("group_key" "text", "type" "text", "notification_ids" "uuid"[], "actor_ids" "uuid"[], "actor_names" "text"[], "actor_usernames" "text"[], "actor_avatars" "text"[], "actor_count" integer, "event_count" integer, "unread_count" integer, "reference_id" "uuid", "thumbnail_url" "text", "title" "text", "message" "text", "latest_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
WITH mine AS (
  SELECT n.id, n.type, n.title, n.message, n.reference_id, n.actor_id,
         n.is_read, n.created_at,
         public.notif_group_key(n.type, n.created_at, n.id) AS gkey
    FROM public.user_notifications n
   WHERE auth.uid() IS NOT NULL
     AND n.user_id = auth.uid()
     AND (_before IS NULL OR n.created_at < _before)
),
actors AS (
  SELECT m.gkey, m.actor_id, max(m.created_at) AS last_at
    FROM mine m WHERE m.actor_id IS NOT NULL GROUP BY m.gkey, m.actor_id
),
actors_ranked AS (
  SELECT a.gkey, a.actor_id,
         row_number() OVER (PARTITION BY a.gkey ORDER BY a.last_at DESC, a.actor_id) AS rn,
         p.full_name, p.custom_url, p.avatar_url
    FROM actors a LEFT JOIN public.profiles p ON p.id = a.actor_id
),
actors_top AS (
  SELECT ar.gkey,
         array_agg(ar.actor_id ORDER BY ar.rn) AS actor_ids,
         array_agg(coalesce(ar.full_name,'') ORDER BY ar.rn) AS actor_names,
         array_agg(coalesce(ar.custom_url,'') ORDER BY ar.rn) AS actor_usernames,
         array_agg(coalesce(ar.avatar_url,'') ORDER BY ar.rn) AS actor_avatars
    FROM actors_ranked ar WHERE ar.rn <= 3 GROUP BY ar.gkey
),
grouped AS (
  SELECT m.gkey, min(m.type) AS type, max(m.created_at) AS latest_at,
         count(*)::int AS event_count,
         count(*) FILTER (WHERE NOT m.is_read)::int AS unread_count,
         count(DISTINCT m.actor_id)::int AS actor_count,
         (array_agg(m.id ORDER BY m.created_at DESC))[1:100] AS notification_ids
    FROM mine m GROUP BY m.gkey
),
latest AS (
  SELECT DISTINCT ON (m.gkey) m.gkey, m.title, m.message, m.reference_id
    FROM mine m ORDER BY m.gkey, m.created_at DESC, m.id
)
SELECT g.gkey AS group_key, g.type, g.notification_ids,
       coalesce(t.actor_ids,'{}'::uuid[]) AS actor_ids,
       coalesce(t.actor_names,'{}'::text[]) AS actor_names,
       coalesce(t.actor_usernames,'{}'::text[]) AS actor_usernames,
       coalesce(t.actor_avatars,'{}'::text[]) AS actor_avatars,
       g.actor_count, g.event_count, g.unread_count, l.reference_id,
       CASE WHEN p.id IS NOT NULL AND (p.privacy = 'public' OR p.user_id = auth.uid())
            THEN p.image_url END AS thumbnail_url,
       l.title, l.message, g.latest_at
  FROM grouped g
  JOIN latest l ON l.gkey = g.gkey
  LEFT JOIN actors_top t ON t.gkey = g.gkey
  LEFT JOIN public.posts p ON p.id = l.reference_id
 ORDER BY g.latest_at DESC
 LIMIT greatest(1, least(coalesce(_limit, 30), 100));
$$;


ALTER FUNCTION "public"."get_my_notifications_grouped"("_limit" integer, "_before" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_my_notifications_grouped"("_limit" integer, "_before" timestamp with time zone) IS 'Grouped notification history for the calling user. Keyset-paginate by passing the previous page''s smallest latest_at as _before. Grouping rule and privacy constraints are documented in the migration that created it.';



CREATE OR REPLACE FUNCTION "public"."get_my_story_view_counts"() RETURNS TABLE("story_id" "uuid", "view_count" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT s.id AS story_id,
         (SELECT count(*)::int
            FROM public.story_views sv
           WHERE sv.story_id = s.id
             AND sv.viewer_id <> s.user_id)   -- don't count the author's own opens
  FROM public.stories s
  WHERE s.user_id = auth.uid()
    AND s.expires_at > now();
$$;


ALTER FUNCTION "public"."get_my_story_view_counts"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_my_unread_notifications_grouped"("_limit" integer DEFAULT 20, "_exclude_types" "text"[] DEFAULT '{}'::"text"[]) RETURNS TABLE("group_key" "text", "type" "text", "notification_ids" "uuid"[], "actor_ids" "uuid"[], "actor_names" "text"[], "actor_usernames" "text"[], "actor_avatars" "text"[], "actor_known" boolean[], "actor_count" integer, "event_count" integer, "unread_count" integer, "reference_id" "uuid", "thumbnail_url" "text", "title" "text", "message" "text", "latest_at" timestamp with time zone, "total_unread" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
WITH mine AS (
  SELECT n.id, n.type, n.title, n.message, n.reference_id, n.actor_id, n.created_at,
         public.notif_group_key(n.type, n.created_at, n.id) AS gkey
    FROM public.user_notifications n
   WHERE auth.uid() IS NOT NULL
     AND n.user_id = auth.uid()
     AND n.is_read = false
     -- '{}' excludes nothing: `x = ANY('{}')` is false, so NOT false lets
     -- every row through. A caller that passes nothing gets the old behaviour.
     AND NOT (n.type = ANY(coalesce(_exclude_types, '{}')))
),
actors AS (
  SELECT m.gkey, m.actor_id, max(m.created_at) AS last_at
    FROM mine m WHERE m.actor_id IS NOT NULL GROUP BY m.gkey, m.actor_id
),
actors_ranked AS (
  SELECT a.gkey, a.actor_id,
         row_number() OVER (PARTITION BY a.gkey ORDER BY a.last_at DESC, a.actor_id) AS rn,
         p.full_name, p.custom_url, p.avatar_url,
         -- The LEFT JOIN below already answers "is this person still here".
         -- Until now the answer was thrown away and the client had to guess.
         (p.id IS NOT NULL) AS profile_exists
    FROM actors a LEFT JOIN public.profiles p ON p.id = a.actor_id
),
actors_top AS (
  SELECT ar.gkey,
         array_agg(ar.actor_id ORDER BY ar.rn) AS actor_ids,
         array_agg(coalesce(ar.full_name,'') ORDER BY ar.rn) AS actor_names,
         array_agg(coalesce(ar.custom_url,'') ORDER BY ar.rn) AS actor_usernames,
         array_agg(coalesce(ar.avatar_url,'') ORDER BY ar.rn) AS actor_avatars,
         array_agg(ar.profile_exists ORDER BY ar.rn) AS actor_known
    FROM actors_ranked ar WHERE ar.rn <= 3 GROUP BY ar.gkey
),
grouped AS (
  SELECT m.gkey, min(m.type) AS type, max(m.created_at) AS latest_at,
         count(*)::int AS event_count,
         count(DISTINCT m.actor_id)::int AS actor_count,
         (array_agg(m.id ORDER BY m.created_at DESC))[1:100] AS notification_ids
    FROM mine m GROUP BY m.gkey
),
latest AS (
  SELECT DISTINCT ON (m.gkey) m.gkey, m.title, m.message, m.reference_id
    FROM mine m ORDER BY m.gkey, m.created_at DESC, m.id
)
SELECT g.gkey AS group_key, g.type, g.notification_ids,
       coalesce(t.actor_ids,'{}'::uuid[]) AS actor_ids,
       coalesce(t.actor_names,'{}'::text[]) AS actor_names,
       coalesce(t.actor_usernames,'{}'::text[]) AS actor_usernames,
       coalesce(t.actor_avatars,'{}'::text[]) AS actor_avatars,
       coalesce(t.actor_known,'{}'::boolean[]) AS actor_known,
       g.actor_count, g.event_count, g.event_count AS unread_count, l.reference_id,
       CASE WHEN p.id IS NOT NULL AND (p.privacy = 'public' OR p.user_id = auth.uid())
            THEN p.image_url END AS thumbnail_url,
       l.title, l.message, g.latest_at,
       -- The badge. Excluded types are left out HERE too, which is the point:
       -- a number that disagrees with the list under it is how this started.
       (SELECT count(*)::int FROM public.user_notifications u
         WHERE u.user_id = auth.uid()
           AND u.is_read = false
           AND NOT (u.type = ANY(coalesce(_exclude_types, '{}')))) AS total_unread
  FROM grouped g
  JOIN latest l ON l.gkey = g.gkey
  LEFT JOIN actors_top t ON t.gkey = g.gkey
  LEFT JOIN public.posts p ON p.id = l.reference_id
 ORDER BY g.latest_at DESC
 LIMIT greatest(1, least(coalesce(_limit, 20), 100));
$$;


ALTER FUNCTION "public"."get_my_unread_notifications_grouped"("_limit" integer, "_exclude_types" "text"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_my_unread_notifications_grouped"("_limit" integer, "_exclude_types" "text"[]) IS 'Unread notifications for the calling user, grouped by notif_group_key(). total_unread is the true count of unread rows MINUS any type in _exclude_types -- the bell passes friend_request because it already renders those from the friendships table with Accept/Decline buttons, and counting both made every pending request count twice. actor_known[i] is FALSE when actor_ids[i] has no row in profiles, which is what lets the bell say "A deleted account" instead of "A member" -- two different facts that shared one sentence until 2026-08-10.';



CREATE OR REPLACE FUNCTION "public"."get_needs_review_recipients_for_round"("p_competition_id" "uuid", "p_round_number" integer) RETURNS TABLE("entry_id" "uuid", "user_id" "uuid", "competition_title" "text", "photo_indices" integer[])
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH nr AS (
    SELECT DISTINCT jd.entry_id, jd.photo_index
    FROM public.judge_decisions jd
    WHERE jd.round_number = p_round_number
      AND p_round_number = 1   -- Spec V3: NR only exists in R1
      AND jd.decision = 'needs_review'
      AND jd.entry_id IN (SELECT id FROM public.competition_entries WHERE competition_id = p_competition_id)
  )
  SELECT e.id, e.user_id, c.title,
         array_agg(DISTINCT nr.photo_index ORDER BY nr.photo_index)
  FROM nr
  JOIN public.competition_entries e ON e.id = nr.entry_id
  JOIN public.competitions c ON c.id = e.competition_id
  GROUP BY e.id, e.user_id, c.title;
$$;


ALTER FUNCTION "public"."get_needs_review_recipients_for_round"("p_competition_id" "uuid", "p_round_number" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_notification_drift_admin"("_window_days" integer DEFAULT 90) RETURNS TABLE("expected_template" "text", "total_entries" bigint, "missing_emit" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT has_role(auth.uid(), 'admin') THEN
    RAISE EXCEPTION 'admin_only';
  END IF;

  RETURN QUERY
  WITH targets AS (
    SELECT
      ce.id AS entry_id,
      ce.user_id AS recipient_user_id,
      (SELECT t.email_template FROM public._notification_template_for_entry(ce.status, ce.placement) t) AS expected_template
    FROM competition_entries ce
    WHERE ce.updated_at > now() - make_interval(days => _window_days)
  )
  SELECT
    t.expected_template,
    count(*)::bigint AS total_entries,
    count(*) FILTER (
      WHERE NOT EXISTS (
        SELECT 1 FROM notification_emit_log nel
        WHERE nel.entity_id = t.entry_id
          AND nel.email_template = t.expected_template
          AND nel.recipient_user_id = t.recipient_user_id
      )
    )::bigint AS missing_emit
  FROM targets t
  WHERE t.expected_template IS NOT NULL
  GROUP BY t.expected_template
  ORDER BY 3 DESC;
END;
$$;


ALTER FUNCTION "public"."get_notification_drift_admin"("_window_days" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_notification_email_enabled"("_user_id" "uuid", "_notif_type" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT CASE
    WHEN _notif_type IN ('ticket_reply', 'role_approved', 'role_rejected', 'friend_accepted') THEN true
    -- ADDED 2026-08-11: the tagged fan-out is in-app and push only (owner's
    -- choice). Placed ABOVE the reaction/comment branches so it cannot be
    -- swallowed by them, and above ELSE true so it cannot fall through to mail.
    WHEN _notif_type IN ('tagged_post_reaction', 'tagged_post_comment') THEN false
    WHEN _notif_type IN ('post_reaction', 'image_reaction', 'competition_vote') THEN
      COALESCE((SELECT email_reactions FROM notification_preferences WHERE user_id = _user_id), true)
    -- ad_comment_reply joins the comment family, so it obeys the member's
    -- existing "email me about comments" switch rather than a new one.
    WHEN _notif_type IN ('post_comment', 'comment_reply', 'image_comment', 'ad_comment_reply') THEN
      COALESCE((SELECT email_comments FROM notification_preferences WHERE user_id = _user_id), true)
    WHEN _notif_type IN ('friend_request') THEN
      COALESCE((SELECT email_friend_requests FROM notification_preferences WHERE user_id = _user_id), true)
    WHEN _notif_type IN ('new_follower') THEN
      COALESCE((SELECT email_new_followers FROM notification_preferences WHERE user_id = _user_id), true)
    -- BUG-039: ALL competition-result types respect the Competition Updates toggle
    WHEN _notif_type IN ('entry_approved', 'entry_rejected', 'competition_winner',
                         'entry_qualified', 'entry_finalist', 'entry_shortlisted',
                         'round_results_published', 'potd_featured') THEN
      COALESCE((SELECT email_competition_updates FROM notification_preferences WHERE user_id = _user_id), true)
    WHEN _notif_type IN ('certificate_issued') THEN
      COALESCE((SELECT email_certificates FROM notification_preferences WHERE user_id = _user_id), true)
    WHEN _notif_type IN ('badge_awarded') THEN
      COALESCE((SELECT email_gift_credits FROM notification_preferences WHERE user_id = _user_id), true)
    -- BUG-039: course publishing is an opt-in broadcast (default OFF preserves BUG-038)
    WHEN _notif_type IN ('course_published') THEN
      COALESCE((SELECT email_course_updates FROM notification_preferences WHERE user_id = _user_id), false)
    -- BUG-038: mass-broadcast types never email the whole base
    WHEN _notif_type IN ('new_competition', 'journal_published') THEN false
    ELSE true
  END;
$$;


ALTER FUNCTION "public"."get_notification_email_enabled"("_user_id" "uuid", "_notif_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_notification_health_stats_admin"() RETURNS TABLE("emits_today" bigint, "emits_total" bigint, "distinct_templates" bigint, "failures_today" bigint, "dlq_count" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT has_role(auth.uid(), 'admin') THEN
    RAISE EXCEPTION 'admin_only';
  END IF;

  RETURN QUERY
  SELECT
    (SELECT count(*) FROM notification_emit_log WHERE created_at::date = current_date)::bigint,
    (SELECT count(*) FROM notification_emit_log)::bigint,
    (SELECT count(DISTINCT email_template) FROM notification_emit_log WHERE email_template IS NOT NULL)::bigint,
    (SELECT count(DISTINCT message_id) FROM email_send_log
      WHERE created_at::date = current_date
        AND status IN ('failed','dlq','bounced'))::bigint,
    (SELECT count(DISTINCT message_id) FROM email_send_log WHERE status = 'dlq')::bigint;
END;
$$;


ALTER FUNCTION "public"."get_notification_health_stats_admin"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_per_photo_consensus"("p_entry_ids" "uuid"[]) RETURNS TABLE("entry_id" "uuid", "photo_index" integer, "round_number" integer, "decision" "text", "judges_decided" integer, "total_judges" integer, "ratio" numeric, "threshold" numeric, "has_consensus" boolean, "status" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_is_admin boolean := false;
BEGIN
  IF v_caller IS NOT NULL THEN
    v_is_admin := public.has_role(v_caller, 'admin'::app_role);
  END IF;

  RETURN QUERY
  WITH visible_entries AS (
    SELECT ce.id, ce.competition_id, ce.user_id, ce.judge_assignment_mode_resolved,
      CASE
        WHEN v_is_admin THEN 'admin'
        WHEN v_caller IS NOT NULL AND ce.user_id = v_caller THEN 'owner'
        WHEN v_caller IS NOT NULL AND EXISTS (
          SELECT 1 FROM public.competition_judges cj
          WHERE cj.competition_id = ce.competition_id AND cj.judge_id = v_caller
        ) THEN 'judge'
        ELSE 'public'
      END AS viewer_role
    FROM (
      SELECT e.id, e.competition_id, e.user_id,
             c.judge_assignment_mode AS judge_assignment_mode_resolved
      FROM public.competition_entries e
      JOIN public.competitions c ON c.id = e.competition_id
      WHERE e.id = ANY(p_entry_ids)
    ) ce
    WHERE v_is_admin
       OR (v_caller IS NOT NULL AND ce.user_id = v_caller)
       OR (v_caller IS NOT NULL AND EXISTS (
            SELECT 1 FROM public.competition_judges cj
            WHERE cj.competition_id = ce.competition_id AND cj.judge_id = v_caller))
       OR EXISTS (
            SELECT 1 FROM public.competition_round_publish crp
            WHERE crp.competition_id = ce.competition_id AND crp.published_at IS NOT NULL)
  ),
  decs AS (
    SELECT jd.entry_id, COALESCE(jd.photo_index, 0) AS photo_index,
           jd.round_number, jd.decision, jd.judge_id
    FROM public.judge_decisions jd
    JOIN visible_entries ve ON ve.id = jd.entry_id
    WHERE ve.viewer_role IN ('admin', 'judge')
       OR EXISTS (
            SELECT 1 FROM public.competition_round_publish crp
            WHERE crp.competition_id = ve.competition_id
              AND crp.round_number = jd.round_number
              AND crp.published_at IS NOT NULL)
  ),
  -- Path B: qualified_r3 (70) and shortlisted_final (65) outrank accept (40)
  -- so on tie counts, "Qualified" beats "Accepted".
  priority(decision_key, prio) AS (
    VALUES
      ('qualified_r3'::text, 70),
      ('shortlisted_final'::text, 65),
      ('shortlist'::text, 60),('shortlisted'::text, 60),
      ('shortlisted_for_final'::text, 60),('shortlisted for final'::text, 60),
      ('qualified'::text, 50),('winner'::text, 55),
      ('finalist'::text, 45),('accept'::text, 40),('accepted'::text, 40),
      ('needs_review'::text, 30),('skip'::text, 20),
      ('reject'::text, 10),('rejected'::text, 10)
  ),
  counts AS (
    SELECT d.entry_id, d.photo_index, d.round_number, d.decision, COUNT(*)::int AS n
    FROM decs d
    GROUP BY d.entry_id, d.photo_index, d.round_number, d.decision
  ),
  ranked AS (
    SELECT cnt.entry_id, cnt.photo_index, cnt.round_number, cnt.decision, cnt.n,
           ROW_NUMBER() OVER (
             PARTITION BY cnt.entry_id, cnt.photo_index, cnt.round_number
             ORDER BY cnt.n DESC, COALESCE(p.prio, 0) DESC, cnt.decision ASC
           ) AS rn
    FROM counts cnt LEFT JOIN priority p ON p.decision_key = cnt.decision
  ),
  winners AS (
    SELECT r.entry_id, r.photo_index, r.round_number, r.decision AS win_decision, r.n AS win_count
    FROM ranked r WHERE r.rn = 1
  ),
  judges_for_entry AS (
    SELECT ve.id AS entry_ref,
      CASE WHEN ve.judge_assignment_mode_resolved = 'distributed' THEN
        (SELECT COUNT(*)::int FROM public.judge_entry_assignments jea WHERE jea.entry_id = ve.id)
      ELSE
        (SELECT COUNT(*)::int FROM public.competition_judges cj WHERE cj.competition_id = ve.competition_id)
      END AS total_judges
    FROM visible_entries ve
  ),
  decided_per_photo AS (
    SELECT d.entry_id, d.photo_index, d.round_number,
           COUNT(DISTINCT d.judge_id)::int AS judges_decided
    FROM decs d
    GROUP BY d.entry_id, d.photo_index, d.round_number
  ),
  cfg AS (
    SELECT jc.competition_id, jc.round_number,
           COALESCE(jc.threshold, 0.5) AS threshold,
           COALESCE(jc.min_judges, 1)  AS min_judges
    FROM public.judging_config jc
  ),
  publish_state AS (
    SELECT crp.competition_id, crp.round_number, crp.published_at IS NOT NULL AS is_published
    FROM public.competition_round_publish crp
  )
  SELECT w.entry_id, w.photo_index, w.round_number,
    w.win_decision AS decision,
    dp.judges_decided,
    GREATEST(jfe.total_judges, 1) AS total_judges,
    ROUND((w.win_count::numeric) / GREATEST(jfe.total_judges, 1)::numeric, 4) AS ratio,
    COALESCE(cfg.threshold, 0.5) AS threshold,
    ((w.win_count::numeric) / GREATEST(jfe.total_judges, 1)::numeric > COALESCE(cfg.threshold, 0.5)
      AND dp.judges_decided >= COALESCE(cfg.min_judges, 1)) AS has_consensus,
    CASE
      WHEN ve.viewer_role = 'owner'
       AND COALESCE((SELECT ps.is_published FROM publish_state ps
                     WHERE ps.competition_id = ve.competition_id
                       AND ps.round_number = w.round_number), false) = false
        THEN 'pending_consensus'
      WHEN NOT ((w.win_count::numeric) / GREATEST(jfe.total_judges, 1)::numeric > COALESCE(cfg.threshold, 0.5)
                AND dp.judges_decided >= COALESCE(cfg.min_judges, 1)) THEN 'pending_consensus'
      WHEN w.round_number = 4 AND w.win_decision = 'winner' THEN 'winner'
      WHEN w.round_number = 4 AND w.win_decision = 'finalist' THEN 'finalist'
      -- R3: shortlisted_final / qualified / accept all advance to finalist
      WHEN w.round_number = 3 AND w.win_decision IN ('shortlisted_final','qualified','shortlist','shortlisted','finalist','shortlisted_for_final','shortlisted for final','accept','accepted') THEN 'finalist'
      WHEN w.round_number = 3 AND w.win_decision IN ('reject','rejected','skip','not_selected_final') THEN 'rejected'
      -- R2: qualified_r3 / qualified / accept all advance to round2_qualified
      WHEN w.round_number = 2 AND w.win_decision IN ('qualified_r3','shortlist','shortlisted','qualified','accept','accepted') THEN 'round2_qualified'
      WHEN w.round_number = 2 AND w.win_decision IN ('skip','reject','rejected','not_selected_r3') THEN 'rejected'
      WHEN w.round_number = 1 AND w.win_decision IN ('accept','accepted') THEN 'round1_qualified'
      WHEN w.round_number = 1 AND w.win_decision IN ('shortlist','shortlisted') THEN 'shortlisted'
      WHEN w.round_number = 1 AND w.win_decision = 'needs_review' THEN 'needs_review'
      WHEN w.round_number = 1 AND w.win_decision IN ('reject','rejected') THEN 'rejected'
      ELSE 'pending_consensus'
    END AS status
  FROM winners w
  JOIN visible_entries ve ON ve.id = w.entry_id
  JOIN judges_for_entry jfe ON jfe.entry_ref = w.entry_id
  JOIN decided_per_photo dp ON dp.entry_id = w.entry_id
                           AND dp.photo_index = w.photo_index
                           AND dp.round_number = w.round_number
  LEFT JOIN cfg ON cfg.competition_id = ve.competition_id AND cfg.round_number = w.round_number
  ORDER BY w.entry_id, w.photo_index, w.round_number;
END;
$$;


ALTER FUNCTION "public"."get_per_photo_consensus"("p_entry_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_per_photo_consensus"("p_entry_ids" "uuid"[]) IS 'Per-photo consensus aggregator. Emits exactly 9 status keys:
4 R1 canonical (r1_accepted/r1_shortlisted_r2/r1_needs_review/r1_rejected),
2 R2 canonical (r2_accepted/r2_qualified_r3),
2 R3 canonical (r3_accepted/r3_qualified_final), plus pending_consensus.
R4 awards are owned by get_per_photo_placement; this RPC never emits R4 keys.
Phase 6 closure (2026-05-02) — dropped legacy ''winner''/''finalist'' R4 emits
to lock the strict 16+2 vocabulary contract enforced by
src/test/rpc-consensus-vocabulary.spec.ts and
scripts/audits/rpc_contract_parity.mjs.';



CREATE OR REPLACE FUNCTION "public"."get_per_photo_placement"("p_entry_ids" "uuid"[]) RETURNS TABLE("entry_id" "uuid", "photo_index" integer, "round_number" integer, "status" "text", "award_label" "text", "declared" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_is_admin boolean := false;
BEGIN
  IF v_caller IS NOT NULL THEN
    v_is_admin := public.has_role(v_caller, 'admin'::app_role);
  END IF;

  RETURN QUERY
  WITH visible_entries AS (
    SELECT ce.id, ce.competition_id, ce.user_id,
      CASE
        WHEN v_is_admin THEN 'admin'
        WHEN v_caller IS NOT NULL AND EXISTS (
          SELECT 1 FROM public.competition_judges cj
          WHERE cj.competition_id = ce.competition_id AND cj.judge_id = v_caller
        ) THEN 'judge'
        WHEN v_caller IS NOT NULL AND ce.user_id = v_caller THEN 'owner'
        ELSE 'public'
      END AS viewer_role
    FROM public.competition_entries ce
    WHERE ce.id = ANY(p_entry_ids)
  ),
  declared_r4 AS (
    SELECT crp.competition_id, crp.published_at IS NOT NULL AS is_declared
    FROM public.competition_round_publish crp
    WHERE crp.round_number = 4
  ),
  raw_tags AS (
    SELECT
      jta.entry_id,
      COALESCE(jta.photo_index, 0) AS photo_index,
      jt.label AS award_label,
      CASE LOWER(TRIM(jt.label))
        WHEN 'winner' THEN 'r4_winner'
        WHEN '1st runner-up' THEN 'r4_runner_up_1'
        WHEN '2nd runner-up' THEN 'r4_runner_up_2'
        WHEN 'top 50' THEN 'r4_top_50'
        WHEN 'top 50 global photographer' THEN 'r4_top_50'
        WHEN 'top 100' THEN 'r4_top_100'
        WHEN 'top 100 global photographer' THEN 'r4_top_100'
        WHEN 'finalist' THEN 'r4_finalist'
        WHEN 'qualified for final' THEN 'r4_finalist'
        WHEN 'qualified for final round' THEN 'r4_finalist'
        WHEN 'honorary mention' THEN 'r4_honorary_mention'
        WHEN 'honourable mention' THEN 'r4_honorary_mention'
        WHEN 'honorable mention' THEN 'r4_honorary_mention'
        WHEN 'special jury award' THEN 'r4_special_jury'
        WHEN 'special jury' THEN 'r4_special_jury'
        ELSE NULL
      END AS canon_key
    FROM public.judge_tag_assignments jta
    JOIN public.judging_tags jt ON jt.id = jta.tag_id
    JOIN visible_entries ve ON ve.id = jta.entry_id
    WHERE jta.round_number = 4
      AND (
        ve.viewer_role IN ('admin','judge')
        OR COALESCE((SELECT dr.is_declared FROM declared_r4 dr WHERE dr.competition_id = ve.competition_id LIMIT 1), false)
      )
  ),
  prio(canon_key, prio) AS (
    VALUES
      ('r4_winner', 100),
      ('r4_runner_up_1', 90),
      ('r4_runner_up_2', 80),
      ('r4_top_50', 70),
      ('r4_top_100', 60),
      ('r4_finalist', 50),
      ('r4_honorary_mention', 40),
      ('r4_special_jury', 30)
  ),
  ranked AS (
    SELECT rt.entry_id, rt.photo_index, rt.canon_key, rt.award_label,
           ROW_NUMBER() OVER (
             PARTITION BY rt.entry_id, rt.photo_index
             ORDER BY COALESCE(p.prio, 0) DESC, rt.award_label ASC
           ) AS rn
    FROM raw_tags rt
    LEFT JOIN prio p ON p.canon_key = rt.canon_key
    WHERE rt.canon_key IS NOT NULL
  )
  SELECT
    r.entry_id, r.photo_index, 4 AS round_number,
    r.canon_key AS status, r.award_label,
    COALESCE((SELECT dr.is_declared FROM declared_r4 dr
              JOIN visible_entries ve ON ve.competition_id = dr.competition_id
              WHERE ve.id = r.entry_id LIMIT 1), false) AS declared
  FROM ranked r
  WHERE r.rn = 1
  ORDER BY r.entry_id, r.photo_index;
END;
$$;


ALTER FUNCTION "public"."get_per_photo_placement"("p_entry_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_per_photo_placement"("p_entry_ids" "uuid"[]) IS 'Phase 3 sibling to get_per_photo_consensus. Returns R4 award placements per photo using the 8 Frozen Contract v3 canonical R4 keys: r4_winner, r4_runner_up_1, r4_runner_up_2, r4_top_50, r4_top_100, r4_finalist, r4_honorary_mention, r4_special_jury. Source: judge_tag_assignments (round_number=4) JOIN judging_tags. Privacy: declared (published_at IS NOT NULL) gate for non-admin/non-judge/non-owner viewers. Tie-break: priority winner > runner_up_1 > runner_up_2 > top_50 > top_100 > finalist > honorary_mention > special_jury.';



CREATE OR REPLACE FUNCTION "public"."get_photo_r4_awards"("p_entry_ids" "uuid"[]) RETURNS TABLE("entry_id" "uuid", "photo_index" integer, "stage_key" "text", "all_stage_keys" "text"[])
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH priority(stage_key, rank) AS (
    VALUES
      ('r4_winner',           1),
      ('r4_runner_up_1',      2),
      ('r4_runner_up_2',      3),
      ('r4_special_jury',     4),
      ('r4_honorary_mention', 5),
      ('r4_top_50',           6),
      ('r4_top_100',          7),
      ('r4_finalist',         8)
  ),
  distinct_tags AS (
    SELECT DISTINCT t.entry_id, t.photo_index, t.stage_key
    FROM public.judge_award_tags t
    WHERE t.entry_id = ANY(p_entry_ids)
      AND t.round_number = 4
  ),
  ranked AS (
    SELECT d.entry_id, d.photo_index, d.stage_key, p.rank
    FROM distinct_tags d
    JOIN priority p USING (stage_key)
  ),
  best AS (
    SELECT DISTINCT ON (entry_id, photo_index)
      entry_id, photo_index, stage_key
    FROM ranked
    ORDER BY entry_id, photo_index, rank ASC
  )
  SELECT
    b.entry_id,
    b.photo_index,
    b.stage_key,
    ARRAY(
      SELECT r.stage_key
      FROM ranked r
      WHERE r.entry_id = b.entry_id AND r.photo_index = b.photo_index
      ORDER BY r.rank ASC
    ) AS all_stage_keys
  FROM best b;
$$;


ALTER FUNCTION "public"."get_photo_r4_awards"("p_entry_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_placement_drift_admin"("_competition_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("entry_id" "uuid", "competition_id" "uuid", "competition_title" "text", "status" "text", "placement" "text", "rank_score" numeric, "expected_rank" integer, "actual_award_rank" integer, "drift_reason" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT has_role(auth.uid(), 'admin') THEN
    RAISE EXCEPTION 'Forbidden: admin role required';
  END IF;

  RETURN QUERY
  WITH r4_entries AS (
    SELECT ce.id AS e_id, ce.competition_id AS comp_id, ce.status AS e_status, ce.placement AS e_placement,
           c.title AS comp_title,
           compute_entry_rank_score(ce.id) AS r_score
    FROM competition_entries ce
    JOIN competitions c ON c.id = ce.competition_id
    WHERE ce.current_round = '4'
      AND (_competition_id IS NULL OR ce.competition_id = _competition_id)
  ),
  ranked AS (
    SELECT r.*,
      ROW_NUMBER() OVER (PARTITION BY r.comp_id ORDER BY r.r_score DESC) AS exp_rank
    FROM r4_entries r
  ),
  award_rank AS (
    SELECT rk.*,
      CASE rk.e_status
        WHEN 'winner' THEN 1
        WHEN 'runner_up_1' THEN 2
        WHEN 'runner_up_2' THEN 3
        WHEN 'special_jury' THEN 4
        WHEN 'honorary_mention' THEN 5
        ELSE NULL
      END AS act_award_rank
    FROM ranked rk
  )
  SELECT
    ar.e_id, ar.comp_id, ar.comp_title, ar.e_status, ar.e_placement,
    ar.r_score, ar.exp_rank::int, ar.act_award_rank,
    CASE
      WHEN ar.e_status IN ('winner','runner_up_1','runner_up_2','special_jury','honorary_mention')
           AND ar.e_placement IS DISTINCT FROM ar.e_status
        THEN 'status_placement_mismatch'
      WHEN ar.e_status = 'winner' AND ar.exp_rank > 1
        THEN 'winner_not_top_ranked'
      WHEN ar.e_status = 'runner_up_1' AND ar.exp_rank > 2
        THEN 'runner_up_1_below_2nd_rank'
      ELSE NULL
    END AS drift_reason
  FROM award_rank ar
  WHERE
    (ar.e_status IN ('winner','runner_up_1','runner_up_2','special_jury','honorary_mention')
     AND ar.e_placement IS DISTINCT FROM ar.e_status)
    OR (ar.e_status = 'winner' AND ar.exp_rank > 1)
    OR (ar.e_status = 'runner_up_1' AND ar.exp_rank > 2);
END;
$$;


ALTER FUNCTION "public"."get_placement_drift_admin"("_competition_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_post_view_counts"("_post_ids" "uuid"[]) RETURNS TABLE("post_id" "uuid", "views" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT p.id AS post_id,
         (SELECT count(DISTINCT fe.user_id)::int
            FROM public.feed_events fe
           WHERE fe.post_id = p.id
             AND fe.event_type IN ('view', 'skip')
             AND fe.user_id <> p.user_id)
  FROM public.posts p
  WHERE p.id = ANY(_post_ids);
$$;


ALTER FUNCTION "public"."get_post_view_counts"("_post_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_primary_admin_user_id"() RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT user_id
  FROM public.user_roles
  WHERE role = 'admin'
  ORDER BY created_at ASC NULLS LAST, user_id ASC
  LIMIT 1
$$;


ALTER FUNCTION "public"."get_primary_admin_user_id"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_profile_admin"("_id" "uuid") RETURNS TABLE("id" "uuid", "full_name" "text", "email" "text", "avatar_url" "text", "bio" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT public.has_role(auth.uid(), 'admin'::app_role) THEN
    RETURN;
  END IF;
  RETURN QUERY
  SELECT p.id, p.full_name, u.email::text, p.avatar_url, p.bio
  FROM public.profiles p
  JOIN auth.users u ON u.id = p.id
  WHERE p.id = _id
  LIMIT 1;
END;
$$;


ALTER FUNCTION "public"."get_profile_admin"("_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_profile_visible_fields"("_target" "uuid") RETURNS TABLE("avatar_url" "text", "bio" "text", "photography_interests" "text"[], "portfolio_url" "text", "facebook_url" "text", "instagram_url" "text", "twitter_url" "text", "youtube_url" "text", "website_url" "text", "current_city" "text", "workplace" "text", "education" "text", "pronouns" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _caller uuid := auth.uid();
  _is_owner boolean := (_caller IS NOT NULL AND _caller = _target);
  _is_admin boolean := (_caller IS NOT NULL AND public.has_role(_caller, 'admin'::app_role));
  _is_friend boolean := (_caller IS NOT NULL AND public.are_friends(_caller, _target));
  ps jsonb;
  p public.profiles%ROWTYPE;
  -- visibility helper values
  _priv boolean := (_is_owner OR _is_admin);           -- sees only_me
  _frnd boolean := (_is_owner OR _is_admin OR _is_friend); -- sees friends
BEGIN
  SELECT * INTO p FROM public.profiles WHERE id = _target;
  IF NOT FOUND THEN
    RETURN;
  END IF;
  ps := COALESCE(p.privacy_settings, '{}'::jsonb);

  RETURN QUERY SELECT
    CASE WHEN public._field_visible(ps->>'avatar',      _frnd, _priv) THEN p.avatar_url    ELSE NULL END,
    CASE WHEN public._field_visible(ps->>'bio',         _frnd, _priv) THEN p.bio           ELSE NULL END,
    CASE WHEN public._field_visible(ps->>'interests',   _frnd, _priv) THEN p.photography_interests ELSE NULL END,
    CASE WHEN public._field_visible(ps->>'portfolio',   _frnd, _priv) THEN p.portfolio_url ELSE NULL END,
    CASE WHEN public._field_visible(ps->>'social_links',_frnd, _priv) THEN p.facebook_url  ELSE NULL END,
    CASE WHEN public._field_visible(ps->>'social_links',_frnd, _priv) THEN p.instagram_url ELSE NULL END,
    CASE WHEN public._field_visible(ps->>'social_links',_frnd, _priv) THEN p.twitter_url   ELSE NULL END,
    CASE WHEN public._field_visible(ps->>'social_links',_frnd, _priv) THEN p.youtube_url   ELSE NULL END,
    CASE WHEN public._field_visible(ps->>'social_links',_frnd, _priv) THEN p.website_url   ELSE NULL END,
    CASE WHEN public._field_visible(ps->>'city_country',_frnd, _priv) THEN p.current_city  ELSE NULL END,
    CASE WHEN public._field_visible(ps->>'workplace',   _frnd, _priv) THEN p.workplace     ELSE NULL END,
    CASE WHEN public._field_visible(ps->>'education',    _frnd, _priv) THEN p.education     ELSE NULL END,
    CASE WHEN public._field_visible(ps->>'pronouns',    _frnd, _priv) THEN p.pronouns      ELSE NULL END;
END;
$$;


ALTER FUNCTION "public"."get_profile_visible_fields"("_target" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_progression_drift_admin"() RETURNS TABLE("entry_id" "uuid", "competition_id" "uuid", "title" "text", "status" "text", "stored_decision" "text", "expected_decision" "text", "total_decisions" bigint, "has_drift" boolean, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT public.has_role(auth.uid(), 'admin'::app_role) THEN
    RAISE EXCEPTION 'forbidden: admin role required';
  END IF;

  RETURN QUERY
  WITH per_entry AS (
    SELECT
      e.id              AS entry_id,
      e.competition_id  AS competition_id,
      e.title           AS title,
      e.status          AS status,
      e.progression_decision AS stored_decision,
      e.updated_at      AS updated_at,
      (
        SELECT count(*)::bigint FROM public.judge_decisions jd
        WHERE jd.entry_id = e.id
      ) AS total_decisions,
      (
        WITH latest_round AS (
          SELECT max(jd.round_number) AS rn
          FROM public.judge_decisions jd
          WHERE jd.entry_id = e.id
        ),
        tally AS (
          SELECT
            CASE
              WHEN lower(jd.decision) IN ('shortlist','shortlisted','qualified','accept','accepted') THEN 'qualified'
              WHEN lower(jd.decision) IN ('reject','rejected') THEN 'rejected'
              ELSE lower(jd.decision)
            END AS norm,
            count(*) AS n
          FROM public.judge_decisions jd, latest_round lr
          WHERE jd.entry_id = e.id
            AND jd.round_number = lr.rn
            AND jd.decision IS NOT NULL
          GROUP BY 1
        ),
        ranked AS (
          SELECT norm, n, rank() OVER (ORDER BY n DESC) AS rk
          FROM tally
        )
        SELECT CASE
          WHEN (SELECT count(*) FROM tally) = 0 THEN NULL
          WHEN (SELECT count(*) FROM ranked WHERE rk = 1) > 1 THEN NULL
          ELSE (SELECT norm FROM ranked WHERE rk = 1 LIMIT 1)
        END
      ) AS expected_decision
    FROM public.competition_entries e
  )
  SELECT
    pe.entry_id,
    pe.competition_id,
    pe.title,
    pe.status,
    pe.stored_decision,
    pe.expected_decision,
    pe.total_decisions,
    (
      pe.expected_decision IS NOT NULL
      AND coalesce(pe.stored_decision, '') <> coalesce(pe.expected_decision, '')
    ) AS has_drift,
    pe.updated_at
  FROM per_entry pe
  WHERE pe.expected_decision IS NOT NULL
    AND coalesce(pe.stored_decision, '') <> coalesce(pe.expected_decision, '')
  ORDER BY pe.updated_at DESC NULLS LAST;
END;
$$;


ALTER FUNCTION "public"."get_progression_drift_admin"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_public_final_votes"("_entry_ids" "uuid"[]) RETURNS TABLE("entry_id" "uuid", "photo_index" integer, "final_votes" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT efv.entry_id,
         COALESCE(efv.photo_index, 0)::integer,
         COALESCE(efv.final_votes, 0)::integer
  FROM public.entry_final_votes efv
  WHERE efv.entry_id = ANY(_entry_ids)
    AND NOT public.is_vote_phase_locked(efv.entry_id);
$$;


ALTER FUNCTION "public"."get_public_final_votes"("_entry_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_public_role_user_ids"("_role" "text") RETURNS SETOF "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- Only expose roles that are safe to enumerate app-wide.
  IF _role NOT IN ('admin', 'judge') THEN
    RAISE EXCEPTION 'role % is not enumerable', _role USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
    SELECT ur.user_id
    FROM public.user_roles ur
    WHERE ur.role::text = _role;
END;
$$;


