CREATE OR REPLACE FUNCTION "public"."get_public_round_scores"("p_competition_id" "uuid", "p_round_number" integer) RETURNS TABLE("entry_id" "uuid", "photo_index" integer, "anonymized_judge_label" "text", "composition_score" integer, "color_palette_score" integer, "technique_score" integer, "line_score" integer, "shape_score" integer, "form_score" integer, "texture_score" integer, "space_score" integer, "tone_score" integer, "balance_score" integer, "light_score" integer, "depth_score" integer, "editing_score" integer, "story_score" integer, "moment_score" integer, "average_score" numeric)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- Gate: scores are public only once the ADMIN DECLARED the round.
  IF NOT EXISTS (
    SELECT 1 FROM public.competition_round_publish crp
    WHERE crp.competition_id = p_competition_id
      AND crp.round_number = p_round_number
      AND crp.published_at IS NOT NULL
  ) THEN
    RETURN;
  END IF;

  RETURN QUERY
  WITH judge_labels AS (
    SELECT js.judge_id,
           'Judge ' || dense_rank() OVER (ORDER BY js.judge_id)::text AS label
    FROM public.judge_scores js
    JOIN public.competition_entries ce ON ce.id = js.entry_id
    WHERE ce.competition_id = p_competition_id
    GROUP BY js.judge_id
  )
  SELECT
    js.entry_id, js.photo_index, jl.label,
    js.composition_score, js.color_palette_score, js.technique_score,
    js.line_score, js.shape_score, js.form_score, js.texture_score,
    js.space_score, js.tone_score, js.balance_score, js.light_score,
    js.depth_score, js.editing_score, js.story_score, js.moment_score,
    ROUND((
      COALESCE(js.composition_score,0)+COALESCE(js.color_palette_score,0)+COALESCE(js.technique_score,0)+
      COALESCE(js.line_score,0)+COALESCE(js.shape_score,0)+COALESCE(js.form_score,0)+
      COALESCE(js.texture_score,0)+COALESCE(js.space_score,0)+COALESCE(js.tone_score,0)+
      COALESCE(js.balance_score,0)+COALESCE(js.light_score,0)+COALESCE(js.depth_score,0)+
      COALESCE(js.editing_score,0)+COALESCE(js.story_score,0)+COALESCE(js.moment_score,0)
    )::numeric / NULLIF(
      (js.composition_score IS NOT NULL)::int+(js.color_palette_score IS NOT NULL)::int+(js.technique_score IS NOT NULL)::int+
      (js.line_score IS NOT NULL)::int+(js.shape_score IS NOT NULL)::int+(js.form_score IS NOT NULL)::int+
      (js.texture_score IS NOT NULL)::int+(js.space_score IS NOT NULL)::int+(js.tone_score IS NOT NULL)::int+
      (js.balance_score IS NOT NULL)::int+(js.light_score IS NOT NULL)::int+(js.depth_score IS NOT NULL)::int+
      (js.editing_score IS NOT NULL)::int+(js.story_score IS NOT NULL)::int+(js.moment_score IS NOT NULL)::int, 0), 2) AS average_score
  FROM public.judge_scores js
  JOIN public.competition_entries ce ON ce.id = js.entry_id
  JOIN judge_labels jl ON jl.judge_id = js.judge_id
  WHERE ce.competition_id = p_competition_id
    AND js.round_number = p_round_number
  ORDER BY js.entry_id, js.photo_index, jl.label;
END;
$$;


ALTER FUNCTION "public"."get_public_round_scores"("p_competition_id" "uuid", "p_round_number" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_push_health"() RETURNS TABLE("devices_registered" integer, "members_with_a_device" integer, "notifications_24h" integer, "queued_24h" integer, "skipped_preference_24h" integer, "skipped_self_24h" integer, "errors_24h" integer, "last_queued_at" timestamp with time zone, "last_error_at" timestamp with time zone, "last_error_detail" "text", "delivery_looks_dead" boolean)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    (SELECT count(*)::int FROM public.push_tokens),
    (SELECT count(DISTINCT user_id)::int FROM public.push_tokens),
    (SELECT count(*)::int FROM public.user_notifications
      WHERE created_at > now() - interval '24 hours'),
    (SELECT count(*)::int FROM public.push_delivery_log
      WHERE outcome = 'queued' AND created_at > now() - interval '24 hours'),
    (SELECT count(*)::int FROM public.push_delivery_log
      WHERE outcome = 'skipped_preference' AND created_at > now() - interval '24 hours'),
    (SELECT count(*)::int FROM public.push_delivery_log
      WHERE outcome = 'skipped_self' AND created_at > now() - interval '24 hours'),
    (SELECT count(*)::int FROM public.push_delivery_log
      WHERE outcome = 'error' AND created_at > now() - interval '24 hours'),
    (SELECT max(created_at) FROM public.push_delivery_log WHERE outcome = 'queued'),
    (SELECT max(created_at) FROM public.push_delivery_log WHERE outcome = 'error'),
    (SELECT detail FROM public.push_delivery_log
      WHERE outcome = 'error' ORDER BY created_at DESC LIMIT 1),
    -- THE alarm. Notifications are being created, devices exist, and yet not one
    -- push has been queued in 24h. That is the exact state the platform sat in,
    -- undetected, from launch until 2026-08-01.
    (SELECT (SELECT count(*) FROM public.user_notifications
              WHERE created_at > now() - interval '24 hours') > 0
        AND (SELECT count(*) FROM public.push_tokens) > 0
        AND (SELECT count(*) FROM public.push_delivery_log
              WHERE outcome = 'queued' AND created_at > now() - interval '24 hours') = 0)
  WHERE public.app_has_role(auth.uid(), 'admin');   -- admins only; others get zero rows
$$;


ALTER FUNCTION "public"."get_push_health"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_push_health"() IS 'Admin-only push delivery health. delivery_looks_dead = notifications are being created and devices are registered but nothing has been queued in 24h — the exact undetected state that persisted from launch until 2026-08-01.';



CREATE OR REPLACE FUNCTION "public"."get_referral_drift_admin"() RETURNS TABLE("drift_type" "text", "referral_id" "uuid", "referrer_id" "uuid", "referred_id" "uuid", "expected_amount" numeric, "actual_amount" numeric, "rewarded_at" timestamp with time zone, "notes" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT has_role(auth.uid(), 'admin') THEN
    RAISE EXCEPTION 'Forbidden: admin role required';
  END IF;

  RETURN QUERY
  -- A) Rewarded referral with no wallet credit
  SELECT 'rewarded_no_wallet_credit'::text,
    r.id, r.referrer_id, r.referred_id, r.reward_amount, NULL::numeric,
    r.rewarded_at, 'Referral marked rewarded but no wallet tx exists'
  FROM referrals r
  WHERE r.rewarded_at IS NOT NULL
    AND r.reward_amount > 0
    AND NOT EXISTS (
      SELECT 1 FROM wallet_transactions wt
      WHERE wt.user_id = r.referrer_id
        AND wt.reference_id = r.id
        AND wt.type = 'referral_bonus'
        AND wt.status = 'completed'
    )
  UNION ALL
  -- B) Amount mismatch
  SELECT 'amount_mismatch'::text,
    r.id, r.referrer_id, r.referred_id, r.reward_amount, wt.amount,
    r.rewarded_at, 'Referral wallet credit amount differs from reward_amount'
  FROM referrals r
  JOIN wallet_transactions wt
    ON wt.user_id = r.referrer_id
   AND wt.reference_id = r.id
   AND wt.type = 'referral_bonus'
   AND wt.status = 'completed'
  WHERE wt.amount <> r.reward_amount
  UNION ALL
  -- C) Orphan: wallet referral_bonus with no source referrals row
  SELECT 'orphan_wallet_credit'::text,
    wt.reference_id, wt.user_id, NULL::uuid, NULL::numeric, wt.amount,
    NULL::timestamptz, 'Wallet credited as referral_bonus but no referrals row exists'
  FROM wallet_transactions wt
  WHERE wt.type = 'referral_bonus'
    AND wt.status = 'completed'
    AND wt.reference_id IS NOT NULL
    AND NOT EXISTS (
      SELECT 1 FROM referrals r WHERE r.id = wt.reference_id
    );
END;
$$;


ALTER FUNCTION "public"."get_referral_drift_admin"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_result_visibility_invariant_admin"() RETURNS TABLE("check_key" "text", "status" "text", "evidence" "jsonb")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH latest_published AS (
    SELECT competition_id,
           max(round_number) FILTER (WHERE published_at IS NOT NULL) AS latest_published_round
    FROM public.competition_round_publish
    GROUP BY competition_id
  ), entries AS (
    SELECT e.id, e.competition_id, e.status, e.placement, e.progression_decision,
           c.round_number AS decision_round, c.family, lp.latest_published_round,
           NULLIF(regexp_replace(COALESCE(e.current_round, ''), '[^0-9]', '', 'g'), '')::int AS current_round_num,
           CASE
             WHEN lp.latest_published_round >= 4 AND e.placement IS NOT NULL THEN e.placement
             WHEN lp.latest_published_round >= 4 AND e.status IN ('winner','finalist') THEN e.status
             WHEN c.stage_key IS NOT NULL AND c.round_number <= lp.latest_published_round THEN c.stage_key
             WHEN lp.latest_published_round >= 3 AND (COALESCE(NULLIF(regexp_replace(COALESCE(e.current_round, ''), '[^0-9]', '', 'g'), '')::int, 0) >= 4 OR e.status IN ('finalist','winner','qualified_final') OR c.round_number >= 4) THEN 'r3_qualified_final'
             WHEN lp.latest_published_round >= 2 AND (COALESCE(NULLIF(regexp_replace(COALESCE(e.current_round, ''), '[^0-9]', '', 'g'), '')::int, 0) >= 3 OR e.status IN ('round2_qualified','finalist','winner','qualified_final') OR c.round_number >= 3) THEN 'r2_qualified_r3'
             WHEN lp.latest_published_round >= 1 AND (COALESCE(NULLIF(regexp_replace(COALESCE(e.current_round, ''), '[^0-9]', '', 'g'), '')::int, 0) >= 2 OR e.status IN ('round1_qualified','round2_qualified','shortlisted','finalist','winner','qualified_final') OR c.round_number >= 2) THEN 'r1_shortlisted_r2'
             ELSE NULL
           END AS expected_status,
           CASE
             WHEN lp.latest_published_round >= 4 AND (e.placement IS NOT NULL OR e.status IN ('winner','finalist')) THEN NULL
             WHEN c.stage_key IS NOT NULL AND c.round_number <= lp.latest_published_round AND c.family IN ('progression_fail','rejection') THEN 'not_selected_for_next_round'
             ELSE NULL
           END AS expected_note
    FROM public.competition_entries e
    JOIN latest_published lp ON lp.competition_id = e.competition_id
    LEFT JOIN public.v3_stage_catalog c ON c.stage_key = e.progression_decision
    WHERE lp.latest_published_round BETWEEN 1 AND 4
  ), eligible AS (
    SELECT * FROM entries WHERE expected_status IS NOT NULL
  ), gated AS (
    SELECT * FROM public.get_gated_entry_status((SELECT COALESCE(array_agg(id), ARRAY[]::uuid[]) FROM eligible))
  ), failures AS (
    SELECT eligible.id, eligible.competition_id, eligible.status AS raw_status, eligible.placement,
           eligible.progression_decision, eligible.decision_round, eligible.latest_published_round,
           eligible.expected_status, eps.public_status AS view_status, gated.public_status AS rpc_status,
           eligible.expected_note, eps.public_progression_note AS view_note, gated.public_progression_note AS rpc_note,
           eps.public_placement AS view_placement, gated.public_placement AS rpc_placement
    FROM eligible
    LEFT JOIN public.entry_public_status eps ON eps.entry_id = eligible.id
    LEFT JOIN gated ON gated.entry_id = eligible.id
    WHERE eps.public_status IS DISTINCT FROM eligible.expected_status
       OR gated.public_status IS DISTINCT FROM eligible.expected_status
       OR eps.public_progression_note IS DISTINCT FROM eligible.expected_note
       OR gated.public_progression_note IS DISTINCT FROM eligible.expected_note
       OR (eligible.latest_published_round >= 4 AND eligible.placement IS NOT NULL AND eps.public_placement IS DISTINCT FROM eligible.placement)
       OR (eligible.latest_published_round >= 4 AND eligible.placement IS NOT NULL AND gated.public_placement IS DISTINCT FROM eligible.placement)
  )
  SELECT 'declared_r1_r2_r3_r4_result_visibility'::text,
         CASE WHEN EXISTS (SELECT 1 FROM failures) THEN 'FAIL' ELSE 'PASS' END::text,
         jsonb_build_object(
           'eligible_declared_results', (SELECT count(*) FROM eligible),
           'failures', (SELECT count(*) FROM failures),
           'failure_rows', COALESCE((SELECT jsonb_agg(to_jsonb(failures)) FROM failures), '[]'::jsonb)
         );
$$;


ALTER FUNCTION "public"."get_result_visibility_invariant_admin"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_round_eligible_photos"("_competition_id" "uuid", "_round_number" integer) RETURNS TABLE("entry_id" "uuid", "photo_index" integer)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  _uid uuid := auth.uid();
BEGIN
  -- Authorization guard. service_role / internal LATERAL callers have auth.jwt() IS NULL
  -- and are permitted to bypass (wrapper RPCs enforce their own auth model).
  IF auth.jwt() IS NOT NULL AND _uid IS NOT NULL THEN
    IF NOT (
      public.has_role(_uid, 'admin'::app_role)
      OR EXISTS (
        SELECT 1 FROM public.competition_judges cj
        WHERE cj.judge_id = _uid AND cj.competition_id = _competition_id
      )
    ) THEN
      RAISE EXCEPTION 'forbidden: not assigned to competition %', _competition_id
        USING ERRCODE = '42501';
    END IF;
  END IF;

  IF to_regclass('public.photo_verification_requests') IS NOT NULL THEN
    RETURN QUERY EXECUTE $sql$
      WITH eligible_prior AS (
        SELECT jd.entry_id, COALESCE(jd.photo_index, 0) AS photo_index
        FROM public.judge_decisions jd
        JOIN public.competition_judges cj
          ON cj.judge_id = jd.judge_id
         AND cj.competition_id = $1
        WHERE jd.round_number = $2 - 1
          AND public.is_qualifying_decision(jd.decision, $2 - 1)
        GROUP BY jd.entry_id, COALESCE(jd.photo_index, 0)
      ),
      active_verification AS (
        SELECT pvr.entry_id, COALESCE(pvr.photo_index, 0) AS photo_index
        FROM public.photo_verification_requests pvr
        WHERE pvr.competition_id = $1
          AND pvr.status IN ('pending', 'submitted')
      )
      SELECT ce.id, gs.idx
      FROM public.competition_entries ce
      CROSS JOIN LATERAL generate_series(0, GREATEST(COALESCE(array_length(ce.photos, 1), 1) - 1, 0)) AS gs(idx)
      WHERE ce.competition_id = $1
        AND ce.status <> 'rejected'
        AND COALESCE((ce.photo_meta->gs.idx->>'rejected')::boolean, false) = false
        AND NOT EXISTS (SELECT 1 FROM active_verification av WHERE av.entry_id = ce.id AND av.photo_index = gs.idx)
        AND (
          $2 = 1
          OR EXISTS (SELECT 1 FROM eligible_prior ep WHERE ep.entry_id = ce.id AND ep.photo_index = gs.idx)
        )
    $sql$ USING _competition_id, _round_number;
  ELSE
    RETURN QUERY
      WITH eligible_prior AS (
        SELECT jd.entry_id, COALESCE(jd.photo_index, 0) AS photo_index
        FROM public.judge_decisions jd
        JOIN public.competition_judges cj
          ON cj.judge_id = jd.judge_id
         AND cj.competition_id = _competition_id
        WHERE jd.round_number = _round_number - 1
          AND public.is_qualifying_decision(jd.decision, _round_number - 1)
        GROUP BY jd.entry_id, COALESCE(jd.photo_index, 0)
      )
      SELECT ce.id, gs.idx
      FROM public.competition_entries ce
      CROSS JOIN LATERAL generate_series(0, GREATEST(COALESCE(array_length(ce.photos, 1), 1) - 1, 0)) AS gs(idx)
      WHERE ce.competition_id = _competition_id
        AND ce.status <> 'rejected'
        AND COALESCE((ce.photo_meta->gs.idx->>'rejected')::boolean, false) = false
        AND (
          _round_number = 1
          OR EXISTS (SELECT 1 FROM eligible_prior ep WHERE ep.entry_id = ce.id AND ep.photo_index = gs.idx)
        );
  END IF;
END;
$_$;


ALTER FUNCTION "public"."get_round_eligible_photos"("_competition_id" "uuid", "_round_number" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_round_judging_gate_admin"("_competition_id" "uuid", "_round_number" integer) RETURNS TABLE("competition_id" "uuid", "round_number" integer, "entry_id" "uuid", "entry_title" "text", "entry_status" "text", "total_photos" integer, "ui_eligible_photos" integer, "ui_eligible_photo_indices" integer[], "assigned_judges" integer, "expected_decisions" integer, "present_decisions" integer, "missing_decisions" integer, "missing_decision_sample" "jsonb", "expected_scores" integer, "missing_scores" integer, "missing_score_sample" "jsonb", "verification_pending" boolean, "ready_to_lock" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
#variable_conflict use_column
DECLARE
  v_is_distributed boolean;
BEGIN
  -- Admin-only — same guard pattern as every other admin audit RPC.
  IF NOT public.has_role(auth.uid(), 'admin'::public.app_role) THEN
    RAISE EXCEPTION 'forbidden: admin role required';
  END IF;

  IF _round_number IS NULL OR _round_number < 1 OR _round_number > 4 THEN
    RAISE EXCEPTION 'round_number must be between 1 and 4';
  END IF;

  SELECT (c.judge_assignment_mode = 'distributed')
    INTO v_is_distributed
  FROM public.competitions c
  WHERE c.id = _competition_id;

  IF v_is_distributed IS NULL THEN
    RAISE EXCEPTION 'competition not found: %', _competition_id;
  END IF;

  RETURN QUERY
  WITH entries AS (
    SELECT
      e.id          AS entry_id,
      e.title       AS entry_title,
      e.status      AS entry_status,
      COALESCE(array_length(e.photos, 1), 0) AS total_photos
    FROM public.competition_entries e
    WHERE e.competition_id = _competition_id
      AND e.status <> 'rejected'          -- PERMFIX: rejected entries are out of the judging surface
  ),
  -- All photo indices for every entry (0-based, matches photo_index storage)
  all_photos AS (
    SELECT
      en.entry_id,
      gs.pi AS photo_index
    FROM entries en
    CROSS JOIN LATERAL generate_series(0, GREATEST(en.total_photos - 1, 0)) AS gs(pi)
    WHERE en.total_photos > 0
  ),
  -- Judge-UI eligible photo set:
  --   R1 -> every uploaded photo
  --   R2+ -> exactly what get_round_eligible_photos returns (the same RPC the
  --          judge classic data hook calls)
  eligible AS (
    SELECT entry_id, photo_index
    FROM all_photos
    WHERE _round_number = 1
    UNION ALL
    SELECT g.entry_id, g.photo_index
    FROM public.get_round_eligible_photos(_competition_id, _round_number) AS g
    WHERE _round_number >= 2
  ),
  eligible_per_entry AS (
    SELECT
      entry_id,
      COUNT(*)::int                          AS ui_eligible_photos,
      ARRAY_AGG(photo_index ORDER BY photo_index) AS ui_eligible_photo_indices
    FROM eligible
    GROUP BY entry_id
  ),
  -- Assigned judges per entry: distributed -> judge_entry_assignments,
  -- otherwise every competition_judges row applies to every entry.
  comp_judges AS (
    SELECT cj.judge_id
    FROM public.competition_judges cj
    WHERE cj.competition_id = _competition_id
  ),
  judges_per_entry AS (
    SELECT en.entry_id, cj.judge_id
    FROM entries en
    CROSS JOIN comp_judges cj
    WHERE NOT v_is_distributed
    UNION ALL
    SELECT jea.entry_id, jea.judge_id
    FROM public.judge_entry_assignments jea
    WHERE v_is_distributed
      AND jea.competition_id = _competition_id
  ),
  judge_count_per_entry AS (
    SELECT entry_id, COUNT(DISTINCT judge_id)::int AS assigned_judges
    FROM judges_per_entry
    GROUP BY entry_id
  ),
  -- Expected (judge, photo) coverage tuples for this round.
  expected AS (
    SELECT el.entry_id, el.photo_index, jpe.judge_id
    FROM eligible el
    JOIN judges_per_entry jpe ON jpe.entry_id = el.entry_id
  ),
  -- Decisions present: explicit judge_decisions for this round
  --   PLUS, in R1 only, synthesized from judge_tag_assignments (mirrors the
  --   "tag-only judges" path inside complete-round).
  decisions_present AS (
    SELECT jd.entry_id, jd.photo_index, jd.judge_id
    FROM public.judge_decisions jd
    JOIN entries en ON en.entry_id = jd.entry_id
    WHERE jd.round_number = _round_number
    UNION
    SELECT jta.entry_id, jta.photo_index, jta.judge_id
    FROM public.judge_tag_assignments jta
    JOIN entries en ON en.entry_id = jta.entry_id
    WHERE _round_number = 1
      AND (
        jta.round_number = 1
        OR jta.round_number IS NULL  -- legacy rows; complete-round treats them as R1
      )
  ),
  decision_stats AS (
    SELECT
      e.entry_id,
      COUNT(*)::int AS expected_decisions,
      COUNT(dp.judge_id)::int AS present_decisions
    FROM expected e
    LEFT JOIN decisions_present dp
      ON dp.entry_id = e.entry_id
     AND dp.photo_index = e.photo_index
     AND dp.judge_id = e.judge_id
    GROUP BY e.entry_id
  ),
  missing_decision_rows AS (
    SELECT e.entry_id, e.photo_index, e.judge_id
    FROM expected e
    LEFT JOIN decisions_present dp
      ON dp.entry_id = e.entry_id
     AND dp.photo_index = e.photo_index
     AND dp.judge_id = e.judge_id
    WHERE dp.judge_id IS NULL
  ),
  missing_decision_sample AS (
    SELECT
      entry_id,
      jsonb_agg(
        jsonb_build_object(
          'judge_id', judge_id,
          'photo_index', photo_index
        )
        ORDER BY photo_index, judge_id
      ) FILTER (WHERE rn <= 20) AS sample
    FROM (
      SELECT
        entry_id, photo_index, judge_id,
        ROW_NUMBER() OVER (PARTITION BY entry_id ORDER BY photo_index, judge_id) AS rn
      FROM missing_decision_rows
    ) s
    GROUP BY entry_id
  ),
  -- 10-criteria score coverage gate (R2/R3/R4 only) — same 10 SOW columns
  -- as supabase/functions/complete-round/index.ts.
  scores_present AS (
    SELECT js.entry_id, js.photo_index, js.judge_id
    FROM public.judge_scores js
    JOIN entries en ON en.entry_id = js.entry_id
    WHERE _round_number >= 2
      AND js.round_number = _round_number
      AND js.line_score          IS NOT NULL
      AND js.shape_score         IS NOT NULL
      AND js.form_score          IS NOT NULL
      AND js.texture_score       IS NOT NULL
      AND js.color_palette_score IS NOT NULL
      AND js.space_score         IS NOT NULL
      AND js.tone_score          IS NOT NULL
      AND js.balance_score       IS NOT NULL
      AND js.light_score         IS NOT NULL
      AND js.depth_score         IS NOT NULL
  ),
  score_stats AS (
    SELECT
      e.entry_id,
      COUNT(*)::int AS expected_scores,
      COUNT(*)::int - COUNT(sp.judge_id)::int AS missing_scores
    FROM expected e
    LEFT JOIN scores_present sp
      ON sp.entry_id = e.entry_id
     AND sp.photo_index = e.photo_index
     AND sp.judge_id = e.judge_id
    WHERE _round_number >= 2
    GROUP BY e.entry_id
  ),
  missing_score_rows AS (
    SELECT e.entry_id, e.photo_index, e.judge_id
    FROM expected e
    LEFT JOIN scores_present sp
      ON sp.entry_id = e.entry_id
     AND sp.photo_index = e.photo_index
     AND sp.judge_id = e.judge_id
    WHERE _round_number >= 2
      AND sp.judge_id IS NULL
  ),
  missing_score_sample AS (
    SELECT
      entry_id,
      jsonb_agg(
        jsonb_build_object(
          'judge_id', judge_id,
          'photo_index', photo_index
        )
        ORDER BY photo_index, judge_id
      ) FILTER (WHERE rn <= 20) AS sample
    FROM (
      SELECT
        entry_id, photo_index, judge_id,
        ROW_NUMBER() OVER (PARTITION BY entry_id ORDER BY photo_index, judge_id) AS rn
      FROM missing_score_rows
    ) s
    GROUP BY entry_id
  )
  SELECT
    _competition_id                           AS competition_id,
    _round_number                             AS round_number,
    en.entry_id,
    en.entry_title,
    en.entry_status,
    en.total_photos,
    COALESCE(epe.ui_eligible_photos, 0)       AS ui_eligible_photos,
    COALESCE(epe.ui_eligible_photo_indices, ARRAY[]::int[]) AS ui_eligible_photo_indices,
    COALESCE(jc.assigned_judges, 0)           AS assigned_judges,
    COALESCE(ds.expected_decisions, 0)        AS expected_decisions,
    COALESCE(ds.present_decisions, 0)         AS present_decisions,
    COALESCE(ds.expected_decisions, 0) - COALESCE(ds.present_decisions, 0)
                                              AS missing_decisions,
    COALESCE(mds.sample, '[]'::jsonb)         AS missing_decision_sample,
    CASE WHEN _round_number >= 2 THEN COALESCE(ss.expected_scores, 0) ELSE 0 END
                                              AS expected_scores,
    CASE WHEN _round_number >= 2 THEN COALESCE(ss.missing_scores, 0) ELSE 0 END
                                              AS missing_scores,
    COALESCE(mss.sample, '[]'::jsonb)         AS missing_score_sample,
    CASE
      WHEN _round_number = 4
        THEN public.any_photo_pending(en.entry_id, _round_number)
      ELSE FALSE
    END                                       AS verification_pending,
    (
      COALESCE(epe.ui_eligible_photos, 0) > 0
      AND (COALESCE(ds.expected_decisions, 0) - COALESCE(ds.present_decisions, 0)) = 0
      AND (CASE WHEN _round_number >= 2 THEN COALESCE(ss.missing_scores, 0) ELSE 0 END) = 0
      AND (
        _round_number <> 4
        OR NOT public.any_photo_pending(en.entry_id, _round_number)
      )
    )                                         AS ready_to_lock
  FROM entries en
  LEFT JOIN eligible_per_entry      epe ON epe.entry_id = en.entry_id
  LEFT JOIN judge_count_per_entry   jc  ON jc.entry_id  = en.entry_id
  LEFT JOIN decision_stats          ds  ON ds.entry_id  = en.entry_id
  LEFT JOIN missing_decision_sample mds ON mds.entry_id = en.entry_id
  LEFT JOIN score_stats             ss  ON ss.entry_id  = en.entry_id
  LEFT JOIN missing_score_sample    mss ON mss.entry_id = en.entry_id
  ORDER BY
    -- mismatches first so admins see them at the top
    (
      COALESCE(epe.ui_eligible_photos, 0) > 0
      AND (COALESCE(ds.expected_decisions, 0) - COALESCE(ds.present_decisions, 0)) = 0
      AND (CASE WHEN _round_number >= 2 THEN COALESCE(ss.missing_scores, 0) ELSE 0 END) = 0
      AND (_round_number <> 4 OR NOT public.any_photo_pending(en.entry_id, _round_number))
    ) ASC,
    en.entry_title NULLS LAST,
    en.entry_id;
END;
$$;


ALTER FUNCTION "public"."get_round_judging_gate_admin"("_competition_id" "uuid", "_round_number" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_round_judging_gate_admin"("_competition_id" "uuid", "_round_number" integer) IS 'Admin-only forensic audit. Returns per-entry comparison of judge-UI eligible photos vs the DB gate requirements (decisions, 10-criteria scores, R4 verification) used by complete-round / publish-round. Read-only.';



CREATE OR REPLACE FUNCTION "public"."get_round_judging_gate_self"("_competition_id" "uuid", "_round_number" integer) RETURNS TABLE("competition_id" "uuid", "round_number" integer, "entry_id" "uuid", "entry_title" "text", "total_photos" integer, "ui_eligible_photo_indices" integer[], "ui_eligible_photos" integer, "my_decisions_present" integer, "my_decisions_missing" integer, "my_scores_missing" integer, "ready_to_complete" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
#variable_conflict use_column
DECLARE
  _caller_id    UUID := auth.uid();
  _is_admin     BOOLEAN;
  _is_judge     BOOLEAN;
  _is_dist      BOOLEAN;
BEGIN
  IF _caller_id IS NULL THEN
    RAISE EXCEPTION 'Unauthorized: must be authenticated';
  END IF;

  SELECT public.has_role(_caller_id, 'admin') INTO _is_admin;

  -- Is the caller an assigned judge for this competition?
  SELECT EXISTS (
    SELECT 1 FROM public.competition_judges
    WHERE competition_id = _competition_id
      AND judge_id       = _caller_id
  ) INTO _is_judge;

  IF NOT (_is_admin OR _is_judge) THEN
    RAISE EXCEPTION 'Forbidden: not an assigned judge for this competition';
  END IF;

  -- Distributed-mode flag (per-entry assignment)
  SELECT (judge_assignment_mode = 'distributed')
    INTO _is_dist
    FROM public.competitions
   WHERE id = _competition_id;
  _is_dist := COALESCE(_is_dist, FALSE);

  RETURN QUERY
  WITH
  -- Step 1: resolve caller's assigned entries.
  -- In distributed mode, restrict to judge_entry_assignments.
  -- Otherwise the judge is responsible for every entry in the comp.
  my_entries AS (
    SELECT
      e.id           AS entry_id,
      e.title        AS entry_title,
      e.photos,
      e.photo_meta,
      COALESCE(array_length(e.photos, 1), 1) AS total_photos
    FROM public.competition_entries e
    WHERE e.competition_id = _competition_id
      AND e.status <> 'rejected'          -- PERMFIX: rejected entries are out of the judging surface
      AND (
        _is_admin
        OR NOT _is_dist
        OR EXISTS (
          SELECT 1 FROM public.judge_entry_assignments jea
          WHERE jea.competition_id = _competition_id
            AND jea.entry_id       = e.id
            AND jea.judge_id       = _caller_id
        )
      )
  ),
  -- Step 2: per-photo eligibility.
  -- R1 → every non-rejected photo of every assigned entry.
  -- R2+ → only photos that the judge personally shortlisted in round N-1.
  --       This mirrors the edge fn's `fetchEligiblePhotoKeys` exactly, scoped
  --       to the caller (instead of "any judge" for the admin-side audit).
  exploded AS (
    SELECT
      m.entry_id,
      m.entry_title,
      m.total_photos,
      gs.pi AS photo_index,
      COALESCE((m.photo_meta -> gs.pi ->> 'rejected')::boolean, FALSE) AS is_rejected
    FROM my_entries m
    CROSS JOIN LATERAL generate_series(0, m.total_photos - 1) AS gs(pi)
  ),
  eligible AS (
    SELECT
      x.entry_id,
      x.entry_title,
      x.total_photos,
      x.photo_index
    FROM exploded x
    WHERE x.is_rejected = FALSE
      AND (
        _round_number = 1
        OR EXISTS (
          SELECT 1 FROM public.judge_decisions jd
          WHERE jd.entry_id     = x.entry_id
            AND jd.photo_index  = x.photo_index
            AND jd.round_number = _round_number - 1
            AND jd.judge_id     = _caller_id
            AND lower(trim(jd.decision)) = ANY (
              CASE _round_number - 1
                WHEN 1 THEN ARRAY['shortlist','shortlisted']
                WHEN 2 THEN ARRAY['qualified_r3','shortlist','shortlisted','qualified','qualified_for_r3','qualified for r3']
                WHEN 3 THEN ARRAY['qualified_final','shortlisted_final','qualified','shortlist','shortlisted','finalist','shortlisted_for_final','shortlisted for final']
                ELSE ARRAY[]::text[]
              END
            )
        )
      )
  ),
  per_entry AS (
    SELECT
      el.entry_id,
      el.entry_title,
      el.total_photos,
      array_agg(el.photo_index ORDER BY el.photo_index) AS ui_eligible_photo_indices,
      COUNT(*)::int AS ui_eligible_photos
    FROM eligible el
    GROUP BY el.entry_id, el.entry_title, el.total_photos
  ),
  my_dec AS (
    SELECT
      pe.entry_id,
      COUNT(*) FILTER (
        WHERE EXISTS (
          SELECT 1 FROM public.judge_decisions jd
          WHERE jd.entry_id     = pe.entry_id
            AND jd.judge_id     = _caller_id
            AND jd.round_number = _round_number
            AND jd.photo_index  = ANY (pe.ui_eligible_photo_indices)
        )
      )::int AS dummy
    FROM per_entry pe
    GROUP BY pe.entry_id
  ),
  my_dec_real AS (
    SELECT
      pe.entry_id,
      COUNT(jd.*)::int AS present
    FROM per_entry pe
    LEFT JOIN public.judge_decisions jd
           ON jd.entry_id     = pe.entry_id
          AND jd.judge_id     = _caller_id
          AND jd.round_number = _round_number
          AND jd.photo_index  = ANY (pe.ui_eligible_photo_indices)
    GROUP BY pe.entry_id
  ),
  my_score_missing AS (
    -- For R2/R3/R4, every eligible photo needs a judge_scores row with all 10
    -- SOW criteria non-null. R1 has no score requirement.
    SELECT
      pe.entry_id,
      CASE
        WHEN _round_number = 1 THEN 0
        ELSE pe.ui_eligible_photos - COUNT(js.*) FILTER (
          WHERE js.line_score IS NOT NULL
            AND js.shape_score IS NOT NULL
            AND js.form_score IS NOT NULL
            AND js.texture_score IS NOT NULL
            AND js.color_palette_score IS NOT NULL
            AND js.space_score IS NOT NULL
            AND js.tone_score IS NOT NULL
            AND js.balance_score IS NOT NULL
            AND js.light_score IS NOT NULL
            AND js.depth_score IS NOT NULL
        )::int
      END AS missing
    FROM per_entry pe
    LEFT JOIN public.judge_scores js
           ON js.entry_id     = pe.entry_id
          AND js.judge_id     = _caller_id
          AND js.round_number = _round_number
          AND js.photo_index  = ANY (pe.ui_eligible_photo_indices)
    GROUP BY pe.entry_id, pe.ui_eligible_photos
  )
  SELECT
    _competition_id,
    _round_number,
    pe.entry_id,
    pe.entry_title,
    pe.total_photos,
    pe.ui_eligible_photo_indices,
    pe.ui_eligible_photos,
    md.present                                      AS my_decisions_present,
    GREATEST(pe.ui_eligible_photos - md.present, 0) AS my_decisions_missing,
    GREATEST(msm.missing, 0)                        AS my_scores_missing,
    (
      pe.ui_eligible_photos = md.present
      AND COALESCE(msm.missing, 0) = 0
    ) AS ready_to_complete
  FROM per_entry pe
  LEFT JOIN my_dec_real    md  ON md.entry_id  = pe.entry_id
  LEFT JOIN my_score_missing msm ON msm.entry_id = pe.entry_id
  ORDER BY pe.entry_title NULLS LAST;
END;
$$;


ALTER FUNCTION "public"."get_round_judging_gate_self"("_competition_id" "uuid", "_round_number" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_round_judging_gate_self"("_competition_id" "uuid", "_round_number" integer) IS 'Judge-scoped twin of get_round_judging_gate_admin. Returns the canonical UI-eligible photo set per assigned entry plus the caller''s personal decision/score coverage. Backs the Complete Round preflight UI so it cannot drift from the complete-round edge fn gate.';



CREATE OR REPLACE FUNCTION "public"."get_round_pending_entries"("p_competition_id" "uuid", "p_round" integer) RETURNS TABLE("entry_id" "uuid")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT e.id
  FROM public.competition_entries e
  WHERE e.competition_id = p_competition_id
    AND NULLIF(regexp_replace(COALESCE(e.current_round, ''), '[^0-9]', '', 'g'), '')::int = p_round
    AND public.any_photo_pending(e.id) = TRUE;
$$;


ALTER FUNCTION "public"."get_round_pending_entries"("p_competition_id" "uuid", "p_round" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_round_pending_entries"("p_competition_id" "uuid", "p_round" integer) IS 'Phase 5 admin pending-gate helper. Returns entry ids in (competition, round) where any_photo_pending() = true. Read-only.';



CREATE OR REPLACE FUNCTION "public"."get_round_summary"("p_competition_id" "uuid", "p_round_number" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_is_admin boolean;
  v_is_judge boolean;
  v_round_str text := p_round_number::text;
  v_total int;
  v_qualified int;
  v_rejected int;
  v_needs_review int;
  v_pending int;
  v_top jsonb;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Unauthorized' USING ERRCODE = '42501'; END IF;
  SELECT has_role(v_uid, 'admin'::app_role) INTO v_is_admin;
  SELECT has_role(v_uid, 'judge'::app_role) INTO v_is_judge;
  IF NOT (v_is_admin OR v_is_judge) THEN
    RAISE EXCEPTION 'Forbidden: judge or admin role required' USING ERRCODE = '42501';
  END IF;

  SELECT COALESCE(SUM(GREATEST(COALESCE(array_length(ce.photos, 1), 0), 1)), 0)
    INTO v_total
  FROM competition_entries ce
  WHERE ce.competition_id = p_competition_id
    AND ce.current_round = v_round_str;

  WITH photo_decisions AS (
    SELECT DISTINCT ON (jd.entry_id, jd.photo_index)
      jd.entry_id, jd.photo_index, jd.decision
    FROM judge_decisions jd
    JOIN competition_entries ce ON ce.id = jd.entry_id
    WHERE ce.competition_id = p_competition_id
      AND ce.current_round = v_round_str
      AND jd.round_number = p_round_number
    ORDER BY jd.entry_id, jd.photo_index, jd.updated_at DESC NULLS LAST, jd.judge_id
  )
  SELECT
    -- Phase R2 Step 2.1b: include canonical v3 tokens in qualified count
    COUNT(*) FILTER (WHERE decision IN (
      'accept','accepted','shortlist','shortlisted',
      'qualified_r3','shortlisted_final',
      'round1_qualified','round2_qualified','finalist','winner'
    )),
    COUNT(*) FILTER (WHERE decision IN ('reject','rejected')),
    COUNT(*) FILTER (WHERE decision = 'needs_review')
  INTO v_qualified, v_rejected, v_needs_review
  FROM photo_decisions;

  v_pending := GREATEST(0, v_total - v_qualified - v_rejected - v_needs_review);

  WITH photo_scores AS (
    SELECT js.entry_id, js.photo_index, AVG(js.score)::numeric AS avg_score
    FROM judge_scores js
    JOIN competition_entries ce ON ce.id = js.entry_id
    WHERE ce.competition_id = p_competition_id
      AND ce.current_round = v_round_str
      AND js.score IS NOT NULL
    GROUP BY js.entry_id, js.photo_index
  ),
  photo_latest_decisions AS (
    SELECT DISTINCT ON (jd.entry_id, jd.photo_index)
      jd.entry_id, jd.photo_index, jd.decision
    FROM judge_decisions jd
    JOIN competition_entries ce ON ce.id = jd.entry_id
    WHERE ce.competition_id = p_competition_id
      AND ce.current_round = v_round_str
      AND jd.round_number = p_round_number
    ORDER BY jd.entry_id, jd.photo_index, jd.updated_at DESC NULLS LAST, jd.judge_id
  )
  SELECT COALESCE(jsonb_agg(t ORDER BY t.avg_score DESC NULLS LAST), '[]'::jsonb)
  INTO v_top
  FROM (
    SELECT ce.id,
      (ce.title || ' (Image ' || (ps.photo_index + 1)::text || ')') AS title,
      COALESCE(pld.decision, 'pending') AS status,
      (CASE
        WHEN COALESCE(array_length(ce.photo_thumbnails, 1), 0) > ps.photo_index
          THEN ce.photo_thumbnails[ps.photo_index + 1]
        WHEN COALESCE(array_length(ce.photos, 1), 0) > ps.photo_index
          THEN ce.photos[ps.photo_index + 1]
        ELSE NULL
      END) AS thumbnail,
      ps.avg_score
    FROM photo_scores ps
    JOIN competition_entries ce ON ce.id = ps.entry_id
    LEFT JOIN photo_latest_decisions pld
      ON pld.entry_id = ps.entry_id AND pld.photo_index = ps.photo_index
    ORDER BY ps.avg_score DESC NULLS LAST
    LIMIT 10
  ) t;

  RETURN jsonb_build_object(
    'total', v_total,
    'qualified', v_qualified,
    'rejected', v_rejected,
    'needs_review', v_needs_review,
    'pending', v_pending,
    'top_entries', v_top
  );
END;
$$;


ALTER FUNCTION "public"."get_round_summary"("p_competition_id" "uuid", "p_round_number" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_status_stage_key_drift_admin"() RETURNS TABLE("entry_id" "uuid", "stage_key" "text", "status" "text", "derived" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT id, stage_key, status::text, public.derive_status_from_stage_key(stage_key)
    FROM public.competition_entries
   WHERE stage_key IS NOT NULL
     AND status::text IS DISTINCT FROM public.derive_status_from_stage_key(stage_key);
$$;


ALTER FUNCTION "public"."get_status_stage_key_drift_admin"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_system_tag_catalog_drift"() RETURNS TABLE("side" "text", "round_number" integer, "label_or_canonical" "text", "tag_id" "uuid", "stage_key" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT 'tag_without_catalog'::text AS side,
         (jt.visible_in_round)[1]    AS round_number,
         jt.label                    AS label_or_canonical,
         jt.id                       AS tag_id,
         NULL::text                  AS stage_key
  FROM public.judging_tags jt
  WHERE jt.is_system = true
    AND jt.is_active = true
    AND NOT EXISTS (
      SELECT 1 FROM public.v3_stage_catalog sc
      WHERE sc.is_active = true
        AND lower(trim(sc.tag_label_canonical)) = lower(trim(jt.label))
    )
  UNION ALL
  SELECT 'catalog_without_tag'::text,
         sc.round_number,
         sc.tag_label_canonical,
         NULL::uuid,
         sc.stage_key
  FROM public.v3_stage_catalog sc
  WHERE sc.is_active = true
    AND sc.tag_label_canonical IS NOT NULL
    AND NOT EXISTS (
      SELECT 1 FROM public.judging_tags jt
      WHERE jt.is_system = true
        AND jt.is_active = true
        AND lower(trim(jt.label)) = lower(trim(sc.tag_label_canonical))
    );
$$;


ALTER FUNCTION "public"."get_system_tag_catalog_drift"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_test_agent_health_admin"() RETURNS TABLE("rpc_parity_pass" boolean, "rpc_parity_sample_size" integer, "rpc_parity_mismatch_count" integer, "nr_drift_5min" integer, "nr_drift_24h" integer, "dual_emit_status" "text", "super_admin_email" "text", "checked_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_sample UUID[];
  v_mismatch_count INTEGER := 0;
  v_sample_size INTEGER := 0;
  v_admin_email TEXT;
  v_dual_emit TEXT := 'unknown';
BEGIN
  IF NOT public.has_role(auth.uid(), 'admin') THEN
    RAISE EXCEPTION 'Forbidden: admin role required';
  END IF;
  SELECT array_agg(id) INTO v_sample
  FROM (
    SELECT id FROM public.competition_entries
    WHERE status IS NOT NULL
    ORDER BY updated_at DESC NULLS LAST
    LIMIT 50
  ) s;

  IF v_sample IS NOT NULL THEN
    SELECT COUNT(*) INTO v_sample_size
    FROM public.get_per_photo_consensus(v_sample);

    SELECT COUNT(*) INTO v_mismatch_count
    FROM public.get_per_photo_consensus(v_sample)
    WHERE status IS NULL;

    v_dual_emit := CASE
      WHEN v_sample_size = 0 THEN 'no_data'
      WHEN v_mismatch_count = 0 THEN 'healthy'
      ELSE 'drift_detected'
    END;
  END IF;

  SELECT u.email::text INTO v_admin_email
  FROM public.user_roles ur
  JOIN auth.users u ON u.id = ur.user_id
  WHERE ur.role::text = 'admin'
    AND u.email IS NOT NULL
  ORDER BY u.email
  LIMIT 1;

  RETURN QUERY SELECT
    (v_mismatch_count = 0 AND v_sample_size > 0) AS rpc_parity_pass,
    v_sample_size,
    v_mismatch_count,
    (SELECT COUNT(*)::INTEGER FROM public.db_audit_logs
     WHERE operation = 'NR_DRIFT_R2_PLUS'
       AND created_at > now() - interval '5 minutes'),
    (SELECT COUNT(*)::INTEGER FROM public.db_audit_logs
     WHERE operation = 'NR_DRIFT_R2_PLUS'
       AND created_at > now() - interval '24 hours'),
    v_dual_emit,
    v_admin_email,
    now();
END;
$$;


ALTER FUNCTION "public"."get_test_agent_health_admin"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_todays_birthdays"("_viewer" "uuid") RETURNS TABLE("id" "uuid", "full_name" "text", "avatar_url" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT p.id, p.full_name, p.avatar_url
  FROM public.profiles p
  WHERE p.is_suspended = false
    AND p.date_of_birth IS NOT NULL
    AND to_char(p.date_of_birth, 'MM-DD') = to_char(now(), 'MM-DD')
    AND (
      p.id = _viewer
      OR COALESCE(NULLIF(p.privacy_settings->>'dob_day_month', ''), 'friends') = 'public'
      OR (
        COALESCE(NULLIF(p.privacy_settings->>'dob_day_month', ''), 'friends') = 'friends'
        AND EXISTS (
          SELECT 1 FROM public.friendships f
          WHERE f.status = 'accepted'
            AND (
              (f.requester_id = _viewer AND f.addressee_id = p.id)
              OR (f.addressee_id = _viewer AND f.requester_id = p.id)
            )
        )
      )
    )
  ORDER BY p.full_name NULLS LAST;
$$;


ALTER FUNCTION "public"."get_todays_birthdays"("_viewer" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_todays_birthdays"("_viewer" "uuid") IS 'Members whose birthday is today, filtered by their own privacy_settings dob_day_month (default friends). No row limit - replaces a LIMIT 50 in dashboard-init that hid 28 of 68 members.';



CREATE OR REPLACE FUNCTION "public"."get_top_contributors_v1"() RETURNS TABLE("user_id" "uuid", "posts_count" bigint, "likes_received" bigint, "comments_received" bigint, "score" numeric)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    p.user_id,
    COUNT(DISTINCT p.id)                AS posts_count,
    COUNT(DISTINCT pr.id)               AS likes_received,
    COUNT(DISTINCT pc.id)               AS comments_received,
    (COUNT(DISTINCT p.id) * 2
     + COUNT(DISTINCT pr.id) * 1
     + COUNT(DISTINCT pc.id) * 1.5)     AS score
  FROM posts p
  LEFT JOIN post_reactions pr ON pr.post_id = p.id
  LEFT JOIN post_comments pc ON pc.post_id = p.id
  WHERE p.privacy = 'public'
    AND p.created_at > now() - interval '30 days'
    AND NOT EXISTS (
      SELECT 1 FROM user_roles ur
      WHERE ur.user_id = p.user_id
        AND ur.role::text IN ('admin', 'moderator')
    )
  GROUP BY p.user_id
  ORDER BY score DESC
  LIMIT 3;
$$;


ALTER FUNCTION "public"."get_top_contributors_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_top_contributors_v2"() RETURNS TABLE("user_id" "uuid", "rank_position" integer, "contributor_score" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH recent AS (
    SELECT r.uid, r.score
    FROM public.contributor_points_since(
      ((now() AT TIME ZONE 'UTC')::date - 29)
    ) r
    WHERE r.score > 0
  ),
  lifetime AS (
    SELECT l.uid, l.score FROM public.contributor_points_since(NULL::date) l
  ),
  ranked AS (
    -- uid is the tie-break so the order is stable between calls rather than
    -- shuffling two equal scores on every refresh.
    SELECT rc.uid,
           ROW_NUMBER() OVER (ORDER BY rc.score DESC, rc.uid) AS pos
    FROM recent rc
  )
  SELECT rk.uid,
         rk.pos::integer,
         ROUND(COALESCE(lf.score, 0))::integer
  FROM ranked rk
  LEFT JOIN lifetime lf ON lf.uid = rk.uid
  WHERE rk.pos <= 3
  ORDER BY rk.pos;
$$;


ALTER FUNCTION "public"."get_top_contributors_v2"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_top_contributors_v2"() IS 'Home page Top Contributors. Ranked by rolling last 30 UTC days, returns the lifetime Contributor Score for display. Never returns the 30-day score, counts or engagement. Replaces get_top_contributors_v1, which is left in place for rollback.';



CREATE OR REPLACE FUNCTION "public"."get_unjudged_parity_admin"("p_judge_id" "uuid", "p_competition_id" "uuid", "p_round_number" integer) RETURNS TABLE("judge_id" "uuid", "competition_id" "uuid", "round_number" integer, "eligible_count" integer, "tagged_count" integer, "sidebar_unjudged" integer, "grid_unjudged" integer, "drift" integer, "drift_photos" "jsonb")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_is_admin boolean;
BEGIN
  -- Admin gate (mirrors other forensic RPCs)
  SELECT public.has_role(auth.uid(), 'admin'::app_role)
    INTO v_is_admin;

  IF NOT COALESCE(v_is_admin, false) THEN
    RAISE EXCEPTION 'forbidden: admin role required';
  END IF;

  RETURN QUERY
  WITH eligible AS (
    -- Round 1: every photo of every submitted entry
    SELECT ce.id AS entry_id, gs.idx AS photo_index
    FROM public.competition_entries ce
    CROSS JOIN LATERAL generate_series(0, GREATEST(array_length(ce.photos, 1), 1) - 1) AS gs(idx)
    WHERE ce.competition_id = p_competition_id
      AND ce.status = 'submitted'
      AND p_round_number = 1

    UNION ALL

    -- Round 2+: photos that ANY judge tagged as shortlist/qualified in prior round
    SELECT jpt.entry_id, jpt.photo_index
    FROM public.judge_tag_assignments jpt
    JOIN public.judging_tags t ON t.id = jpt.tag_id
    JOIN public.competition_entries ce ON ce.id = jpt.entry_id
    WHERE ce.competition_id = p_competition_id
      AND p_round_number > 1
      AND jpt.round_number = p_round_number - 1
      AND COALESCE(t.label, '') ILIKE ANY (ARRAY['%shortlist%', '%qualified%'])
    GROUP BY jpt.entry_id, jpt.photo_index
  ),
  eligible_dedup AS (
    SELECT DISTINCT entry_id, photo_index FROM eligible
  ),
  tagged AS (
    SELECT DISTINCT jpt.entry_id, jpt.photo_index
    FROM public.judge_tag_assignments jpt
    JOIN public.competition_entries ce ON ce.id = jpt.entry_id
    WHERE ce.competition_id = p_competition_id
      AND jpt.judge_id = p_judge_id
      AND jpt.round_number = p_round_number
  ),
  unjudged AS (
    SELECT e.entry_id, e.photo_index
    FROM eligible_dedup e
    LEFT JOIN tagged tg
      ON tg.entry_id = e.entry_id AND tg.photo_index = e.photo_index
    WHERE tg.entry_id IS NULL
  ),
  totals AS (
    SELECT
      (SELECT count(*)::int FROM eligible_dedup)               AS eligible_count,
      (SELECT count(*)::int FROM tagged
        WHERE (entry_id, photo_index) IN
              (SELECT entry_id, photo_index FROM eligible_dedup)) AS tagged_count,
      (SELECT count(*)::int FROM unjudged)                     AS unjudged_count
  )
  SELECT
    p_judge_id,
    p_competition_id,
    p_round_number,
    t.eligible_count,
    t.tagged_count,
    (t.eligible_count - t.tagged_count)::int  AS sidebar_unjudged,
    t.unjudged_count                          AS grid_unjudged,
    ((t.eligible_count - t.tagged_count) - t.unjudged_count)::int AS drift,
    COALESCE(
      (SELECT jsonb_agg(jsonb_build_object(
        'entry_id', u.entry_id,
        'photo_index', u.photo_index
      ) ORDER BY u.entry_id, u.photo_index)
       FROM unjudged u),
      '[]'::jsonb
    ) AS drift_photos
  FROM totals t;
END;
$$;


ALTER FUNCTION "public"."get_unjudged_parity_admin"("p_judge_id" "uuid", "p_competition_id" "uuid", "p_round_number" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_unjudged_parity_admin"("p_judge_id" "uuid", "p_competition_id" "uuid", "p_round_number" integer) IS 'J-03 forensic parity: compares sidebar unjudged count vs grid unjudged set for one (judge, competition, round) under the strict v5 tag-only rule. Admin/super_admin only.';



CREATE OR REPLACE FUNCTION "public"."global_search"("term" "text", "section" "text" DEFAULT 'all'::"text", "username_only" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  q text := lower(trim(term));
  pat text;
  result jsonb := '{}'::jsonb;
BEGIN
  IF q IS NULL OR length(q) < 1 THEN
    RETURN '{}'::jsonb;
  END IF;
  q := left(q, 80);
  pat := '%' || q || '%';

  IF section IN ('all', 'person') THEN
    result := result || jsonb_build_object('people', COALESCE((
      SELECT jsonb_agg(to_jsonb(t)) FROM (
        SELECT p.id, p.full_name, p.avatar_url, p.custom_url,
               COALESCE(ps.followers_count, 0) AS followers_count,
               (CASE
                  WHEN lower(coalesce(p.custom_url, '')) = q
                    OR (NOT username_only AND lower(coalesce(p.full_name, '')) = q) THEN 3
                  WHEN lower(coalesce(p.custom_url, '')) LIKE q || '%'
                    OR (NOT username_only AND lower(coalesce(p.full_name, '')) LIKE q || '%') THEN 2
                  WHEN NOT username_only AND lower(coalesce(p.full_name, '')) LIKE '% ' || q || '%' THEN 1.5
                  ELSE greatest(
                    similarity(lower(coalesce(p.custom_url, '')), q),
                    CASE WHEN username_only THEN 0
                         ELSE similarity(lower(coalesce(p.full_name, '')), q) END)
                END)::float AS score
        FROM public.profiles_public_data p
        LEFT JOIN public.profile_stats ps ON ps.user_id = p.id
        WHERE p.is_suspended = false
          AND (
            (username_only AND (p.custom_url ILIKE pat
              OR similarity(lower(coalesce(p.custom_url, '')), q) > 0.3))
            OR
            (NOT username_only AND (p.full_name ILIKE pat OR p.custom_url ILIKE pat
              OR similarity(lower(coalesce(p.full_name, '')), q) > 0.3
              OR similarity(lower(coalesce(p.custom_url, '')), q) > 0.3))
          )
        ORDER BY score DESC, COALESCE(ps.followers_count, 0) DESC, p.full_name
        LIMIT CASE WHEN section = 'person' THEN 15 ELSE 8 END
      ) t), '[]'::jsonb));
  END IF;

  IF section IN ('all', 'competition') AND NOT username_only THEN
    result := result || jsonb_build_object('competitions', COALESCE((
      SELECT jsonb_agg(to_jsonb(t)) FROM (
        SELECT c.id, c.title, c.category, c.status, c.starts_at,
               (CASE
                  WHEN lower(c.title) = q THEN 3
                  WHEN lower(c.title) LIKE q || '%' THEN 2
                  WHEN lower(c.title) LIKE '% ' || q || '%' THEN 1.5
                  ELSE similarity(lower(c.title), q)
                END)::float AS score
        FROM public.competitions c
        WHERE c.title ILIKE pat OR similarity(lower(c.title), q) > 0.3
        ORDER BY score DESC, c.starts_at DESC NULLS LAST
        LIMIT 8
      ) t), '[]'::jsonb));
  END IF;

  IF section IN ('all', 'course') AND NOT username_only THEN
    result := result || jsonb_build_object('courses', COALESCE((
      SELECT jsonb_agg(to_jsonb(t)) FROM (
        SELECT c.id, c.title, c.slug, c.category, c.difficulty, c.published_at,
               (CASE
                  WHEN lower(c.title) = q THEN 3
                  WHEN lower(c.title) LIKE q || '%' THEN 2
                  WHEN lower(c.title) LIKE '% ' || q || '%' THEN 1.5
                  ELSE similarity(lower(c.title), q)
                END)::float AS score
        FROM public.courses c
        WHERE c.status = 'published'
          AND (c.title ILIKE pat OR similarity(lower(c.title), q) > 0.3)
        ORDER BY score DESC, c.published_at DESC NULLS LAST
        LIMIT 8
      ) t), '[]'::jsonb));
  END IF;

  IF section IN ('all', 'article') AND NOT username_only THEN
    result := result || jsonb_build_object('articles', COALESCE((
      SELECT jsonb_agg(to_jsonb(t)) FROM (
        SELECT a.id, a.title, a.slug, left(coalesce(a.excerpt, ''), 80) AS excerpt, a.published_at,
               (CASE
                  WHEN lower(a.title) = q THEN 3
                  WHEN lower(a.title) LIKE q || '%' THEN 2
                  WHEN lower(a.title) LIKE '% ' || q || '%' THEN 1.5
                  ELSE similarity(lower(a.title), q)
                END)::float AS score
        FROM public.journal_articles a
        WHERE a.status = 'published'
          AND (a.title ILIKE pat OR similarity(lower(a.title), q) > 0.3)
        ORDER BY score DESC, a.published_at DESC NULLS LAST
        LIMIT 8
      ) t), '[]'::jsonb));
  END IF;

  IF section IN ('all', 'post') AND NOT username_only THEN
    result := result || jsonb_build_object('posts', COALESCE((
      SELECT jsonb_agg(to_jsonb(t)) FROM (
        SELECT p.id, left(coalesce(p.content, ''), 80) AS content, p.user_id, p.created_at
        FROM public.posts p
        WHERE p.privacy = 'public' AND p.content ILIKE pat
        ORDER BY p.created_at DESC
        LIMIT 8
      ) t), '[]'::jsonb));
  END IF;

  RETURN result;
END;
$$;


ALTER FUNCTION "public"."global_search"("term" "text", "section" "text", "username_only" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."global_search_hashtags"("term" "text") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
  SELECT COALESCE(jsonb_agg(to_jsonb(t)), '[]'::jsonb) FROM (
    SELECT tag, count(*)::int AS uses
    FROM (
      SELECT lower(m[1]) AS tag
      FROM public.posts p,
           LATERAL regexp_matches(coalesce(p.content, ''), '#([A-Za-z0-9_]{2,40})', 'g') m
      WHERE p.privacy = 'public'
    ) tags
    WHERE lower(trim(term)) <> ''
      AND (
        tag LIKE lower(trim(term)) || '%'
        OR similarity(tag, lower(trim(term))) > 0.3
      )
    GROUP BY tag
    ORDER BY (tag LIKE lower(trim(term)) || '%') DESC, count(*) DESC, tag
    LIMIT 6
  ) t;
$$;


ALTER FUNCTION "public"."global_search_hashtags"("term" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_needs_review_round1_only"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.decision = 'needs_review' AND COALESCE(NEW.round_number, 0) <> 1 THEN
    RAISE EXCEPTION
      '"Needs Review" decisions are only permitted in Round 1 (Spec V3). Got round_number=%',
      NEW.round_number
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


