CREATE OR REPLACE FUNCTION "public"."guard_profile_moderation_columns"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- Only act when a moderation column actually changes
  IF NEW.is_banned IS DISTINCT FROM OLD.is_banned
     OR NEW.is_suspended IS DISTINCT FROM OLD.is_suspended
     OR NEW.suspended_until IS DISTINCT FROM OLD.suspended_until THEN

    -- Trusted actors may change anything: service_role (auth.uid() IS NULL) or an admin
    IF auth.uid() IS NULL OR has_role(auth.uid(), 'admin'::app_role) THEN
      RETURN NEW;
    END IF;

    -- Non-admin acting on a row (RLS already limits them to their own):
    -- (a) may NEVER change the ban flag
    IF NEW.is_banned IS DISTINCT FROM OLD.is_banned THEN
      RAISE EXCEPTION 'Not permitted to change ban status' USING ERRCODE = '42501';
    END IF;

    -- (b) may only CLEAR an already-expired suspension (matches app auto-expiry)
    IF NEW.is_suspended IS DISTINCT FROM OLD.is_suspended
       OR NEW.suspended_until IS DISTINCT FROM OLD.suspended_until THEN
      IF NOT (OLD.is_suspended = true
              AND OLD.suspended_until IS NOT NULL
              AND OLD.suspended_until < now()
              AND NEW.is_suspended = false) THEN
        RAISE EXCEPTION 'Not permitted to change suspension status' USING ERRCODE = '42501';
      END IF;
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."guard_profile_moderation_columns"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_stage_key_immutability"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _allow text := current_setting('app.allow_stage_rewind', true);
  _old_order int;
  _new_order int;
BEGIN
  IF NEW.stage_key IS NULL OR OLD.stage_key IS NULL THEN
    RETURN NEW;
  END IF;

  IF NEW.stage_key = OLD.stage_key THEN
    RETURN NEW;
  END IF;

  _old_order := public.progression_order(OLD.stage_key);
  _new_order := public.progression_order(NEW.stage_key);

  IF _new_order >= _old_order THEN
    RETURN NEW;
  END IF;

  IF _allow IS DISTINCT FROM 'on' THEN
    RAISE EXCEPTION
      'stage_key rewind blocked: % (%) -> % (%). Use admin_rewind_stage().',
      OLD.stage_key, _old_order, NEW.stage_key, _new_order
      USING ERRCODE = 'check_violation';
  END IF;

  INSERT INTO public.db_audit_logs(table_name, operation, row_id, old_data, new_data, changed_by)
  VALUES (
    'competition_entries',
    'stage_key_rewind',
    NEW.id::text,
    jsonb_build_object('stage_key', OLD.stage_key, 'order', _old_order),
    jsonb_build_object('stage_key', NEW.stage_key, 'order', _new_order),
    auth.uid()
  );
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."guard_stage_key_immutability"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."handle_first_admin"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.user_roles WHERE role = 'admin') THEN
    INSERT INTO public.user_roles (user_id, role)
    VALUES (NEW.id, 'admin')
    ON CONFLICT DO NOTHING;
  END IF;
  RETURN NEW;
END;
$$;


