CREATE OR REPLACE FUNCTION "public"."html_escape"("_s" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT replace(replace(replace(replace(replace(COALESCE(_s,''),
    '&','&amp;'),'<','&lt;'),'>','&gt;'),'"','&quot;'),'''','&#39;')
$$;


