CREATE OR REPLACE FUNCTION "public"."is_qualifying_decision"("_decision" "text", "_from_round" integer) RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
  SELECT CASE
    WHEN _decision IS NULL THEN false
    WHEN _from_round = 1 THEN
      lower(_decision) IN ('shortlist','shortlisted')
    WHEN _from_round = 2 THEN
      lower(_decision) IN (
        'qualified_r3',
        'shortlist','shortlisted',
        'qualified',
        'qualified_for_r3','qualified for r3'
      )
    WHEN _from_round = 3 THEN
      lower(_decision) IN (
        'qualified_final',
        'shortlisted_final',
        'qualified',
        'shortlist','shortlisted',
        'finalist',
        'shortlisted_for_final','shortlisted for final'
      )
    ELSE false
  END;
$$;


ALTER FUNCTION "public"."is_qualifying_decision"("_decision" "text", "_from_round" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."is_qualifying_decision"("_decision" "text", "_from_round" integer) IS 'Round eligibility helper. Round 3 canonical final-qualification token is qualified_final.';



