CREATE OR REPLACE FUNCTION "public"."issue_course_completion_certificate"("_course_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _uid uuid := auth.uid();
  _course record;
  _total_lessons int;
  _completed_lessons int;
  _existing_id uuid;
  _new_id uuid;
BEGIN
  IF _uid IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT id, title INTO _course
  FROM public.courses
  WHERE id = _course_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Course not found';
  END IF;

  -- Gate 1: must be enrolled (enrollment is created only by enroll_in_course,
  -- which already enforces payment + published status).
  IF NOT EXISTS (
    SELECT 1 FROM public.course_enrollments
    WHERE user_id = _uid AND course_id = _course_id
  ) THEN
    RAISE EXCEPTION 'Not enrolled in this course';
  END IF;

  -- Gate 2: every lesson of the course completed.
  SELECT count(*) INTO _total_lessons
  FROM public.lessons
  WHERE course_id = _course_id;

  IF _total_lessons = 0 THEN
    RAISE EXCEPTION 'Course has no lessons';
  END IF;

  SELECT count(DISTINCT lp.lesson_id) INTO _completed_lessons
  FROM public.lesson_progress lp
  JOIN public.lessons l ON l.id = lp.lesson_id
  WHERE lp.user_id = _uid
    AND l.course_id = _course_id
    AND lp.completed = true;

  IF _completed_lessons < _total_lessons THEN
    RAISE EXCEPTION 'Course not complete: % of % lessons finished',
      _completed_lessons, _total_lessons;
  END IF;

  -- Idempotency: one completion certificate per (user, course), ever.
  -- Deliberately does NOT exclude revoked rows — re-issuing after an admin
  -- revocation must stay an admin decision, not a self-service loophole.
  SELECT id INTO _existing_id
  FROM public.certificates
  WHERE user_id = _uid
    AND type = 'course_completion'
    AND reference_id = _course_id
  ORDER BY issued_at ASC
  LIMIT 1;

  IF _existing_id IS NOT NULL THEN
    RETURN _existing_id;
  END IF;

  -- Title/description strings byte-match the current client writer
  -- (CourseDetail.tsx:85-86) so Certificates.tsx's
  -- `.replace(" — Completion Certificate", "")` keeps working.
  INSERT INTO public.certificates (user_id, type, title, description, reference_id)
  VALUES (
    _uid,
    'course_completion',
    _course.title || ' — Completion Certificate',
    'Successfully completed all ' || _total_lessons || ' lessons in "' || _course.title || '".',
    _course_id
  )
  RETURNING id INTO _new_id;

  RETURN _new_id;
END;
$$;


ALTER FUNCTION "public"."issue_course_completion_certificate"("_course_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."judge_apply_single_tag"("_entry_id" "uuid", "_photo_index" integer, "_round_number" integer, "_tag_id" "uuid", "_judge_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- Remove this judge's other round-visible tags on this (entry, photo, round).
  DELETE FROM public.judge_tag_assignments
   WHERE entry_id     = _entry_id
     AND photo_index  = _photo_index
     AND round_number = _round_number
     AND judge_id     = _judge_id
     AND tag_id <> _tag_id
     AND tag_id IN (
       SELECT id FROM public.judging_tags
       WHERE visible_in_round @> ARRAY[_round_number]
     );

  -- Insert the new tag. If this fails, the DELETE above rolls back (atomic).
  INSERT INTO public.judge_tag_assignments
    (entry_id, photo_index, round_number, tag_id, judge_id)
  VALUES (_entry_id, _photo_index, _round_number, _tag_id, _judge_id);
END;
$$;


ALTER FUNCTION "public"."judge_apply_single_tag"("_entry_id" "uuid", "_photo_index" integer, "_round_number" integer, "_tag_id" "uuid", "_judge_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."judge_can_access_entry"("_entry_id" "uuid", "_judge_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM competition_entries ce
    JOIN competition_judges cj ON cj.competition_id = ce.competition_id AND cj.judge_id = _judge_id
    JOIN competitions c ON c.id = ce.competition_id
    WHERE ce.id = _entry_id
      AND (
        c.judge_assignment_mode != 'distributed'
        OR EXISTS (
          SELECT 1 FROM judge_entry_assignments ja
          WHERE ja.entry_id = _entry_id AND ja.judge_id = _judge_id
        )
      )
  );
$$;


