CREATE OR REPLACE FUNCTION "public"."judging_invariants_check"() RETURNS TABLE("check_name" "text", "status" "text", "fail_count" integer, "sample" "jsonb")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_caller uuid := auth.uid();
BEGIN
  IF v_caller IS NOT NULL AND NOT public.has_role(v_caller, 'admin'::app_role) THEN
    RAISE EXCEPTION 'admin only';
  END IF;

  -- 1. tag_decision_drift (unchanged)
  RETURN QUERY
  WITH drift AS (
    SELECT jta.entry_id, jta.judge_id, jta.tag_id, m.round_number, m.decision
    FROM public.judge_tag_assignments jta
    JOIN public.system_tag_decision_map m ON m.tag_id = jta.tag_id
    LEFT JOIN public.judge_decisions jd
      ON jd.entry_id = jta.entry_id
     AND jd.judge_id = jta.judge_id
     AND jd.round_number = m.round_number
     AND jd.decision = m.decision
     AND COALESCE(jd.photo_index, 0) = COALESCE(jta.photo_index, 0)
    WHERE jd.id IS NULL
  )
  SELECT 'tag_decision_drift'::text,
         CASE WHEN COUNT(*) = 0 THEN 'ok' ELSE 'fail' END,
         COUNT(*)::int,
         COALESCE(jsonb_agg(to_jsonb(d)) FILTER (WHERE d.entry_id IS NOT NULL), '[]'::jsonb)
  FROM (SELECT * FROM drift LIMIT 5) d;

  -- 2. current_round_canonical (unchanged)
  RETURN QUERY
  WITH bad AS (
    SELECT 'competition_entries' AS t, id::text, current_round
    FROM public.competition_entries
    WHERE current_round IS NOT NULL AND current_round !~ '^[1-4]$'
    UNION ALL
    SELECT 'competitions', id::text, current_round
    FROM public.competitions
    WHERE current_round IS NOT NULL AND current_round !~ '^[1-4]$'
  )
  SELECT 'current_round_canonical'::text,
         CASE WHEN COUNT(*) = 0 THEN 'ok' ELSE 'fail' END,
         COUNT(*)::int,
         COALESCE(jsonb_agg(to_jsonb(b)) FILTER (WHERE b.id IS NOT NULL), '[]'::jsonb)
  FROM (SELECT * FROM bad LIMIT 5) b;

  -- 3. decision_vocabulary -- NOW CATALOG-DRIVEN (U-1)
  -- Canonical set = active v3_stage_catalog.decision_token values
  --              + small legacy alias whitelist for historical rows.
  RETURN QUERY
  WITH canonical AS (
    SELECT DISTINCT lower(decision_token) AS token
    FROM public.v3_stage_catalog
    WHERE is_active = true
    UNION
    -- Legacy aliases that historical rows may still carry (R1 era + spec V3 forgivers)
    SELECT unnest(ARRAY[
      'accepted','shortlisted','qualified','rejected',
      'needs_review','skip','finalist'
    ])
  ),
  bad AS (
    SELECT id::text, decision, round_number
    FROM public.judge_decisions
    WHERE lower(decision) NOT IN (SELECT token FROM canonical)
  )
  SELECT 'decision_vocabulary'::text,
         CASE WHEN COUNT(*) = 0 THEN 'ok' ELSE 'fail' END,
         COUNT(*)::int,
         COALESCE(jsonb_agg(to_jsonb(b)) FILTER (WHERE b.id IS NOT NULL), '[]'::jsonb)
  FROM (SELECT * FROM bad LIMIT 5) b;

  -- 4. eligibility_consistency (unchanged)
  RETURN QUERY
  WITH per_comp AS (
    SELECT c.id AS competition_id,
           public.current_round_int(c.current_round) AS rn
    FROM public.competitions c
    WHERE c.current_round IS NOT NULL
      AND public.current_round_int(c.current_round) >= 2
  ),
  expected AS (
    SELECT pc.competition_id, jd.entry_id, COALESCE(jd.photo_index, 0) AS photo_index
    FROM per_comp pc
    JOIN public.judge_decisions jd ON jd.round_number = pc.rn - 1
    JOIN public.competition_entries ce ON ce.id = jd.entry_id AND ce.competition_id = pc.competition_id AND ce.status <> 'rejected'
    JOIN public.competition_judges cj ON cj.judge_id = jd.judge_id AND cj.competition_id = pc.competition_id
    WHERE public.is_qualifying_decision(jd.decision, pc.rn - 1)
    GROUP BY pc.competition_id, jd.entry_id, COALESCE(jd.photo_index, 0)
  ),
  actual AS (
    SELECT pc.competition_id, ge.entry_id, ge.photo_index
    FROM per_comp pc, LATERAL public.get_round_eligible_photos(pc.competition_id, pc.rn) ge
  ),
  diff AS (
    SELECT 'missing' AS kind, competition_id, entry_id, photo_index FROM expected
    EXCEPT SELECT 'missing', competition_id, entry_id, photo_index FROM actual
    UNION ALL
    SELECT 'extra' AS kind, competition_id, entry_id, photo_index FROM actual
    EXCEPT SELECT 'extra', competition_id, entry_id, photo_index FROM expected
  )
  SELECT 'eligibility_consistency'::text,
         CASE WHEN COUNT(*) = 0 THEN 'ok' ELSE 'fail' END,
         COUNT(*)::int,
         COALESCE(jsonb_agg(to_jsonb(d)) FILTER (WHERE d.entry_id IS NOT NULL), '[]'::jsonb)
  FROM (SELECT * FROM diff LIMIT 5) d;

  -- 5. r4_stuck (unchanged — preserve original body)
  RETURN QUERY
  WITH stuck AS (
    SELECT c.id::text AS competition_id, c.title, c.status AS comp_status, c.current_round,
           jr.id::text AS round_id, jr.status AS round_status
    FROM public.competitions c
    JOIN public.judging_rounds jr ON jr.competition_id = c.id AND jr.round_number = 4
    WHERE jr.status = 'completed'
      AND c.status IN ('judging','active')
  )
  SELECT 'r4_stuck'::text,
         CASE WHEN COUNT(*) = 0 THEN 'ok' ELSE 'fail' END,
         COUNT(*)::int,
         COALESCE(jsonb_agg(to_jsonb(s)) FILTER (WHERE s.competition_id IS NOT NULL), '[]'::jsonb)
  FROM (SELECT * FROM stuck LIMIT 5) s;

  -- 6. no_legacy_in_progression_writers (preserve)
  RETURN QUERY
  SELECT 'no_legacy_in_progression_writers'::text, 'ok'::text, 0, '[]'::jsonb;

  -- 7. rejected_entry_gate_leak (GUARDRAIL, 2026-07-20)
  --    A rejected entry must NEVER be returned by get_round_eligible_photos.
  --    This catches — the moment it happens — the class of bug where a whole
  --    entry is rejected but a judging gate still counts its shortlisted photos
  --    (which froze "Complete Round" for the judge). If this ever flips to
  --    'fail', a gate has regressed to ignoring entry-level rejection.
  RETURN QUERY
  WITH per_comp AS (
    SELECT c.id AS competition_id, r.rn AS round_number
    FROM public.competitions c
    CROSS JOIN (VALUES (2),(3),(4)) AS r(rn)
  ),
  leak AS (
    SELECT pc.competition_id, pc.round_number, ge.entry_id, ge.photo_index, ce.status
    FROM per_comp pc
    CROSS JOIN LATERAL public.get_round_eligible_photos(pc.competition_id, pc.round_number) ge
    JOIN public.competition_entries ce ON ce.id = ge.entry_id
    WHERE ce.status = 'rejected'
  )
  SELECT 'rejected_entry_gate_leak'::text,
         CASE WHEN COUNT(*) = 0 THEN 'ok' ELSE 'fail' END,
         COUNT(*)::int,
         COALESCE(jsonb_agg(to_jsonb(l)) FILTER (WHERE l.entry_id IS NOT NULL), '[]'::jsonb)
  FROM (SELECT * FROM leak LIMIT 5) l;

END;
$_$;


ALTER FUNCTION "public"."judging_invariants_check"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."judging_write_decision_atomic"("p_entry_id" "uuid", "p_stage_key" "text", "p_current_round" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_catalog       record;
  v_old_stage_key text;
  v_txid          bigint;
BEGIN
  PERFORM set_config('app.write_path', 'judging_write_decision_atomic', true);
  v_txid := txid_current();

  IF p_entry_id IS NULL THEN
    RAISE EXCEPTION 'judging_write_decision_atomic: p_entry_id required' USING ERRCODE = '22023';
  END IF;
  IF p_stage_key IS NULL OR length(btrim(p_stage_key)) = 0 THEN
    RAISE EXCEPTION 'judging_write_decision_atomic: p_stage_key required' USING ERRCODE = '22023';
  END IF;
  IF p_current_round IS NULL OR length(btrim(p_current_round)) = 0 THEN
    RAISE EXCEPTION 'judging_write_decision_atomic: p_current_round required' USING ERRCODE = '22023';
  END IF;

  SELECT stage_key, round_number, decision_token, family, is_active
    INTO v_catalog
    FROM public.v3_stage_catalog
   WHERE stage_key = p_stage_key;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'judging_write_decision_atomic: unknown stage_key %', p_stage_key USING ERRCODE = '22023';
  END IF;
  IF NOT v_catalog.is_active THEN
    RAISE EXCEPTION 'judging_write_decision_atomic: stage_key % is inactive', p_stage_key USING ERRCODE = '22023';
  END IF;

  SELECT stage_key INTO v_old_stage_key
    FROM public.competition_entries
   WHERE id = p_entry_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'judging_write_decision_atomic: entry % not found', p_entry_id USING ERRCODE = 'P0002';
  END IF;

  -- BUG-053 (owner decision 2026-07-16): DO NOT write competition_entries here.
  -- Entry stage/current_round are owned exclusively by complete-round
  -- aggregation at round close. This call is now validate + audit only.
  INSERT INTO public.db_audit_logs (table_name, operation, row_id, new_data, changed_by)
  VALUES (
    'competition_entries',
    'judging_write_decision_atomic',
    p_entry_id::text,
    jsonb_build_object(
      'txid',            v_txid,
      'stage_key_old',   v_old_stage_key,
      'stage_key_asked', p_stage_key,
      'current_round',   p_current_round,
      'write_path',      'judging_write_decision_atomic',
      'entry_write',     'suppressed_per_judge (BUG-053: round-close owns entry stage)',
      'rows_updated',    0
    ),
    auth.uid()
  );

  RETURN jsonb_build_object(
    'ok', true,
    'entry_id', p_entry_id,
    'stage_key', p_stage_key,
    'entry_write_suppressed', true,
    'note', 'entry stage is decided at round close (BUG-053)'
  );
END;
$$;


ALTER FUNCTION "public"."judging_write_decision_atomic"("p_entry_id" "uuid", "p_stage_key" "text", "p_current_round" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_tag_decision_drift_admin"() RETURNS TABLE("entry_id" "uuid", "competition_id" "uuid", "competition_title" "text", "judge_id" "uuid", "judge_handle" "text", "tag_id" "uuid", "tag_label" "text", "round_number" integer, "decision" "text", "photo_index" integer, "entry_title" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF auth.uid() IS NULL OR NOT public.has_role(auth.uid(), 'admin'::app_role) THEN
    RAISE EXCEPTION 'admin only';
  END IF;

  RETURN QUERY
  SELECT
    jta.entry_id,
    ce.competition_id,
    c.title AS competition_title,
    jta.judge_id,
    COALESCE(p.full_name, p.custom_url, 'Judge ' || substr(jta.judge_id::text,1,8)) AS judge_handle,
    jta.tag_id,
    jt.label AS tag_label,
    m.round_number,
    m.decision,
    COALESCE(jta.photo_index, 0) AS photo_index,
    ce.title AS entry_title
  FROM public.judge_tag_assignments jta
  JOIN public.system_tag_decision_map m ON m.tag_id = jta.tag_id
  LEFT JOIN public.judge_decisions jd
    ON jd.entry_id = jta.entry_id
   AND jd.judge_id = jta.judge_id
   AND jd.round_number = m.round_number
   AND jd.decision = m.decision
   AND COALESCE(jd.photo_index, 0) = COALESCE(jta.photo_index, 0)
  LEFT JOIN public.competition_entries ce ON ce.id = jta.entry_id
  LEFT JOIN public.competitions c ON c.id = ce.competition_id
  LEFT JOIN public.judging_tags jt ON jt.id = jta.tag_id
  LEFT JOIN public.profiles p ON p.id = jta.judge_id
  WHERE jd.id IS NULL
  ORDER BY c.title NULLS LAST, m.round_number, ce.title NULLS LAST, jta.photo_index;
END;
$$;


ALTER FUNCTION "public"."list_tag_decision_drift_admin"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."log_app_event"("_code" "text", "_event" "text", "_severity" "text", "_message" "text", "_fn" "text" DEFAULT NULL::"text", "_file" "text" DEFAULT NULL::"text", "_reason" "text" DEFAULT NULL::"text", "_expected" "text" DEFAULT NULL::"text", "_actual" "text" DEFAULT NULL::"text", "_next_step" "text" DEFAULT NULL::"text", "_duration_ms" integer DEFAULT NULL::integer, "_correlation_id" "text" DEFAULT NULL::"text", "_detail" "jsonb" DEFAULT NULL::"jsonb", "_platform" "text" DEFAULT NULL::"text", "_app_build" "text" DEFAULT NULL::"text", "_url" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  _uid    uuid := auth.uid();
  _recent integer;
BEGIN
  IF _code IS NULL OR _code !~ '^[A-Z]{2,6}-[0-9]{4}$' THEN
    RETURN;
  END IF;
  IF _severity IS NULL
     OR lower(_severity) NOT IN ('trace','debug','info','warn','error','fatal') THEN
    RETURN;
  END IF;
  IF _message IS NULL OR btrim(_message) = '' THEN
    RETURN;
  END IF;
  IF _uid IS NOT NULL THEN
    SELECT count(*) INTO _recent FROM public.client_errors
     WHERE user_id = _uid AND code IS NOT NULL AND created_at > now() - interval '1 hour';
    IF _recent >= 40 THEN RETURN; END IF;
  ELSE
    SELECT count(*) INTO _recent FROM public.client_errors
     WHERE user_id IS NULL AND code IS NOT NULL AND created_at > now() - interval '1 hour';
    IF _recent >= 300 THEN RETURN; END IF;
  END IF;
  INSERT INTO public.client_errors (
    user_id, kind, message, detail, platform, app_build, url,
    code, event, severity, fn, src_file, expected, actual, reason, next_step,
    duration_ms, correlation_id
  )
  VALUES (
    _uid,
    lower(split_part(_code, '-', 1)),
    left(_message, 500),
    _detail,
    left(_platform, 16),
    left(_app_build, 32),
    left(_url, 300),
    left(_code, 16),
    left(_event, 80),
    lower(left(_severity, 8)),
    left(_fn, 80),
    left(_file, 120),
    left(_expected, 300),
    left(_actual, 300),
    left(_reason, 400),
    left(_next_step, 300),
    _duration_ms,
    left(_correlation_id, 40)
  );
EXCEPTION WHEN OTHERS THEN
  RETURN;
END;
$_$;


ALTER FUNCTION "public"."log_app_event"("_code" "text", "_event" "text", "_severity" "text", "_message" "text", "_fn" "text", "_file" "text", "_reason" "text", "_expected" "text", "_actual" "text", "_next_step" "text", "_duration_ms" integer, "_correlation_id" "text", "_detail" "jsonb", "_platform" "text", "_app_build" "text", "_url" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."log_client_error"("_kind" "text", "_message" "text", "_detail" "jsonb" DEFAULT NULL::"jsonb", "_platform" "text" DEFAULT NULL::"text", "_app_build" "text" DEFAULT NULL::"text", "_url" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _uid    uuid := auth.uid();
  _recent integer;
  _cap    integer;
BEGIN
  IF _kind NOT IN ('post_create', 'reply', 'upload', 'blank_page', 'image_load') THEN
    RETURN;
  END IF;

  IF _message IS NULL OR btrim(_message) = '' THEN
    RETURN;
  END IF;

  _cap := CASE WHEN _kind = 'image_load' THEN 10 ELSE 20 END;

  IF _uid IS NOT NULL THEN
    SELECT count(*) INTO _recent
      FROM public.client_errors
     WHERE user_id = _uid
       AND (kind = 'image_load') = (_kind = 'image_load')
       AND created_at > now() - interval '1 hour';
    IF _recent >= _cap THEN RETURN; END IF;
  ELSE
    SELECT count(*) INTO _recent
      FROM public.client_errors
     WHERE user_id IS NULL
       AND created_at > now() - interval '1 hour';
    IF _recent >= 200 THEN RETURN; END IF;
  END IF;

  INSERT INTO public.client_errors (user_id, kind, message, detail, platform, app_build, url)
  VALUES (
    _uid,
    _kind,
    left(_message, 500),
    _detail,
    left(_platform, 16),
    left(_app_build, 32),
    left(_url, 300)
  );

EXCEPTION WHEN OTHERS THEN
  RETURN;
END;
$$;


ALTER FUNCTION "public"."log_client_error"("_kind" "text", "_message" "text", "_detail" "jsonb", "_platform" "text", "_app_build" "text", "_url" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."log_push_outcome"("_user_id" "uuid", "_notification_id" "uuid", "_type" "text", "_outcome" "text", "_detail" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  INSERT INTO public.push_delivery_log (user_id, notification_id, type, outcome, detail)
  VALUES (_user_id, _notification_id, _type, _outcome, left(_detail, 500));
EXCEPTION WHEN OTHERS THEN
  RAISE LOG 'log_push_outcome failed (observability only, notification unaffected): % / %',
            SQLSTATE, SQLERRM;
END;
