CREATE OR REPLACE FUNCTION "public"."log_raw_commitments"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _meta_len integer := COALESCE(jsonb_array_length(NEW.photo_meta), 0);
  _i integer;
  _new_raw boolean;
  _old_raw boolean;
  _src text;
BEGIN
  IF _meta_len = 0 THEN RETURN NEW; END IF;

  FOR _i IN 0.._meta_len - 1 LOOP
    _new_raw := COALESCE((NEW.photo_meta -> _i ->> 'raw_required')::boolean, false);

    IF TG_OP = 'INSERT' THEN
      _old_raw := false;
      _src := 'submit';
    ELSE
      _old_raw := COALESCE((OLD.photo_meta -> _i ->> 'raw_required')::boolean, false);
      _src := CASE
        WHEN _new_raw AND NOT _old_raw THEN 'admin_request'
        WHEN NOT _new_raw AND _old_raw THEN 'revoked'
        ELSE NULL
      END;
    END IF;

    -- Only log on transition (or first submit when true)
    IF _src IS NOT NULL AND (TG_OP = 'INSERT' AND _new_raw OR _new_raw <> _old_raw) THEN
      INSERT INTO public.raw_commitments (
        entry_id, competition_id, user_id, photo_index, raw_required, source
      ) VALUES (
        NEW.id, NEW.competition_id, NEW.user_id, _i, _new_raw, _src
      );
    END IF;
  END LOOP;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."log_raw_commitments"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maintain_competition_entry_counts"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if (tg_op = 'INSERT') then
    insert into public.competition_entry_counts (competition_id, status, cnt)
      values (new.competition_id, new.status, 1)
      on conflict (competition_id, status)
      do update set cnt = competition_entry_counts.cnt + 1, updated_at = now();
  elsif (tg_op = 'DELETE') then
    update public.competition_entry_counts
      set cnt = greatest(cnt - 1, 0), updated_at = now()
      where competition_id = old.competition_id and status = old.status;
  elsif (tg_op = 'UPDATE') then
    if (new.competition_id is distinct from old.competition_id)
       or (new.status is distinct from old.status) then
      update public.competition_entry_counts
        set cnt = greatest(cnt - 1, 0), updated_at = now()
        where competition_id = old.competition_id and status = old.status;
      insert into public.competition_entry_counts (competition_id, status, cnt)
        values (new.competition_id, new.status, 1)
        on conflict (competition_id, status)
        do update set cnt = competition_entry_counts.cnt + 1, updated_at = now();
    end if;
  end if;
  return null;
end;
$$;


ALTER FUNCTION "public"."maintain_competition_entry_counts"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mark_expiring_post_drafts"("_days" integer DEFAULT 7) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE _n integer;
BEGIN
  UPDATE public.post_drafts
     SET expiring_at = now()
   WHERE expiring_at IS NULL
     AND updated_at < now() - make_interval(days => _days);
  GET DIAGNOSTICS _n = ROW_COUNT;
  RETURN _n;
END;
$$;


ALTER FUNCTION "public"."mark_expiring_post_drafts"("_days" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."media_begin_upload"("_sha256" "bytea", "_width" integer, "_height" integer, "_bytes" bigint, "_mime" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _uid     uuid := auth.uid();
  _id      uuid;
  _state   text;
  _pending int;
BEGIN
  IF _uid IS NULL THEN
    RAISE EXCEPTION 'media_begin_upload requires an authenticated caller'
      USING ERRCODE = '42501';
  END IF;

  -- Validated here rather than left to the table CHECKs so the client gets a
  -- stable, readable error instead of a constraint name that describes our
  -- schema to it.
  IF octet_length(_sha256) <> 32 THEN
    RAISE EXCEPTION 'sha256 must be exactly 32 bytes' USING ERRCODE = '22023';
  END IF;
  IF _width IS NULL OR _height IS NULL OR _width <= 0 OR _height <= 0
     OR _width > 100000 OR _height > 100000 THEN
    RAISE EXCEPTION 'width and height must be between 1 and 100000' USING ERRCODE = '22023';
  END IF;
  IF _bytes IS NULL OR _bytes <= 0 THEN
    RAISE EXCEPTION 'bytes must be positive' USING ERRCODE = '22023';
  END IF;
  IF _mime NOT IN ('image/webp','image/jpeg','image/png','image/avif') THEN
    RAISE EXCEPTION 'unsupported mime %', _mime USING ERRCODE = '22023';
  END IF;

  -- An authenticated member can otherwise create unbounded rows without ever
  -- uploading a byte. The cap counts only rows that never completed, so a
  -- prolific photographer with thousands of `ready` objects is unaffected.
  SELECT count(*) INTO _pending
  FROM public.media_objects
  WHERE owner_id = _uid AND state IN ('pending', 'verified');

  IF _pending >= 50 THEN
    RAISE EXCEPTION 'too many uploads in flight (%); finish or abandon them before starting more', _pending
      USING ERRCODE = '54000';
  END IF;

  SELECT id, state INTO _id, _state
  FROM public.media_objects
  WHERE owner_id = _uid AND sha256 = _sha256;

  IF FOUND THEN
    -- A quarantined object is not handed back. Returning it would put the
    -- client in a loop it cannot exit: it uploads, we refuse, it retries.
    IF _state = 'quarantined' THEN
      RAISE EXCEPTION 'this image was rejected by content verification and cannot be re-uploaded'
        USING ERRCODE = '42501';
    END IF;
    RETURN _id;
  END IF;

  BEGIN
    INSERT INTO public.media_objects (owner_id, sha256, width, height, bytes, mime)
    VALUES (_uid, _sha256, _width, _height, _bytes, _mime)
    RETURNING id INTO _id;
  EXCEPTION WHEN unique_violation THEN
    -- Two devices, or two taps, racing on the same bytes. Both get the same
    -- object; neither gets an error.
    SELECT id INTO _id FROM public.media_objects
    WHERE owner_id = _uid AND sha256 = _sha256;
  END;

  RETURN _id;
END $$;


ALTER FUNCTION "public"."media_begin_upload"("_sha256" "bytea", "_width" integer, "_height" integer, "_bytes" bigint, "_mime" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."media_mark_ready"("_id" "uuid", "_derivatives" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _bad   text;
  _owner uuid;
  _orig  text;
BEGIN
  IF _derivatives IS NULL OR jsonb_typeof(_derivatives) <> 'object'
     OR NOT (_derivatives ? 'original') THEN
    RAISE EXCEPTION 'derivatives must be an object containing at least "original"'
      USING ERRCODE = '22023';
  END IF;

  SELECT string_agg(k, ',') INTO _bad
  FROM jsonb_object_keys(_derivatives) k
  WHERE k NOT IN ('original', '1440', '1080', '600');

  IF _bad IS NOT NULL THEN
    RAISE EXCEPTION 'unknown derivative rung(s): % (allowed: original,1440,1080,600)', _bad
      USING ERRCODE = '22023';
  END IF;

  SELECT owner_id INTO _owner FROM public.media_objects WHERE id = _id;
  IF _owner IS NULL THEN
    RAISE EXCEPTION 'MEDIA-2101 media % does not exist', _id USING ERRCODE = '23503';
  END IF;

  _orig := _derivatives->>'original';

  -- DO NOT REMOVE, AND DO NOT WIDEN THE PREFIX LIST. The object a row is
  -- marked ready against must live inside that row's OWNER's folder. The two
  -- prefixes are the two key prefixes of the one R2 bucket that hold member
  -- media; adding a third would let a writer point a member's row at platform
  -- assets. The owner segment is the part that must never move.
  IF _orig IS NULL
     OR _orig !~ ('^(post-images|avatars)/' || _owner::text || '/') THEN
    RAISE EXCEPTION 'MEDIA-2102 derivative original % is not inside <post-images|avatars>/%/', _orig, _owner
      USING ERRCODE = '23514';
  END IF;

  IF _orig LIKE '%..%' OR _orig LIKE '/%' OR _orig ~* '^https?://' THEN
    RAISE EXCEPTION 'MEDIA-2103 derivative original % must be a bucket-relative path', _orig
      USING ERRCODE = '23514';
  END IF;

  UPDATE public.media_objects
     SET state = 'ready', derivatives = _derivatives
   WHERE id = _id AND state = 'verified';

  IF NOT FOUND THEN
    RAISE EXCEPTION 'media % is not in state verified', _id USING ERRCODE = '23514';
  END IF;
END $$;


ALTER FUNCTION "public"."media_mark_ready"("_id" "uuid", "_derivatives" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."media_mark_verified"("_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  UPDATE public.media_objects
     SET state = 'verified', verified_at = now()
   WHERE id = _id AND state = 'pending';

  IF NOT FOUND THEN
    RAISE EXCEPTION 'media % is not in state pending', _id USING ERRCODE = '23514';
  END IF;
END $$;


ALTER FUNCTION "public"."media_mark_verified"("_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."media_migrate_post"("_post_id" "uuid", "_owner_id" "uuid", "_items" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare
  _item jsonb;
  _sha bytea;
  _mid uuid;
  _state text;
  _created int := 0;
  _reused  int := 0;
  _repaired int := 0;
  _refs int := 0;
  _ids uuid[] := '{}';
  _actual_owner uuid;
  _live_slides int;
  _existing int;
  _matched int;
begin
  if _items is null or jsonb_typeof(_items) <> 'array' or jsonb_array_length(_items) = 0 then
    raise exception 'MIG-2001 _items must be a non-empty array' using errcode = '22023';
  end if;

  -- The post must exist, and the owner the caller claims must be its real
  -- author. Never take the caller's word for whose photograph this is.
  select user_id, coalesce(cardinality(image_urls), 0) into _actual_owner, _live_slides
  from public.posts where id = _post_id;
  if not found then
    raise exception 'MIG-2002 post % does not exist', _post_id using errcode = '23503';
  end if;
  if _actual_owner is distinct from _owner_id then
    raise exception 'MIG-2003 post % belongs to %, not %', _post_id, _actual_owner, _owner_id
      using errcode = '23514';
  end if;

  -- ── ALREADY DONE? PROVE IT. ────────────────────────────────────────────
  -- ⚠ This block replaces a bare `if exists (…) then return 'skipped'`.
  -- Audited 2026-08-17 (Cycle 7): existence alone checked NOTHING — not ord,
  -- not owner, not sha256, not dimensions, not mime, not readiness. This
  -- function is all-or-nothing so IT cannot leave a partial set, but the check
  -- does not know who wrote the rows: `post_publish_with_media` (which
  -- `authenticated` may execute), the abandoned backfill, or a manual repair
  -- all produce references this would have accepted unseen.
  --
  -- So: a post that already has references is compared, row for row, against
  -- the items supplied. Three outcomes and no fourth — verified-skip, or
  -- refuse. Never a silent skip.
  select count(*) into _existing from public.post_media where post_id = _post_id;
  if _existing > 0 then
    if _existing <> jsonb_array_length(_items) then
      raise exception 'MIG-2020 post % has % references, manifest has % — refusing to skip',
        _post_id, _existing, jsonb_array_length(_items) using errcode = '23514';
    end if;
    -- Every existing reference must match the manifest item at that position:
    -- content hash, dimensions, size, mime, owner, and readiness.
    select count(*) into _matched
    from public.post_media pm
    join public.media_objects mo on mo.id = pm.media_id
    join lateral (
      select (e->>'ord')::int - 1            as ord0,
             decode(e->>'sha256','hex')      as sha,
             (e->>'width')::int              as w,
             (e->>'height')::int             as h,
             (e->>'bytes')::bigint           as b,
             e->>'mime'                      as m
      from jsonb_array_elements(_items) e
    ) it on it.ord0 = pm.ord
    where pm.post_id = _post_id
      and mo.sha256 = it.sha and mo.width = it.w and mo.height = it.h
      and mo.bytes = it.b and mo.mime = it.m
      and mo.owner_id = _owner_id and mo.state = 'ready';

    if _matched <> _existing then
      raise exception 'MIG-2021 post % has % references but only % match the manifest — refusing to skip',
        _post_id, _existing, _matched using errcode = '23514';
    end if;
    -- Proven equal. A different word from 'skipped', deliberately.
    return jsonb_build_object('post_id', _post_id, 'result', 'verified-skip',
                              'references', _existing, 'invariants_checked',
                              jsonb_build_array('count','ord','sha256','width','height',
                                                'bytes','mime','owner_id','state'));
  end if;

  -- Whole post or nothing: the number of items must equal the number of
  -- photographs the post actually carries.
  if jsonb_array_length(_items) <> _live_slides then
    raise exception 'MIG-2004 post % has % slides, % items supplied',
      _post_id, _live_slides, jsonb_array_length(_items) using errcode = '23514';
  end if;

  for _item in select * from jsonb_array_elements(_items) loop
    if length(_item->>'sha256') <> 64 or (_item->>'sha256') !~ '^[0-9a-f]{64}$' then
      raise exception 'MIG-2005 sha256 must be 64 lowercase hex characters' using errcode = '22023';
    end if;
    -- The object path must belong to the owner. Cycle 5A found three rows in
    -- the OLD migrator's population where it did not.
    if split_part(_item->>'object_path', '/', 2) <> _owner_id::text then
      raise exception 'MIG-2006 object_path % is not in owner %s folder', _item->>'object_path', _owner_id
        using errcode = '23514';
    end if;
    _sha := decode(_item->>'sha256', 'hex');

    select id, state into _mid, _state
    from public.media_objects where owner_id = _owner_id and sha256 = _sha;

    if _mid is null then
      insert into public.media_objects (owner_id, sha256, width, height, bytes, mime, visibility)
      values (_owner_id, _sha,
              (_item->>'width')::int, (_item->>'height')::int, (_item->>'bytes')::bigint,
              _item->>'mime', _item->>'visibility')
      returning id, state into _mid, _state;
      _created := _created + 1;
    else
      -- Content identity already exists. Reuse it — but never reuse something
      -- quarantined, and never silently accept a row whose recorded shape
      -- disagrees with the bytes we just verified.
      if _state = 'quarantined' then
        raise exception 'MIG-2007 media % for this content is quarantined', _mid using errcode = '23514';
      end if;
      if exists (
        select 1 from public.media_objects
        where id = _mid
          and (width <> (_item->>'width')::int
            or height <> (_item->>'height')::int
            or bytes <> (_item->>'bytes')::bigint
            or mime <> _item->>'mime')
      ) then
        raise exception 'MIG-2008 existing media % disagrees with the verified bytes', _mid
          using errcode = '23514';
      end if;
      if _state = 'ready' then
        _reused := _reused + 1;
      else
        _repaired := _repaired + 1;   -- stuck pending/verified: drive it forward
      end if;
    end if;

    -- Walk the state machine. The trigger refuses pending -> ready, so this
    -- proves the bytes were looked at rather than asserting it.
    if _state = 'pending' then
      update public.media_objects set state = 'verified', verified_at = now() where id = _mid;
      _state := 'verified';
    end if;
    if _state = 'verified' then
      update public.media_objects
      set state = 'ready',
          derivatives = jsonb_build_object('original', _item->>'object_path')
      where id = _mid;
    end if;

    _ids := _ids || _mid;
  end loop;

  -- References, in the manifest's own order, contiguous from 0 because
  -- post_media.ord is 0-based while the manifest's ord is 1-based.
  insert into public.post_media (post_id, ord, media_id)
  select _post_id, (i.idx - 1), i.mid
  from (
    select row_number() over (order by (e->>'ord')::int) as idx,
           _ids[row_number() over (order by (e->>'ord')::int)] as mid
    from jsonb_array_elements(_items) e
  ) i;
  get diagnostics _refs = row_count;

  -- Post-write verification INSIDE the transaction, so a mismatch rolls the
  -- whole post back instead of being reported after the fact.
  if _refs <> jsonb_array_length(_items) then
    raise exception 'MIG-2009 wrote % references, expected %', _refs, jsonb_array_length(_items)
      using errcode = '23514';
  end if;
  if (select count(*) from public.post_media where post_id = _post_id) <> _refs then
    raise exception 'MIG-2010 verification read-back disagrees for post %', _post_id using errcode = '23514';
  end if;
  if exists (
    select 1 from public.post_media pm
    join public.media_objects mo on mo.id = pm.media_id
    where pm.post_id = _post_id and (mo.state <> 'ready' or mo.owner_id <> _owner_id)
  ) then
    raise exception 'MIG-2011 a reference on post % points at media that is not ready or not owned', _post_id
      using errcode = '23514';
  end if;

  return jsonb_build_object(
    'post_id', _post_id, 'result', 'migrated',
    'media_created', _created, 'media_reused', _reused,
    'media_repaired', _repaired, 'references', _refs);
end;
$_$;


ALTER FUNCTION "public"."media_migrate_post"("_post_id" "uuid", "_owner_id" "uuid", "_items" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."media_migrate_post"("_post_id" "uuid", "_owner_id" "uuid", "_items" "jsonb") IS 'One post, one transaction: all of its media_objects rows and all of its post_media references, or none. Idempotent; repairs a media row stuck below ready. Never touches posts.image_urls. service_role only.';



CREATE OR REPLACE FUNCTION "public"."media_migration_fence_digest"("_fence" timestamp with time zone) RETURNS TABLE("key_set_md5" "text", "item_count" integer, "post_count" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
  with cand as (
    select p.id::text as post_id, u.ord::int as ord, u.url
    from public.posts p
    cross join lateral unnest(p.image_urls) with ordinality as u(url, ord)
    where p.image_urls is not null
      and p.privacy = 'public'
      and p.created_at <= _fence
      and u.url ~ '^https://cdn\.50mmretina\.com/post-images/[0-9a-f-]{36}/posts/[^/?]+$'
  )
  select md5(string_agg(post_id||'|'||ord||'|'||url, E'\n' order by post_id||'|'||ord||'|'||url)),
         count(*)::int,
         count(distinct post_id)::int
  from cand;
$_$;


ALTER FUNCTION "public"."media_migration_fence_digest"("_fence" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."media_migration_fence_digest"("_fence" timestamp with time zone) IS 'Read-only. Digest over the fenced candidate key set so a migration can prove it is operating on the approved SET, not merely on the approved COUNT.';



CREATE OR REPLACE FUNCTION "public"."media_migration_fence_digest_wide"("_fence" timestamp with time zone) RETURNS TABLE("key_set_md5" "text", "item_count" integer, "post_count" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
  with cand as (
    select p.id::text as post_id, u.ord::int as ord, u.url
    from public.posts p
    cross join lateral unnest(p.image_urls) with ordinality as u(url, ord)
    where p.image_urls is not null
      and p.privacy = 'public'
      and p.created_at <= _fence
      and (
        u.url ~ '^https://cdn\.50mmretina\.com/post-images/[0-9a-f-]{36}/posts/[^/?]+$'
        or u.url ~ '^https://cdn\.50mmretina\.com/post-images/[0-9a-f-]{36}/[^/?]+$'
        or u.url ~ '^https://cdn\.50mmretina\.com/avatars/[0-9a-f-]{36}/my-photos/[0-9a-f-]{36}/[^/?]+$'
      )
  )
  select md5(string_agg(post_id||'|'||ord||'|'||url, E'\n' order by post_id||'|'||ord||'|'||url)),
         count(*)::int,
         count(distinct post_id)::int
  from cand;
$_$;


ALTER FUNCTION "public"."media_migration_fence_digest_wide"("_fence" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."media_migration_fence_digest_wide"("_fence" timestamp with time zone) IS 'The candidate population including classes B and C, as of a fence. A DROP-IN for media_migration_fence_digest: same columns, wider population. The ORIGINAL is frozen and must never be widened - 27-34 class B/C slides predate every historical fence, so widening it would retroactively change four approved digests. service_role only.';



CREATE OR REPLACE FUNCTION "public"."media_migration_reconcile"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select jsonb_build_object(
    'post_media_rows',        (select count(*) from public.post_media),
    'media_objects_rows',     (select count(*) from public.media_objects),
    'unreferenced_media',     (select count(*) from public.media_objects mo
                               where not exists (select 1 from public.post_media pm where pm.media_id = mo.id)),
    'non_ready_media',        (select count(*) from public.media_objects where state <> 'ready'),
    'refs_to_non_ready',      (select count(*) from public.post_media pm
                               join public.media_objects mo on mo.id = pm.media_id where mo.state <> 'ready'),
    'refs_with_owner_mismatch',(select count(*) from public.post_media pm
                               join public.media_objects mo on mo.id = pm.media_id
                               join public.posts p on p.id = pm.post_id
                               where mo.owner_id <> p.user_id),
    'posts_with_gapped_ords', (select count(*) from (
                                 select post_id from public.post_media
                                 group by post_id having max(ord) <> count(*) - 1) g),
    -- ⚠ COUNT EQUALITY MUST NOT BE ABLE TO PRODUCE A PASS.
    -- Audited 2026-08-17 (Cycle 7): the previous reconciliation compared
    -- totals only, so a post carrying the right NUMBER of references pointing
    -- at the WRONG media reconciled clean. This digest is over the actual
    -- (post, position, content) triples, so the end state must be the manifest
    -- itself and not merely the same size as it.
    'ref_set_md5', (select md5(string_agg(k, E'\n' order by k)) from (
                      select pm.post_id::text||'|'||pm.ord::text||'|'||encode(mo.sha256,'hex') as k
                      from public.post_media pm
                      join public.media_objects mo on mo.id = pm.media_id) t)
  );
$$;


ALTER FUNCTION "public"."media_migration_reconcile"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."media_migration_reconcile"() IS 'Read-only end-state check for the media migration. service_role only.';



CREATE OR REPLACE FUNCTION "public"."media_quarantine"("_id" "uuid", "_reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE _detached int;
BEGIN
  IF _reason IS NULL OR btrim(_reason) = '' THEN
    RAISE EXCEPTION 'a quarantine must record a reason' USING ERRCODE = '22023';
  END IF;

  UPDATE public.media_objects
     SET state = 'quarantined', quarantine_reason = _reason
   WHERE id = _id AND state <> 'quarantined';

  IF NOT FOUND THEN
    RAISE EXCEPTION 'media % does not exist or is already quarantined', _id
      USING ERRCODE = '23514';
  END IF;

  -- Same transaction as the state change: there is no window in which the
  -- media is quarantined but still on someone's post.
  DELETE FROM public.post_media WHERE media_id = _id;
  GET DIAGNOSTICS _detached = ROW_COUNT;
  IF _detached > 0 THEN
    RAISE NOTICE 'quarantine of % detached % live reference(s)', _id, _detached;
  END IF;
END $$;


ALTER FUNCTION "public"."media_quarantine"("_id" "uuid", "_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."media_write_path_delta"("_since" timestamp with time zone DEFAULT ("now"() - '24:00:00'::interval)) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
  with scoped as (
    select p.id,
           p.created_at,
           p.post_kind,
           coalesce(array_length(p.image_urls, 1), 0) as slides,
           (select count(*) from public.post_media pm where pm.post_id = p.id) as refs,
           (select bool_or(u.url ~ '^https://cdn\.50mmretina\.com/avatars/[0-9a-f-]{36}/(avatar|cover)\.[A-Za-z0-9]+(\?|$)')
              from unnest(p.image_urls) u(url)) as has_mutable_media
    from public.posts p
    where coalesce(array_length(p.image_urls, 1), 0) > 0
  ),
  legacy as (select * from scoped where refs = 0),
  recent as (select * from scoped where created_at > _since),
  recent_legacy as (select * from recent where refs = 0)
  select jsonb_build_object(
    'since', _since,
    'measured_at', now(),
    'posts_with_images',        (select count(*) from scoped),
    'slides_total',             (select coalesce(sum(slides), 0) from scoped),
    'legacy_only_posts',        (select count(*) from legacy),
    'legacy_only_slides',       (select coalesce(sum(slides), 0) from legacy),
    'partial_posts',            (select count(*) from scoped where refs > 0 and refs < slides),
    'permanent_legacy_posts',   (select count(*) from legacy where has_mutable_media),
    'permanent_legacy_slides',  (select coalesce(sum(slides), 0) from legacy where has_mutable_media),
    'migratable_legacy_posts',  (select count(*) from legacy where not has_mutable_media),
    'migratable_legacy_slides', (select coalesce(sum(slides), 0) from legacy where not has_mutable_media),
    'new_posts',                (select count(*) from recent),
    'new_legacy_only_posts',    (select count(*) from recent_legacy),
    'new_legacy_only_slides',   (select coalesce(sum(slides), 0) from recent_legacy),
    'new_unexplained_legacy_posts',
      (select count(*) from recent_legacy where not has_mutable_media),
    'new_permanent_legacy_posts',
      (select count(*) from recent_legacy where has_mutable_media),
    'by_kind', (
      select coalesce(jsonb_object_agg(k, n), '{}'::jsonb)
      from (select coalesce(post_kind,'(null)') as k, count(*) as n from recent_legacy group by 1) x
    ),
    'newest_legacy_only_post',  (select max(created_at) from recent_legacy),
    'delta_growing',            (select count(*) > 0 from recent_legacy where not has_mutable_media)
  );
$_$;


ALTER FUNCTION "public"."media_write_path_delta"("_since" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."media_write_path_delta"("_since" timestamp with time zone) IS 'Phase 2 delta check. Committed rows only, so a stale client cannot blind it. delta_growing=true means a post created since _since landed image_urls-only WITHOUT the mutable-media excuse. permanent_* is the documented floor (profile/cover announcements); migratable_* is the backlog.';



CREATE OR REPLACE FUNCTION "public"."mirror_system_tag_to_decision"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_bypass        text;
  v_tag_id        uuid;
  v_tag_label     text;
  v_stage         public.v3_stage_catalog%ROWTYPE;
  v_alias_key     text;
  v_resolved_via  text := 'direct';
  v_entry_id      uuid;
  v_judge_id      uuid;
  v_round         integer;
  v_photo_idx     integer;
  v_op            text := TG_OP;
BEGIN
  BEGIN
    v_bypass := current_setting('app.bypass_mirror_trigger', true);
  EXCEPTION WHEN OTHERS THEN
    v_bypass := NULL;
  END;
  IF v_bypass = 'on' THEN
    INSERT INTO public.v3_mirror_log
      (trigger_op, action, source_tag_id, tag_id, entry_id, judge_id, round_number, photo_index)
    VALUES (
      v_op, 'bypassed',
      COALESCE(NEW.id, OLD.id),
      COALESCE(NEW.tag_id, OLD.tag_id),
      COALESCE(NEW.entry_id, OLD.entry_id),
      COALESCE(NEW.judge_id, OLD.judge_id),
      COALESCE(NEW.round_number, OLD.round_number),
      COALESCE(NEW.photo_index, OLD.photo_index, 0)
    );
    RETURN COALESCE(NEW, OLD);
  END IF;

  IF v_op = 'DELETE' THEN
    v_tag_id    := OLD.tag_id;
    v_entry_id  := OLD.entry_id;
    v_judge_id  := OLD.judge_id;
    v_round     := OLD.round_number;
    v_photo_idx := COALESCE(OLD.photo_index, 0);
  ELSE
    v_tag_id    := NEW.tag_id;
    v_entry_id  := NEW.entry_id;
    v_judge_id  := NEW.judge_id;
    v_round     := NEW.round_number;
    v_photo_idx := COALESCE(NEW.photo_index, 0);
  END IF;

  SELECT label INTO v_tag_label FROM public.judging_tags WHERE id = v_tag_id;

  IF v_tag_label IS NULL THEN
    INSERT INTO public.v3_mirror_log
      (trigger_op, action, source_tag_id, tag_id, entry_id, judge_id, round_number, photo_index, error_message)
    VALUES (v_op, 'noop', COALESCE(NEW.id, OLD.id), v_tag_id,
            v_entry_id, v_judge_id, v_round, v_photo_idx,
            'tag row not found in judging_tags');
    RETURN COALESCE(NEW, OLD);
  END IF;

  SELECT * INTO v_stage
  FROM public.v3_stage_catalog
  WHERE is_active = true
    AND round_number = v_round
    AND lower(trim(tag_label_canonical)) = lower(trim(v_tag_label))
  LIMIT 1;

  IF v_stage.stage_key IS NULL THEN
    SELECT canonical_stage_key INTO v_alias_key
    FROM public.v3_tag_label_alias
    WHERE round_number = v_round
      AND lower(trim(alias_label)) = lower(trim(v_tag_label))
    LIMIT 1;

    IF v_alias_key IS NOT NULL THEN
      SELECT * INTO v_stage
      FROM public.v3_stage_catalog
      WHERE stage_key = v_alias_key
        AND is_active = true
      LIMIT 1;
      IF v_stage.stage_key IS NOT NULL THEN
        v_resolved_via := 'alias';
        INSERT INTO public.v3_mirror_log
          (trigger_op, action, source_tag_id, tag_id, tag_label, matched_stage,
           entry_id, judge_id, round_number, photo_index, decision_token)
        VALUES (v_op, 'alias_resolved', COALESCE(NEW.id, OLD.id), v_tag_id, v_tag_label,
                v_stage.stage_key, v_entry_id, v_judge_id, v_round, v_photo_idx,
                v_stage.decision_token);
      END IF;
    END IF;
  END IF;

  IF v_stage.stage_key IS NULL THEN
    INSERT INTO public.v3_mirror_log
      (trigger_op, action, source_tag_id, tag_id, tag_label, entry_id, judge_id,
       round_number, photo_index, error_message)
    VALUES (v_op, 'noop_alias_miss', COALESCE(NEW.id, OLD.id), v_tag_id, v_tag_label,
            v_entry_id, v_judge_id, v_round, v_photo_idx,
            'no direct catalog hit and no alias entry');
    RETURN COALESCE(NEW, OLD);
  END IF;

  IF v_op = 'DELETE' THEN
    IF v_round = 4 THEN
      DELETE FROM public.judge_award_tags
       WHERE entry_id     = v_entry_id
         AND judge_id     = v_judge_id
         AND round_number = v_round
         AND photo_index  = v_photo_idx
         AND stage_key    = v_stage.stage_key;

      INSERT INTO public.v3_mirror_log
        (trigger_op, action, source_tag_id, tag_id, tag_label, matched_stage,
         entry_id, judge_id, round_number, photo_index, decision_token)
      VALUES (v_op, 'r4_award_delete', OLD.id, v_tag_id, v_tag_label, v_stage.stage_key,
              v_entry_id, v_judge_id, v_round, v_photo_idx, v_stage.decision_token);
    END IF;

    IF NOT EXISTS (
      SELECT 1
      FROM public.judge_tag_assignments other_jta
      JOIN public.judging_tags other_t ON other_t.id = other_jta.tag_id
      LEFT JOIN public.v3_stage_catalog other_s
        ON other_s.is_active = true
       AND other_s.round_number = other_jta.round_number
       AND lower(trim(other_s.tag_label_canonical)) = lower(trim(other_t.label))
      LEFT JOIN public.v3_tag_label_alias other_a
        ON other_a.round_number = other_jta.round_number
       AND lower(trim(other_a.alias_label)) = lower(trim(other_t.label))
      WHERE other_jta.entry_id = v_entry_id
        AND other_jta.judge_id = v_judge_id
        AND other_jta.round_number = v_round
        AND COALESCE(other_jta.photo_index, 0) = v_photo_idx
        AND other_jta.id <> OLD.id
        AND (other_s.stage_key IS NOT NULL OR other_a.canonical_stage_key IS NOT NULL)
    ) THEN
      DELETE FROM public.judge_decisions
       WHERE entry_id = v_entry_id
         AND judge_id = v_judge_id
         AND round_number = v_round
         AND COALESCE(photo_index, 0) = v_photo_idx;

      INSERT INTO public.v3_mirror_log
        (trigger_op, action, source_tag_id, tag_id, tag_label, matched_stage,
         entry_id, judge_id, round_number, photo_index, decision_token)
      VALUES (v_op, 'delete', OLD.id, v_tag_id, v_tag_label, v_stage.stage_key,
              v_entry_id, v_judge_id, v_round, v_photo_idx, v_stage.decision_token);
    ELSE
      INSERT INTO public.v3_mirror_log
        (trigger_op, action, source_tag_id, tag_id, tag_label, matched_stage,
         entry_id, judge_id, round_number, photo_index, error_message)
      VALUES (v_op, 'noop', OLD.id, v_tag_id, v_tag_label, v_stage.stage_key,
              v_entry_id, v_judge_id, v_round, v_photo_idx,
              'sibling system tag still present; preserving decision');
    END IF;

    RETURN OLD;
  END IF;

  IF v_round = 4 THEN
    INSERT INTO public.judge_award_tags
      (entry_id, judge_id, round_number, photo_index,
       stage_key, decision_token, tag_label, tag_id, source_assignment_id)
    VALUES
      (v_entry_id, v_judge_id, v_round, v_photo_idx,
       v_stage.stage_key, v_stage.decision_token, v_tag_label, v_tag_id, NEW.id)
    ON CONFLICT (entry_id, judge_id, round_number, photo_index, stage_key)
    DO UPDATE
      SET decision_token       = EXCLUDED.decision_token,
          tag_label            = EXCLUDED.tag_label,
          tag_id               = EXCLUDED.tag_id,
          source_assignment_id = EXCLUDED.source_assignment_id,
          updated_at           = now();

    INSERT INTO public.v3_mirror_log
      (trigger_op, action, source_tag_id, tag_id, tag_label, matched_stage,
       entry_id, judge_id, round_number, photo_index, decision_token)
    VALUES (v_op, 'r4_award_upsert', NEW.id, v_tag_id, v_tag_label, v_stage.stage_key,
            v_entry_id, v_judge_id, v_round, v_photo_idx, v_stage.decision_token);
  END IF;

  INSERT INTO public.judge_decisions
    (entry_id, judge_id, round_number, photo_index, decision, stage_key)
  VALUES
    (v_entry_id, v_judge_id, v_round, v_photo_idx, v_stage.decision_token, v_stage.stage_key)
  ON CONFLICT (entry_id, judge_id, round_number, photo_index)
  DO UPDATE
    SET decision   = EXCLUDED.decision,
        stage_key  = EXCLUDED.stage_key,
        updated_at = now();

  INSERT INTO public.v3_mirror_log
    (trigger_op, action, source_tag_id, tag_id, tag_label, matched_stage,
     entry_id, judge_id, round_number, photo_index, decision_token)
  VALUES (v_op,
          CASE WHEN v_resolved_via = 'alias' THEN 'upsert_via_alias' ELSE 'upsert' END,
          NEW.id, v_tag_id, v_tag_label, v_stage.stage_key,
          v_entry_id, v_judge_id, v_round, v_photo_idx, v_stage.decision_token);

  RETURN NEW;

EXCEPTION WHEN OTHERS THEN
  -- BUG-052: do NOT swallow. Surface a server-log warning and re-raise so the
  -- judge-tag write cannot commit without its mirrored decision.
  RAISE WARNING '[mirror_system_tag_to_decision] entry=% judge=% round=% photo=%: %',
    v_entry_id, v_judge_id, v_round, v_photo_idx, SQLERRM;
  RAISE;
END;
$$;


ALTER FUNCTION "public"."mirror_system_tag_to_decision"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."mirror_system_tag_to_decision"() IS 'Phase R1 Step 1.3 (2026-04-30): mirrors judge_tag_assignments → judge_decisions via v3_stage_catalog. Bypass with set_config(''app.bypass_mirror_trigger'',''on'',true).';



CREATE OR REPLACE FUNCTION "public"."moderate_post_content"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  blocked_word text;
BEGIN
  SELECT keyword INTO blocked_word
  FROM public.blocked_keywords
  WHERE is_active = true
    AND severity IN ('auto_hide', 'high', 'critical')
    AND NEW.content ILIKE '%' || keyword || '%'
  LIMIT 1;

  IF blocked_word IS NOT NULL THEN
    RAISE EXCEPTION 'Post contains restricted content and cannot be published.';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."moderate_post_content"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."move_to_dlq"("source_queue" "text", "dlq_name" "text", "message_id" bigint, "payload" "jsonb") RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE new_id BIGINT;
BEGIN
  -- Named queues only, on BOTH sides. The source guard is the one that matters:
  -- without it, pgmq.delete() below reaches any queue in the system.
  IF source_queue IS NULL OR source_queue NOT IN ('transactional_emails', 'auth_emails')
     OR dlq_name IS NULL OR dlq_name NOT IN ('transactional_emails_dlq', 'auth_emails_dlq') THEN
    RAISE EXCEPTION 'move_to_dlq: % -> % is not a permitted queue pair',
      coalesce(source_queue, '<null>'), coalesce(dlq_name, '<null>')
      USING ERRCODE = '42501';
  END IF;

  SELECT pgmq.send(dlq_name, payload) INTO new_id;
  PERFORM pgmq.delete(source_queue, message_id);
  RETURN new_id;
EXCEPTION
  -- Reachable only for an allow-listed pair, because the check above passed.
  WHEN undefined_table THEN
    BEGIN
      PERFORM pgmq.create(dlq_name);
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;
    SELECT pgmq.send(dlq_name, payload) INTO new_id;
    BEGIN
      PERFORM pgmq.delete(source_queue, message_id);
    EXCEPTION WHEN undefined_table THEN
      NULL;
    END;
    RETURN new_id;
END;
$$;


ALTER FUNCTION "public"."move_to_dlq"("source_queue" "text", "dlq_name" "text", "message_id" bigint, "payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mutual_friend_ids"("_user_a" "uuid", "_user_b" "uuid", "_limit" integer DEFAULT 5) RETURNS TABLE("friend_id" "uuid")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT CASE WHEN f1.requester_id = _user_a THEN f1.addressee_id ELSE f1.requester_id END AS friend_id
  FROM friendships f1
  JOIN friendships f2 ON (
    CASE WHEN f1.requester_id = _user_a THEN f1.addressee_id ELSE f1.requester_id END
    =
    CASE WHEN f2.requester_id = _user_b THEN f2.addressee_id ELSE f2.requester_id END
  )
  WHERE f1.status = 'accepted'
    AND f2.status = 'accepted'
    AND (f1.requester_id = _user_a OR f1.addressee_id = _user_a)
    AND (f2.requester_id = _user_b OR f2.addressee_id = _user_b)
    AND CASE WHEN f1.requester_id = _user_a THEN f1.addressee_id ELSE f1.requester_id END != _user_a
    AND CASE WHEN f1.requester_id = _user_a THEN f1.addressee_id ELSE f1.requester_id END != _user_b
  LIMIT _limit;
$$;


ALTER FUNCTION "public"."mutual_friend_ids"("_user_a" "uuid", "_user_b" "uuid", "_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mutual_friends_count"("_user_a" "uuid", "_user_b" "uuid") RETURNS integer
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT count(*)::integer
  FROM friendships f1
  JOIN friendships f2 ON (
    CASE WHEN f1.requester_id = _user_a THEN f1.addressee_id ELSE f1.requester_id END
    =
    CASE WHEN f2.requester_id = _user_b THEN f2.addressee_id ELSE f2.requester_id END
  )
  WHERE f1.status = 'accepted'
    AND f2.status = 'accepted'
    AND (f1.requester_id = _user_a OR f1.addressee_id = _user_a)
    AND (f2.requester_id = _user_b OR f2.addressee_id = _user_b)
    AND CASE WHEN f1.requester_id = _user_a THEN f1.addressee_id ELSE f1.requester_id END != _user_a
    AND CASE WHEN f1.requester_id = _user_a THEN f1.addressee_id ELSE f1.requester_id END != _user_b;
$$;


ALTER FUNCTION "public"."mutual_friends_count"("_user_a" "uuid", "_user_b" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."normalize_hashtag"("raw" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
  select nullif(lower(regexp_replace(coalesce(raw, ''), '^#', '')), '');
$$;


ALTER FUNCTION "public"."normalize_hashtag"("raw" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."normalize_hashtag"("raw" "text") IS 'The single definition of "the same hashtag". Strips a leading # and lowercases. Both the trigger and the suggestion RPC go through this, so a tag can never be stored one way and searched another.';



CREATE OR REPLACE FUNCTION "public"."notif_action_phrase"("_type" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT CASE _type
           WHEN 'new_post_from_following' THEN 'shared a photo.'
           WHEN 'post_reaction'           THEN 'reacted to your photo.'
           WHEN 'image_reaction'          THEN 'reacted to your photo.'
           WHEN 'post_comment'            THEN 'commented on your photo.'
           WHEN 'image_comment'           THEN 'commented on your photo.'
           WHEN 'comment_reply'           THEN 'replied to your comment.'
           WHEN 'new_follower'            THEN 'started following you.'
           WHEN 'friend_request'          THEN 'sent you a friend request.'
           WHEN 'friend_accepted'         THEN 'accepted your friend request.'
           WHEN 'post_tag'                THEN 'tagged you in a photo.'
           WHEN 'tagged_post_reaction'    THEN 'reacted to a photo you are tagged in.'
           WHEN 'tagged_post_comment'     THEN 'commented on a photo you are tagged in.'
           WHEN 'ad_comment_reply'        THEN 'replied to your comment on a sponsored post.'
           ELSE NULL
         END;
$$;


ALTER FUNCTION "public"."notif_action_phrase"("_type" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."notif_action_phrase"("_type" "text") IS 'Singular action phrase for a notification type. Byte-identical copy of ACTION_CATALOG in src/lib/notifications/describe.ts, enforced by pushCatalogParity.test.ts.';



CREATE OR REPLACE FUNCTION "public"."notif_display_name"("_actor_id" "uuid") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT CASE
           WHEN _actor_id IS NULL                                THEN 'A member'
           WHEN public.has_role(_actor_id, 'admin'::app_role)    THEN '50mm Retina World'
           WHEN p.id IS NULL                                     THEN 'A deleted account'
           ELSE COALESCE(NULLIF(btrim(p.full_name), ''),
                         NULLIF(btrim(p.custom_url), ''),
                         'A member')
         END
  FROM (SELECT 1) AS _one
  LEFT JOIN public.profiles p ON p.id = _actor_id;
$$;


ALTER FUNCTION "public"."notif_display_name"("_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notif_group_key"("_type" "text", "_created_at" timestamp with time zone, "_id" "uuid") RETURNS "text"
    LANGUAGE "sql" STABLE
    AS $$
  SELECT CASE
           WHEN _type IN ('post_reaction','image_reaction','post_comment',
                          'image_comment','comment_reply','new_post_from_following',
                          'tagged_post_reaction','tagged_post_comment',
                          'ad_comment_reply')
             THEN _type || '|' || to_char(date_trunc('day', _created_at), 'YYYY-MM-DD')
           ELSE _type || '|' || _id::text          -- never grouped: unique key
         END;
$$;


ALTER FUNCTION "public"."notif_group_key"("_type" "text", "_created_at" timestamp with time zone, "_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."notif_group_key"("_type" "text", "_created_at" timestamp with time zone, "_id" "uuid") IS 'The one definition of what counts as a single notification group. Called by get_my_notifications_grouped and get_my_unread_notifications_grouped so the history page and the bell can never disagree.';



CREATE OR REPLACE FUNCTION "public"."notif_push_body"("_type" "text", "_actor_id" "uuid", "_message" "text") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT CASE
           WHEN public.notif_action_phrase(_type) IS NULL
             THEN COALESCE(_message, '')
           ELSE public.notif_display_name(_actor_id) || ' ' || public.notif_action_phrase(_type)
         END;
$$;


ALTER FUNCTION "public"."notif_push_body"("_type" "text", "_actor_id" "uuid", "_message" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_ad_comment_reply"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _parent_author uuid;
  _actor_name    text;
BEGIN
  IF NEW.parent_id IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT user_id INTO _parent_author
  FROM public.ad_creative_comments WHERE id = NEW.parent_id;

  IF _parent_author IS NULL OR _parent_author = NEW.user_id THEN
    RETURN NULL;
  END IF;

  SELECT COALESCE(full_name, 'Someone') INTO _actor_name
  FROM public.profiles WHERE id = NEW.user_id;

  INSERT INTO public.user_notifications
    (user_id, actor_id, type, title, message, reference_id, dedup_key)
  VALUES (
    _parent_author,
    NEW.user_id,
    'ad_comment_reply',
    'New Reply',
    COALESCE(_actor_name, 'Someone') || ' replied to your comment on a sponsored post',
    NEW.creative_id,
    'ad_comment_reply:' || NEW.id::text
  )
  ON CONFLICT (dedup_key) WHERE dedup_key IS NOT NULL DO NOTHING;

  RETURN NULL;
END;
$$;


