CREATE OR REPLACE FUNCTION "public"."password_verification_hook"("event" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _uid uuid := (event->>'user_id')::uuid;
  _valid boolean := COALESCE((event->>'valid')::boolean, false);
  _row public.auth_login_attempts;
  _lock_seconds integer := 0;
  _remaining integer;
BEGIN
  SELECT * INTO _row FROM public.auth_login_attempts WHERE user_id = _uid FOR UPDATE;

  -- Currently locked -> reject even a correct password until the lock expires.
  IF _row.locked_until IS NOT NULL AND _row.locked_until > now() THEN
    _remaining := CEIL(EXTRACT(EPOCH FROM (_row.locked_until - now())))::integer;
    RETURN jsonb_build_object(
      'decision', 'reject',
      'message', 'Too many failed sign-in attempts. Try again in ' || _remaining || ' seconds.',
      'should_logout_user', false
    );
  END IF;

  IF _valid THEN
    DELETE FROM public.auth_login_attempts WHERE user_id = _uid;
    RETURN jsonb_build_object('decision', 'continue');
  END IF;

  -- Failed attempt: reset stale counters (1h quiet window), then increment.
  IF _row.user_id IS NULL OR _row.last_attempt < now() - interval '1 hour' THEN
    INSERT INTO public.auth_login_attempts AS a (user_id, failed_count, last_attempt, locked_until)
    VALUES (_uid, 1, now(), NULL)
    ON CONFLICT (user_id) DO UPDATE SET failed_count = 1, last_attempt = now(), locked_until = NULL
    RETURNING * INTO _row;
  ELSE
    UPDATE public.auth_login_attempts
    SET failed_count = failed_count + 1, last_attempt = now()
    WHERE user_id = _uid
    RETURNING * INTO _row;
  END IF;

  _lock_seconds := CASE
    WHEN _row.failed_count >= 10 THEN 900
    WHEN _row.failed_count >= 7  THEN 300
    WHEN _row.failed_count >= 5  THEN 120
    WHEN _row.failed_count >= 3  THEN 30
    ELSE 0
  END;

  IF _lock_seconds > 0 THEN
    UPDATE public.auth_login_attempts
    SET locked_until = now() + make_interval(secs => _lock_seconds)
    WHERE user_id = _uid;
    RETURN jsonb_build_object(
      'decision', 'reject',
      'message', 'Too many failed sign-in attempts. Try again in ' || _lock_seconds || ' seconds.',
      'should_logout_user', false
    );
  END IF;

  -- Let GoTrue return its normal invalid-credentials error.
  RETURN jsonb_build_object('decision', 'continue');
END;
$$;


ALTER FUNCTION "public"."password_verification_hook"("event" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pj_handle_comment_notification"("_msg" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _comment_id    uuid := (_msg->>'comment_id')::uuid;
  _post_id       uuid := (_msg->>'post_id')::uuid;
  _actor_id      uuid := (_msg->>'actor_id')::uuid;
  _parent_id     uuid;   -- read from the live row, not the payload
  _post_owner    uuid;
  _parent_author uuid;
  _actor_name    text;
  _tagged        record; -- ADDED 2026-08-11
BEGIN
  -- Skip if the comment was deleted before we ran.
  SELECT parent_id INTO _parent_id
  FROM public.post_comments WHERE id = _comment_id;
  IF NOT FOUND THEN
    RETURN;
  END IF;

  SELECT user_id INTO _post_owner FROM public.posts WHERE id = _post_id;
  SELECT COALESCE(full_name, 'Someone') INTO _actor_name
  FROM public.profiles WHERE id = _actor_id;

  -- 1) Notify post owner (same guard as original trigger).
  IF _post_owner IS NOT NULL AND _post_owner <> _actor_id THEN
    INSERT INTO public.user_notifications
      (user_id, actor_id, type, title, message, reference_id, dedup_key)
    VALUES (
      _post_owner,
      _actor_id,
      'post_comment',
      'New Comment',
      COALESCE(_actor_name, 'Someone') || ' commented on your post',
      _post_id,
      'post_comment:' || _comment_id::text || ':owner'
    )
    ON CONFLICT (dedup_key) WHERE dedup_key IS NOT NULL DO NOTHING;
  END IF;

  -- 2) Notify parent-comment author on replies (same guards as original).
  IF _parent_id IS NOT NULL THEN
    SELECT user_id INTO _parent_author
    FROM public.post_comments WHERE id = _parent_id;
    IF _parent_author IS NOT NULL
       AND _parent_author <> _actor_id
       AND (_post_owner IS NULL OR _parent_author <> _post_owner) THEN
      INSERT INTO public.user_notifications
        (user_id, actor_id, type, title, message, reference_id, dedup_key)
      VALUES (
        _parent_author,
        _actor_id,
        'comment_reply',
        'New Reply',
        COALESCE(_actor_name, 'Someone') || ' replied to your comment',
        _post_id,
        'post_comment:' || _comment_id::text || ':reply'
      )
      ON CONFLICT (dedup_key) WHERE dedup_key IS NOT NULL DO NOTHING;
    END IF;
  END IF;

  -- ── ADDED 2026-08-11: 3) everyone tagged in this photo, while the tag is live.
  -- The parent-comment author is excluded because step 2 has already told them
  -- about this very comment, in more specific words.
  FOR _tagged IN
    SELECT t.tagged_user_id
    FROM public.post_tags t
    WHERE t.post_id = _post_id
      AND t.status IN ('pending', 'approved')
      AND t.tagged_user_id <> _actor_id
      AND (_post_owner IS NULL OR t.tagged_user_id <> _post_owner)
      AND (_parent_author IS NULL OR t.tagged_user_id <> _parent_author)
  LOOP
    INSERT INTO public.user_notifications
      (user_id, actor_id, type, title, message, reference_id, dedup_key)
    VALUES (
      _tagged.tagged_user_id,
      _actor_id,
      'tagged_post_comment',
      'New Comment',
      COALESCE(_actor_name, 'Someone') || ' commented on a photo you are tagged in',
      _post_id,
      'tagged_post_comment:' || _comment_id::text || ':' || _tagged.tagged_user_id::text
    )
    ON CONFLICT (dedup_key) WHERE dedup_key IS NOT NULL DO NOTHING;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."pj_handle_comment_notification"("_msg" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pj_handle_reaction_notification"("_msg" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _reaction_id uuid := (_msg->>'reaction_id')::uuid;
  _post_id     uuid := (_msg->>'post_id')::uuid;
  _actor_id    uuid := (_msg->>'actor_id')::uuid;
  _post_owner  uuid;
  _actor_name  text;
  _tagged      record;   -- ADDED 2026-08-11
BEGIN
  -- Skip if the user un-reacted before we ran (old sync path would already
  -- have notified; skipping is the more correct behaviour).
  IF NOT EXISTS (SELECT 1 FROM public.post_reactions WHERE id = _reaction_id) THEN
    RETURN;
  END IF;

  SELECT user_id INTO _post_owner FROM public.posts WHERE id = _post_id;
  -- Post deleted. Nothing to notify anybody about, owner or tagged.
  IF _post_owner IS NULL THEN
    RETURN;
  END IF;

  SELECT COALESCE(full_name, 'Someone') INTO _actor_name
  FROM public.profiles WHERE id = _actor_id;

  -- Same title/message as the original sync trigger (migration 20260323093425).
  --
  -- CHANGED 2026-08-11: this used to be an early RETURN when the actor was the
  -- owner. It is now a guard around the owner's row only, so that an owner
  -- liking their own photo still reaches the people tagged in it. No existing
  -- recipient gains or loses a row: the owner is skipped in exactly the same
  -- case as before.
  IF _post_owner <> _actor_id THEN
    INSERT INTO public.user_notifications
      (user_id, actor_id, type, title, message, reference_id, dedup_key)
    VALUES (
      _post_owner,
      _actor_id,
      'post_reaction',
      'New Reaction',
      COALESCE(_actor_name, 'Someone') || ' reacted to your post',
      _post_id,
      'post_reaction:' || _reaction_id::text
    )
    ON CONFLICT (dedup_key) WHERE dedup_key IS NOT NULL DO NOTHING;
  END IF;

  -- ── ADDED 2026-08-11: everyone tagged in this photo, while the tag is live ──
  -- 'removed' (self-removal from the post menu) and 'declined' both drop out of
  -- this list immediately, which is the whole of "untill bering removed the tag".
  FOR _tagged IN
    SELECT t.tagged_user_id
    FROM public.post_tags t
    WHERE t.post_id = _post_id
      AND t.status IN ('pending', 'approved')
      AND t.tagged_user_id <> _actor_id     -- not your own like
      AND t.tagged_user_id <> _post_owner   -- the owner already has a row above
  LOOP
    INSERT INTO public.user_notifications
      (user_id, actor_id, type, title, message, reference_id, dedup_key)
    VALUES (
      _tagged.tagged_user_id,
      _actor_id,
      'tagged_post_reaction',
      'New Reaction',
      COALESCE(_actor_name, 'Someone') || ' reacted to a photo you are tagged in',
      _post_id,
      'tagged_post_reaction:' || _reaction_id::text || ':' || _tagged.tagged_user_id::text
    )
    ON CONFLICT (dedup_key) WHERE dedup_key IS NOT NULL DO NOTHING;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."pj_handle_reaction_notification"("_msg" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pj_handle_recount_engagement"("_msg" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _post_id uuid := (_msg->>'post_id')::uuid;
BEGIN
  UPDATE public.posts p SET
    likes_count    = (SELECT COUNT(*) FROM public.post_reactions r WHERE r.post_id = p.id),
    comments_count = (SELECT COUNT(*) FROM public.post_comments  c WHERE c.post_id = p.id),
    shares_count   = (SELECT COUNT(*) FROM public.post_shares    s WHERE s.post_id = p.id)
  WHERE p.id = _post_id;
END;
$$;


ALTER FUNCTION "public"."pj_handle_recount_engagement"("_msg" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pj_handle_tag_notification"("_msg" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _tag_id         uuid := (_msg->>'tag_id')::uuid;
  _post_id        uuid := (_msg->>'post_id')::uuid;
  _tagger_id      uuid := (_msg->>'tagger_id')::uuid;
  _tagged_user_id uuid := (_msg->>'tagged_user_id')::uuid;
  _tagger_name    text;
BEGIN
  -- Skip if the tag no longer exists (removed/declined before we ran).
  IF NOT EXISTS (SELECT 1 FROM public.post_tags WHERE id = _tag_id) THEN
    RETURN;
  END IF;

  SELECT COALESCE(full_name, 'Someone') INTO _tagger_name
  FROM public.profiles WHERE id = _tagger_id;

  -- Same title/message as the original sync trigger (migration 20260418111925).
  INSERT INTO public.user_notifications
    (user_id, actor_id, type, title, message, reference_id, dedup_key)
  VALUES (
    _tagged_user_id,
    _tagger_id,
    'post_tag',
    'New Photo Tag',
    COALESCE(_tagger_name, 'Someone') || ' tagged you in a photo. Approve or decline?',
    _post_id,
    'post_tag:' || _tag_id::text
  )
  ON CONFLICT (dedup_key) WHERE dedup_key IS NOT NULL DO NOTHING;
END;
$$;


ALTER FUNCTION "public"."pj_handle_tag_notification"("_msg" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."post_attach_media"("_post_id" "uuid", "_media_ids" "uuid"[]) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _n       int;
  _bad     int;
  _author  uuid;
  _slides  text[];
  _origin  text;
BEGIN
  IF _media_ids IS NULL OR array_length(_media_ids, 1) IS NULL THEN
    RETURN 0;               -- nothing offered; the post stays legacy
  END IF;
  _n := array_length(_media_ids, 1);

  -- The author comes from the POST, never from the caller. The scheduled
  -- publisher runs as service_role with no session, so there is no auth.uid()
  -- to fall back on and nothing here may be taken on trust.
  SELECT user_id, coalesce(image_urls, '{}') INTO _author, _slides
  FROM public.posts WHERE id = _post_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'MEDIA-2200 post % does not exist', _post_id USING ERRCODE = '23503';
  END IF;

  IF EXISTS (SELECT 1 FROM public.post_media WHERE post_id = _post_id) THEN
    RAISE EXCEPTION 'MEDIA-2203 post % already has media references', _post_id
      USING ERRCODE = '23505';
  END IF;

  IF (SELECT count(*) FROM (SELECT DISTINCT unnest(_media_ids) m) d) <> _n THEN
    RAISE EXCEPTION 'MEDIA-2202 the same photograph appears more than once'
      USING ERRCODE = '22023';
  END IF;

  -- Whole post or nothing. A post carrying three photographs and two references
  -- is the ord gap every other gate in this engine exists to prevent.
  IF coalesce(array_length(_slides, 1), 0) <> _n THEN
    RAISE EXCEPTION 'MEDIA-2204 post % shows % photographs, % media offered',
      _post_id, coalesce(array_length(_slides, 1), 0), _n USING ERRCODE = '23514';
  END IF;

  SELECT count(*) INTO _bad
  FROM unnest(_media_ids) AS m(id)
  LEFT JOIN public.media_objects mo ON mo.id = m.id
  WHERE mo.id IS NULL OR mo.owner_id <> _author OR mo.state <> 'ready';

  IF _bad > 0 THEN
    RAISE EXCEPTION 'MEDIA-2201 % of % media are missing, not the author''s, or not ready',
      _bad, _n USING ERRCODE = '42501';
  END IF;

  SELECT value->>'public_url' INTO _origin
  FROM public.site_settings WHERE key = 's3_storage_settings';
  IF _origin IS NULL OR _origin = '' THEN
    RAISE EXCEPTION 'MEDIA-2110 s3_storage_settings.public_url is not configured'
      USING ERRCODE = '22023';
  END IF;
  _origin := rtrim(_origin, '/');

  -- THE CHECK THAT MAKES THIS SAFE. Ownership and readiness would happily
  -- accept the member's OTHER photographs. Each media object must resolve to
  -- the exact URL this post is already showing at that position.
  SELECT count(*) INTO _bad
  FROM unnest(_media_ids) WITH ORDINALITY AS t(mid, ord)
  JOIN public.media_objects mo ON mo.id = t.mid
  WHERE _origin || '/' || (mo.derivatives->>'original') IS DISTINCT FROM _slides[t.ord];

  IF _bad > 0 THEN
    RAISE EXCEPTION 'MEDIA-2205 % of % media do not resolve to the photographs this post shows',
      _bad, _n USING ERRCODE = '23514';
  END IF;

  INSERT INTO public.post_media (post_id, ord, media_id)
  SELECT _post_id, ord - 1, mid
  FROM unnest(_media_ids) WITH ORDINALITY AS t(mid, ord);

  SELECT count(*) INTO _bad FROM public.post_media WHERE post_id = _post_id;
  IF _bad <> _n THEN
    RAISE EXCEPTION 'MEDIA-2206 attach aborted: % of % references landed', _bad, _n
      USING ERRCODE = '23514';
  END IF;

  RETURN _n;
END $$;


ALTER FUNCTION "public"."post_attach_media"("_post_id" "uuid", "_media_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."post_attach_media"("_post_id" "uuid", "_media_ids" "uuid"[]) IS 'Attach post_media references to a post that already exists, all or nothing. The author is read from the post; every media object must be that author''s, ready, and resolve to the exact URL the post already shows at that position (MEDIA-2205). service_role only; SECURITY DEFINER callers reach it as owner.';



CREATE OR REPLACE FUNCTION "public"."post_media_for"("_post_ids" "uuid"[]) RETURNS TABLE("post_id" "uuid", "ord" integer, "object_path" "text", "width" integer, "height" integer, "mime" "text", "bytes" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  -- No input is not an error. A feed page with no posts asks for nothing.
  if _post_ids is null or array_length(_post_ids, 1) is null then
    return;
  end if;

  -- The cap is what stops this becoming a media export API. The feed asks for
  -- 20; the profile grid asks for fewer. 50 is generous and finite.
  if array_length(_post_ids, 1) > 50 then
    raise exception 'MEDIA-1001 at most 50 post ids per call, got %',
      array_length(_post_ids, 1) using errcode = '22023';
  end if;

  return query
    select pm.post_id, pm.ord, mo.derivatives->>'original',
           mo.width, mo.height, mo.mime, mo.bytes
    from public.post_media pm
    join public.media_objects mo on mo.id = pm.media_id
    join public.posts p          on p.id  = pm.post_id
    where pm.post_id = any(_post_ids)
      -- ⚠ DO NOT REMOVE. This is the entire access control.
      and public.can_view_post(auth.uid(), p.user_id, p.privacy)
    order by pm.post_id, pm.ord;
end;
$$;


ALTER FUNCTION "public"."post_media_for"("_post_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."post_media_for"("_post_ids" "uuid"[]) IS 'The only client read path to post media. SECURITY DEFINER, so can_view_post in the WHERE clause is the sole access control. Returns no content digest, no verification timestamp and no quarantine reason. Capped at 50 post ids (MEDIA-1001). Grants nothing on media_objects or post_media.';



CREATE OR REPLACE FUNCTION "public"."post_publish_with_media"("_media_ids" "uuid"[], "_content" "text" DEFAULT ''::"text", "_privacy" "text" DEFAULT 'public'::"text", "_categories" "text"[] DEFAULT '{}'::"text"[], "_indexing_disabled" boolean DEFAULT false, "_idempotency_key" "text" DEFAULT NULL::"text", "_thumbnail_urls" "text"[] DEFAULT NULL::"text"[]) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  _uid        uuid := auth.uid();
  _post_id    uuid;
  _n          int;
  _bad        int;
  _existing   uuid;
  _origin     text;
  _image_urls text[];
  _thumbs     text[];
BEGIN
  IF _uid IS NULL THEN
    RAISE EXCEPTION 'publishing requires an authenticated caller' USING ERRCODE = '42501';
  END IF;

  IF _media_ids IS NULL OR array_length(_media_ids, 1) IS NULL THEN
    RAISE EXCEPTION 'a post must carry at least one photograph' USING ERRCODE = '22023';
  END IF;

  _n := array_length(_media_ids, 1);
  IF _n > 10 THEN
    RAISE EXCEPTION 'a post carries at most 10 photographs (got %)', _n USING ERRCODE = '22023';
  END IF;

  -- Retry safety BEFORE any write.
  IF _idempotency_key IS NOT NULL THEN
    SELECT id INTO _existing FROM public.posts
     WHERE user_id = _uid AND idempotency_key = _idempotency_key;
    IF FOUND THEN
      RETURN _existing;
    END IF;
  END IF;

  SELECT count(*) INTO _bad
  FROM (SELECT DISTINCT unnest(_media_ids) AS m) d;
  IF _bad <> _n THEN
    RAISE EXCEPTION 'the same photograph appears more than once in this post' USING ERRCODE = '22023';
  END IF;

  -- Ownership AND readiness, checked as a set.
  SELECT count(*) INTO _bad
  FROM unnest(_media_ids) AS m(id)
  LEFT JOIN public.media_objects mo ON mo.id = m.id
  WHERE mo.id IS NULL OR mo.owner_id <> _uid OR mo.state <> 'ready';

  IF _bad > 0 THEN
    RAISE EXCEPTION
      '% of % photographs are not yours, do not exist, or are not finished uploading', _bad, _n
      USING ERRCODE = '42501';
  END IF;

  -- The delivery origin, read from settings rather than hardcoded. Fail loud:
  -- a published post carrying half a URL is worse than a refused publish.
  SELECT value->>'public_url' INTO _origin
  FROM public.site_settings WHERE key = 's3_storage_settings';

  IF _origin IS NULL OR _origin = '' THEN
    RAISE EXCEPTION 'MEDIA-2110 s3_storage_settings.public_url is not configured'
      USING ERRCODE = '22023';
  END IF;
  _origin := rtrim(_origin, '/');

  -- image_urls: DERIVED, never supplied, so the legacy array and post_media
  -- cannot disagree about which photograph this is.
  SELECT array_agg(_origin || '/' || (mo.derivatives->>'original') ORDER BY t.ord)
    INTO _image_urls
  FROM unnest(_media_ids) WITH ORDINALITY AS t(mid, ord)
  JOIN public.media_objects mo ON mo.id = t.mid;

  IF _image_urls IS NULL OR array_length(_image_urls, 1) <> _n THEN
    RAISE EXCEPTION 'MEDIA-2111 could not derive % legacy urls', _n USING ERRCODE = '23514';
  END IF;

  -- thumbnail_urls: SUPPLIED but CONSTRAINED to the photograph or its -thumb
  -- sibling. Anything else would let a caller point a grid at an image the
  -- post does not contain.
  IF _thumbnail_urls IS NULL THEN
    _thumbs := _image_urls;
  ELSE
    IF array_length(_thumbnail_urls, 1) IS DISTINCT FROM _n THEN
      RAISE EXCEPTION 'MEDIA-2112 % thumbnails supplied for % photographs',
        coalesce(array_length(_thumbnail_urls, 1), 0), _n USING ERRCODE = '22023';
    END IF;

    SELECT count(*) INTO _bad
    FROM generate_subscripts(_image_urls, 1) AS i
    WHERE _thumbnail_urls[i] IS DISTINCT FROM _image_urls[i]
      AND _thumbnail_urls[i] IS DISTINCT FROM
          regexp_replace(_image_urls[i], '\.([A-Za-z0-9]+)$', '-thumb.\1');

    IF _bad > 0 THEN
      RAISE EXCEPTION 'MEDIA-2113 % thumbnail url(s) are neither the photograph nor its -thumb sibling', _bad
        USING ERRCODE = '23514';
    END IF;
    _thumbs := _thumbnail_urls;
  END IF;

  INSERT INTO public.posts (user_id, content, privacy, categories, indexing_disabled,
                            idempotency_key, image_url, image_urls, thumbnail_urls)
  VALUES (_uid, COALESCE(_content, ''), _privacy, COALESCE(_categories, '{}'),
          COALESCE(_indexing_disabled, false), _idempotency_key,
          _image_urls[1], _image_urls, _thumbs)
  RETURNING id INTO _post_id;

  -- Contiguous ords 0..n-1 by construction (R15).
  INSERT INTO public.post_media (post_id, ord, media_id)
  SELECT _post_id, ord - 1, mid
  FROM unnest(_media_ids) WITH ORDINALITY AS t(mid, ord);

  -- Completeness gate.
  SELECT count(*) INTO _bad FROM public.post_media WHERE post_id = _post_id;
  IF _bad <> _n THEN
    RAISE EXCEPTION 'publish aborted: % of % photographs attached', _bad, _n USING ERRCODE = '23514';
  END IF;

  RETURN _post_id;
END $_$;


ALTER FUNCTION "public"."post_publish_with_media"("_media_ids" "uuid"[], "_content" "text", "_privacy" "text", "_categories" "text"[], "_indexing_disabled" boolean, "_idempotency_key" "text", "_thumbnail_urls" "text"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."post_publish_with_media"("_media_ids" "uuid"[], "_content" "text", "_privacy" "text", "_categories" "text"[], "_indexing_disabled" boolean, "_idempotency_key" "text", "_thumbnail_urls" "text"[]) IS 'One transaction: the post, all of its post_media references, and the legacy image_urls/thumbnail_urls arrays. image_urls is DERIVED from the media rows; thumbnail_urls is constrained to the photograph or its -thumb sibling. The dual-write is D-004 and is load-bearing for the Android binary.';



