CREATE OR REPLACE FUNCTION "public"."process_post_jobs"("_batch" integer DEFAULT 50) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _m         record;
  _type      text;
  _ok        int := 0;
  _failed    int := 0;
  _archived  int := 0;
BEGIN
  FOR _m IN
    SELECT * FROM pgmq.read('post_jobs', 30 /* vt seconds */, _batch)
  LOOP
    BEGIN
      _type := _m.message->>'type';

      IF _type = 'post_created' THEN
        -- v1: deliberate no-op (no push fan-out exists in this codebase;
        -- feed is pull-based). Reserved for future fan-out/indexing work.
        NULL;

      ELSIF _type = 'tag_notification' THEN
        PERFORM public.pj_handle_tag_notification(_m.message);

      ELSIF _type = 'reaction_notification' THEN
        PERFORM public.pj_handle_reaction_notification(_m.message);

      ELSIF _type = 'comment_notification' THEN
        PERFORM public.pj_handle_comment_notification(_m.message);

      ELSIF _type = 'recount_engagement' THEN
        PERFORM public.pj_handle_recount_engagement(_m.message);

      ELSE
        -- Unknown type: keep for forensics, do not retry forever.
        RAISE WARNING 'process_post_jobs: unknown job type % (msg_id=%)', _type, _m.msg_id;
        PERFORM pgmq.archive('post_jobs', _m.msg_id);
        _archived := _archived + 1;
        CONTINUE;
      END IF;

      -- Success: remove from queue.
      PERFORM pgmq.delete('post_jobs', _m.msg_id);
      _ok := _ok + 1;

    EXCEPTION WHEN OTHERS THEN
      -- Handler failed: the sub-transaction rolled back (no partial
      -- notification/email state). Message stays invisible until its
      -- 30s visibility timeout lapses, then is redelivered.
      IF _m.read_ct >= 5 THEN
        -- Poison message: park it in the archive after 5 attempts.
        RAISE WARNING 'process_post_jobs: archiving poison msg_id=% after % reads: %',
          _m.msg_id, _m.read_ct, SQLERRM;
        PERFORM pgmq.archive('post_jobs', _m.msg_id);
        _archived := _archived + 1;
      ELSE
        RAISE WARNING 'process_post_jobs: msg_id=% failed (read_ct=%), will retry: %',
          _m.msg_id, _m.read_ct, SQLERRM;
        _failed := _failed + 1;
      END IF;
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'processed', _ok,
    'failed',    _failed,
    'archived',  _archived,
    'ran_at',    now()
  );
END;
$$;


ALTER FUNCTION "public"."process_post_jobs"("_batch" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."process_referral_reward"("_referred_user_id" "uuid", "_activity_type" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _referral record;
  _referrer_reward numeric;
  _referee_bonus numeric;
  _setting jsonb;
BEGIN
  -- BUG-049: lock the pending referral so a concurrent call blocks and then finds
  -- it already 'rewarded' (no double-credit).
  SELECT * INTO _referral
  FROM public.referrals
  WHERE referred_id = _referred_user_id AND status = 'pending'
  LIMIT 1
  FOR UPDATE;

  IF _referral IS NULL THEN RETURN; END IF;
  -- BUG-047: never reward a self-referral.
  IF _referral.referrer_id = _referred_user_id THEN RETURN; END IF;

  SELECT value INTO _setting FROM public.site_settings WHERE key = 'referral_reward';
  _referrer_reward := COALESCE((_setting->>'referrer_amount')::numeric, (_setting->>'amount')::numeric, 1.00);
  _referee_bonus := COALESCE((_setting->>'referee_bonus')::numeric, 0.50);

  PERFORM wallet_transaction(
    _referral.referrer_id,
    'referral_earning',
    _referrer_reward,
    'Referral Reward – your invited friend completed their first ' || _activity_type,
    _referral.id,
    'referral'
  );

  IF _referee_bonus > 0 THEN
    PERFORM wallet_transaction(
      _referred_user_id,
      'referral_bonus',
      _referee_bonus,
      'Welcome bonus – reward for joining via referral',
      _referral.id,
      'referral'
    );
  END IF;

  UPDATE public.referrals
  SET status = 'rewarded', reward_amount = _referrer_reward, rewarded_at = now()
  WHERE id = _referral.id;
END;
$$;


ALTER FUNCTION "public"."process_referral_reward"("_referred_user_id" "uuid", "_activity_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."process_referral_reward"("_referred_user_id" "uuid", "_activity_type" "text", "_txn_amount" numeric DEFAULT 0) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _referral record;
  _referrer_reward numeric;
  _referee_bonus numeric;
  _setting jsonb;
  _enabled boolean;
  _min_amount numeric;
  _monthly_cap integer;
  _manual_approval boolean;
  _month_count integer;
BEGIN
  -- BUG-049: lock the pending referral (serialize concurrent qualifying activity).
  SELECT * INTO _referral
  FROM public.referrals
  WHERE referred_id = _referred_user_id AND status = 'pending'
  LIMIT 1
  FOR UPDATE;

  IF _referral IS NULL THEN RETURN; END IF;
  -- BUG-047: never reward a self-referral.
  IF _referral.referrer_id = _referred_user_id THEN RETURN; END IF;

  SELECT value INTO _setting FROM public.site_settings WHERE key = 'referral_reward';
  _enabled := COALESCE((_setting->>'enabled')::boolean, true);
  _referrer_reward := COALESCE((_setting->>'referrer_amount')::numeric, 1.00);
  _referee_bonus := COALESCE((_setting->>'referee_bonus')::numeric, 0.50);
  _min_amount := COALESCE((_setting->>'min_qualifying_amount')::numeric, 0);
  _monthly_cap := COALESCE((_setting->>'monthly_cap')::integer, 10);
  _manual_approval := COALESCE((_setting->>'manual_approval')::boolean, false);

  IF NOT _enabled THEN RETURN; END IF;

  IF _txn_amount > 0 AND _txn_amount < _min_amount THEN RETURN; END IF;

  IF _manual_approval THEN RETURN; END IF;

  SELECT COUNT(*) INTO _month_count
  FROM public.referrals
  WHERE referrer_id = _referral.referrer_id
    AND status = 'rewarded'
    AND rewarded_at >= date_trunc('month', now());

  IF _month_count >= _monthly_cap THEN
    UPDATE public.referrals SET status = 'capped' WHERE id = _referral.id;
    RETURN;
  END IF;

  PERFORM wallet_transaction(
    _referral.referrer_id,
    'referral_earning',
    _referrer_reward,
    'Referral Reward – your invited friend completed their first ' || _activity_type,
    _referral.id,
    'referral'
  );

  IF _referee_bonus > 0 THEN
    PERFORM wallet_transaction(
      _referred_user_id,
      'referral_bonus',
      _referee_bonus,
      'Welcome bonus – reward for joining via referral',
      _referral.id,
      'referral'
    );
  END IF;

  UPDATE public.referrals
  SET status = 'rewarded', reward_amount = _referrer_reward, rewarded_at = now()
  WHERE id = _referral.id;
END;
$$;


ALTER FUNCTION "public"."process_referral_reward"("_referred_user_id" "uuid", "_activity_type" "text", "_txn_amount" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."progression_order"("_stage_key" "text") RETURNS integer
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT COALESCE(
    (SELECT (round_number * 100)
              + CASE family
                  -- Round-1 vocabulary
                  WHEN 'needs_review'      THEN 1
                  WHEN 'verification'      THEN 2
                  -- Cross-round progression
                  WHEN 'progression_pass'  THEN 5  -- accepted/qualified/shortlisted (forward)
                  WHEN 'progression_fail'  THEN 8  -- not_selected_*  (terminal-fail in round)
                  WHEN 'rejection'         THEN 9  -- rejected (terminal)
                  -- R4 awards (all forward, ranked by prestige)
                  WHEN 'award'             THEN 10
                  ELSE 0
                END
       FROM public.v3_stage_catalog
      WHERE stage_key = _stage_key
        AND is_active = true
      LIMIT 1),
    0
  );
$$;


ALTER FUNCTION "public"."progression_order"("_stage_key" "text") OWNER TO "postgres";


