CREATE OR REPLACE FUNCTION "public"."protect_system_tags_fn"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND OLD.is_system THEN
    RAISE EXCEPTION 'System tags cannot be deleted (label=%)', OLD.label;
  END IF;
  IF TG_OP = 'UPDATE' AND OLD.is_system AND NEW.label IS DISTINCT FROM OLD.label THEN
    IF current_setting('app.allow_system_tag_rename', true) IS DISTINCT FROM 'on' THEN
      RAISE EXCEPTION 'System tag labels cannot be renamed via UI (label=%)', OLD.label;
    END IF;
  END IF;
  RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION "public"."protect_system_tags_fn"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prune_activity_minutes"("_dry_run" boolean DEFAULT true) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _cutoff timestamptz := now() - interval '40 days';
  _n integer;
BEGIN
  IF _dry_run THEN
    SELECT COUNT(*) INTO _n
    FROM public.member_activity_minutes
    WHERE minute_bucket < _cutoff;
    RETURN _n;
  END IF;

  -- Refuse to delete a day that has not been rolled up, or lifetime engagement
  -- would be silently lost with it.
  DELETE FROM public.member_activity_minutes m
  WHERE m.minute_bucket < _cutoff
    AND EXISTS (
      SELECT 1 FROM public.contributor_engagement_daily d
      WHERE d.user_id = m.user_id
        AND d.utc_date = (m.minute_bucket AT TIME ZONE 'UTC')::date
    );

  GET DIAGNOSTICS _n = ROW_COUNT;
  RETURN _n;
END;
$$;


ALTER FUNCTION "public"."prune_activity_minutes"("_dry_run" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."prune_activity_minutes"("_dry_run" boolean) IS 'Deletes raw minutes older than 40 days, but ONLY for days already present in contributor_engagement_daily so lifetime totals survive. Defaults to a dry run that counts without deleting.';



CREATE OR REPLACE FUNCTION "public"."prune_client_errors"("_days" integer DEFAULT 30) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE _deleted integer;
BEGIN
  DELETE FROM public.client_errors WHERE created_at < now() - make_interval(days => GREATEST(7, _days));
  GET DIAGNOSTICS _deleted = ROW_COUNT;
  RETURN _deleted;
END;
$$;


ALTER FUNCTION "public"."prune_client_errors"("_days" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prune_old_notifications"("_days" integer DEFAULT 90, "_max_rows" integer DEFAULT 5000) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _deleted int;
  _window int := greatest(coalesce(_days, 90), 30);
  _cap    int := greatest(least(coalesce(_max_rows, 5000), 50000), 1);
BEGIN
  WITH doomed AS (
    SELECT id FROM public.user_notifications
     WHERE is_read = true AND created_at < now() - make_interval(days => _window)
     ORDER BY created_at LIMIT _cap
  )
  DELETE FROM public.user_notifications n USING doomed d WHERE n.id = d.id;
  GET DIAGNOSTICS _deleted = ROW_COUNT;
  RAISE LOG 'prune_old_notifications: deleted % read notifications older than % days', _deleted, _window;
  RETURN _deleted;
END;
$$;


ALTER FUNCTION "public"."prune_old_notifications"("_days" integer, "_max_rows" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."publish_post_draft"("_draft_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _uid uuid := auth.uid();
  _d   public.post_drafts%ROWTYPE;
  _post_id uuid;
  _t   jsonb;
BEGIN
  IF _uid IS NULL THEN
    RAISE EXCEPTION 'AUTH-0001: sign-in required' USING ERRCODE = 'insufficient_privilege';
  END IF;

  -- Lock the row so two taps of Publish cannot both proceed.
  SELECT * INTO _d FROM public.post_drafts
   WHERE id = _draft_id AND user_id = _uid AND expiring_at IS NULL
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'DRAFT-003: draft not found, not yours, or expired'
      USING ERRCODE = 'no_data_found';
  END IF;

  -- post_kind is set explicitly. Inside a SECURITY DEFINER function
  -- current_user is the owner, so enforce_post_categories() does NOT treat this
  -- as a client insert and will not pin post_kind for us. A published draft is
  -- a member post - a person wrote it - so it must say so.
  INSERT INTO public.posts (
    user_id, content, image_url, image_urls, thumbnail_urls,
    privacy, indexing_disabled, categories, post_kind
  ) VALUES (
    _uid, _d.content, _d.image_url, _d.image_urls, _d.thumbnail_urls,
    _d.privacy, _d.indexing_disabled, _d.categories, 'member'
  )
  RETURNING id INTO _post_id;

  -- Media references. Same guarded shape as the people-tags block below, and
  -- for the same reason: a refused attach must never cost the member the post
  -- they just published. The sub-transaction makes it all-or-nothing, so a
  -- partial carousel is not reachable.
  BEGIN
    PERFORM public.post_attach_media(_post_id, _d.media_ids);
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'DRAFT-005: media references not attached to post %: %', _post_id, SQLERRM;
  END;

  -- People-tags. Wrapped so a malformed tag can never cost the member their
  -- post: that is exactly how the direct posting path behaves today (it logs
  -- POST-2005 and carries on), and publishing must not be stricter.
  BEGIN
    FOR _t IN SELECT * FROM jsonb_array_elements(COALESCE(_d.pending_tags, '[]'::jsonb))
    LOOP
      INSERT INTO public.post_tags (
        post_id, tagger_id, tagged_user_id, photo_index, x_position, y_position
      ) VALUES (
        _post_id, _uid,
        (_t->>'taggedUserId')::uuid,
        COALESCE((_t->>'photoIndex')::int, 0),
        COALESCE((_t->>'xPosition')::numeric, 0),
        COALESCE((_t->>'yPosition')::numeric, 0)
      );
    END LOOP;
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'DRAFT-004: people-tags skipped for post %: %', _post_id, SQLERRM;
  END;

  -- The draft row goes. Its IMAGES DO NOT - the post now references those very
  -- URLs. Deleting them here would blank the post that was just created.
  DELETE FROM public.post_drafts WHERE id = _draft_id;

  RETURN _post_id;
END $$;


ALTER FUNCTION "public"."publish_post_draft"("_draft_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."push_on_notification"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _cfg   public.push_config%ROWTYPE;
  _allow boolean := true;
BEGIN
  SELECT * INTO _cfg FROM public.push_config WHERE id LIMIT 1;
  IF _cfg.function_url IS NULL THEN RETURN NEW; END IF;
  IF NEW.actor_id IS NOT NULL AND NEW.actor_id = NEW.user_id THEN RETURN NEW; END IF;
  SELECT CASE
           WHEN np.user_id IS NULL THEN true
           WHEN np.push_enabled = false THEN false
           WHEN NEW.type IN ('post_reaction','image_reaction')            THEN np.push_reactions
           WHEN NEW.type IN ('post_comment','image_comment','comment_reply') THEN np.push_comments
           WHEN NEW.type = 'friend_request'                                THEN np.push_friend_requests
           WHEN NEW.type = 'new_follower'                                  THEN np.push_new_followers
           WHEN NEW.type = 'new_post_from_following'                       THEN np.push_new_posts
           WHEN NEW.type IN ('competition_vote','entry_approved','entry_rejected',
                             'competition_winner','new_competition')       THEN np.push_competition_updates
           -- ADDED 2026-08-15: the two platform broadcasts. Placed ABOVE
           -- `ELSE true` so they cannot fall through to it, and BELOW the
           -- specific branches above so it cannot swallow one of them.
           -- Neither type appears in any earlier branch (verified against the
           -- live definition before this was written), so nothing above shadows
           -- it and it shadows nothing.
           WHEN NEW.type IN ('journal_published','course_published')        THEN np.push_announcements
           ELSE true
         END
    INTO _allow
  FROM (SELECT 1) AS _one
  LEFT JOIN public.notification_preferences np ON np.user_id = NEW.user_id;
  IF _allow IS DISTINCT FROM true THEN RETURN NEW; END IF;
  PERFORM net.http_post(
    url     := _cfg.function_url,
    headers := jsonb_build_object('Content-Type','application/json','x-internal-secret', _cfg.internal_secret),
    body    := jsonb_build_object('user_id', NEW.user_id, 'title', NEW.title,
                 'body', public.notif_push_body(NEW.type, NEW.actor_id, NEW.message),
                 'data', jsonb_build_object('type', NEW.type, 'reference_id', COALESCE(NEW.reference_id::text,'')))
  );
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RAISE LOG 'push_on_notification failed for user % : % / %', NEW.user_id, SQLSTATE, SQLERRM;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."push_on_notification"() OWNER TO "postgres";


