BEGIN
  SELECT COUNT(*) INTO recent_count
  FROM public.comments
  WHERE user_id = NEW.user_id
    AND created_at > now() - interval '1 hour';
  IF recent_count >= 100 THEN
    RAISE EXCEPTION 'Rate limit exceeded: maximum 100 comments per hour';
  END IF;
  RETURN NEW;
END;
$$;


