CREATE OR REPLACE FUNCTION "public"."rate_limit_competition_entry"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  recent_count integer;
BEGIN
  SELECT COUNT(*) INTO recent_count
  FROM public.competition_entries
  WHERE user_id = NEW.user_id
    AND created_at > now() - interval '1 hour';

  IF recent_count >= 500 THEN
    RAISE EXCEPTION 'Rate limit exceeded: maximum 500 competition submissions per hour';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."rate_limit_competition_entry"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rate_limit_competition_votes"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _hourly_count integer;
  _minute_count integer;
BEGIN
  SELECT COUNT(*) INTO _minute_count
  FROM public.competition_votes
  WHERE user_id = NEW.user_id
    AND created_at > now() - interval '1 minute';

  IF _minute_count >= 10 THEN
    RAISE EXCEPTION 'Slow down: too many votes in a short time. Please wait.';
  END IF;

  SELECT COUNT(*) INTO _hourly_count
  FROM public.competition_votes
  WHERE user_id = NEW.user_id
    AND created_at > now() - interval '1 hour';

  IF _hourly_count >= 50 THEN
    RAISE EXCEPTION 'Rate limit exceeded: maximum 50 votes per hour.';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."rate_limit_competition_votes"() OWNER TO "postgres";


