CREATE OR REPLACE FUNCTION "public"."read_email_batch"("queue_name" "text", "batch_size" integer, "vt" integer) RETURNS TABLE("msg_id" bigint, "read_ct" integer, "message" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF queue_name IS NULL OR queue_name NOT IN ('transactional_emails', 'auth_emails') THEN
    RAISE EXCEPTION 'read_email_batch: queue % is not permitted', coalesce(queue_name, '<null>')
      USING ERRCODE = '42501';
  END IF;

  RETURN QUERY SELECT r.msg_id, r.read_ct, r.message
               FROM pgmq.read(queue_name, vt, batch_size) r;
EXCEPTION
  WHEN undefined_table THEN
    -- A consumer reading a queue that does not exist gets nothing. It must not
    -- create one: the reader is not the producer, and creating here is how an
    -- unrecognised name became a table.
    RETURN;
END;
$$;


ALTER FUNCTION "public"."read_email_batch"("queue_name" "text", "batch_size" integer, "vt" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reap_post_drafts"("_ids" "uuid"[]) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE _n integer;
BEGIN
  DELETE FROM public.post_drafts
   WHERE id = ANY(COALESCE(_ids,'{}')) AND expiring_at IS NOT NULL;
  GET DIAGNOSTICS _n = ROW_COUNT;
  RETURN _n;
END;
$$;


