CREATE OR REPLACE FUNCTION "public"."recompute_entry_public_status"("p_entry_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  UPDATE public.competition_entries ce
     SET public_status_derived           = v.public_status,
         public_round_derived            = v.public_round,
         public_placement_derived        = v.public_placement,
         public_progression_note_derived = v.public_progression_note,
         public_r4_tags_derived          = v.public_r4_tags
    FROM public.entry_public_status v
   WHERE ce.id = p_entry_id
     AND v.entry_id = ce.id
     AND (
          ce.public_status_derived           IS DISTINCT FROM v.public_status
       OR ce.public_round_derived            IS DISTINCT FROM v.public_round
       OR ce.public_placement_derived        IS DISTINCT FROM v.public_placement
       OR ce.public_progression_note_derived IS DISTINCT FROM v.public_progression_note
       OR ce.public_r4_tags_derived          IS DISTINCT FROM v.public_r4_tags
     );
END;
$$;


ALTER FUNCTION "public"."recompute_entry_public_status"("p_entry_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_activity_minute"("_segment" "text", "_interacted" boolean DEFAULT false) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _user    uuid := auth.uid();
  _bucket  timestamptz;
  _surface text;
BEGIN
  -- Signed out: nothing to record, and no error worth raising.
  IF _user IS NULL THEN
    RETURN;
  END IF;

  _bucket := date_trunc('minute', now());

  -- Owner, 2026-08-11: "/admin/* and /judge/* must never produce
  -- contributor-credit engagement." Applied here, on the server, so it holds
  -- regardless of what any client build does.
  _surface := CASE
    WHEN lower(coalesce(_segment, '')) IN ('admin', 'judge') THEN 'internal'
    ELSE 'public'
  END;

  INSERT INTO public.member_activity_minutes (user_id, minute_bucket, surface, had_interaction)
  VALUES (_user, _bucket, _surface, coalesce(_interacted, false))
  ON CONFLICT (user_id, minute_bucket) DO UPDATE
  SET
    -- THE STRICTEST PING WINS, AND IT NEVER UNWINDS.
    -- A minute that touched /admin at any point is an internal minute, even if
    -- the member also glanced at the feed inside the same sixty seconds. Being
    -- conservative here is what makes it impossible to launder administrative
    -- time into contributor credit by tapping a public page.
    surface = CASE
      WHEN public.member_activity_minutes.surface = 'internal' THEN 'internal'
      WHEN EXCLUDED.surface = 'internal' THEN 'internal'
      ELSE 'public'
    END,
    -- If any ping in the minute carried a real interaction, the minute had one.
    had_interaction = public.member_activity_minutes.had_interaction OR EXCLUDED.had_interaction;
END;
$$;


ALTER FUNCTION "public"."record_activity_minute"("_segment" "text", "_interacted" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."record_activity_minute"("_segment" "text", "_interacted" boolean) IS 'The only way a row enters member_activity_minutes. Takes a path SEGMENT (never a full path, id or slug) and a diagnostic interaction flag. Derives the member from auth.uid() and the minute from the server clock; the client cannot name either.';



CREATE OR REPLACE FUNCTION "public"."record_test_agent_run"("p_token" "text", "p_run_id" "text", "p_trigger" "text", "p_commit_sha" "text", "p_branch" "text", "p_status" "text", "p_rpc_parity_pass" boolean, "p_nr_drift_5min" integer, "p_dual_emit_status" "text", "p_tsc_pass" boolean, "p_vitest_pass" boolean, "p_eslint_pass" boolean, "p_failures" "jsonb", "p_duration_ms" integer, "p_github_run_url" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_expected_token TEXT;
  v_id UUID;
BEGIN
  SELECT decrypted_secret INTO v_expected_token
  FROM vault.decrypted_secrets
  WHERE name = 'test_agent_ingest_token'
  LIMIT 1;

  IF v_expected_token IS NULL OR p_token IS NULL OR p_token <> v_expected_token THEN
    RAISE EXCEPTION 'invalid_token';
  END IF;

  INSERT INTO public.test_agent_runs (
    run_id, trigger, commit_sha, branch, status,
    rpc_parity_pass, nr_drift_5min, dual_emit_status,
    tsc_pass, vitest_pass, eslint_pass,
    failures, duration_ms, github_run_url
  ) VALUES (
    p_run_id, p_trigger, p_commit_sha, p_branch, p_status,
    p_rpc_parity_pass, p_nr_drift_5min, p_dual_emit_status,
    p_tsc_pass, p_vitest_pass, p_eslint_pass,
    COALESCE(p_failures, '[]'::jsonb), p_duration_ms, p_github_run_url
  )
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


ALTER FUNCTION "public"."record_test_agent_run"("p_token" "text", "p_run_id" "text", "p_trigger" "text", "p_commit_sha" "text", "p_branch" "text", "p_status" "text", "p_rpc_parity_pass" boolean, "p_nr_drift_5min" integer, "p_dual_emit_status" "text", "p_tsc_pass" boolean, "p_vitest_pass" boolean, "p_eslint_pass" boolean, "p_failures" "jsonb", "p_duration_ms" integer, "p_github_run_url" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."recount_hashtags"("tag_ids" "uuid"[]) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if tag_ids is null or array_length(tag_ids, 1) is null then
    return;
  end if;

  update public.hashtags h
  set unique_user_count = coalesce(c.users, 0),
      post_count        = coalesce(c.posts, 0),
      last_used_at      = c.last_used,
      updated_at        = now()
  from (
    select ph.hashtag_id,
           count(distinct ph.author_id) as users,
           count(*)                     as posts,
           max(p.created_at)            as last_used
    from public.post_hashtags ph
    join public.posts p on p.id = ph.post_id
    -- PRIVATE POSTS DO NOT FEED PUBLIC COUNTS. Today every production post is
    -- public so this changes nothing; it is written now because the day it
    -- starts mattering is the day somebody's private post has already been
    -- counted into a number strangers can see.
    where p.privacy = 'public'
    group by ph.hashtag_id
  ) c
  where h.id = c.hashtag_id
    and h.id = any(tag_ids);

  -- Tags whose last public post just went away fall out of the join above and
  -- must be zeroed, not left at their old value.
  update public.hashtags h
  set unique_user_count = 0, post_count = 0, updated_at = now()
  where h.id = any(tag_ids)
    and not exists (
      select 1 from public.post_hashtags ph
      join public.posts p on p.id = ph.post_id
      where ph.hashtag_id = h.id and p.privacy = 'public'
    );
end;
$$;


ALTER FUNCTION "public"."recount_hashtags"("tag_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."refresh_score_cache"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  target_entry_id UUID;
BEGIN
  target_entry_id := COALESCE(NEW.entry_id, OLD.entry_id);

  INSERT INTO public.entry_score_cache (entry_id, avg_score, total_scores, last_updated)
  SELECT
    target_entry_id,
    COALESCE(
      AVG(
        -- Per-row criterion average (NULL-safe). Falls back to legacy `score`
        -- if no criterion values exist on this row.
        COALESCE(
          (
            SELECT AVG(v)::numeric
            FROM unnest(ARRAY[
              js.line_score::numeric, js.shape_score::numeric, js.form_score::numeric,
              js.texture_score::numeric, js.space_score::numeric, js.tone_score::numeric,
              js.balance_score::numeric, js.light_score::numeric, js.depth_score::numeric
            ]) AS v
            WHERE v IS NOT NULL
          ),
          js.score::numeric
        )
      ),
      0
    ),
    COUNT(*),
    now()
  FROM public.judge_scores js
  WHERE js.entry_id = target_entry_id
  ON CONFLICT (entry_id) DO UPDATE SET
    avg_score = EXCLUDED.avg_score,
    total_scores = EXCLUDED.total_scores,
    last_updated = EXCLUDED.last_updated;

  RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION "public"."refresh_score_cache"() OWNER TO "postgres";


