CREATE OR REPLACE FUNCTION "public"."register_push_token"("_token" "text", "_platform" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not authenticated';
  END IF;
  IF _token IS NULL OR length(_token) = 0 THEN
    RAISE EXCEPTION 'token required';
  END IF;
  IF _platform NOT IN ('ios','android','web') THEN
    RAISE EXCEPTION 'invalid platform: %', _platform;
  END IF;

  INSERT INTO public.push_tokens (user_id, token, platform)
  VALUES (auth.uid(), _token, _platform)
  ON CONFLICT (token) DO UPDATE
    SET user_id = auth.uid(), platform = EXCLUDED.platform, updated_at = now();
END;
$$;


ALTER FUNCTION "public"."register_push_token"("_token" "text", "_platform" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."release_award_certs_on_publish"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.published_at IS NULL OR NEW.round_number <> 4 THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'UPDATE' AND OLD.published_at IS NOT NULL THEN
    RETURN NEW;  -- already published earlier
  END IF;
  UPDATE public.certificates
     SET published_at = now()
   WHERE reference_id = NEW.competition_id
     AND type LIKE 'competition\_%'
     AND published_at IS NULL;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."release_award_certs_on_publish"() OWNER TO "postgres";


