CREATE OR REPLACE FUNCTION "public"."request_withdrawal"("_amount" numeric, "_bank_details" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_user_id uuid := auth.uid();
  v_withdrawal_id uuid;
  v_pending_count int;
  v_wallet_error text;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  IF _amount IS NULL OR _amount < 1 OR _amount > 50000 THEN
    RAISE EXCEPTION 'Amount must be between $1 and $50,000' USING ERRCODE = '22023';
  END IF;

  -- Advisory lock per-user to serialize concurrent withdrawal attempts
  PERFORM pg_advisory_xact_lock(hashtextextended('withdrawal:' || v_user_id::text, 0));

  -- Block if pending exists
  SELECT count(*) INTO v_pending_count
  FROM public.withdrawal_requests
  WHERE user_id = v_user_id AND status = 'pending';

  IF v_pending_count > 0 THEN
    RAISE EXCEPTION 'You already have a pending withdrawal request' USING ERRCODE = 'P0001';
  END IF;

  -- Atomic: insert request first
  INSERT INTO public.withdrawal_requests (user_id, amount, bank_details, status)
  VALUES (v_user_id, _amount, _bank_details, 'pending')
  RETURNING id INTO v_withdrawal_id;

  -- Then debit wallet via canonical RPC (raises on insufficient funds)
  PERFORM public.wallet_transaction(
    _user_id := v_user_id,
    _type := 'withdrawal',
    _amount := -_amount,
    _description := 'Withdrawal request — $' || _amount::text,
    _reference_id := v_withdrawal_id,
    _reference_type := 'withdrawal_request'
  );

  -- Audit log
  INSERT INTO public.db_audit_logs (table_name, operation, row_id, old_data, new_data, changed_by)
  VALUES (
    'withdrawal_requests',
    'INSERT',
    v_withdrawal_id,
    NULL,
    jsonb_build_object('amount', _amount, 'status', 'pending', 'user_id', v_user_id),
    v_user_id
  );

  RETURN v_withdrawal_id;
END;
$_$;


ALTER FUNCTION "public"."request_withdrawal"("_amount" numeric, "_bank_details" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_custom_url"("_url" "text") RETURNS TABLE("user_id" "uuid", "is_current" boolean, "released_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT h.user_id, h.is_current, h.released_at
  FROM public.custom_url_history h
  WHERE lower(h.custom_url) = lower(_url)
  ORDER BY h.created_at DESC
  LIMIT 1;
$$;


ALTER FUNCTION "public"."resolve_custom_url"("_url" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rollup_engagement_daily"("_utc_date" "date" DEFAULT NULL::"date") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _d date := coalesce(_utc_date, ((now() AT TIME ZONE 'UTC')::date - 1));
  _n integer;
BEGIN
  DELETE FROM public.contributor_engagement_daily WHERE utc_date = _d;

  INSERT INTO public.contributor_engagement_daily (
    user_id, utc_date, minutes_actual, minutes_public, minutes_internal,
    minutes_credited, minutes_interacted, minutes_carried
  )
  SELECT
    m.user_id,
    _d,
    COUNT(*),
    COUNT(*) FILTER (WHERE m.surface = 'public'),
    COUNT(*) FILTER (WHERE m.surface = 'internal'),
    -- The 30-minute daily cap. Applied to PUBLIC minutes only, so administrative
    -- time cannot consume or contribute to a member's credit either way.
    LEAST(COUNT(*) FILTER (WHERE m.surface = 'public'), 30),
    COUNT(*) FILTER (WHERE m.surface = 'public' AND m.had_interaction),
    COUNT(*) FILTER (WHERE m.surface = 'public' AND NOT m.had_interaction)
  FROM public.member_activity_minutes m
  WHERE (m.minute_bucket AT TIME ZONE 'UTC')::date = _d
  GROUP BY m.user_id;

  GET DIAGNOSTICS _n = ROW_COUNT;
  RETURN _n;
END;
$$;


ALTER FUNCTION "public"."rollup_engagement_daily"("_utc_date" "date") OWNER TO "postgres";


