CREATE OR REPLACE FUNCTION "public"."search_certificates"("_name" "text", "_course_title" "text", "_issued_date" "date") RETURNS TABLE("id" "uuid", "title" "text", "description" "text", "type" "text", "issued_at" timestamp with time zone, "recipient_name" "text", "certificate_id" "text", "verification_token" "text", "is_revoked" boolean, "revoked_at" timestamp with time zone, "revoked_reason" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT c.id, c.title, c.description, c.type, c.issued_at,
         p.full_name, c.certificate_id, NULL::text AS verification_token,
         COALESCE(c.is_revoked, false), c.revoked_at, c.revoked_reason
  FROM public.certificates c
  LEFT JOIN public.profiles p ON p.id = c.user_id
  WHERE
    -- require at least one real search term (blocks the all-blank bulk dump)
    (NULLIF(btrim(_name),'') IS NOT NULL OR NULLIF(btrim(_course_title),'') IS NOT NULL OR _issued_date IS NOT NULL)
    AND (_name IS NULL OR p.full_name ILIKE '%' || _name || '%')
    AND (_course_title IS NULL OR c.title ILIKE '%' || _course_title || '%')
    AND (_issued_date IS NULL OR DATE(c.issued_at) = _issued_date)
  ORDER BY c.issued_at DESC
  LIMIT 50;
$$;


ALTER FUNCTION "public"."search_certificates"("_name" "text", "_course_title" "text", "_issued_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."search_profiles_admin"("q" "text") RETURNS TABLE("id" "uuid", "full_name" "text", "email" "text", "avatar_url" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT public.has_role(auth.uid(), 'admin'::app_role) THEN
    RETURN;
  END IF;

  IF q IS NULL OR length(trim(q)) < 2 THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT p.id, p.full_name, u.email::text, p.avatar_url
  FROM public.profiles p
  JOIN auth.users u ON u.id = p.id
  WHERE p.full_name ILIKE '%' || q || '%'
     OR u.email      ILIKE '%' || q || '%'
  ORDER BY
    CASE WHEN p.full_name ILIKE q || '%' OR u.email ILIKE q || '%' THEN 0 ELSE 1 END,
    p.full_name NULLS LAST
  LIMIT 10;
END;
$$;


ALTER FUNCTION "public"."search_profiles_admin"("q" "text") OWNER TO "postgres";


