COMMENT ON FUNCTION "public"."set_write_path"("p" "text") IS 'B2.5b: Sanctioned edge fns call this as their first DB action to stamp app.write_path on every v3_mirror_log row written in the same transaction. Service-role only.';



CREATE OR REPLACE FUNCTION "public"."should_test_agent_run"("p_trigger" "text" DEFAULT 'schedule'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  cfg public.test_agent_config%ROWTYPE;
  last_run timestamptz;
  minutes_since numeric;
BEGIN
  SELECT * INTO cfg FROM public.test_agent_config WHERE id = true;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('should_run', true, 'reason', 'no_config');
  END IF;

  -- Push / PR / manual always run when enabled
  IF p_trigger IN ('push','pull_request','workflow_dispatch') THEN
    RETURN jsonb_build_object(
      'should_run', cfg.enabled,
      'reason', CASE WHEN cfg.enabled THEN 'enabled_event' ELSE 'disabled' END,
      'enabled', cfg.enabled,
      'interval_minutes', cfg.interval_minutes
    );
  END IF;

  IF NOT cfg.enabled THEN
    RETURN jsonb_build_object('should_run', false, 'reason', 'disabled', 'enabled', false, 'interval_minutes', cfg.interval_minutes);
  END IF;

  SELECT MAX(created_at) INTO last_run FROM public.test_agent_runs;
  IF last_run IS NULL THEN
    RETURN jsonb_build_object('should_run', true, 'reason', 'no_prior_run', 'enabled', true, 'interval_minutes', cfg.interval_minutes);
  END IF;

  minutes_since := EXTRACT(EPOCH FROM (now() - last_run)) / 60.0;
  IF minutes_since >= cfg.interval_minutes THEN
    RETURN jsonb_build_object(
      'should_run', true, 'reason', 'interval_elapsed',
      'minutes_since_last', minutes_since,
      'enabled', true, 'interval_minutes', cfg.interval_minutes
    );
  ELSE
    RETURN jsonb_build_object(
      'should_run', false, 'reason', 'interval_not_elapsed',
      'minutes_since_last', minutes_since,
      'enabled', true, 'interval_minutes', cfg.interval_minutes
    );
  END IF;
END;
$$;


ALTER FUNCTION "public"."should_test_agent_run"("p_trigger" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."soft_void_wallet_transactions"("p_txn_ids" "uuid"[], "p_reason" "text", "p_batch_id" "uuid" DEFAULT "gen_random_uuid"()) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _caller uuid := auth.uid();
  _voided_count int := 0;
  _reversed_count int := 0;
  _skipped int := 0;
  _txn record;
  _already_reversed boolean;
BEGIN
  -- BUG-105: authority = admin, OR genuine service_role. A NULL auth.uid() is
  -- ONLY trusted when it is NOT the anon role. Previously ANY null caller was
  -- trusted, so an anon-key caller could void their own wallet debits and have
  -- the balance credited back (self-mint).
  IF _caller IS NOT NULL THEN
    IF NOT has_role(_caller, 'admin'::app_role) THEN
      RAISE EXCEPTION 'soft_void_wallet_transactions: admin/service_role only';
    END IF;
  ELSIF coalesce((current_setting('request.jwt.claims', true))::jsonb ->> 'role', 'service_role') = 'anon' THEN
    RAISE EXCEPTION 'soft_void_wallet_transactions: admin/service_role only';
  END IF;

  IF p_txn_ids IS NULL OR array_length(p_txn_ids, 1) IS NULL THEN
    RETURN jsonb_build_object(
      'voided_count', 0,
      'reversed_count', 0,
      'skipped_already_voided', 0,
      'batch_id', p_batch_id
    );
  END IF;

  FOR _txn IN
    SELECT id, user_id, amount, type, status
    FROM public.wallet_transactions
    WHERE id = ANY(p_txn_ids)
    FOR UPDATE
  LOOP
    IF _txn.status = 'voided' THEN
      _skipped := _skipped + 1;
      CONTINUE;
    END IF;

    -- 1. Soft-void: flip status + merge audit metadata
    UPDATE public.wallet_transactions
    SET status = 'voided',
        metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object(
          'voided_at', to_jsonb(now()),
          'voided_by', to_jsonb(_caller),
          'void_reason', to_jsonb(p_reason),
          'void_batch_id', to_jsonb(p_batch_id),
          'original_status', to_jsonb(_txn.status)
        )
    WHERE id = _txn.id;
    _voided_count := _voided_count + 1;

    -- 2. Idempotency check: skip reversal if one already exists for this original
    SELECT EXISTS(
      SELECT 1 FROM public.wallet_transactions
      WHERE reference_id = _txn.id AND type = 'void_reversal'
    ) INTO _already_reversed;

    IF NOT _already_reversed THEN
      -- 3. Paired reversing row via canonical wallet_transaction() RPC.
      --    Sign-flip restores wallets.balance atomically.
      PERFORM public.wallet_transaction(
        _txn.user_id,
        'void_reversal',
        -_txn.amount,
        'Reversal of voided txn ' || _txn.id::text || ' (' || p_reason || ')',
        _txn.id,
        'void_reversal',
        jsonb_build_object(
          'void_batch_id', p_batch_id,
          'original_txn_id', _txn.id,
          'original_type', _txn.type,
          'original_amount', _txn.amount,
          'void_reason', p_reason
        )
      );
      _reversed_count := _reversed_count + 1;
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'voided_count', _voided_count,
    'reversed_count', _reversed_count,
    'skipped_already_voided', _skipped,
    'batch_id', p_batch_id
  );
END;
$$;


ALTER FUNCTION "public"."soft_void_wallet_transactions"("p_txn_ids" "uuid"[], "p_reason" "text", "p_batch_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."soft_void_wallet_transactions"("p_txn_ids" "uuid"[], "p_reason" "text", "p_batch_id" "uuid") IS 'Phase 1 Mut #4: Soft-void wallet_transactions + emit paired void_reversal rows. service_role/admin only. Idempotent on (reference_id, type=void_reversal).';



CREATE OR REPLACE FUNCTION "public"."submit_competition_entry"("_competition_id" "uuid", "_title" "text", "_description" "text", "_photos" "text"[], "_photo_thumbnails" "text"[], "_photo_meta" "jsonb", "_is_ai_generated" boolean, "_exif_data" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  _user_id uuid;
  _entry_fee numeric;
  _comp_phase text;
  _wallet_balance numeric;
  _new_balance numeric;
  _txn_id uuid;
  _entry_id uuid;
  _order_id uuid;
  _order_no text;
  _n int;
BEGIN
  _user_id := auth.uid();
  IF _user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  _n := COALESCE(array_length(_photos, 1), 0);
  IF _n = 0 THEN
    RAISE EXCEPTION 'At least one photo is required' USING ERRCODE = '22023';
  END IF;
  IF jsonb_array_length(_photo_meta) <> _n THEN
    RAISE EXCEPTION 'photo_meta length (%) must match photos length (%)',
      jsonb_array_length(_photo_meta), _n USING ERRCODE = '22023';
  END IF;
  IF _photo_thumbnails IS NOT NULL
     AND COALESCE(array_length(_photo_thumbnails, 1), 0) <> _n THEN
    RAISE EXCEPTION 'photo_thumbnails length must match photos length' USING ERRCODE = '22023';
  END IF;

  SELECT entry_fee, phase INTO _entry_fee, _comp_phase
  FROM public.competitions
  WHERE id = _competition_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Competition not found' USING ERRCODE = '22023';
  END IF;
  IF _comp_phase <> 'submission_open' THEN
    RAISE EXCEPTION 'Submissions are closed for this competition' USING ERRCODE = '22023';
  END IF;

  _entry_fee := COALESCE(_entry_fee, 0);

  IF _entry_fee > 0 THEN
    INSERT INTO public.wallets (user_id, balance)
    VALUES (_user_id, 0)
    ON CONFLICT (user_id) DO NOTHING;

    SELECT balance INTO _wallet_balance
    FROM public.wallets
    WHERE user_id = _user_id
    FOR UPDATE;

    IF _wallet_balance < _entry_fee THEN
      RAISE EXCEPTION 'Insufficient wallet balance: need $% but have $%',
        _entry_fee, _wallet_balance USING ERRCODE = 'P0001';
    END IF;

    UPDATE public.wallets
       SET balance = balance - _entry_fee,
           updated_at = now()
     WHERE user_id = _user_id
     RETURNING balance INTO _new_balance;

    INSERT INTO public.wallet_transactions
      (user_id, type, amount, balance_after, description, reference_id, reference_type, status, metadata)
    VALUES
      (_user_id, 'competition_fee', -_entry_fee, _new_balance,
       'Entry fee for competition',
       _competition_id, 'competition_entry_fee', 'completed',
       jsonb_build_object('source', 'submit_competition_entry'))
    RETURNING id INTO _txn_id;
  END IF;

  INSERT INTO public.competition_entries
    (competition_id, user_id, title, description, photos, photo_thumbnails,
     photo_meta, is_ai_generated, exif_data, is_ai_advisory, ai_detection_result)
  VALUES
    (_competition_id, _user_id, _title, _description, _photos, _photo_thumbnails,
     _photo_meta, COALESCE(_is_ai_generated, false), _exif_data, false, NULL)
  RETURNING id INTO _entry_id;

  _order_no := public._gen_competition_order_no();
  INSERT INTO public.competition_orders
    (order_no, user_id, competition_id, entry_id, order_type, amount, wallet_txn_id, status, metadata)
  VALUES
    (_order_no, _user_id, _competition_id, _entry_id, 'photo_competition',
     _entry_fee, _txn_id, 'completed',
     jsonb_build_object('phase', _comp_phase))
  RETURNING id INTO _order_id;

  RETURN jsonb_build_object(
    'entry_id',  _entry_id,
    'order_id',  _order_id,
    'order_no',  _order_no,
    'wallet_txn_id', _txn_id,
    'amount',    _entry_fee
  );
END;
$_$;


ALTER FUNCTION "public"."submit_competition_entry"("_competition_id" "uuid", "_title" "text", "_description" "text", "_photos" "text"[], "_photo_thumbnails" "text"[], "_photo_meta" "jsonb", "_is_ai_generated" boolean, "_exif_data" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."suggest_hashtags"("prefix" "text", "max_results" integer DEFAULT 5) RETURNS TABLE("tag" "text", "display_tag" "text", "unique_user_count" integer, "post_count" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with q as (select public.normalize_hashtag(prefix) as p)
  select h.tag, h.display_tag, h.unique_user_count, h.post_count
  from public.hashtags h, q
  where q.p is not null
    and h.tag like q.p || '%'          -- index range scan, never a full scan
  order by
    (h.tag = q.p) desc,                -- 1. the exact tag first
    h.unique_user_count desc,          -- 2. how many PEOPLE use it
    h.post_count desc,                 -- 3. overall usage
    h.last_used_at desc nulls last,    -- 4. recent activity, as a tie-break
    length(h.tag),                     --    then the shorter, closer match
    h.tag
  limit greatest(1, least(coalesce(max_results, 5), 10));
$$;


ALTER FUNCTION "public"."suggest_hashtags"("prefix" "text", "max_results" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."suggest_hashtags"("prefix" "text", "max_results" integer) IS 'Typeahead source. PREFIX ONLY — deliberately not fuzzy, because the brief says an unrelated hashtag must never appear. Ranked by unique users, not alphabetically. Capped at 10 whatever the caller asks for.';



CREATE OR REPLACE FUNCTION "public"."suggest_username"("display_name" "text") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  base text;
  candidate text;
  n int := 0;
BEGIN
  -- lowercase, spaces->dot, strip everything not [a-z0-9._], squeeze dots
  base := lower(coalesce(display_name, ''));
  base := regexp_replace(base, '\s+', '.', 'g');
  base := regexp_replace(base, '[^a-z0-9._]', '', 'g');
  base := regexp_replace(base, '\.{2,}', '.', 'g');
  base := trim(both '._' from base);
  IF length(base) < 3 THEN
    base := 'user' || floor(random() * 9000 + 1000)::int::text;
  END IF;
  base := left(base, 24);  -- room for numeric suffix
  candidate := base;
  WHILE NOT public.username_available(candidate) AND n < 500 LOOP
    n := n + 1;
    candidate := base || n::text;
  END LOOP;
  RETURN candidate;
END;
$$;


ALTER FUNCTION "public"."suggest_username"("display_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_competition_result_state_from_round_publish"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.round_number = 4 THEN
    IF NEW.published_at IS NOT NULL THEN
      UPDATE public.competitions
      SET
        current_round = '4',
        phase = 'result',
        status = 'result',
        judging_completed = true,
        updated_at = now()
      WHERE id = NEW.competition_id
        AND (
          current_round IS DISTINCT FROM '4'
          OR phase IS DISTINCT FROM 'result'
          OR status IS DISTINCT FROM 'result'
          OR judging_completed IS DISTINCT FROM true
        );
    ELSE
      UPDATE public.competitions c
      SET
        phase = 'judging',
        status = 'judging',
        judging_completed = false,
        updated_at = now()
      WHERE c.id = NEW.competition_id
        AND NOT EXISTS (
          SELECT 1
          FROM public.competition_round_publish crp
          WHERE crp.competition_id = NEW.competition_id
            AND crp.round_number = 4
            AND crp.published_at IS NOT NULL
        )
        AND c.phase = 'result'
        AND c.status = 'result'
        AND c.judging_completed = true;
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


