CREATE OR REPLACE FUNCTION "public"."sync_fallback_avatar_to_gender"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
BEGIN
  IF NEW.gender IS NOT DISTINCT FROM OLD.gender OR NEW.gender IS NULL THEN RETURN NEW; END IF;
  IF NEW.avatar_url IS NULL OR NEW.avatar_url NOT LIKE '/avatars/fallback/%' THEN RETURN NEW; END IF;
  NEW.avatar_url := '/avatars/fallback/' || CASE WHEN NEW.gender = 'female' THEN 'f' ELSE 'm' END
    || regexp_replace(NEW.avatar_url, '^/avatars/fallback/[mf]([1-5])\.svg$', '\1') || '.svg';
  RETURN NEW;
END; $_$;


ALTER FUNCTION "public"."sync_fallback_avatar_to_gender"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_oauth_on_login"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _oauth_name text;
  _is_admin boolean;
BEGIN
  IF OLD.last_sign_in_at IS NOT DISTINCT FROM NEW.last_sign_in_at THEN
    RETURN NEW;
  END IF;

  _oauth_name := COALESCE(
    NEW.raw_user_meta_data->>'full_name',
    NEW.raw_user_meta_data->>'name',
    NULL
  );

  SELECT EXISTS (
    SELECT 1 FROM public.user_roles WHERE user_id = NEW.id AND role = 'admin'
  ) INTO _is_admin;

  -- Avatar sync removed on purpose: it was the path that kept restoring
  -- hotlinked pictures after they were blanked. Names still sync.
  IF _is_admin THEN
    UPDATE public.profiles
    SET full_name = '50mm Retina World',
        updated_at = now()
    WHERE id = NEW.id
      AND full_name IS DISTINCT FROM '50mm Retina World';
  ELSE
    IF _oauth_name IS NOT NULL THEN
      UPDATE public.profiles
      SET full_name = COALESCE(full_name, _oauth_name),
          updated_at = now()
      WHERE id = NEW.id
        AND full_name IS NULL;
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."sync_oauth_on_login"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_post_hashtags"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  tags     text[];
  affected uuid[] := '{}';
  t        text;
  hid      uuid;
begin
  -- ⚠ A HASHTAG MUST NEVER STOP SOMEBODY POSTING.
  --
  -- This trigger runs INSIDE the member's INSERT. An exception here does not
  -- produce a wrong count — it aborts their whole post. Weighed plainly: a
  -- hashtag statistic that is temporarily wrong is a cosmetic fault that
  -- `recount_hashtags` repairs in one statement; a photographer who cannot
  -- publish is the platform being broken.
  --
  -- So the entire body is wrapped, and any failure is logged as a WARNING and
  -- swallowed. This is the ONE place in this migration where correctness of a
  -- number is deliberately ranked below the member finishing their action.
  begin

  -- Every tag this post pointed at BEFORE the change has to be recounted too,
  -- or a hashtag removed by an edit keeps the author it no longer has.
  if tg_op = 'UPDATE' then
    select coalesce(array_agg(hashtag_id), '{}') into affected
    from public.post_hashtags where post_id = old.id;
  end if;

  tags := public.extract_hashtags(new.content);

  -- Replace this post's set outright. Simpler than diffing, and the primary
  -- key already guarantees one row per (post, tag).
  delete from public.post_hashtags where post_id = new.id;

  foreach t in array tags loop
    insert into public.hashtags (tag, display_tag)
    values (t, t)
    on conflict (tag) do update set updated_at = now()
    returning id into hid;

    if hid is null then
      select id into hid from public.hashtags where tag = t;
    end if;

    insert into public.post_hashtags (post_id, hashtag_id, author_id)
    values (new.id, hid, new.user_id)
    on conflict (post_id, hashtag_id) do nothing;

    affected := affected || hid;
  end loop;

  perform public.recount_hashtags(affected);

  exception when others then
    -- Logged, not raised. See the note at the top of this function.
    raise warning 'sync_post_hashtags failed for post % (%): %',
      coalesce(new.id, old.id), tg_op, sqlerrm;
  end;

  return new;
end;
$$;


ALTER FUNCTION "public"."sync_post_hashtags"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."sync_post_hashtags"() IS 'The only writer of hashtag statistics. Fires on create, edit, delete and privacy change, so counts stay true no matter which screen changed the post — including screens that know nothing about hashtags.';



CREATE OR REPLACE FUNCTION "public"."sync_profiles_public_data"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  ps jsonb := COALESCE(NEW.privacy_settings, '{}'::jsonb);
  v_avatar     text := CASE WHEN COALESCE(ps->>'avatar','public')      = 'public' THEN NEW.avatar_url    ELSE NULL END;
  v_bio        text := CASE WHEN COALESCE(ps->>'bio','public')         = 'public' THEN NEW.bio           ELSE NULL END;
  v_interests  text[] := CASE WHEN COALESCE(ps->>'interests','public') = 'public' THEN NEW.photography_interests ELSE NULL END;
  v_portfolio  text := CASE WHEN COALESCE(ps->>'portfolio','public')   = 'public' THEN NEW.portfolio_url ELSE NULL END;
  v_fb         text := CASE WHEN COALESCE(ps->>'social_links','public')= 'public' THEN NEW.facebook_url  ELSE NULL END;
  v_ig         text := CASE WHEN COALESCE(ps->>'social_links','public')= 'public' THEN NEW.instagram_url ELSE NULL END;
  v_tw         text := CASE WHEN COALESCE(ps->>'social_links','public')= 'public' THEN NEW.twitter_url   ELSE NULL END;
  v_yt         text := CASE WHEN COALESCE(ps->>'social_links','public')= 'public' THEN NEW.youtube_url   ELSE NULL END;
  v_web        text := CASE WHEN COALESCE(ps->>'social_links','public')= 'public' THEN NEW.website_url   ELSE NULL END;
  v_city       text := CASE WHEN COALESCE(ps->>'city_country','public')= 'public' THEN NEW.current_city  ELSE NULL END;
  v_workplace  text := CASE WHEN COALESCE(ps->>'workplace','public')   = 'public' THEN NEW.workplace     ELSE NULL END;
  v_education  text := CASE WHEN COALESCE(ps->>'education','public')    = 'public' THEN NEW.education     ELSE NULL END;
  v_pronouns   text := CASE WHEN COALESCE(ps->>'pronouns','public')    = 'public' THEN NEW.pronouns      ELSE NULL END;
  -- Presence opt-out: 'off' hides active status.
  v_last_active timestamptz := CASE WHEN COALESCE(ps->>'active_status','on') = 'off' THEN NULL ELSE NEW.last_active_at END;
BEGIN
  IF TG_OP = 'DELETE' THEN
    DELETE FROM public.profiles_public_data WHERE id = OLD.id;
    RETURN OLD;
  END IF;

  INSERT INTO public.profiles_public_data (
    id, full_name, avatar_url, bio, portfolio_url,
    photography_interests, facebook_url, instagram_url, twitter_url,
    youtube_url, website_url, preferred_language, is_suspended,
    created_at, updated_at, custom_url, pronouns,
    current_city, workplace, education, is_banned,
    last_active_at, notification_sound_enabled
  ) VALUES (
    NEW.id, NEW.full_name, v_avatar, v_bio, v_portfolio,
    v_interests, v_fb, v_ig, v_tw,
    v_yt, v_web, NEW.preferred_language, NEW.is_suspended,
    NEW.created_at, NEW.updated_at, NEW.custom_url, v_pronouns,
    v_city, v_workplace, v_education, NEW.is_banned,
    v_last_active, NEW.notification_sound_enabled
  )
  ON CONFLICT (id) DO UPDATE SET
    full_name = EXCLUDED.full_name,
    avatar_url = EXCLUDED.avatar_url,
    bio = EXCLUDED.bio,
    portfolio_url = EXCLUDED.portfolio_url,
    photography_interests = EXCLUDED.photography_interests,
    facebook_url = EXCLUDED.facebook_url,
    instagram_url = EXCLUDED.instagram_url,
    twitter_url = EXCLUDED.twitter_url,
    youtube_url = EXCLUDED.youtube_url,
    website_url = EXCLUDED.website_url,
    preferred_language = EXCLUDED.preferred_language,
    is_suspended = EXCLUDED.is_suspended,
    created_at = EXCLUDED.created_at,
    updated_at = EXCLUDED.updated_at,
    custom_url = EXCLUDED.custom_url,
    pronouns = EXCLUDED.pronouns,
    current_city = EXCLUDED.current_city,
    workplace = EXCLUDED.workplace,
    education = EXCLUDED.education,
    is_banned = EXCLUDED.is_banned,
    last_active_at = EXCLUDED.last_active_at,
    notification_sound_enabled = EXCLUDED.notification_sound_enabled;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."sync_profiles_public_data"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_system_tag_decision_map_from_catalog"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  UPDATE public.system_tag_decision_map m
  SET decision = NEW.decision_token
  FROM public.judging_tags jt
  WHERE m.tag_id = jt.id
    AND lower(trim(jt.label)) = lower(trim(NEW.tag_label_canonical))
    AND m.round_number = NEW.round_number
    AND NEW.is_active = true
    AND m.decision IS DISTINCT FROM NEW.decision_token;
  RETURN NEW;
END;
$$;


