CREATE OR REPLACE FUNCTION "public"."tg_feed_events_viewer_count"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.event_type NOT IN ('view','skip') THEN RETURN NEW; END IF;
  -- Only the FIRST view/skip by this member on this post counts, so the column
  -- means "distinct viewers" and matches the backfill above.
  IF EXISTS (SELECT 1 FROM public.feed_events fe
             WHERE fe.post_id = NEW.post_id AND fe.user_id = NEW.user_id
               AND fe.event_type IN ('view','skip') AND fe.id <> NEW.id) THEN
    RETURN NEW;
  END IF;
  UPDATE public.posts SET viewer_count = viewer_count + 1 WHERE id = NEW.post_id;
  RETURN NEW;
END $$;


ALTER FUNCTION "public"."tg_feed_events_viewer_count"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tg_media_state_transition"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- Content identity is immutable. A row that reached `ready` was verified
  -- against THESE bytes for THIS owner; allowing either to change afterwards
  -- retroactively invalidates that verification.
  IF NEW.owner_id IS DISTINCT FROM OLD.owner_id THEN
    RAISE EXCEPTION 'media_objects.owner_id is immutable (% -> %)', OLD.owner_id, NEW.owner_id
      USING ERRCODE = '23514';
  END IF;

  IF NEW.sha256 IS DISTINCT FROM OLD.sha256 THEN
    RAISE EXCEPTION 'media_objects.sha256 is immutable'
      USING ERRCODE = '23514';
  END IF;

  IF NEW.state IS DISTINCT FROM OLD.state THEN
    -- Legal edges only. Anything absent from this list is refused, which is
    -- the whole reason the machine lives here and not in the worker.
    IF NOT (
         (OLD.state = 'pending'  AND NEW.state IN ('verified', 'quarantined'))
      OR (OLD.state = 'verified' AND NEW.state IN ('ready', 'quarantined'))
      OR (OLD.state = 'ready'    AND NEW.state = 'quarantined')
    ) THEN
      RAISE EXCEPTION 'illegal media state transition % -> % (legal: pending->verified->ready, any->quarantined)',
        OLD.state, NEW.state
        USING ERRCODE = '23514';
    END IF;
  END IF;

  RETURN NEW;
END $$;


ALTER FUNCTION "public"."tg_media_state_transition"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tg_one_judge_per_competition"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _existing uuid;
BEGIN
  SELECT judge_id INTO _existing
    FROM public.competition_judges
   WHERE competition_id = NEW.competition_id
     AND (TG_OP = 'INSERT' OR id <> NEW.id)
   LIMIT 1;

  IF _existing IS NOT NULL AND _existing <> NEW.judge_id THEN
    RAISE EXCEPTION
      'This competition already has a judge assigned. One judge per competition is a platform rule — remove the current judge first, then assign the new one.'
      USING ERRCODE = 'unique_violation';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."tg_one_judge_per_competition"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tg_post_media_requires_ready"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE _state text;
BEGIN
  -- FOR UPDATE: a concurrent quarantine of this media waits for this publish
  -- rather than interleaving with it. Whichever lands first, the other sees a
  -- settled state instead of a stale one.
  SELECT state INTO _state FROM public.media_objects WHERE id = NEW.media_id FOR UPDATE;
  IF _state IS DISTINCT FROM 'ready' THEN
    RAISE EXCEPTION 'post_media: media % is in state %, only ready may be referenced',
      NEW.media_id, coalesce(_state, '<missing>')
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END $$;


