CREATE OR REPLACE FUNCTION "public"."throttle_competition_entry_inserts"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _recent integer;
BEGIN
  SELECT count(*) INTO _recent
  FROM public.competition_entries
  WHERE user_id = NEW.user_id
    AND competition_id = NEW.competition_id
    AND created_at > now() - interval '60 seconds';

  IF _recent >= 5 THEN
    RAISE EXCEPTION 'Submission throttle: too many entries in the last 60 seconds (max 5 per competition)'
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN NEW;
END;
$$;


