CREATE OR REPLACE FUNCTION "public"."validate_competition_entry_photo_meta"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  _photos_len  integer := COALESCE(array_length(NEW.photos, 1), 0);
  _meta_len    integer := COALESCE(jsonb_array_length(NEW.photo_meta), 0);
  _i           integer;
  _item        jsonb;
  _sha         text;
  _exif_avail  jsonb;
  _title       text;
  _desc        text;
  _ai_flag     jsonb;
BEGIN
  -- Photos cap (raised 10 → 20 to align with admin form max)
  IF _photos_len > 20 THEN
    RAISE EXCEPTION 'Maximum 20 photos per entry (got %)', _photos_len
      USING ERRCODE = 'check_violation';
  END IF;

  -- Entry title length 3-200
  IF NEW.title IS NULL OR char_length(btrim(NEW.title)) < 3 OR char_length(NEW.title) > 200 THEN
    RAISE EXCEPTION 'Title must be 3-200 characters'
      USING ERRCODE = 'check_violation';
  END IF;

  -- Entry description cap
  IF NEW.description IS NOT NULL AND char_length(NEW.description) > 5000 THEN
    RAISE EXCEPTION 'Description must be at most 5000 characters'
      USING ERRCODE = 'check_violation';
  END IF;

  -- meta length must match photo count
  IF _photos_len = 0 AND _meta_len = 0 THEN
    RETURN NEW;
  END IF;
  IF _meta_len <> _photos_len THEN
    RAISE EXCEPTION 'photo_meta length (%) must match photos length (%)', _meta_len, _photos_len
      USING ERRCODE = 'check_violation';
  END IF;

  -- Per-photo integrity
  FOR _i IN 0 .. _meta_len - 1 LOOP
    _item := NEW.photo_meta -> _i;

    _exif_avail := _item -> 'exif_available';
    IF _exif_avail IS NULL OR jsonb_typeof(_exif_avail) <> 'boolean' THEN
      RAISE EXCEPTION 'photo_meta[%].exif_available must be boolean', _i
        USING ERRCODE = 'check_violation';
    END IF;

    _sha := _item #>> '{image_hash,sha256}';
    IF _sha IS NULL OR _sha !~ '^[0-9a-f]{64}$' THEN
      RAISE EXCEPTION 'photo_meta[%].image_hash.sha256 must be 64 hex chars', _i
        USING ERRCODE = 'check_violation';
    END IF;

    _title := _item ->> 'title';
    IF _title IS NULL OR char_length(btrim(_title)) < 1 OR char_length(_title) > 120 THEN
      RAISE EXCEPTION 'photo_meta[%].title must be 1-120 characters', _i
        USING ERRCODE = 'check_violation';
    END IF;

    _desc := _item ->> 'description';
    IF _desc IS NOT NULL AND char_length(_desc) > 500 THEN
      RAISE EXCEPTION 'photo_meta[%].description must be at most 500 characters', _i
        USING ERRCODE = 'check_violation';
    END IF;

    _ai_flag := _item -> 'is_ai_generated';
    IF _ai_flag IS NOT NULL AND jsonb_typeof(_ai_flag) <> 'boolean' THEN
      RAISE EXCEPTION 'photo_meta[%].is_ai_generated must be boolean when present', _i
        USING ERRCODE = 'check_violation';
    END IF;
  END LOOP;

  RETURN NEW;
END;
$_$;


ALTER FUNCTION "public"."validate_competition_entry_photo_meta"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_competition_entry_status_transition"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _allowed text[] := ARRAY[
    'draft','submitted','approved','round1_qualified','round2_qualified',
    'round3_qualified',
    'finalist','winner','rejected','hold','shortlisted','needs_review'
  ];
  _ok boolean := false;
BEGIN
  IF NOT (NEW.status = ANY(_allowed)) THEN
    RAISE EXCEPTION 'Unknown entry status %', NEW.status USING ERRCODE = 'check_violation';
  END IF;
  IF TG_OP = 'INSERT' THEN
    IF NEW.status NOT IN ('draft','submitted','approved') THEN
      RAISE EXCEPTION 'New entries must start as draft, submitted, or approved (got %)', NEW.status USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END IF;
  IF OLD.status = NEW.status THEN RETURN NEW; END IF;
  _ok := CASE OLD.status
    WHEN 'draft'             THEN NEW.status IN ('submitted','rejected')
    WHEN 'submitted'         THEN NEW.status IN ('approved','rejected','hold','round1_qualified','shortlisted','needs_review')
    WHEN 'approved'          THEN NEW.status IN ('submitted','round1_qualified','rejected','hold','shortlisted','needs_review')
    WHEN 'round1_qualified'  THEN NEW.status IN ('submitted','approved','round2_qualified','rejected','hold','shortlisted','needs_review')
    WHEN 'shortlisted'       THEN NEW.status IN ('submitted','approved','round1_qualified','round2_qualified','rejected','hold','needs_review')
    WHEN 'needs_review'      THEN NEW.status IN ('submitted','approved','round1_qualified','shortlisted','rejected','hold')
    WHEN 'round2_qualified'  THEN NEW.status IN ('submitted','round1_qualified','round3_qualified','finalist','rejected','hold','shortlisted')
    WHEN 'round3_qualified'  THEN NEW.status IN ('round2_qualified','finalist','rejected','hold')
    WHEN 'finalist'          THEN NEW.status IN ('round2_qualified','round3_qualified','winner','rejected','hold')
    WHEN 'hold'              THEN NEW.status IN ('approved','submitted','rejected','round1_qualified','round2_qualified','round3_qualified','finalist','shortlisted','needs_review')
    WHEN 'rejected'          THEN NEW.status IN ('hold','submitted','approved','needs_review','shortlisted','round1_qualified')
    WHEN 'winner'            THEN NEW.status IN ('hold','finalist')
    ELSE false
  END;
  IF NOT _ok THEN
    RAISE EXCEPTION 'Illegal status transition % -> %', OLD.status, NEW.status USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."validate_competition_entry_status_transition"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_feed_event_author"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  real_author uuid;
BEGIN
  -- Look up the actual author from the posts table
  SELECT user_id INTO real_author
  FROM public.posts
  WHERE id = NEW.post_id::uuid;

  IF real_author IS NULL THEN
    -- Post doesn't exist, reject the event
    RAISE EXCEPTION 'Invalid post_id: post does not exist';
  END IF;

  -- Override client-provided author_id with real value
  NEW.author_id := real_author;

  -- Prevent self-interaction boosting for ranking-relevant events
  IF NEW.user_id = real_author AND NEW.event_type IN ('like', 'share', 'comment') THEN
    -- Allow the event but neutralize it (won't boost own ranking)
    NEW.event_type := 'self_' || NEW.event_type;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."validate_feed_event_author"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_judge_criteria_scores"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.line_score IS NOT NULL AND (NEW.line_score < 0 OR NEW.line_score > 10) THEN
    RAISE EXCEPTION 'Line score must be between 0 and 10';
  END IF;
  IF NEW.shape_score IS NOT NULL AND (NEW.shape_score < 0 OR NEW.shape_score > 10) THEN
    RAISE EXCEPTION 'Shape score must be between 0 and 10';
  END IF;
  IF NEW.form_score IS NOT NULL AND (NEW.form_score < 0 OR NEW.form_score > 10) THEN
    RAISE EXCEPTION 'Form score must be between 0 and 10';
  END IF;
  IF NEW.texture_score IS NOT NULL AND (NEW.texture_score < 0 OR NEW.texture_score > 10) THEN
    RAISE EXCEPTION 'Texture score must be between 0 and 10';
  END IF;
  IF NEW.space_score IS NOT NULL AND (NEW.space_score < 0 OR NEW.space_score > 10) THEN
    RAISE EXCEPTION 'Space score must be between 0 and 10';
  END IF;
  IF NEW.tone_score IS NOT NULL AND (NEW.tone_score < 0 OR NEW.tone_score > 10) THEN
    RAISE EXCEPTION 'Tone score must be between 0 and 10';
  END IF;
  IF NEW.balance_score IS NOT NULL AND (NEW.balance_score < 0 OR NEW.balance_score > 10) THEN
    RAISE EXCEPTION 'Balance score must be between 0 and 10';
  END IF;
  IF NEW.light_score IS NOT NULL AND (NEW.light_score < 0 OR NEW.light_score > 10) THEN
    RAISE EXCEPTION 'Light score must be between 0 and 10';
  END IF;
  IF NEW.depth_score IS NOT NULL AND (NEW.depth_score < 0 OR NEW.depth_score > 10) THEN
    RAISE EXCEPTION 'Depth score must be between 0 and 10';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."validate_judge_criteria_scores"() OWNER TO "postgres";


