CREATE OR REPLACE FUNCTION "public"."validate_scheduled_post_window"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.scheduled_for < now() + interval '5 minutes' THEN
      RAISE EXCEPTION 'scheduled_for must be at least 5 minutes in the future';
    END IF;
    IF NEW.scheduled_for > now() + interval '90 days' THEN
      RAISE EXCEPTION 'scheduled_for cannot be more than 90 days in the future';
    END IF;
  ELSIF TG_OP = 'UPDATE' AND NEW.scheduled_for IS DISTINCT FROM OLD.scheduled_for THEN
    IF NEW.scheduled_for < now() + interval '5 minutes' THEN
      RAISE EXCEPTION 'Rescheduled time must be at least 5 minutes in the future';
    END IF;
    IF NEW.scheduled_for > now() + interval '90 days' THEN
      RAISE EXCEPTION 'Rescheduled time cannot be more than 90 days in the future';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."validate_scheduled_post_window"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."verify_certificate"("_cert_id" "text") RETURNS TABLE("id" "uuid", "title" "text", "description" "text", "type" "text", "issued_at" timestamp with time zone, "recipient_name" "text", "certificate_id" "text", "verification_token" "text", "is_revoked" boolean, "revoked_at" timestamp with time zone, "revoked_reason" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT c.id, c.title, c.description, c.type, c.issued_at,
         p.full_name, c.certificate_id, NULL::text AS verification_token,
         COALESCE(c.is_revoked, false), c.revoked_at, c.revoked_reason
  FROM public.certificates c
  LEFT JOIN public.profiles p ON p.id = c.user_id
  WHERE c.id::text = _cert_id
     OR upper(c.certificate_id) = upper(_cert_id)
  LIMIT 1;
$$;


