    "family" "text" NOT NULL,
    "decision_token" "text" NOT NULL,
    "tag_label_canonical" "text" NOT NULL,
    "advances_to_round" integer,
    "blocks_from_round" integer,
    "description" "text" NOT NULL,
    "is_active" boolean DEFAULT true NOT NULL,
