CREATE OR REPLACE VIEW "public"."judging_progression_audit" WITH ("security_invoker"='true') AS
 WITH "per_photo" AS (
         SELECT "jta"."entry_id",
            "jta"."photo_index",
            "mode"() WITHIN GROUP (ORDER BY "c_1"."family") AS "majority_family",
            "count"(DISTINCT "jta"."judge_id") AS "judge_count"
           FROM (("public"."judge_tag_assignments" "jta"
             JOIN "public"."judging_tags" "t" ON (("t"."id" = "jta"."tag_id")))
             CROSS JOIN LATERAL "public"."classify_judging_tag"("t"."label", "t"."visible_in_round") "c_1"("family", "advances_to", "blocks_from", "verification_round"))
          GROUP BY "jta"."entry_id", "jta"."photo_index"
        ), "agg" AS (
         SELECT "per_photo"."entry_id",
            "bool_or"(("per_photo"."majority_family" = 'progression_pass'::"text")) AS "any_pass",
            "bool_or"(("per_photo"."majority_family" = 'progression_fail'::"text")) AS "any_fail",
            "bool_or"(("per_photo"."majority_family" = 'rejection'::"text")) AS "any_reject",
            "sum"("per_photo"."judge_count") AS "total_decisions"
           FROM "per_photo"
          GROUP BY "per_photo"."entry_id"
        ), "computed" AS (
         SELECT "agg"."entry_id",
                CASE
                    WHEN "agg"."any_pass" THEN 'qualified'::"text"
                    WHEN "agg"."any_fail" THEN 'not_selected'::"text"
                    WHEN "agg"."any_reject" THEN 'reject'::"text"
                    ELSE NULL::"text"
                END AS "expected_decision",
            "agg"."total_decisions"
           FROM "agg"
        )
 SELECT "ce"."id" AS "entry_id",
    "ce"."competition_id",
    "ce"."title",
    "ce"."status",
    "ce"."progression_decision" AS "stored_decision",
    "c"."expected_decision",
    "c"."total_decisions",
        CASE
            WHEN (("ce"."progression_decision" IS NULL) AND ("c"."expected_decision" IS NULL)) THEN false
            WHEN ("ce"."progression_decision" IS DISTINCT FROM "c"."expected_decision") THEN true
            ELSE false
        END AS "has_drift",
    "ce"."updated_at"
   FROM ("public"."competition_entries" "ce"
     LEFT JOIN "computed" "c" ON (("c"."entry_id" = "ce"."id")));


ALTER VIEW "public"."judging_progression_audit" OWNER TO "postgres";


