CREATE TABLE IF NOT EXISTS "public"."media_objects" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "owner_id" "uuid" NOT NULL,
    "sha256" "bytea" NOT NULL,
    "width" integer NOT NULL,
    "height" integer NOT NULL,
    "bytes" bigint NOT NULL,
    "mime" "text" NOT NULL,
    "visibility" "text" DEFAULT 'private'::"text" NOT NULL,
    "derivatives" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "state" "text" DEFAULT 'pending'::"text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "verified_at" timestamp with time zone,
    "quarantine_reason" "text",
    CONSTRAINT "media_objects_bytes_check" CHECK (("bytes" > 0)),
    CONSTRAINT "media_objects_height_check" CHECK ((("height" > 0) AND ("height" <= 100000))),
    CONSTRAINT "media_objects_mime_check" CHECK (("mime" = ANY (ARRAY['image/webp'::"text", 'image/jpeg'::"text", 'image/png'::"text", 'image/avif'::"text"]))),
    CONSTRAINT "media_objects_quarantine_has_reason" CHECK ((("state" <> 'quarantined'::"text") OR ("quarantine_reason" IS NOT NULL))),
    CONSTRAINT "media_objects_ready_has_derivatives" CHECK ((("state" <> 'ready'::"text") OR ("derivatives" ? 'original'::"text"))),
    CONSTRAINT "media_objects_sha256_len" CHECK (("octet_length"("sha256") = 32)),
    CONSTRAINT "media_objects_state_check" CHECK (("state" = ANY (ARRAY['pending'::"text", 'verified'::"text", 'ready'::"text", 'quarantined'::"text"]))),
    CONSTRAINT "media_objects_verified_has_ts" CHECK ((("state" = ANY (ARRAY['pending'::"text", 'quarantined'::"text"])) OR ("verified_at" IS NOT NULL))),
    CONSTRAINT "media_objects_visibility_check" CHECK (("visibility" = ANY (ARRAY['public'::"text", 'restricted'::"text", 'private'::"text"]))),
    CONSTRAINT "media_objects_width_check" CHECK ((("width" > 0) AND ("width" <= 100000)))
);


ALTER TABLE "public"."media_objects" OWNER TO "postgres";


COMMENT ON COLUMN "public"."media_objects"."sha256" IS 'Content identity. SERVER-SIDE ONLY — must never appear in a URL, an RPC return type or a client payload. A public CDN plus a content-derived address lets anyone holding candidate bytes probe whether a given member uploaded a given photograph. Enforced by src/__tests__/mediaIdentityContainment.test.ts.';



COMMENT ON COLUMN "public"."media_objects"."state" IS 'pending -> verified -> ready, or quarantined. Only `ready` may be referenced by post_media; enforced by trg_post_media_requires_ready, not by convention.';



COMMENT ON COLUMN "public"."media_objects"."quarantine_reason" IS 'Why this object was quarantined. NULL unless state = quarantined. Set by media_quarantine(); a quarantine with no reason is not reviewable.';



