    "rand_key" double precision DEFAULT "random"() NOT NULL,
    "viewer_count" integer DEFAULT 0 NOT NULL,
    "viewer_bucket_stable" integer DEFAULT 0 NOT NULL,
    "idempotency_key" "text",
