 SELECT 'F1_TAG_WITHOUT_DECISION'::"text" AS "finding_code",
    'judge_tag_assignments'::"text" AS "source_table",
    "jta"."id" AS "source_row_id",
    "jta"."entry_id",
    "jta"."judge_id",
    "jta"."round_number",
    "jta"."photo_index",
    "jt"."label" AS "detail_label",
    NULL::"text" AS "expected_value",
    NULL::"text" AS "actual_value",
    "jta"."created_at" AS "occurred_at"
   FROM ("public"."judge_tag_assignments" "jta"
     LEFT JOIN "public"."judging_tags" "jt" ON (("jt"."id" = "jta"."tag_id")))
  WHERE (NOT (EXISTS ( SELECT 1
           FROM "public"."judge_decisions" "jd"
          WHERE (("jd"."entry_id" = "jta"."entry_id") AND ("jd"."judge_id" = "jta"."judge_id") AND ("jd"."round_number" = "jta"."round_number") AND (NOT ("jd"."photo_index" IS DISTINCT FROM "jta"."photo_index"))))))
UNION ALL
 SELECT 'F2_DECISION_WITHOUT_ALIAS'::"text" AS "finding_code",
    'judge_decisions'::"text" AS "source_table",
    "jd"."id" AS "source_row_id",
    "jd"."entry_id",
    "jd"."judge_id",
    "jd"."round_number",
    "jd"."photo_index",
    "jd"."decision" AS "detail_label",
    "jd"."stage_key" AS "expected_value",
    NULL::"text" AS "actual_value",
    "jd"."created_at" AS "occurred_at"
   FROM "public"."judge_decisions" "jd"
  WHERE (("jd"."decision" IS NOT NULL) AND (NOT (EXISTS ( SELECT 1
           FROM "public"."v3_tag_label_alias" "a"
          WHERE (("lower"("a"."alias_label") = "lower"("jd"."decision")) AND ("a"."round_number" = "jd"."round_number"))))))
UNION ALL
 SELECT DISTINCT 'F3_TAG_LABEL_NO_ALIAS'::"text" AS "finding_code",
    'judging_tags'::"text" AS "source_table",
    "jt"."id" AS "source_row_id",
    NULL::"uuid" AS "entry_id",
    NULL::"uuid" AS "judge_id",
    "jta"."round_number",
    NULL::integer AS "photo_index",
    "jt"."label" AS "detail_label",
    NULL::"text" AS "expected_value",
    NULL::"text" AS "actual_value",
    "min"("jta"."created_at") AS "occurred_at"
   FROM ("public"."judge_tag_assignments" "jta"
     JOIN "public"."judging_tags" "jt" ON (("jt"."id" = "jta"."tag_id")))
  WHERE (("jt"."label" IS NOT NULL) AND (NOT (EXISTS ( SELECT 1
           FROM "public"."v3_tag_label_alias" "a"
          WHERE (("lower"("a"."alias_label") = "lower"("jt"."label")) AND ("a"."round_number" = "jta"."round_number"))))))
  GROUP BY "jt"."id", "jt"."label", "jta"."round_number"
UNION ALL
 SELECT 'F4_MIRROR_LOG_ERROR'::"text" AS "finding_code",
    'v3_mirror_log'::"text" AS "source_table",
    "ml"."id" AS "source_row_id",
    "ml"."entry_id",
    "ml"."judge_id",
    "ml"."round_number",
    "ml"."photo_index",
    "ml"."tag_label" AS "detail_label",
    "ml"."matched_stage" AS "expected_value",
    "ml"."error_message" AS "actual_value",
    "ml"."occurred_at"
   FROM "public"."v3_mirror_log" "ml"
  WHERE (("ml"."action" = 'error'::"text") AND ("ml"."occurred_at" >= ("now"() - '30 days'::interval)) AND ("ml"."reviewed_at" IS NULL))
UNION ALL
 SELECT 'F5_CURRENT_ROUND_INVALID'::"text" AS "finding_code",
    'competition_entries'::"text" AS "source_table",
    "ce"."id" AS "source_row_id",
    "ce"."id" AS "entry_id",
    NULL::"uuid" AS "judge_id",
    NULL::integer AS "round_number",
    NULL::integer AS "photo_index",
    "ce"."current_round" AS "detail_label",
    '1|2|3|4'::"text" AS "expected_value",
    "ce"."current_round" AS "actual_value",
    "ce"."updated_at" AS "occurred_at"
   FROM "public"."competition_entries" "ce"
  WHERE (("ce"."current_round" IS NOT NULL) AND ((COALESCE(NULLIF("regexp_replace"("ce"."current_round", '[^0-9]'::"text", ''::"text", 'g'::"text"), ''::"text"), '0'::"text"))::integer <> ALL (ARRAY[1, 2, 3, 4])));


